export const config = { runtime: 'edge' };
import { GoogleGenAI } from "@google/genai";
import { createClient } from "@supabase/supabase-js";

const GEMINI_FALLBACK_MODELS = [
  process.env.GEMINI_MODEL || "gemini-3-flash-preview",
  "gemini-flash-latest",
  "gemini-3.5-flash"
];

export default async (req: Request) => {
  // CORS Preflight
  if (req.method === "OPTIONS") {
    return new Response(null, {
      status: 204,
      headers: {
        "Access-Control-Allow-Origin": "*",
        "Access-Control-Allow-Headers": "Content-Type",
        "Access-Control-Allow-Methods": "POST, OPTIONS",
      },
    });
  }

  if (req.method !== "POST") {
    return new Response(JSON.stringify({ error: "Method Not Allowed" }), {
      status: 405,
      headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
    });
  }

  try {
    const { message } = await req.json();
    if (!message || typeof message !== "string") {
      return new Response(JSON.stringify({ error: "Mensagem inválida" }), {
        status: 400,
        headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
      });
    }

    const lowercaseMsg = message.toLowerCase();
    const isTestRequest = 
      lowercaseMsg.includes("varredura") || 
      lowercaseMsg.includes("testar o site") ||
      lowercaseMsg.includes("testar as abas") ||
      lowercaseMsg.includes("testar abas") ||
      lowercaseMsg.includes("teste o site") ||
      lowercaseMsg.includes("rodar testes") ||
      lowercaseMsg.includes("executar testes") ||
      lowercaseMsg.includes("rodar playwright") ||
      lowercaseMsg.includes("executar playwright") ||
      lowercaseMsg.includes("playwright") ||
      (lowercaseMsg.includes("teste") && lowercaseMsg.includes("site")) ||
      (lowercaseMsg.includes("teste") && lowercaseMsg.includes("aba"));

    if (isTestRequest) {
      const reply = `Olá, Dr. Agnaldo! Entendi que você deseja realizar uma varredura ou teste completo das abas do site.

Como esta versão hospedada no Vercel roda em um ambiente *Serverless*, eu não consigo executar o Playwright com navegadores Chromium em tempo real devido a limitações de ambiente e tempo limite de execução.

No entanto, o **Sentinel Agent** está configurado e ativo na sua **VPS Oracle**, realizando essa auditoria completa de forma automática a cada **3 horas** e sincronizando os relatórios diretamente aqui no painel.

Caso precise rodar a varredura manualmente agora, você pode:
1. Acessar a VPS Oracle via SSH e executar o script:
   \`python scripts/vps_agent_loop.py\`
2. Rodar o servidor do projeto localmente (onde o terminal possui suporte total) e enviar este mesmo comando no chat.`;

      return new Response(JSON.stringify({ reply }), {
        status: 200,
        headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
      });
    }

    const apiKey = process.env.GEMINI_API_KEY;
    if (!apiKey) {
      return new Response(JSON.stringify({ error: "GEMINI_API_KEY não configurada." }), {
        status: 500,
        headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
      });
    }

    // Fetch sentinel reports from Supabase for context
    let reportsSummary = "Nenhum relatório de erros registrado no momento.";
    try {
      const supabaseUrl = process.env.VITE_SUPABASE_URL || "";
      const supabaseKey = process.env.SUPABASE_SERVICE_ROLE_KEY || "";
      const userId = process.env.DEFAULT_USER_ID || "";

      if (supabaseUrl && supabaseKey && userId) {
        const supabase = createClient(supabaseUrl, supabaseKey, {
          auth: { persistSession: false, autoRefreshToken: false }
        });
        const { data } = await supabase
          .from("clinic_data")
          .select("crm_data")
          .eq("user_id", userId)
          .single();

        const reports = data?.crm_data?.sentinelReports || [];
        if (reports.length > 0) {
          const pending = reports.filter((r: any) => r.status === "pending");
          const applied = reports.filter((r: any) => r.status === "applied");
          reportsSummary = `Erros Pendentes (${pending.length}):\n` +
            pending.slice(0, 10).map((r: any) => `- [${r.timestamp}] ${r.message} no arquivo ${r.file}:${r.line}`).join("\n") +
            `\n\nCorreções Aplicadas (${applied.length}):\n` +
            applied.slice(0, 10).map((r: any) => `- [${r.timestamp}] ${r.message} (PR criado para o arquivo ${r.file})`).join("\n");
        }
      }
    } catch (_) {
      reportsSummary = "Não foi possível carregar o histórico de relatórios.";
    }

    const prompt = `Você é o Agente IA DevOps e de Qualidade de Software do Consultório Odontológico do Dr. Agnaldo Ferreira.
O Dr. Agnaldo está conversando com você pela Central IA do sistema.

URL Oficial do Sistema: https://sistema-aistudio.vercel.app

Seu papel é responder com palavras simples, claras e fáceis de entender ("palavras de leigo", sem jargões de programação excessivos) sobre o status do sistema, o que você andou analisando, corrigindo ou melhorando.

Aqui está o histórico das suas atividades de auditoria recentes (Sentinel Reports) na VPS Oracle para seu contexto:
${reportsSummary}

Responda à mensagem abaixo de forma amigável, prestativa e muito clara (seja conciso e direto):
Mensagem do Dr. Agnaldo: "${message}"`;

    const reply = await callLLM(prompt);

    return new Response(JSON.stringify({ reply }), {
      status: 200,
      headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
    });
  } catch (error: any) {
    console.error("Agent Chat Error:", error);
    const isQuota = error?.status === 429 || error?.message?.includes("RESOURCE_EXHAUSTED");
    return new Response(JSON.stringify({
      reply: isQuota
        ? "Desculpe, Dr. Agnaldo. Os créditos da API de inteligência artificial estão temporariamente esgotados. Tente novamente mais tarde."
        : "Desculpe, Dr. Agnaldo. Ocorreu um erro interno ao processar sua mensagem. Tente novamente em instantes."
    }), {
      status: 200,
      headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
    });
  }
};

// Helper para chamar a LLM (NVIDIA, OpenRouter ou Gemini)
async function callLLM(prompt: string, jsonMode: boolean = false): Promise<string> {
  const nvidiaKey = process.env.NVIDIA_API_KEY;
  const openrouterKey = process.env.OPENROUTER_API_KEY;
  const geminiKey = process.env.GEMINI_API_KEY;
  const modelName = process.env.LLM_MODEL || "minimaxai/minimax-m3";

  if (nvidiaKey) {
    console.log(`[LLM API] Chamando NVIDIA com o modelo ${modelName}...`);
    try {
      const response = await fetch("https://integrate.api.nvidia.com/v1/chat/completions", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${nvidiaKey}`
        },
        body: JSON.stringify({
          model: modelName,
          messages: [{ role: "user", content: prompt }],
          response_format: jsonMode ? { type: "json_object" } : undefined
        })
      });
      if (response.ok) {
        const data: any = await response.json();
        return data.choices?.[0]?.message?.content || "";
      }
      console.error(`[LLM API] Erro NVIDIA: ${response.status} ${response.statusText}`);
    } catch (err) {
      console.error("[LLM API] Erro ao chamar NVIDIA:", err);
    }
  }

  if (openrouterKey) {
    console.log(`[LLM API] Chamando OpenRouter com o modelo ${modelName}...`);
    try {
      const response = await fetch("https://openrouter.ai/api/v1/chat/completions", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${openrouterKey}`,
          "HTTP-Referer": "https://github.com/Agnaldojjr/sistema-aistudio",
          "X-Title": "Hermes Chat Agent"
        },
        body: JSON.stringify({
          model: modelName,
          messages: [{ role: "user", content: prompt }],
          response_format: jsonMode ? { type: "json_object" } : undefined
        })
      });
      if (response.ok) {
        const data: any = await response.json();
        return data.choices?.[0]?.message?.content || "";
      }
      console.error(`[LLM API] Erro OpenRouter: ${response.status} ${response.statusText}`);
    } catch (err) {
      console.error("[LLM API] Erro ao chamar OpenRouter:", err);
    }
  }

  if (geminiKey) {
    for (const modelName of GEMINI_FALLBACK_MODELS) {
      console.log(`[LLM API] Chamando Gemini (${modelName})...`);
      try {
        const response = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${modelName}:generateContent?key=${geminiKey}`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            contents: [{ parts: [{ text: prompt }] }],
            generationConfig: jsonMode ? { responseMimeType: "application/json" } : undefined
          })
        });
        if (response.ok) {
          const data: any = await response.json();
          return data.candidates?.[0]?.content?.parts?.[0]?.text || "";
        }
        console.warn(`[LLM API] Erro Gemini (${modelName}): ${response.status} ${response.statusText}. Tentando próximo modelo...`);
      } catch (err) {
        console.warn(`[LLM API] Erro ao chamar Gemini (${modelName}):`, err);
      }
    }
  }

  throw new Error("Nenhuma chave de API de LLM configurada (NVIDIA_API_KEY, OPENROUTER_API_KEY ou GEMINI_API_KEY).");
}

export const config = { runtime: 'edge' };

export default async (req: Request) => {
  if (req.method === 'OPTIONS') {
    return new Response(null, {
      status: 204,
      headers: {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Headers': 'Content-Type',
        'Access-Control-Allow-Methods': 'GET, OPTIONS',
      },
    });
  }

  try {
    const url = new URL(req.url);
    const format = url.searchParams.get('format') || 'json';
    const fileParam = url.searchParams.get('file');
    const origin = url.origin;

    if (format === 'txt' || format === 'llms') {
      const res = await fetch(`${origin}/llms.txt`);
      const text = await res.text();
      return new Response(text, {
        status: 200,
        headers: {
          'Content-Type': 'text/plain; charset=utf-8',
          'Access-Control-Allow-Origin': '*',
          'Cache-Control': 'public, max-age=60',
        },
      });
    }

    if (format === 'full') {
      const res = await fetch(`${origin}/llms-full.txt`);
      const text = await res.text();
      return new Response(text, {
        status: 200,
        headers: {
          'Content-Type': 'text/plain; charset=utf-8',
          'Access-Control-Allow-Origin': '*',
          'Cache-Control': 'public, max-age=60',
        },
      });
    }

    const res = await fetch(`${origin}/ai-context.json`);
    const manifest = await res.json();

    if (fileParam && Array.isArray(manifest.files)) {
      const matched = manifest.files.find((f: any) => f.path === fileParam || f.path.endsWith(fileParam));
      if (!matched) {
        return new Response(JSON.stringify({ error: `Arquivo '${fileParam}' não encontrado no manifesto.` }), {
          status: 404,
          headers: {
            'Content-Type': 'application/json; charset=utf-8',
            'Access-Control-Allow-Origin': '*',
          },
        });
      }
      if (format === 'raw' || url.searchParams.get('raw') === 'true') {
        return new Response(matched.content, {
          status: 200,
          headers: {
            'Content-Type': 'text/plain; charset=utf-8',
            'Access-Control-Allow-Origin': '*',
          },
        });
      }
      return new Response(JSON.stringify(matched, null, 2), {
        status: 200,
        headers: {
          'Content-Type': 'application/json; charset=utf-8',
          'Access-Control-Allow-Origin': '*',
        },
      });
    }

    return new Response(JSON.stringify(manifest), {
      status: 200,
      headers: {
        'Content-Type': 'application/json; charset=utf-8',
        'Access-Control-Allow-Origin': '*',
        'Cache-Control': 'public, max-age=60',
      },
    });
  } catch (err: any) {
    return new Response(
      JSON.stringify({
        error: 'Falha ao carregar contexto de IA',
        details: err?.message || String(err),
        fallbackLinks: ['/llms.txt', '/llms-full.txt', '/ai-context.json', '/ai-inspector'],
      }),
      {
        status: 500,
        headers: {
          'Content-Type': 'application/json; charset=utf-8',
          'Access-Control-Allow-Origin': '*',
        },
      }
    );
  }
};

import { GoogleGenAI } from "@google/genai";

const FALLBACK_MODELS = [
  process.env.GEMINI_MODEL || "gemini-3-flash-preview",
  "gemini-flash-latest",
  "gemini-3.5-flash"
];

async function generateWithFallback(ai: GoogleGenAI, payload: any) {
  let lastError: any = null;
  for (const model of FALLBACK_MODELS) {
    try {
      const response = await ai.models.generateContent({
        ...payload,
        model
      });
      return response;
    } catch (err: any) {
      lastError = err;
      console.warn(`[Gemini Fallback] Modelo ${model} falhou:`, err?.message || err);
      if (err?.status === 401 || err?.status === 403) throw err;
    }
  }
  throw lastError;
}

export default async function handler(req: any, res: any) {
  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method Not Allowed' });
  }

  try {
    const { patientName, doctorName, procedures } = req.body;

    const prompt = `
    Aja como a secretária comercial premium do dentista ${doctorName}.
    Escreva um script curto de fechamento de venda via WhatsApp para enviar o orçamento em PDF para o paciente chamado ${patientName}.
    O paciente fará os seguintes tratamentos: ${(procedures || []).join(', ')}.
    
    A mensagem deve:
    1. Ser extremamente cordial, mas direta e com gatilho de autoridade.
    2. Explicar brevemente que o orçamento do planejamento está no PDF anexo.
    3. Perguntar qual a melhor forma de pagamento ou se podemos agendar o início.
    4. Não inventar valores em dinheiro, o valor já estará no PDF.
    `;

    let responseText = "";

    if (process.env.GEMINI_API_KEY) {
      const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY });
      const response = await generateWithFallback(ai, {
        contents: prompt,
        config: { temperature: 0.7 }
      });
      responseText = response.text || "";
    } else if (process.env.DEEPSEEK_API_KEY) {
      const deepseekKey = process.env.DEEPSEEK_API_KEY;
      const aiResponse = await fetch("https://api.deepseek.com/chat/completions", {
        method: "POST",
        headers: { 
          "Content-Type": "application/json",
          "Authorization": `Bearer ${deepseekKey}`
        },
        body: JSON.stringify({
          model: "deepseek-chat",
          messages: [{ role: "user", content: prompt }]
        })
      });
      const data = await aiResponse.json();
      responseText = data.choices?.[0]?.message?.content || "Erro ao gerar script com AI.";
    } else {
      throw new Error("Nenhuma chave de IA configurada (GEMINI_API_KEY ou DEEPSEEK_API_KEY).");
    }

    res.status(200).json({ message: responseText });
  } catch (error: any) {
    console.error("Gemini API Error (budget-script):", error);
    res.status(500).json({ 
      error: "Erro ao gerar script de orçamento.", 
      details: error?.message || String(error) 
    });
  }
}

export const config = { runtime: 'edge' };
import { GoogleGenAI } from "@google/genai";

export default async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response(null, {
      status: 204,
      headers: {
        "Access-Control-Allow-Origin": "*",
        "Access-Control-Allow-Headers": "Content-Type",
        "Access-Control-Allow-Methods": "POST, OPTIONS",
      },
    });
  }

  if (req.method !== "POST") {
    return new Response(JSON.stringify({ error: "Method Not Allowed" }), {
      status: 405,
      headers: { "Content-Type": "application/json" },
    });
  }

  try {
    const body = await req.json();
    const acquirer = body?.acquirer === "infinitetap" ? "infinitetap" : "ton";

    const apiKey = process.env.GEMINI_API_KEY;
    if (!apiKey) {
      return new Response(
        JSON.stringify({ error: "GEMINI_API_KEY não configurada." }),
        { status: 503, headers: { "Content-Type": "application/json" } }
      );
    }

    const ai = new GoogleGenAI({ apiKey });

    const acquirerLabel =
      acquirer === "infinitetap"
        ? "InfinitePay / InfiniteTap (Brasil - recebimento em 1 dia útil)"
        : "Ton (Stone - Planos Ton Brother / PromoTon no Brasil - recebimento em 1 dia útil)";

    const prompt = `Consulte as taxas oficiais vigentes no Brasil para a maquininha ${acquirerLabel}.
Retorne APENAS um objeto JSON válido (sem blocos markdown) exatamente no formato abaixo, onde:
- "under_3" representa a faixa padrão de entrada (até R$ 3 mil/mês no Ton ou padrão 1 dia útil no InfiniteTap)
- "between_3_6" representa a faixa promocional / maior faturamento (PromoTon / acima de R$ 3 mil no Ton ou faixa reduzida no InfiniteTap)
- "credit.visa_master" e "credit.elo_amex" possuem EXATAMENTE 12 números decimais (1x até 12x) em ordem crescente, representando a porcentagem (ex: 3.15 para 3,15%).

Formato obrigatório:
{
  "source": "Resumo da fonte oficial e data",
  "tiers": {
    "under_3": {
      "debit": { "visa_master": 1.37, "elo_amex": 2.51 },
      "credit": {
        "visa_master": [3.15, 5.39, 6.12, 6.85, 7.57, 8.28, 8.99, 9.69, 10.38, 11.06, 11.74, 12.40],
        "elo_amex": [4.91, 6.47, 7.20, 7.92, 8.63, 9.33, 10.03, 10.72, 11.40, 12.08, 12.75, 13.41]
      }
    },
    "between_3_6": {
      "debit": { "visa_master": 0.75, "elo_amex": 1.88 },
      "credit": {
        "visa_master": [2.69, 3.94, 4.46, 4.98, 5.49, 5.99, 6.51, 6.99, 7.51, 7.99, 8.49, 8.99],
        "elo_amex": [3.89, 5.14, 5.66, 6.18, 6.69, 7.19, 7.71, 8.19, 8.71, 9.19, 9.69, 10.19]
      }
    }
  }
}`;

    const response = await ai.models.generateContent({
      model: process.env.GEMINI_MODEL || "gemini-2.5-flash",
      contents: prompt,
      config: {
        temperature: 0.1,
        tools: [{ googleSearch: {} }],
      },
    });

    const rawText = (response.text || "").trim();
    const jsonMatch = rawText.match(/\{[\s\S]*\}/);
    if (!jsonMatch) {
      throw new Error("Resposta da IA não continha JSON estruturado.");
    }

    const parsed = JSON.parse(jsonMatch[0]);
    return new Response(JSON.stringify(parsed), {
      status: 200,
      headers: {
        "Content-Type": "application/json",
        "Access-Control-Allow-Origin": "*",
      },
    });
  } catch (err: any) {
    return new Response(
      JSON.stringify({
        error: "Falha ao sincronizar taxas via IA",
        details: err?.message || String(err),
      }),
      { status: 500, headers: { "Content-Type": "application/json" } }
    );
  }
};

import { GoogleGenAI } from "@google/genai";

const FALLBACK_MODELS = [
  process.env.GEMINI_MODEL || "gemini-3-flash-preview",
  "gemini-flash-latest",
  "gemini-3.5-flash"
];

async function generateWithFallback(ai: GoogleGenAI, payload: any) {
  let lastError: any = null;
  for (const model of FALLBACK_MODELS) {
    try {
      const response = await ai.models.generateContent({
        ...payload,
        model
      });
      return response;
    } catch (err: any) {
      lastError = err;
      console.warn(`[Gemini Fallback] Modelo ${model} falhou:`, err?.message || err);
      if (err?.status === 401 || err?.status === 403) throw err;
    }
  }
  throw lastError;
}

export default async function handler(req: any, res: any) {
  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method Not Allowed' });
  }

  try {
    const { patientName, lastProcedure, lastVisitDate, doctorName } = req.body;

    if (!process.env.GEMINI_API_KEY) {
      return res.status(401).json({ error: "API key is not set in environment variables." });
    }

    const ai = new GoogleGenAI({
      apiKey: process.env.GEMINI_API_KEY,
      httpOptions: {
        headers: {
          'User-Agent': 'aistudio-build',
        }
      }
    });

    const prompt = `
    Aja como a secretária simpática e profissional do dentista ${doctorName}.
    Escreva uma mensagem de WhatsApp para o paciente chamado ${patientName}.
    O objetivo da mensagem é ser um lembrete caloroso para agendar uma revisão (profilaxia) 
    pois já faz um tempo desde a última consulta (${lastVisitDate}) onde ele fez: ${lastProcedure}.
    Mantenha a mensagem curta (máximo 3 frases), use emojis sutis, seja educada e não invente datas ou valores.
    `;

    const response = await generateWithFallback(ai, {
      contents: prompt,
      config: {
        temperature: 0.7,
      }
    });

    res.status(200).json({ message: response.text });
  } catch (error: any) {
    console.error("Gemini API Error (recall):", error);
    if (error?.status === 403 || error?.status === 401) {
      return res.status(403).json({ error: "Chave da API inválida ou sem permissão." });
    }
    if (error?.status === 429) {
      return res.status(429).json({ error: "Créditos da API Google Gemini esgotados." });
    }
    res.status(500).json({ error: "Erro ao gerar mensagem de recall." });
  }
}

import { GoogleGenAI } from "@google/genai";

const FALLBACK_MODELS = [
  process.env.GEMINI_MODEL || "gemini-3-flash-preview",
  "gemini-flash-latest",
  "gemini-3.5-flash"
];

async function generateWithFallback(ai: GoogleGenAI, payload: any) {
  let lastError: any = null;
  for (const model of FALLBACK_MODELS) {
    try {
      const response = await ai.models.generateContent({
        ...payload,
        model
      });
      return response;
    } catch (err: any) {
      lastError = err;
      console.warn(`[Gemini Fallback] Modelo ${model} falhou:`, err?.message || err);
      if (err?.status === 401 || err?.status === 403) throw err;
    }
  }
  throw lastError;
}

export default async function handler(req: any, res: any) {
  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method Not Allowed' });
  }

  try {
    const { notes } = req.body;

    if (!notes) {
      return res.status(400).json({ error: "Texto clínico de entrada é obrigatório." });
    }

    if (!process.env.GEMINI_API_KEY) {
      return res.status(401).json({ error: "API key is not set in environment variables." });
    }

    const ai = new GoogleGenAI({
      apiKey: process.env.GEMINI_API_KEY,
      httpOptions: {
        headers: {
          'User-Agent': 'aistudio-build',
        }
      }
    });

    const prompt = `
    Você é um assistente de inteligência artificial de alto nível integrado a um prontuário clínico odontológico.
    Sua função é transformar anotações clínicas rápidas, transcrições de voz ou observações do dentista em um plano de tratamento odontológico estruturado (ODONTOGRAMA).
    
    Regras Clínicas Estritas:
    1. Identifique os dentes envolvidos utilizando o sistema de numeração FDI (Ex: 11 a 18, 21 a 28, 31 a 38, 41 a 48).
    2. Identifique as faces quando mencionadas (M: Mesial, D: Distal, O: Oclusal, V: Vestibular, L: Lingual/Palatina).
    3. Categorize o estado/condição do dente:
       - 'CARIES' (Cárie ativa / restauração necessária)
       - 'FRACTURE' (Dente quebrado/fraturado)
       - 'PULPITIS' (Dor intensa, necessidade de canal/endodontia)
       - 'MISSING' (Dente ausente)
       - 'IMPLANT' (Implante planejado/executado)
       - 'CROWN' (Coroa, faceta ou bloco planejado)
    4. Sugira procedimentos e preços médios adequados para cada dente:
       - Cárie -> "Restauração de Resina" (Preço: 250.00) aplicada na respectiva face.
       - Canal/Pulpite -> "Tratamento de Canal (Endodontia)" (Preço: 800.00).
       - Dente Ausente / Implante -> "Implante de Titânio" (Preço: 2500.00).
       - Faceta -> "Faceta de Porcelana" (Preço: 1800.00).
       - Fratura complexa -> "Coroa Provisória" (Preço: 400.00).
    `;

    const response = await generateWithFallback(ai, {
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: "OBJECT",
          properties: {
            teeth: {
              type: "ARRAY",
              items: {
                type: "OBJECT",
                properties: {
                  tooth: { type: "INTEGER" },
                  condition: { type: "STRING" }, // Ex: CARIES, PULPITIS, IMPLANT
                  notes: { type: "STRING" },
                  surfaces: {
                    type: "ARRAY",
                    items: { type: "STRING" } // Ex: ["O", "M"]
                  },
                  procedures: {
                    type: "ARRAY",
                    items: {
                      type: "OBJECT",
                      properties: {
                        name: { type: "STRING" },
                        price: { type: "NUMBER" }
                      },
                      required: ["name", "price"]
                    }
                  }
                },
                required: ["tooth", "condition", "procedures"]
              }
            }
          },
          required: ["teeth"]
        }
      }
    });

    const result = JSON.parse(response.text || "{}");
    res.status(200).json(result);
  } catch (error: any) {
    console.error("Gemini API Error (suggest-plan):", error);
    res.status(500).json({ error: "Erro ao processar análise clínica de IA." });
  }
}

