    const loginRes = await fetch(`${hermesUrl}/auth/password-login`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        provider: "basic",
        username,
        password,
        next: "/sessions"
      })
    });

    if (!loginRes.ok) {
      console.error("[Hermes API] Falha no login do Hermes:", loginRes.statusText);
      return new Response(JSON.stringify({ name: null }), {
        status: 200,
        headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
      });
    }

    // Capturar o set-cookie da resposta do login
    const cookieHeader = loginRes.headers.get("set-cookie");
    if (!cookieHeader) {
      console.error("[Hermes API] set-cookie ausente");
      return new Response(JSON.stringify({ name: null }), {
        status: 200,
        headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
      });
    }

    // 2. Buscar lista de sessões
    const sessionsRes = await fetch(`${hermesUrl}/api/sessions`, {
      headers: {
        "Cookie": cookieHeader
      }
    });

    if (!sessionsRes.ok) {
      console.error("[Hermes API] Falha ao buscar sessões do Hermes:", sessionsRes.statusText);
      return new Response(JSON.stringify({ name: null }), {
        status: 200,
        headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
      });
    }

    const { sessions } = await sessionsRes.json();
    if (!Array.isArray(sessions)) {
      return new Response(JSON.stringify({ name: null }), {
        status: 200,
        headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
      });
    }

    // Normalizar telefone para comparação (somente números)
    const targetPhone = phone.replace(/\D/g, "");

    // Buscar sessão associada a este número de telefone
    const matchedSession = sessions.find((s: any) => {
      if (s.source !== "whatsapp") return false;
      const skey = s.session_key || "";
      const phoneMatch = skey.match(/:(\d+)$/);
      if (phoneMatch) {
        const sessPhone = phoneMatch[1];
        return sessPhone.includes(targetPhone) || targetPhone.includes(sessPhone);
      }
      return false;
    });

    if (!matchedSession) {
      console.log(`[Hermes API] Nenhuma sessão encontrada para o telefone: ${targetPhone}`);
      return new Response(JSON.stringify({ name: null }), {
        status: 200,
        headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
      });
    }

    const sessionId = matchedSession.id;
    const displayName = matchedSession.display_name || "";

    // 3. Buscar mensagens da sessão identificada
    const messagesRes = await fetch(`${hermesUrl}/api/sessions/${sessionId}/messages`, {
      headers: {
        "Cookie": cookieHeader
      }
    });

    if (!messagesRes.ok) {
      return new Response(JSON.stringify({ name: displayName || null }), {
        status: 200,
        headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
      });
    }

    const { messages } = await messagesRes.json();
    if (!Array.isArray(messages) || messages.length === 0) {
      return new Response(JSON.stringify({ name: displayName || null }), {
        status: 200,
        headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
      });
    }

    // Estruturar histórico de conversa para alimentar o Gemini
    const chatHistory = messages
      .filter((m: any) => m.role === "user" || m.role === "assistant")
      .map((m: any) => `${m.role === 'user' ? 'Paciente' : 'Assistente'}: ${m.content || ''}`)
      .join("\n");

    if (!chatHistory.trim()) {
      return new Response(JSON.stringify({ name: displayName || null }), {
        status: 200,
        headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
      });
    }

    // 4. Usar Gemini para extrair o nome completo caso tenha sido informado
    const geminiApiKey = process.env.GEMINI_API_KEY;
    if (!geminiApiKey) {
      return new Response(JSON.stringify({ name: displayName || null }), {
        status: 200,
        headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
      });
    }

    const ai = new GoogleGenAI({
      apiKey: geminiApiKey,
      httpOptions: { headers: { 'User-Agent': 'aistudio-build' } }
    });

    const prompt = `Analise o histórico de conversa de WhatsApp abaixo entre um paciente e o assistente virtual da clínica.
Identifique e extraia o NOME COMPLETO do paciente (como ele se apresentou ou assinou).
Se o paciente não informou o nome completo na conversa, retorne apenas o nome de exibição (Display Name): "${displayName}".
Responda APENAS com o nome extraído. Não adicione nenhuma introdução, explicação ou formatação de markdown.

Histórico de Conversa:
${chatHistory}`;

    const geminiResponse = await generateWithFallback(ai, {
      contents: prompt,
      config: { temperature: 0.1 }
    });

    const extractedName = geminiResponse.text?.trim();
    if (extractedName && extractedName.length < 50) {
      return new Response(JSON.stringify({ name: extractedName }), {
        status: 200,
        headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
      });
    }

    return new Response(JSON.stringify({ name: displayName || null }), {
      status: 200,
      headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
    });

  } catch (error: any) {
    console.error("Hermes-Name API Error:", error);
    return new Response(JSON.stringify({ name: null, error: error.message }), {
      status: 500,
      headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
    });
  }
};

export const config = { runtime: 'edge' };
import { createClient } from "@supabase/supabase-js";
import { format, addDays } from "date-fns";

const supabaseUrl = process.env.VITE_SUPABASE_URL || "";
const supabaseServiceKey = process.env.SUPABASE_SERVICE_ROLE_KEY || "";

const supabaseAdmin = supabaseUrl && supabaseServiceKey
  ? createClient(supabaseUrl, supabaseServiceKey, {
      auth: {
        persistSession: false,
        autoRefreshToken: false
      }
    })
  : null;

// Helper para buscar a base do CRM no Supabase
async function getCRMDatabase(userId: string) {
  if (!supabaseAdmin) {
    throw new Error("Supabase Admin Client não configurado no servidor.");
  }
  const { data, error } = await supabaseAdmin
    .from("clinic_data")
    .select("crm_data")
    .eq("user_id", userId)
    .single();

  if (error && error.code !== "PGRST116") {
    console.error("Erro ao buscar dados do CRM no Supabase:", error);
    throw error;
  }

  return data?.crm_data || null;
}

// Helper para salvar a base do CRM no Supabase
async function saveCRMDatabase(userId: string, crmData: any) {
  if (!supabaseAdmin) {
    throw new Error("Supabase Admin Client não configurado no servidor.");
  }
  const { error } = await supabaseAdmin
    .from("clinic_data")
    .upsert({
      user_id: userId,
      crm_data: crmData,
      updated_at: new Date().toISOString()
    }, { onConflict: "user_id" });

  if (error) {
    console.error("Erro ao salvar dados do CRM no Supabase:", error);
    throw error;
  }
}

// Helper para enviar mensagens por meio da API oficial de WhatsApp Cloud da Meta
async function sendWhatsAppTemplate(to: string, patientName: string, dentistName: string, date: string, time: string) {
  const token = process.env.WHATSAPP_ACCESS_TOKEN;
  const phoneId = process.env.WHATSAPP_PHONE_NUMBER_ID;
  const templateName = process.env.WHATSAPP_TEMPLATE_NAME || "confirmacao_consulta";

  if (!token || !phoneId) {
    console.warn("[Scheduled reminders] WhatsApp não está configurado no servidor. Pulando envio.");
    return false;
  }

  // Limpa o número de telefone do paciente (apenas números)
  let cleanPhone = to.replace(/\D/g, "");
  // Adiciona DDI do Brasil se necessário
  if (cleanPhone.length >= 10 && !cleanPhone.startsWith("55")) {
    cleanPhone = "55" + cleanPhone;
  }

  const url = `https://graph.facebook.com/v18.0/${phoneId}/messages`;
  const payload = {
    messaging_product: "whatsapp",
    recipient_type: "individual",
    to: cleanPhone,
    type: "template",
    template: {
      name: templateName,
      language: {
        code: "pt_BR"
      },
      components: [
        {
          type: "body",
          parameters: [
            { type: "text", text: patientName },
            { type: "text", text: dentistName },
            { type: "text", text: date },
            { type: "text", text: time }
          ]
        }
      ]
    }
  };

  try {
    const response = await fetch(url, {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${token}`,
        "Content-Type": "application/json"
      },
      body: JSON.stringify(payload)
    });

    const data = await response.json() as any;
    if (!response.ok) {
      console.error("[Scheduled reminders] Erro ao enviar mensagem WhatsApp:", data);
      return false;
    }

    console.log(`[Scheduled reminders] Lembrete enviado com sucesso para ${cleanPhone}. ID:`, data.messages?.[0]?.id);
    return true;
  } catch (error) {
    console.error("[Scheduled reminders] Erro na requisição para Meta API:", error);
    return false;
  }
}

const handler = async (event: any) => {
  console.log("[Scheduled reminders] Iniciando verificação de lembretes...");
  try {
    const userId = process.env.DEFAULT_USER_ID;
    if (!userId) {
      console.log("[Scheduled reminders] DEFAULT_USER_ID não configurado no servidor. Pulando.");
      return new Response("DEFAULT_USER_ID missing", { status: 500 });
    }

    const db = await getCRMDatabase(userId);
    if (!db || !db.appointments) {
      console.log("[Scheduled reminders] Sem agendamentos para processar.");
      return new Response("No appointments found", { status: 200 });
    }

    // Calcula amanhã no formato YYYY-MM-DD
    const tomorrowStr = format(addDays(new Date(), 1), "yyyy-MM-dd");
    const todayStr = format(new Date(), "yyyy-MM-dd");

    console.log(`[Scheduled reminders] Buscando consultas para amanhã (${tomorrowStr})...`);

    const tomorrowAppointments = db.appointments.filter((app: any) =>
      app.date === tomorrowStr && app.status === "Agendado"
    );

    console.log(`[Scheduled reminders] Encontradas ${tomorrowAppointments.length} consultas agendadas.`);

    let dbChanged = false;
    for (const app of tomorrowAppointments) {
      const patient = db.patients.find((p: any) => p.id === app.patientId);
      if (!patient) continue;

      const recipientPhone = patient.mobile || patient.phone;
      if (!recipientPhone) continue;

      // Evita duplicidade nas últimas 24 horas
      const alreadySentToday = db.communications.some((comm: any) =>
        comm.patientId === app.patientId &&
        comm.type === "Confirmação" &&
        comm.date.startsWith(todayStr)
      );

      if (alreadySentToday) {
        console.log(`[Scheduled reminders] Lembrete já enviado hoje para o paciente ${patient.name}. Pulando.`);
        continue;
      }

      const messageText = `Olá, ${patient.name}! Confirmamos sua consulta com o(a) Dr(a). ${app.dentist} amanhã (${app.date}) às ${app.time}?`;

      console.log(`[Scheduled reminders] Enviando lembrete para ${patient.name} (${recipientPhone})...`);

      const success = await sendWhatsAppTemplate(
        recipientPhone,
        patient.name,
        app.dentist,
        format(addDays(new Date(), 1), "dd/MM/yyyy"),
        app.time
      );

      if (success) {
        db.communications.push({
          id: crypto.randomUUID(),
          patientId: app.patientId,
          type: "Confirmação",
          date: new Date().toISOString(),
          message: messageText,
          status: "Enviado",
          token: app.id
        });
        dbChanged = true;
      }
    }

    if (dbChanged) {
      await saveCRMDatabase(userId, db);
      console.log("[Scheduled reminders] Banco de dados atualizado com novos logs de envio.");
    }

    console.log("[Scheduled reminders] Rotina concluída.");
    return new Response("Reminders processed successfully", { status: 200 });

  } catch (error: any) {
    console.error("[Scheduled reminders] Erro crítico:", error);
    return new Response(error.message || "Internal Server Error", { status: 500 });
  }
};

export default handler;

export const config = { runtime: 'edge' };
import { createClient } from "@supabase/supabase-js";

export default async (req: Request) => {
  // CORS Preflight
  if (req.method === "OPTIONS") {
    return new Response(null, {
      status: 204,
      headers: {
        "Access-Control-Allow-Origin": "*",
        "Access-Control-Allow-Headers": "Content-Type",
        "Access-Control-Allow-Methods": "POST, OPTIONS",
      },
    });
  }

  if (req.method !== "POST") {
    return new Response(JSON.stringify({ error: "Method Not Allowed" }), {
      status: 405,
      headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
    });
  }

  try {
    const { reportId } = await req.json();
    if (!reportId) {
      return new Response(JSON.stringify({ error: "reportId é obrigatório" }), {
        status: 400,
        headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
      });
    }

    const supabaseUrl = process.env.VITE_SUPABASE_URL || "";
    const supabaseKey = process.env.SUPABASE_SERVICE_ROLE_KEY || "";
    const userId = process.env.DEFAULT_USER_ID || "";
    const githubToken = process.env.GITHUB_TOKEN || "";

    if (!supabaseUrl || !supabaseKey || !userId) {
      return new Response(JSON.stringify({ error: "Credenciais do Supabase não configuradas." }), {
        status: 500,
        headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
      });
    }

    const supabase = createClient(supabaseUrl, supabaseKey, {
      auth: { persistSession: false, autoRefreshToken: false }
    });

    // Read current CRM data
    const { data, error } = await supabase
      .from("clinic_data")
      .select("crm_data")
      .eq("user_id", userId)
      .single();

    if (error) throw error;

    const crmData = data?.crm_data || {};
    const reports = crmData.sentinelReports || [];
    const rIdx = reports.findIndex((r: any) => r.id === reportId);

    if (rIdx === -1) {
      return new Response(JSON.stringify({ error: "Relatório não localizado" }), {
        status: 404,
        headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
      });
    }

    const report = reports[rIdx];

    if (!report.file || !report.proposedFix) {
      return new Response(JSON.stringify({ error: "Caminho do arquivo ou correção proposta ausentes" }), {
        status: 400,
        headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
      });
    }

    // Create PR on GitHub using the GitHub API
    if (githubToken) {
      const owner = "Agnaldojjr";
      const repo = "sistema-aistudio";
      const branchName = `fix/sentinel-${reportId.slice(0, 8)}-${Date.now()}`;
      const apiBase = `https://api.github.com/repos/${owner}/${repo}`;
      const headers = {
        "Authorization": `Bearer ${githubToken}`,
        "Accept": "application/vnd.github.v3+json",
        "Content-Type": "application/json",
      };

      // 1. Get main branch SHA
      const mainRef = await fetch(`${apiBase}/git/refs/heads/main`, { headers });
      const mainRefData = await mainRef.json();
      const mainSha = mainRefData.object?.sha;

      if (!mainSha) {
        return new Response(JSON.stringify({ error: "Não foi possível obter a referência da branch main." }), {
          status: 500,
          headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
        });
      }

      // 2. Create new branch
      await fetch(`${apiBase}/git/refs`, {
        method: "POST",
        headers,
        body: JSON.stringify({ ref: `refs/heads/${branchName}`, sha: mainSha }),
      });

      // 3. Get current file to obtain its SHA
      const filePath = report.file.replace(/^\//, "").replace(/\\/g, "/");
      const fileRes = await fetch(`${apiBase}/contents/${filePath}?ref=main`, { headers });
      const fileData = await fileRes.json();

      // 4. Update file on the new branch
      const encodedContent = btoa(unescape(encodeURIComponent(report.proposedFix)));
      await fetch(`${apiBase}/contents/${filePath}`, {
        method: "PUT",
        headers,
        body: JSON.stringify({
          message: `fix(sentinel): correção automática - ${report.message || reportId}`,
          content: encodedContent,
          branch: branchName,
          sha: fileData.sha,
        }),
      });

      // 5. Create Pull Request
      const prRes = await fetch(`${apiBase}/pulls`, {
        method: "POST",
        headers,
        body: JSON.stringify({
          title: `🤖 Sentinel Fix: ${report.message || reportId}`,
          body: `## Correção Automática do Agente Sentinela\n\n**Erro detectado:** ${report.message}\n**Arquivo:** \`${report.file}\`\n**Linha:** ${report.line || 'N/A'}\n**Timestamp:** ${report.timestamp}\n\n---\n*Pull Request criado automaticamente pelo Agente Sentinela de UX.*`,
          head: branchName,
          base: "main",
        }),
      });
      const prData = await prRes.json();

      // 6. Update report status in Supabase
      reports[rIdx].status = "applied";
      reports[rIdx].prUrl = prData.html_url || "";
      crmData.sentinelReports = reports;

      await supabase
        .from("clinic_data")
        .update({ crm_data: crmData, updated_at: new Date().toISOString() })
        .eq("user_id", userId);

      return new Response(JSON.stringify({
        success: true,
        message: "Correção enviada como Pull Request no GitHub!",
        prUrl: prData.html_url || "",
      }), {
        status: 200,
        headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
      });
    }

    return new Response(JSON.stringify({ error: "GITHUB_TOKEN não configurado." }), {
      status: 500,
      headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
    });
  } catch (error: any) {
    console.error("Apply Fix Error:", error);
    return new Response(JSON.stringify({ error: error.message || "Erro interno ao aplicar correção." }), {
      status: 500,
      headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
    });
  }
};

