export const config = { runtime: 'edge' };

import { createClient } from "@supabase/supabase-js";

export default async function handler(req: Request) {
  // CORS Preflight
  if (req.method === "OPTIONS") {
    return new Response(null, {
      status: 204,
      headers: {
        "Access-Control-Allow-Origin": "*",
        "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
        "Access-Control-Allow-Headers": "Content-Type, Authorization",
      },
    });
  }

  const supabaseUrl = process.env.VITE_SUPABASE_URL || process.env.SUPABASE_URL || "";
  const supabaseServiceKey = process.env.SUPABASE_SERVICE_ROLE_KEY || "";

  if (!supabaseUrl || !supabaseServiceKey) {
    return new Response(
      JSON.stringify({ error: "Supabase Service Role Key não configurada no servidor." }),
      {
        status: 500,
        headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
      }
    );
  }

  try {
    const url = new URL(req.url);
    const patientId = url.searchParams.get("patientId") || "";
    const patientName = url.searchParams.get("patientName") || "";
    const subfolder = url.searchParams.get("subfolder") || "";
    const userId = url.searchParams.get("userId") || "";

    const cleanPatientId = (patientId || "Anonimo").replace(/[^a-zA-Z0-9 _-]/g, "").trim().replace(/\s+/g, "_");
    const cleanPatientName = patientName ? (patientName || "Anonimo").replace(/[^a-zA-Z0-9 _-]/g, "").trim().replace(/\s+/g, "_") : "";
    const cleanSub = subfolder ? subfolder.replace(/^\/+|\/+$/g, "") : "";

    const targetBucket = 'patient_files';
    const supabaseAdmin = createClient(supabaseUrl, supabaseServiceKey, {
      auth: { persistSession: false, autoRefreshToken: false },
    });

    const candidateFolders: string[] = [];
    const addCandidates = (folderName: string) => {
      if (!folderName) return;
      if (cleanSub) {
        candidateFolders.push(`clinic-master/${folderName}/${cleanSub}`);
        if (userId && userId !== 'clinic-master') candidateFolders.push(`${userId}/${folderName}/${cleanSub}`);
        candidateFolders.push(`${folderName}/${cleanSub}`);
      } else {
        candidateFolders.push(`clinic-master/${folderName}`);
        if (userId && userId !== 'clinic-master') candidateFolders.push(`${userId}/${folderName}`);
        candidateFolders.push(folderName);
        candidateFolders.push(`clinic-master/${folderName}/Orcamentos`);
        if (userId && userId !== 'clinic-master') candidateFolders.push(`${userId}/${folderName}/Orcamentos`);
        candidateFolders.push(`${folderName}/Orcamentos`);
      }
    };

    addCandidates(cleanPatientId);
    if (cleanPatientName && cleanPatientName !== cleanPatientId) {
      addCandidates(cleanPatientName);
    }

    const uniqueFolders = Array.from(new Set(candidateFolders));
    const foundFilesMap = new Map<string, any>();

    // 1. Listar do Supabase Storage via admin
    for (const folder of uniqueFolders) {
      try {
        const { data: items } = await supabaseAdmin.storage
          .from(targetBucket)
          .list(folder);

        if (Array.isArray(items)) {
          for (const item of items) {
            if (item.name && !item.name.endsWith(".emptyFolderPlaceholder") && item.id !== null) {
              const fullStoragePath = `${folder}/${item.name}`;
              if (!foundFilesMap.has(item.name)) {
                const basePublicUrl = `${supabaseUrl}/storage/v1/object/public/${targetBucket}/${fullStoragePath}`;
                const publicUrl = item.name.endsWith(".json")
                  ? `${basePublicUrl}?_t=${Date.now()}`
                  : basePublicUrl;
                const isOrcamento = folder.endsWith("Orcamentos");
                const displayName = isOrcamento ? `Orcamentos/${item.name}` : item.name;

                foundFilesMap.set(item.name, {
                  id: fullStoragePath,
                  name: displayName,
                  storagePath: fullStoragePath,
                  thumbnailLink: publicUrl,
                  createdTime: item.created_at || new Date().toISOString(),
                  modifiedTime: item.updated_at || new Date().toISOString(),
                  mimeType: item.name.endsWith(".pdf")
                    ? "application/pdf"
                    : item.name.endsWith(".json")
                    ? "application/json"
                    : item.name.match(/\.(jpe?g|png|webp|gif|bmp)$/i)
                    ? "image/jpeg"
                    : "application/octet-stream",
                  subfolder: isOrcamento ? "Orcamentos" : (cleanSub || undefined),
                  source: "supabase",
                });
              }
            }
          }
        }
      } catch (err) {
        // Ignora pastas que não existirem
      }
    }

    // 2. Buscar fotos já indexadas do Cloudflare R2 no Supabase CRM (crm_data.galeria)
    try {
      let clinicRecords: any[] | null = null;
      try {
        const { data, error } = await supabaseAdmin
          .from('clinic_data')
          .select('crm_data')
          .limit(5);
        if (!error && Array.isArray(data)) clinicRecords = data;
      } catch (_) {}

      // Fallback com anon key se admin falhar
      if (!clinicRecords && process.env.VITE_SUPABASE_ANON_KEY) {
        try {
          const supaAnon = createClient(supabaseUrl, process.env.VITE_SUPABASE_ANON_KEY, {
            auth: { persistSession: false, autoRefreshToken: false },
          });
          const { data, error } = await supaAnon
            .from('clinic_data')
            .select('crm_data')
            .limit(5);
          if (!error && Array.isArray(data)) clinicRecords = data;
        } catch (_) {}
      }

      if (Array.isArray(clinicRecords)) {
        for (const row of clinicRecords) {
          const galeria = row.crm_data?.galeria;
          if (Array.isArray(galeria)) {
            for (const g of galeria) {
              const matchPatient = (
                (g.patientId && (g.patientId === patientId || g.patientId === cleanPatientId)) ||
                (patientName && g.url && g.url.toLowerCase().includes(cleanPatientName.toLowerCase())) ||
                (g.url && g.url.includes(cleanPatientId))
              );

              if (matchPatient && g.url) {
                const fileName = g.description || g.url.split('/').pop() || 'foto_cloudflare.jpg';
                if (!foundFilesMap.has(fileName)) {
                  foundFilesMap.set(fileName, {
                    id: g.url,
                    name: fileName,
                    storagePath: g.url,
                    thumbnailLink: g.url,
                    createdTime: g.date || new Date().toISOString(),
                    modifiedTime: g.date || new Date().toISOString(),
                    mimeType: "image/jpeg",
                    subfolder: cleanSub || undefined,
                    source: "r2",
                  });
                }
              }
            }
          }
        }
      }
    } catch (_) {}

    const files = Array.from(foundFilesMap.values());

    return new Response(
      JSON.stringify({
        success: true,
        patientId: cleanPatientId,
        files: files,
      }),
      {
        status: 200,
        headers: {
          "Content-Type": "application/json",
          "Access-Control-Allow-Origin": "*",
          "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0"
        },
      }
    );
  } catch (err: any) {
    console.error("Exceção em /api/storage-list:", err);
    return new Response(
      JSON.stringify({ error: err.message || String(err), files: [] }),
      {
        status: 500,
        headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
      }
    );
  }
}

export const config = { runtime: 'edge' };

import { createClient } from "@supabase/supabase-js";

export default async function handler(req: Request) {
  // CORS Preflight
  if (req.method === "OPTIONS") {
    return new Response(null, {
      status: 204,
      headers: {
        "Access-Control-Allow-Origin": "*",
        "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
        "Access-Control-Allow-Headers": "Content-Type, Authorization",
      },
    });
  }

  if (req.method !== "POST") {
    return new Response(JSON.stringify({ error: "Método não suportado" }), {
      status: 405,
      headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
    });
  }

  const supabaseUrl = process.env.VITE_SUPABASE_URL || process.env.SUPABASE_URL || "";
  const supabaseServiceKey = process.env.SUPABASE_SERVICE_ROLE_KEY || "";

  if (!supabaseUrl || !supabaseServiceKey) {
    return new Response(
      JSON.stringify({ error: "Supabase Service Role Key não configurada no servidor." }),
      {
        status: 500,
        headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
      }
    );
  }

  try {
    const supabaseAdmin = createClient(supabaseUrl, supabaseServiceKey, {
      auth: { persistSession: false, autoRefreshToken: false },
    });

    const targetBucket = 'patient_files';

    // 1. Garantir que o bucket exista
    const { data: buckets } = await supabaseAdmin.storage.listBuckets();
    const bucketExists = Array.isArray(buckets) && buckets.some(b => b.name === targetBucket || b.id === targetBucket);
    if (!bucketExists) {
      await supabaseAdmin.storage.createBucket(targetBucket, {
        public: true,
        fileSizeLimit: 52428800, // 50MB
      });
    }

    const contentType = req.headers.get("content-type") || "";
    let filePath = "";
    let filename = "foto.jpg";
    let patientId = "paciente_anonimo";
    let fileBuffer: ArrayBuffer;
    let fileType = "application/octet-stream";

    if (contentType.includes("multipart/form-data")) {
      const formData = await req.formData();
      const file = formData.get("file") as File | null;
      filePath = (formData.get("filePath") as string) || "";
      filename = (formData.get("filename") as string) || (file?.name || "foto.jpg");
      patientId = (formData.get("patientId") as string) || "paciente_anonimo";
      const subfolder = (formData.get("subfolder") as string) || "";

      if (!file) {
        return new Response(JSON.stringify({ error: "Arquivo ausente no FormData" }), {
          status: 400,
          headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
        });
      }

      if (!filePath) {
        const cleanPatient = patientId.replace(/[^a-zA-Z0-9 _-]/g, '').trim().replace(/\s+/g, '_');
        const cleanSub = subfolder ? `${subfolder.replace(/^\/|\/$/g, '')}/` : '';
        const cleanName = filename.normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, '_').replace(/[^a-zA-Z0-9_\-.]/g, '');
        filePath = `clinic-master/${cleanPatient}/${cleanSub}${cleanName}`;
      }

      fileBuffer = await file.arrayBuffer();
      fileType = file.type || "image/jpeg";
    } else {
      // Suporte a JSON com base64
      const body = await req.json();
      filePath = body.filePath || "";
      filename = body.filename || "foto.jpg";
      patientId = body.patientId || "paciente_anonimo";
      fileType = body.contentType || "image/jpeg";
      const base64Data = body.base64?.replace(/^data:.*?;base64,/, "");

      if (!base64Data || !filePath) {
        return new Response(JSON.stringify({ error: "filePath ou base64 ausente" }), {
          status: 400,
          headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
        });
      }

      const binaryStr = atob(base64Data);
      const len = binaryStr.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) {
        bytes[i] = binaryStr.charCodeAt(i);
      }
      fileBuffer = bytes.buffer;
    }

    // 2. Upload via Supabase Admin (bypassa RLS)
    const { data, error } = await supabaseAdmin.storage
      .from(targetBucket)
      .upload(filePath, fileBuffer, {
        contentType: fileType,
        upsert: true,
      });

    if (error) {
      console.error("Erro no upload do storage via admin:", error);
      return new Response(JSON.stringify({ error: error.message }), {
        status: 500,
        headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
      });
    }

    // 3. Gerar URL pública
    const { data: publicData } = supabaseAdmin.storage.from(targetBucket).getPublicUrl(filePath);
    const publicUrl = publicData?.publicUrl || null;

    // 4. Sincronizar na galeria do paciente no CRM se for imagem
    const isImage = fileType.startsWith("image/") || filename.match(/\.(jpe?g|png|webp|gif|bmp)$/i);
    if (isImage && patientId && patientId !== "paciente_anonimo" && publicUrl) {
      try {
        const { data: clinicRecords } = await supabaseAdmin
          .from('clinic_data')
          .select('id, user_id, crm_data')
          .limit(5);

        if (Array.isArray(clinicRecords)) {
          for (const clinicRow of clinicRecords) {
            const crm = clinicRow.crm_data;
            if (crm && Array.isArray(crm.patients)) {
              if (!Array.isArray(crm.galeria)) crm.galeria = [];
              const exists = crm.galeria.some((g: any) => g.url === publicUrl || g.id === filePath);
              if (!exists) {
                crm.galeria.push({
                  id: `gal_${Date.now()}_${Math.floor(Math.random() * 10000)}`,
                  patientId: patientId,
                  url: publicUrl,
                  description: filename,
                  date: new Date().toISOString()
                });
                await supabaseAdmin
                  .from('clinic_data')
                  .update({ crm_data: crm, updated_at: new Date().toISOString() })
                  .eq('id', clinicRow.id);
              }
            }
          }
        }
      } catch (galErr) {
        console.warn("Aviso ao vincular foto no CRM clinic_data:", galErr);
      }
    }

    return new Response(
      JSON.stringify({
        success: true,
        path: filePath,
        url: publicUrl,
      }),
      {
        status: 200,
        headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
      }
    );
  } catch (err: any) {
    console.error("Exceção em /api/storage-upload:", err);
    return new Response(JSON.stringify({ error: err.message || String(err) }), {
      status: 500,
      headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
    });
  }
}

export const config = { runtime: 'edge' };
import { GoogleGenAI } from "@google/genai";

const FALLBACK_MODELS = [
  process.env.GEMINI_MODEL || "gemini-3-flash-preview",
  "gemini-flash-latest",
  "gemini-3.5-flash"
];

async function generateWithFallback(ai: GoogleGenAI, payload: any) {
  let lastError: any = null;
  for (const model of FALLBACK_MODELS) {
    try {
      const response = await ai.models.generateContent({
        ...payload,
        model
      });
      return response;
    } catch (err: any) {
      lastError = err;
      console.warn(`[Gemini Fallback] Modelo ${model} falhou:`, err?.message || err);
      if (err?.status === 401 || err?.status === 403) throw err;
    }
  }
  throw lastError;
}

export default async (req: Request) => {
  // CORS Preflight
  if (req.method === "OPTIONS") {
    return new Response(null, {
      status: 204,
      headers: {
        "Access-Control-Allow-Origin": "*",
        "Access-Control-Allow-Headers": "Content-Type",
        "Access-Control-Allow-Methods": "POST, OPTIONS",
      },
    });
  }

  if (req.method !== "POST") {
    return new Response(JSON.stringify({ error: "Method Not Allowed" }), {
      status: 405,
      headers: {
        "Content-Type": "application/json",
        "Access-Control-Allow-Origin": "*",
      },
    });
  }

  try {
    const { procedure } = await req.json();
    if (!procedure || typeof procedure !== 'string' || !procedure.trim() || procedure.length > 1000) {
      return new Response(JSON.stringify({ error: "Procedimento não informado." }), {
        status: 400,
        headers: {
          "Content-Type": "application/json",
          "Access-Control-Allow-Origin": "*",
        },
      });
    }

    const apiKey = process.env.GEMINI_API_KEY;
    if (!apiKey) {
      return new Response(JSON.stringify({ error: "Chave da API Gemini não configurada no servidor." }), {
        status: 500,
        headers: {
          "Content-Type": "application/json",
          "Access-Control-Allow-Origin": "*",
        },
      });
    }

    const ai = new GoogleGenAI({
      apiKey: apiKey,
      httpOptions: {
        headers: {
          'User-Agent': 'aistudio-build',
        }
      }
    });

    const prompt = `Você é um dentista experiente. O usuário vai descrever o procedimento odontológico realizado e você deve sugerir automaticamente a prescrição e instruções (posologia) para o receituário do paciente.
Por favor, liste as medicações (ex: 1. Amoxicilina 500mg - Tomar 1 cp a cada 8h por 7 dias) e em seguida as recomendações principais relacionadas ao procedimento.
Responda sempre em português, em um formato claro, para o paciente ler diretamente.
Não inclua nenhuma introdução nem saudação ("Olá, aqui está..."), responda apenas com as prescrições médicas formatadas.
Não use markdown complexo, pode usar números ou traços.

Procedimento realizado: ${procedure}`;

    const response = await generateWithFallback(ai, {
      contents: prompt,
      config: {
        temperature: 0.2,
      }
    });

    return new Response(JSON.stringify({ suggestion: response.text }), {
      status: 200,
      headers: {
        "Content-Type": "application/json",
        "Access-Control-Allow-Origin": "*",
      },
    });

  } catch (err: any) {
    console.error("Erro na geração de receita via Gemini:", err);
    return new Response(JSON.stringify({ error: "Falha na comunicação com o assistente de IA.", details: err?.message || String(err) }), {
      status: 500,
      headers: {
        "Content-Type": "application/json",
        "Access-Control-Allow-Origin": "*",
      },
    });
  }
};

export const config = { runtime: 'edge' };

export default async function handler(req: Request) {
  const verify_token = process.env.WHATSAPP_VERIFY_TOKEN || "senha_secreta_webhook_123";
  const url = new URL(req.url);

  // Verificação de Webhook (GET)
  if (req.method === "GET") {
    const mode = url.searchParams.get("hub.mode");
    const token = url.searchParams.get("hub.verify_token");
    const challenge = url.searchParams.get("hub.challenge");

    if (mode === "subscribe" && token === verify_token) {
      console.log("WEBHOOK_VERIFIED");
      return new Response(challenge || "", { status: 200 });
    } else {
      return new Response("Forbidden", { status: 403 });
    }
  }

  // Recebimento de mensagens (POST)
  if (req.method === "POST") {
    try {
      const body = await req.json();
      if (body.object) {
        if (
          body.entry &&
          body.entry[0].changes &&
          body.entry[0].changes[0].value.messages &&
          body.entry[0].changes[0].value.messages[0]
        ) {
          const message = body.entry[0].changes[0].value.messages[0];
          console.log("Nova mensagem no WhatsApp:", JSON.stringify(message, null, 2));
        }
        return new Response("EVENT_RECEIVED", { status: 200 });
      } else {
        return new Response("Not Found", { status: 404 });
      }
    } catch (e) {
      return new Response("Bad Request", { status: 400 });
    }
  }

  return new Response("Method Not Allowed", { status: 405 });
}

