// ─── Main App ─────────────────────────────────────────────────────────────────
export default function App() {
  // --- AUTH STATE ---
  const [needsAuth, setNeedsAuth] = useState(true);
  const [isLoggingIn, setIsLoggingIn] = useState(false);
  const [user, setUser] = useState<User | null>(null);

  // --- URL PARAMS ---
  const getQueryParam = (name: string) => {
    if (typeof window === 'undefined') return null;
    const searchParams = new URLSearchParams(window.location.search);
    if (searchParams.has(name)) return searchParams.get(name);
    
    const hash = window.location.hash;
    const qIndex = hash.indexOf('?');
    if (qIndex !== -1) {
      const hashParams = new URLSearchParams(hash.substring(qIndex));
      if (hashParams.has(name)) return hashParams.get(name);
    }
    return null;
  };
  const urlMode = getQueryParam('mode');

  // --- SPA ROUTING HELPERS ---
  const getInitialRoute = () => {
    if (typeof window === 'undefined') return { view: 'dashboard' as AppView, tab: 'registration' };
    const pathname = window.location.pathname;
    const segments = pathname.split('/').filter(Boolean);
    const primaryView = segments[0] as AppView;
    const validViews: AppView[] = ['dashboard', 'calendar', 'crm', 'settings', 'financeiro', 'ai-inspector'];
    
    if (validViews.includes(primaryView)) {
      let tab = 'registration';
      if (primaryView === 'crm' && segments[1]) {
        const validTabs = ['registration', 'editor', 'negotiation', 'documents'];
        if (validTabs.includes(segments[1])) {
          tab = segments[1];
        }
      }
      return { view: primaryView, tab };
    }
    return { view: 'dashboard' as AppView, tab: 'registration' };
  };

  const initialRoute = getInitialRoute();

  // --- APP STATE ---
  const [procedures, setProcedures] = useState<Procedure[]>(() => {
    const cached = localStorage.getItem('agnaldo_dent_procedures');
    return cached ? JSON.parse(cached) : DEFAULT_PROCEDURES;
  });
  const [showProcedureManager, setShowProcedureManager] = useState(false);

  const [clinicSettings, setClinicSettings] = useState<ClinicSettings>(() => {
    const cached = localStorage.getItem('agnaldo_dent_clinic_settings');
    return cached ? JSON.parse(cached) : DEFAULT_CLINIC_SETTINGS;
  });

  const [activeTab, setActiveTab] = useState<'registration' | 'editor' | 'negotiation' | 'documents'>(initialRoute.tab as any);
  const [showPatientsModal, setShowPatientsModal] = useState(false);
  const [currentAppView, setCurrentAppView] = useState<AppView>(initialRoute.view);
  const [appointmentPatientName, setAppointmentPatientName] = useState<string | undefined>();
  const [initialNewPatientData, setInitialNewPatientData] = useState<{name: string, phone: string, email: string} | undefined>();
  const [crmPatientName, setCrmPatientName] = useState<string | undefined>();
  const [currentTheme, setCurrentTheme] = useState(() => {
    const saved = localStorage.getItem('agnaldo_dent_theme') || 'padrao';
    if (saved === 'bordo-escuro') return 'bordo-nobre';
    if (saved === 'preto-ouro') return 'bege-real';
    if (saved === 'azul-noturno') return 'bordo-imperial';
    return saved;
  });
  const [currentFileId, setCurrentFileId] = useState<string | null>(null);

  const { activeSections: sections, setActiveSections: setSections, activeProposal: proposal, setActiveProposal: setProposal, selectedPatient } = usePatientContext();


  // Sidebar state
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [mobileSidebarOpen, setMobileSidebarOpen] = useState(false);

  const [isMobileOptimized, setIsMobileOptimized] = useState(() => {
    if (typeof window !== 'undefined') {
      const stored = localStorage.getItem('agnaldo_dent_mobile_opt');
      if (stored) return stored === 'true';
      return window.innerWidth < 1024;
    }
    return false;
  });

  const [isAutosaving] = useState(false);

  // --- EFFECTS ---
  useEffect(() => {
    initAiRuntimeTelemetry();
    const unsubscribe = initAuth(
      (usr) => { setUser(usr); setNeedsAuth(false); },
      () => setNeedsAuth(true)
    );
    return () => unsubscribe();
  }, []);

  useEffect(() => { localStorage.setItem('agnaldo_dent_procedures', JSON.stringify(procedures)); }, [procedures]);
  // sections and proposal are now managed globally via PatientContext

  useEffect(() => { localStorage.setItem('agnaldo_dent_clinic_settings', JSON.stringify(clinicSettings)); }, [clinicSettings]);
  useEffect(() => { localStorage.setItem('agnaldo_dent_mobile_opt', isMobileOptimized.toString()); }, [isMobileOptimized]);
  useEffect(() => {
    localStorage.setItem('agnaldo_dent_theme', currentTheme);
    document.body.className = currentTheme === 'padrao' ? '' : `theme-${currentTheme}`;
  }, [currentTheme]);


  // Sincronizar estado do app com a URL
  useEffect(() => {
    if (typeof window === 'undefined') return;

    let targetPath = `/${currentAppView}`;
    if (currentAppView === 'crm') {
      targetPath += `/${activeTab}`;
    }

    const currentPath = window.location.pathname;
    const search = window.location.search;
    const hash = window.location.hash;
    const targetUrl = `${targetPath}${search}${hash}`;

    if (currentPath !== targetPath) {
      window.history.pushState({ view: currentAppView, tab: activeTab }, '', targetUrl);
    }
  }, [currentAppView, activeTab]);

  // Escutar eventos de voltar/avançar no navegador (popstate)
  useEffect(() => {
    if (typeof window === 'undefined') return;

    const handlePopState = (event: PopStateEvent) => {
      if (event.state && event.state.view) {
        setCurrentAppView(event.state.view);
        if (event.state.tab) {
          setActiveTab(event.state.tab);
        }
      } else {
        const route = getInitialRoute();
        setCurrentAppView(route.view);
        setActiveTab(route.tab as any);
      }
    };

    window.addEventListener('popstate', handlePopState);

    // Salvar estado inicial no histórico para que popstate funcione corretamente desde a primeira rota
    let initialPath = `/${currentAppView}`;
    if (currentAppView === 'crm') {
      initialPath += `/${activeTab}`;
    }
    const search = window.location.search;
    const hash = window.location.hash;
    window.history.replaceState({ view: currentAppView, tab: activeTab }, '', `${initialPath}${search}${hash}`);

    return () => {
      window.removeEventListener('popstate', handlePopState);
    };
  }, []);

  // --- ACTIONS ---
  const handleLogin = async () => {
    setIsLoggingIn(true);
    try {
      const result = await googleSignIn();
      if (result) { setUser(result.user); setNeedsAuth(false); }
    } catch (err: any) {
      if (err?.code !== 'auth/popup-closed-by-user') console.error('Login failed:', err);
    } finally {
      setIsLoggingIn(false);
    }
  };

  const handleLogout = async () => {
    try { await logout(); setNeedsAuth(true); setUser(null); }
    catch (err) { console.error('Logout failed:', err); }
  };

  const handleUpdateSection = (updated: PhotoSection) => {
    setSections((prev) => prev.map((s) => (s.id === updated.id ? updated : s)));
  };

  const handleResetProcedures = () => {
    if (confirm('Deseja restaurar a tabela de termos e valores para as definições originais do sistema?')) {
      setProcedures(DEFAULT_PROCEDURES);
    }
  };

  const handleResetAll = () => {
    setSections(INITIAL_SECTIONS);
    setProposal(INITIAL_PROPOSAL);
    setCurrentFileId(null);
    setActiveTab('editor');
  };

  const handleNewProposalForPatient = (patientName: string) => {
    setSections(INITIAL_SECTIONS);
    setProposal({ ...INITIAL_PROPOSAL, patientName });
    setCurrentFileId('NEW_FILE');
    setCrmPatientName(patientName);
    setCurrentAppView('crm');
    setActiveTab('registration');
    setShowPatientsModal(false);
  };

  const handleLoadPatientData = (data: any) => {
    if (data.procedures) setProcedures(data.procedures);
    if (data.sections) {
      const merged = INITIAL_SECTIONS.map((initSec) => {
        const existing = data.sections.find((s: PhotoSection) => s.id === initSec.id);
        return existing || initSec;
      });
      setSections(merged);
    }
    if (data.proposal) {
      setProposal(data.proposal);
      if (data.proposal.patientName) {
        setCrmPatientName(data.proposal.patientName);
      }
    }
    if (data.__fileId) setCurrentFileId(data.__fileId);
    if (data.selectedPlanIndex !== undefined) {
      localStorage.setItem('ag_neg_selected_plan', data.selectedPlanIndex.toString());
    }
    setCurrentAppView('crm');
    setActiveTab('editor');
    setShowPatientsModal(false);
  };

  const handleLoadSamplePlan = () => {
    setProcedures(DEFAULT_PROCEDURES);
    setProposal({
      patientName: 'VALDERMON DA SILVA LOPES',
      notes: 'Orçamento feito sem radiografia atual pós trat. de canal, podendo haver alterações posteriores.',
      discountPercent: 5,
      pixDiscountLabel: '5% DESCONTO NO PIX',
      installments: 12,
      installmentsLabel: 'Parcelamento em até 12x (com taxas).',
      customDiscountAmount: 0,
      showTotalBySection: true,
      markerSize: 26,
    });
    const mockSections: PhotoSection[] = [
      { id: 'upper', title: 'Arcada Superior', subtitle: 'Dentes Posteriores e Anteriores Superiores', image: DEMO_SVG_PLACEHOLDERS.upper, markers: [
        { id: 'upper-14', toothNumber: 14, x: 50.5, y: 25.5, procedures: ['p2'] },
        { id: 'upper-15', toothNumber: 15, x: 53.5, y: 35.5, procedures: ['p2'] },
        { id: 'upper-16', toothNumber: 16, x: 54.8, y: 46.5, procedures: ['p4'] },
        { id: 'upper-17', toothNumber: 17, x: 58.5, y: 56.5, procedures: ['p5'] },
        { id: 'upper-24', toothNumber: 24, x: 30.2, y: 26.5, procedures: ['p2'] },
        { id: 'upper-26', toothNumber: 26, x: 23.5, y: 52.5, procedures: ['p5'] },
      ]},
      { id: 'lower', title: 'Arcada Inferior', subtitle: 'Dentes Posteriores e Anteriores Inferiores', image: DEMO_SVG_PLACEHOLDERS.lower, markers: [
        { id: 'lower-47', toothNumber: 47, x: 34.5, y: 28.5, procedures: ['p1'] },
        { id: 'lower-45', toothNumber: 45, x: 41.5, y: 42.5, procedures: ['p2'] },
        { id: 'lower-44', toothNumber: 44, x: 43.5, y: 49.5, procedures: ['p4'] },
        { id: 'lower-34', toothNumber: 34, x: 58.5, y: 49.5, procedures: ['p5'] },
        { id: 'lower-35', toothNumber: 35, x: 60.5, y: 42.5, procedures: ['p5'] },
        { id: 'lower-37', toothNumber: 37, x: 64.5, y: 28.5, procedures: ['p5'] },
      ]},
      { id: 'smile', title: 'Estética do Sorriso', subtitle: 'Mapeamento de Dentes Anteriores e Estética', image: DEMO_SVG_PLACEHOLDERS.smile, markers: [
        { id: 'smile-12', toothNumber: 12, x: 27.2, y: 26.5, procedures: ['p1'] },
        { id: 'smile-11', toothNumber: 11, x: 32.5, y: 27.0, procedures: ['p1'] },
        { id: 'smile-21', toothNumber: 21, x: 37.2, y: 27.0, procedures: ['p1'] },
        { id: 'smile-22', toothNumber: 22, x: 42.0, y: 26.5, procedures: ['p1'] },
        { id: 'smile-23', toothNumber: 23, x: 45.8, y: 26.0, procedures: ['p1', 'p5'] },
        { id: 'smile-43', toothNumber: 43, x: 27.2, y: 32.5, procedures: ['p1'] },
        { id: 'smile-42', toothNumber: 42, x: 30.5, y: 32.5, procedures: ['p1'] },
        { id: 'smile-41', toothNumber: 41, x: 34.5, y: 32.5, procedures: ['p1'] },
        { id: 'smile-31', toothNumber: 31, x: 38.5, y: 32.5, procedures: ['p1'] },
      ]},
    ];
    setSections(mockSections);
    setActiveTab('negotiation');
  };

  const hasAnyMarkers = sections.some((s) => s.markers.length > 0);

  // --- RENDER: Special URL modes ---
  if (urlMode === 'patient_mapping' || urlMode === 'patient') {
    return <PatientScreen hideSimulation={false} />;
  }

  if (urlMode === 'anamnese') {
    return <PatientAnamnesisForm />;
  }


  // --- RENDER: Login Screen ---
  if (needsAuth) {
    return (
      <LoginScreen
        onLogin={handleLogin}
        isLoggingIn={isLoggingIn}
        onEnterAiSandbox={() => {
          enableAiSandboxMode();
          setNeedsAuth(false);
          setCurrentAppView('ai-inspector');
        }}
      />
    );
  }

  // --- RENDER: Mobile-optimized workspace ---
  if (isMobileOptimized && currentAppView !== 'ai-inspector') {
    return (
      <div className="app-shell">
        <Sidebar
          currentView={currentAppView}
          onChangeView={setCurrentAppView}
          onLogout={handleLogout}
          clinicSettings={clinicSettings}
          collapsed={false}
          onToggleCollapse={() => {}}
          mobileOpen={mobileSidebarOpen}
          onCloseMobile={() => setMobileSidebarOpen(false)}
        />
        <div className="main-content">
          <TopBar
            currentView={currentAppView}
            proposal={proposal}
            selectedPatient={selectedPatient}
            sections={sections}
            currentFileId={currentFileId}
            onChangeView={setCurrentAppView}
            onOpenMobileMenu={() => setMobileSidebarOpen(true)}
            isMobileOptimized={isMobileOptimized}
            setIsMobileOptimized={setIsMobileOptimized}
          />
          <main className="flex-1 mx-auto w-full max-w-md px-2 py-4">
            <MobileWorkspace
              sections={sections}
              onUpdateSection={handleUpdateSection}
              procedures={procedures}
              proposal={proposal}
              setProposal={setProposal}
              clinicSettings={clinicSettings}
              onExitMobile={() => setIsMobileOptimized(false)}
              onNewProposalForPatient={handleNewProposalForPatient}
            />
          </main>
        </div>
      </div>
    );
  }

  // --- RENDER: Main Desktop App ---
  return (
    <>
      {showProcedureManager && (
        <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-md flex items-center justify-center p-4">
          <div className="w-full max-w-4xl h-[80vh] flex flex-col bg-white rounded-xl shadow-2xl overflow-hidden">
            <ProcedureManager
              procedures={procedures}
              setProcedures={setProcedures}
              onResetProcedures={() => setProcedures(DEFAULT_PROCEDURES)}
              onClose={() => setShowProcedureManager(false)}
            />
          </div>
        </div>
      )}
      <div className="app-shell">
      <Sidebar
        currentView={currentAppView}
        onChangeView={setCurrentAppView}
        onLogout={handleLogout}
        clinicSettings={clinicSettings}
        collapsed={sidebarCollapsed}
        onToggleCollapse={() => setSidebarCollapsed(!sidebarCollapsed)}
        mobileOpen={mobileSidebarOpen}
        onCloseMobile={() => setMobileSidebarOpen(false)}
      />

      <div className={`main-content ${sidebarCollapsed ? 'sidebar-collapsed' : ''}`}>
        <TopBar
          currentView={currentAppView}
          proposal={proposal}
          selectedPatient={selectedPatient}
          sections={sections}
          currentFileId={currentFileId}
          onChangeView={setCurrentAppView}
          onOpenMobileMenu={() => setMobileSidebarOpen(true)}
          isMobileOptimized={isMobileOptimized}
          setIsMobileOptimized={setIsMobileOptimized}
        />

        {/* ── Dashboard ───────────────────────────────────────── */}
        {currentAppView === 'dashboard' && (
          <main className="flex-1 px-5 py-6 lg:px-8 lg:py-8 max-w-7xl w-full mx-auto animate-fade-in-up">
            <DashboardView
              clinicSettings={clinicSettings}
              proposal={proposal}
              onNavigateToPlanning={(patientName, status) => {
                if (patientName) {
                  setProposal((prev) => ({ ...prev, patientName, status: (status || 'Em Andamento') as any }));
                  setCrmPatientName(patientName);
                }
                setCurrentAppView('crm');
              }}
              onOpenPatient={(patientName) => {
                setCrmPatientName(patientName);
                setCurrentAppView('crm');
              }}
              onOpenRegistry={() => { 
                setCurrentAppView('crm'); 
              }}
              onOpenPatientsList={() => { setCurrentAppView('crm'); }}
              onOpenCalendar={() => setCurrentAppView('calendar')}
              isMobileOptimized={isMobileOptimized}
              setIsMobileOptimized={setIsMobileOptimized}
            />
          </main>
        )}

        {/* ── Financeiro ───────────────────────────────────────── */}
        {currentAppView === 'financeiro' && (
          <main className="flex-1 px-5 py-6 lg:px-8 lg:py-8 w-full animate-fade-in-up">
            <FinancialView onOpenPatient={(patientName) => {
              setCrmPatientName(patientName);
              setCurrentAppView('crm');
            }} />
          </main>
        )}

        {/* ── CRM ─────────────────────────────────────────────── */}
        {currentAppView === 'crm' && (
          <main className="flex-1 px-5 py-6 lg:px-8 lg:py-8 w-full animate-fade-in-up">
            <DentalCRMView
              onLoadPatientData={handleLoadPatientData}
              onNewProposal={handleNewProposalForPatient}
              onChangeView={setCurrentAppView}
              clinicSettings={clinicSettings}
              setClinicSettings={setClinicSettings}
              initialPatientName={crmPatientName}
              onClearInitialPatient={() => setCrmPatientName(undefined)}
              initialNewPatientData={initialNewPatientData}
              onClearInitialNewPatientData={() => setInitialNewPatientData(undefined)}
              onNewAppointment={(patientName) => {
                setAppointmentPatientName(patientName);
                setCurrentAppView('calendar');
              }}
              procedures={procedures}
              setProcedures={setProcedures}
              currentFileId={currentFileId}
              setCurrentFileId={setCurrentFileId}
            />
          </main>
        )}

        {/* ── Calendar ─────────────────────────────────────────── */}
        {currentAppView === 'calendar' && (
          <main className="flex-1 px-5 py-6 lg:px-8 lg:py-8 w-full h-[calc(100vh-60px)] animate-fade-in-up">
            <CalendarView
              onNewPatient={(name, phone, email) => {
                setInitialNewPatientData({ name: name || '', phone: phone || '', email: email || '' });
                handleResetAll();
                setCurrentAppView('crm');
              }}
              initialPatientName={appointmentPatientName}
              onClearInitialPatient={() => setAppointmentPatientName(undefined)}
            />
          </main>
        )}

        {/* ── Settings ────────────────────────────────────────── */}
        {currentAppView === 'settings' && (
          <main className="flex-1 px-5 py-6 lg:px-8 lg:py-8 max-w-7xl w-full mx-auto animate-fade-in-up">
            <SettingsView
              currentTheme={currentTheme}
              onChangeTheme={setCurrentTheme}
              clinicSettings={clinicSettings}
            />
          </main>
        )}

        {/* ── AI Inspector & Sandbox Hub ───────────────────────── */}
        {currentAppView === 'ai-inspector' && (
          <main className="flex-1 px-5 py-6 lg:px-8 lg:py-8 max-w-7xl w-full mx-auto animate-fade-in-up">
            <AIInspectorView
              onNavigateView={(view, crmTab) => {
                setCurrentAppView(view);
                if (crmTab) {
                  setActiveTab(crmTab);
                }
              }}
            />
          </main>
        )}


        {/* Footer */}
        <footer className="bg-white border-t border-[#E6DEC9] py-4 px-6 print:hidden mt-auto">
          <div className="flex items-center justify-between max-w-7xl mx-auto">
            <div className="flex items-center gap-2">
              <AFLogoSVG className="w-6 h-6" />
              <div>
                <p className="text-[11px] font-bold text-[#8B0000] tracking-wider uppercase" style={{ fontFamily: 'Playfair Display, serif' }}>
                  Dr. Agnaldo Ferreira
                </p>
                <p className="text-[9px] text-zinc-400 font-mono tracking-widest">
                  ODONTOLOGIA RESTAURADORA
                </p>
              </div>
            </div>
            <p className="text-[10px] text-zinc-400">
              {new Date().toLocaleDateString('pt-BR', { year: 'numeric', month: 'long', day: 'numeric' })}
            </p>
          </div>
        </footer>
      </div>

      {showPatientsModal && (
        <PatientsModal
          onClose={() => setShowPatientsModal(false)}
          onLoadPatient={handleLoadPatientData}
          onNewProposal={handleNewProposalForPatient}
          clinicSettings={clinicSettings}
          onNewAppointment={(patientName) => {
            setShowPatientsModal(false);
            setAppointmentPatientName(patientName);
            setCurrentAppView('calendar');
          }}
        />
      )}
    </div>
    </>
  );
}

import React, { useState, useEffect } from 'react';
import { Phone, MessageCircle, Loader2, Zap } from 'lucide-react';

interface AIAssistedWhatsAppProps {
  patientName: string;
  patientPhone: string;
}

export function AIAssistedWhatsApp({ patientName, patientPhone }: AIAssistedWhatsAppProps) {
  const [whatsappNumber, setWhatsappNumber] = useState(patientPhone || '');
  const [whatsappMessage, setWhatsappMessage] = useState('');
  const [selectedTemplate, setSelectedTemplate] = useState('lembrete');
  const [isGeneratingMessage, setIsGeneratingMessage] = useState(false);

  useEffect(() => {
    if (patientPhone) setWhatsappNumber(patientPhone);
  }, [patientPhone]);

  useEffect(() => {
    let base = `Olá ${patientName.split(' ')[0]}, tudo bem? Aqui é do consultório do Dr. Agnaldo. `;
    if (selectedTemplate === 'lembrete') {
      setWhatsappMessage(base + `Passando para lembrar da sua consulta amanhã. Podemos confirmar?`);
    } else if (selectedTemplate === 'aniversario') {
      setWhatsappMessage(`Parabéns ${patientName.split(' ')[0]}! 🎉 Que o seu dia seja cheio de sorrisos. Um abraço de toda a equipe do Dr. Agnaldo!`);
    } else if (selectedTemplate === 'profilaxia') {
      setWhatsappMessage(base + `Já faz um tempinho desde sua última limpeza (profilaxia). Que tal agendarmos uma revisão para manter seu sorriso sempre saudável?`);
    } else if (selectedTemplate === 'feriado') {
      setWhatsappMessage(base + `Desejamos a você e sua família excelentes festas e um próspero ano novo! ✨`);
    }
  }, [selectedTemplate, patientName]);

  const handleGenerateMessageWithAI = async () => {
    try {
      setIsGeneratingMessage(true);
      const response = await fetch('/api/ai/recall', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          patientName: patientName,
          doctorName: 'Dr. Agnaldo',
          lastProcedure: 'Avaliação/Profilaxia',
          lastVisitDate: 'há 6 meses'
        })
      });
      if (response.ok) {
        const data = await response.json();
        if (data.message) {
          setWhatsappMessage(data.message);
        }
      } else {
        alert("Erro na API da IA. Verifique as configurações de chave no backend.");
      }
    } catch (err: any) {
      alert("Falha ao contatar servidor de IA: " + err.message);
    } finally {
      setIsGeneratingMessage(false);
    }
  };

  const handleSend = () => {
    const cleanNumber = whatsappNumber.replace(/\D/g, '');
    const finalNum = (cleanNumber.length === 10 || cleanNumber.length === 11) ? '55' + cleanNumber : cleanNumber;
    const encodedMessage = encodeURIComponent(whatsappMessage);
    const url = finalNum ? `https://wa.me/${finalNum}?text=${encodedMessage}` : `https://wa.me/?text=${encodedMessage}`;
    window.open(url, '_blank');
  };

  return (
    <div className="bg-white border rounded-xl p-5 border-[#E6DEC9] shadow-2xs space-y-5">
      <div className="border-b border-zinc-100 pb-3">
        <span className="text-[10px] uppercase font-bold text-amber-800 tracking-wider font-mono">COMUNICAÇÃO E WHATSAPP</span>
        <h4 className="font-serif font-bold text-lg text-[#8B0000]">Envio Rápido de Mensagens</h4>
        <p className="text-xs text-zinc-500 mt-1">Utilize a Inteligência Artificial para redigir lembretes amigáveis ou use os templates rápidos abaixo.</p>
      </div>

      <div className="flex gap-2 flex-wrap">
        <button
          type="button"
          onClick={() => setSelectedTemplate('lembrete')}
          className={`px-3 py-1.5 rounded-xl border text-[10px] font-bold transition-all cursor-pointer ${
            selectedTemplate === 'lembrete'
              ? 'bg-[#8B0000] text-white border-[#8B0000]'
              : 'bg-white text-zinc-600 border-zinc-200 hover:bg-zinc-50'
          }`}
        >
          📅 Lembrete de Consulta
        </button>
        <button
          type="button"
          onClick={() => setSelectedTemplate('aniversario')}
          className={`px-3 py-1.5 rounded-xl border text-[10px] font-bold transition-all cursor-pointer ${
            selectedTemplate === 'aniversario'
              ? 'bg-amber-600 text-white border-amber-600'
              : 'bg-white text-zinc-600 border-zinc-200 hover:bg-zinc-50'
          }`}
        >
          🎂 Parabéns/Aniversário
        </button>
        <button
          type="button"
          onClick={() => setSelectedTemplate('profilaxia')}
          className={`px-3 py-1.5 rounded-xl border text-[10px] font-bold transition-all cursor-pointer ${
            selectedTemplate === 'profilaxia'
              ? 'bg-emerald-600 text-white border-emerald-600'
              : 'bg-white text-zinc-600 border-zinc-200 hover:bg-zinc-50'
          }`}
        >
          🦷 Lembrete de Profilaxia (6 meses)
        </button>
      </div>

      <div className="grid grid-cols-1 gap-4">
        <div className="space-y-1.5">
          <label className="text-xs font-bold text-zinc-500 uppercase">Número do Celular</label>
          <div className="relative">
            <Phone className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-400" />
            <input
              type="text"
              placeholder="Ex: 5511999999999"
              value={whatsappNumber}
              onChange={(e) => setWhatsappNumber(e.target.value)}
              className="w-full pl-9 pr-3 py-2 rounded-xl border border-zinc-300 focus:border-green-500 focus:ring focus:ring-green-500/20 text-xs"
            />
          </div>
        </div>
      </div>

      <div className="space-y-1.5">
        <label className="text-xs font-bold text-zinc-500 uppercase">Mensagem</label>
        <textarea
          value={whatsappMessage}
          onChange={(e) => setWhatsappMessage(e.target.value)}
          className="w-full p-3 rounded-xl border border-zinc-300 focus:border-green-500 focus:ring focus:ring-green-500/20 text-xs min-h-[100px] resize-y"
        />
      </div>

      <div className="flex justify-between items-center flex-wrap gap-3">
        <button
          type="button"
          onClick={handleGenerateMessageWithAI}
          disabled={isGeneratingMessage}
          className="w-full sm:w-auto px-6 py-2.5 bg-teal-600 text-white font-bold rounded-xl hover:bg-teal-700 transition-colors flex items-center justify-center gap-2 cursor-pointer text-xs disabled:opacity-50 shadow-sm"
        >
          {isGeneratingMessage ? <Loader2 className="w-4 h-4 animate-spin" /> : <Zap className="w-4 h-4" />}
          ✨ Gerar Mensagem de Retorno com IA
        </button>

        <button
          type="button"
          onClick={handleSend}
          className="w-full sm:w-auto px-6 py-2.5 bg-green-600 text-white font-bold rounded-xl hover:bg-green-700 transition-colors flex items-center justify-center gap-2 cursor-pointer text-xs shadow-sm"
        >
          <MessageCircle className="w-4 h-4" />
          Enviar via WhatsApp Web
        </button>
      </div>
    </div>
  );
}

import React, { useEffect, useState, useMemo } from 'react';
import {
  Terminal,
  FileCode,
  Bug,
  Layers,
  Copy,
  Check,
  ExternalLink,
  RefreshCw,
  Search,
  ShieldCheck,
  AlertTriangle,
  Database,
  Play,
  Sparkles,
  Download,
  Trash2,
  FolderTree,
  ArrowRight,
  Activity,
} from 'lucide-react';
import {
  getAiRuntimeLogs,
  clearAiRuntimeLogs,
  subscribeAiRuntimeLogs,
  getStaticAuditFindings,
  resetAiSandboxData,
  getAiSandboxCRMDatabase,
  isAiSandboxMode,
  enableAiSandboxMode,
  type AIRuntimeLogEntry,
} from '../lib/aiSandbox';

interface AIContextFile {
  path: string;
  category: string;
  lines: number;
  sizeBytes: number;
  content: string;
}

interface AIContextManifest {
  generatedAt: string;
  projectUrl: string;
  totalFiles: number;
  totalLines: number;
  techStack: string[];
  routes: { path: string; view: string; description: string }[];
  apiEndpoints: { method: string; path: string; description: string }[];
  files: AIContextFile[];
}

interface AIInspectorViewProps {
  onNavigateView?: (view: 'dashboard' | 'calendar' | 'crm' | 'settings' | 'financeiro' | 'ai-inspector', crmTab?: 'registration' | 'editor' | 'negotiation' | 'documents') => void;
}

export default function AIInspectorView({ onNavigateView }: AIInspectorViewProps) {
  const [activeSection, setActiveSection] = useState<'overview' | 'source' | 'diagnostics' | 'prompt'>('overview');
  const [manifest, setManifest] = useState<AIContextManifest | null>(null);
  const [loadingManifest, setLoadingManifest] = useState(true);
  const [selectedFilePath, setSelectedFilePath] = useState<string>('src/App.tsx');
  const [searchQuery, setSearchQuery] = useState('');
  const [logs, setLogs] = useState<AIRuntimeLogEntry[]>(() => getAiRuntimeLogs());
  const [copiedId, setCopiedId] = useState<string | null>(null);

  useEffect(() => {
    if (!isAiSandboxMode()) {
      // Não força modo sandbox automaticamente ao abrir a aba para preservar a sessão clínica real do cirurgião-dentista
    }
    const unsub = subscribeAiRuntimeLogs(() => {
      setLogs(getAiRuntimeLogs());
    });
    return () => unsub();
  }, []);

  useEffect(() => {
    let mounted = true;
    setLoadingManifest(true);
    fetch('/ai-context.json')
      .then((res) => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res.json();
      })
      .then((data: AIContextManifest) => {
        if (!mounted) return;
        setManifest(data);
        if (data.files && data.files.length > 0 && !data.files.some((f) => f.path === selectedFilePath)) {
          setSelectedFilePath(data.files[0].path);
        }
      })
      .catch(() => {
        // Fallback to /api/ai-context if static file not yet built
        fetch('/api/ai-context')
          .then((r) => (r.ok ? r.json() : null))
          .then((data) => {
            if (mounted && data) setManifest(data);
          })
          .catch(() => {});
      })
      .finally(() => {
        if (mounted) setLoadingManifest(false);
      });
    return () => {
      mounted = false;
    };
  }, []);

  const filteredFiles = useMemo(() => {
    if (!manifest?.files) return [];
    const q = searchQuery.trim().toLowerCase();
    if (!q) return manifest.files;
    return manifest.files.filter(
      (f) => f.path.toLowerCase().includes(q) || f.content.toLowerCase().includes(q)
    );
  }, [manifest, searchQuery]);

  const selectedFile = useMemo(() => {
    if (!manifest?.files) return null;
    return manifest.files.find((f) => f.path === selectedFilePath) || filteredFiles[0] || null;
  }, [manifest, selectedFilePath, filteredFiles]);

  const staticFindings = useMemo(() => getStaticAuditFindings(), []);
  const sandboxCrm = useMemo(() => getAiSandboxCRMDatabase(), [logs]);

  const storageDiagnostics = useMemo(() => {
    if (typeof window === 'undefined') return { localKeys: 0, localBytes: 0, sessionKeys: 0 };
    let localBytes = 0;
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i) || '';
      const v = localStorage.getItem(k) || '';
      localBytes += k.length + v.length;
    }
    return {
      localKeys: localStorage.length,
      localBytes,
      sessionKeys: sessionStorage.length,
    };
  }, [logs]);

  const copyText = (id: string, text: string) => {
    navigator.clipboard.writeText(text);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2000);
  };

  const baseUrl = typeof window !== 'undefined' ? window.location.origin : 'https://sistema-aistudio.vercel.app';

  const masterAiPrompt = `Você é um Arquiteto de Software Sênior e Especialista em Auditoria de Bugs React + TypeScript + Supabase.
Preciso que você acesse e analise toda a estrutura, código-fonte e fluxos do meu sistema odontológico hospedado em:
${baseUrl}

🔗 LINKS DIRETOS DE ACESSO PARA IA (Sem bloqueio de login):
1. Resumo Arquitetural, Rotas, Banco de Dados e Índice Completo de Arquivos (Leve, ~18 KB):
   ${baseUrl}/llms.txt
2. Leitura de Qualquer Arquivo Individual em Texto Puro (Ideal para ChatGPT/Claude lerem arquivos específicos sem truncar):
   ${baseUrl}/api/ai-context?file=src/App.tsx&raw=true
   (Basta trocar "src/App.tsx" por qualquer caminho listado em /llms.txt)
3. Código-Fonte Completo de Todos os 98 Arquivos de Uma Vez:
   ${baseUrl}/llms-full.txt
4. Manifesto Estruturado em JSON (Árvore de arquivos + código + endpoints):
   ${baseUrl}/ai-context.json
5. Acesso Visual / Navegador em Modo Sandbox (Com dados clínicos fictícios pré-carregados, sem precisar de login):
   ${baseUrl}/?ai=true
6. Painel Técnico de Inspeção e Telemetria:
   ${baseUrl}/ai-inspector

📋 DIAGNÓSTICO ATUAL DA SESSÃO:
- Total de arquivos mapeados: ${manifest?.totalFiles || 45} arquivos (${manifest?.totalLines || 18000}+ linhas de código)
- Erros/Alertas de Runtime capturados na sessão: ${logs.length}
${logs.length > 0 ? logs.slice(0, 5).map((l) => `  • [${l.level.toUpperCase()}] (${l.source}): ${l.message}`).join('\n') : '  • Nenhum erro de runtime registrado até o momento.'}

🎯 SUA TAREFA:
1. Leia ${baseUrl}/llms.txt e ${baseUrl}/llms-full.txt (ou navegue em ${baseUrl}/?ai=true).
2. Identifique bugs ocultos, condições de corrida (race conditions), gargalos de performance e falhas de UX/responsividade.
3. Proponha melhorias concretas indicando o caminho exato do arquivo (ex: src/components/...) e o trecho de código corrigido.`;

  return (
    <div className="space-y-6" data-ai-inspector="root">
      {/* Top Banner — Machine & Human Readable */}
      <section
        className="rounded-2xl border border-[#C09553]/40 bg-gradient-to-r from-[#5C0000] via-[#8B0000] to-[#4A0000] text-white p-6 shadow-lg"
        data-ai-section="header"
      >
        <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-4">
          <div className="space-y-2">
            <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-white/15 border border-white/20 text-[11px] font-bold uppercase tracking-wider text-[#F3E5AB]">
              <Terminal className="w-3.5 h-3.5" />
              Modo de Inspeção Aberto para IA • Sandbox Seguro (LGPD)
            </div>
            <h1 className="text-xl sm:text-2xl font-bold tracking-tight" style={{ fontFamily: 'Playfair Display, serif' }}>
              Central de Acesso & Auditoria para Inteligência Artificial
            </h1>
            <p className="text-xs sm:text-sm text-white/85 max-w-3xl leading-relaxed">
              Qualquer IA (ChatGPT, Claude, Gemini, Perplexity, Cursor, Playwright) pode ler todo o código-fonte,
              arquitetura e testar todas as telas deste sistema usando os links públicos abaixo ou navegando pelo Modo Sandbox com dados fictícios.
            </p>
          </div>

          <div className="flex flex-wrap items-center gap-2.5 shrink-0">
            <a
              href="/llms.txt"
              target="_blank"
              rel="noopener noreferrer"
              className="inline-flex items-center gap-1.5 px-3.5 py-2 rounded-xl bg-white/15 hover:bg-white/25 border border-white/25 text-xs font-semibold text-white transition-all"
            >
              <FileCode className="w-4 h-4 text-[#F3E5AB]" />
              /llms.txt
              <ExternalLink className="w-3 h-3 opacity-70" />
            </a>
            <a
              href="/llms-full.txt"
              target="_blank"
              rel="noopener noreferrer"
              className="inline-flex items-center gap-1.5 px-3.5 py-2 rounded-xl bg-white/15 hover:bg-white/25 border border-white/25 text-xs font-semibold text-white transition-all"
            >
              <Download className="w-4 h-4 text-[#F3E5AB]" />
              /llms-full.txt (Código Completo)
              <ExternalLink className="w-3 h-3 opacity-70" />
            </a>
            <a
              href="/ai-context.json"
              target="_blank"
              rel="noopener noreferrer"
              className="inline-flex items-center gap-1.5 px-3.5 py-2 rounded-xl bg-white/15 hover:bg-white/25 border border-white/25 text-xs font-semibold text-white transition-all"
            >
              <Database className="w-4 h-4 text-[#F3E5AB]" />
              /ai-context.json
              <ExternalLink className="w-3 h-3 opacity-70" />
            </a>
            <button
              onClick={() => copyText('header-prompt', masterAiPrompt)}
              className="inline-flex items-center gap-1.5 px-4 py-2 rounded-xl bg-[#C09553] hover:bg-[#d1a764] text-[#2A0000] text-xs font-bold shadow-md transition-all cursor-pointer"
            >
              {copiedId === 'header-prompt' ? <Check className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
              {copiedId === 'header-prompt' ? 'Prompt Copiado!' : 'Copiar Prompt para IA'}
            </button>
          </div>
        </div>
      </section>

      {/* Quick Metrics Bar */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3.5" data-ai-section="metrics">
        <div className="bg-white rounded-xl border border-[#E6DEC9] p-4 shadow-2xs">
          <p className="text-[11px] font-bold uppercase tracking-wider text-zinc-400">Arquivos Mapeados</p>
          <p className="text-2xl font-bold text-[#8B0000] mt-1">{manifest ? manifest.totalFiles : '...'}</p>
          <p className="text-[11px] text-zinc-500 mt-0.5">
            {manifest ? `${manifest.totalLines.toLocaleString('pt-BR')} linhas de código` : 'Carregando manifesto...'}
          </p>
        </div>

        <div className="bg-white rounded-xl border border-[#E6DEC9] p-4 shadow-2xs">
          <p className="text-[11px] font-bold uppercase tracking-wider text-zinc-400">Pacientes no Sandbox</p>
          <p className="text-2xl font-bold text-emerald-700 mt-1">{sandboxCrm.patients?.length || 0}</p>
          <p className="text-[11px] text-zinc-500 mt-0.5">
            {sandboxCrm.appointments?.length || 0} consultas fictícias ativas
          </p>
        </div>

        <div className="bg-white rounded-xl border border-[#E6DEC9] p-4 shadow-2xs">
          <p className="text-[11px] font-bold uppercase tracking-wider text-zinc-400">Erros / Alertas Runtime</p>
          <p className={`text-2xl font-bold mt-1 ${logs.some((l) => l.level === 'error') ? 'text-red-600' : 'text-zinc-800'}`}>
            {logs.length}
          </p>
          <p className="text-[11px] text-zinc-500 mt-0.5">
            Monitorando console, promises e fetch
          </p>
        </div>

        <div className="bg-white rounded-xl border border-[#E6DEC9] p-4 shadow-2xs">
          <p className="text-[11px] font-bold uppercase tracking-wider text-zinc-400">Uso de Storage Local</p>
          <p className="text-2xl font-bold text-zinc-800 mt-1">
            {(storageDiagnostics.localBytes / 1024).toFixed(1)} KB
          </p>
          <p className="text-[11px] text-zinc-500 mt-0.5">
            {storageDiagnostics.localKeys} chaves local • {storageDiagnostics.sessionKeys} chaves sessão
          </p>
        </div>
      </div>

      {/* Section Navigation Tabs */}
      <div className="flex flex-wrap items-center justify-between gap-2 border-b border-[#E6DEC9] pb-3">
        <div className="flex flex-wrap gap-2">
          <button
            onClick={() => setActiveSection('overview')}
            className={`inline-flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold transition-all cursor-pointer ${
              activeSection === 'overview'
                ? 'bg-[#8B0000] text-white shadow-sm'
                : 'bg-white border border-[#E6DEC9] text-zinc-700 hover:bg-zinc-50'
            }`}
          >
            <Layers className="w-4 h-4" />
            1. Arquitetura, Telas & Fluxos
          </button>

          <button
            onClick={() => setActiveSection('source')}
            className={`inline-flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold transition-all cursor-pointer ${
              activeSection === 'source'
                ? 'bg-[#8B0000] text-white shadow-sm'
                : 'bg-white border border-[#E6DEC9] text-zinc-700 hover:bg-zinc-50'
            }`}
          >
            <FolderTree className="w-4 h-4" />
            2. Código-Fonte Completo ({manifest?.totalFiles || '...'})
          </button>

          <button
            onClick={() => setActiveSection('diagnostics')}
            className={`inline-flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold transition-all cursor-pointer ${
              activeSection === 'diagnostics'
                ? 'bg-[#8B0000] text-white shadow-sm'
                : 'bg-white border border-[#E6DEC9] text-zinc-700 hover:bg-zinc-50'
            }`}
          >
            <Bug className="w-4 h-4" />
            3. Auditoria de Bugs & Logs ({logs.length})
          </button>

          <button
            onClick={() => setActiveSection('prompt')}
            className={`inline-flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold transition-all cursor-pointer ${
              activeSection === 'prompt'
                ? 'bg-[#8B0000] text-white shadow-sm'
                : 'bg-white border border-[#E6DEC9] text-zinc-700 hover:bg-zinc-50'
            }`}
          >
            <Sparkles className="w-4 h-4" />
            4. Como Usar com Qualquer IA
          </button>
        </div>

        <button
          onClick={() => {
            resetAiSandboxData();
            window.location.reload();
          }}
          className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg border border-zinc-200 bg-white hover:bg-zinc-50 text-[11px] font-semibold text-zinc-600 cursor-pointer"
          title="Restaura os pacientes, agendamentos e orçamentos fictícios para o estado original"
        >
          <RefreshCw className="w-3.5 h-3.5" />
          Resetar Dados Sandbox
        </button>
      </div>

      {/* SECTION 1: OVERVIEW, ROUTES & ARCHITECTURE */}
      {activeSection === 'overview' && (
        <div className="space-y-6" data-ai-section="architecture-overview">
          {/* Interactive Screen Launcher for Browser AIs */}
          <div className="bg-white rounded-2xl border border-[#E6DEC9] p-5 shadow-2xs">
            <div className="flex items-center justify-between mb-4">
              <div>
                <h2 className="text-base font-bold text-zinc-800 flex items-center gap-2">
                  <Play className="w-4 h-4 text-[#8B0000]" />
                  Navegação Rápida pelas Telas do Sistema (Modo Sandbox Ativo)
                </h2>
                <p className="text-xs text-zinc-500 mt-0.5">
                  Clique em qualquer módulo abaixo para inspecionar a interface real carregada com pacientes e orçamentos fictícios.
                </p>
              </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
              {[
                {
                  title: 'Painel Geral (Dashboard)',
                  route: '/dashboard?ai=true',
                  view: 'dashboard' as const,
                  desc: 'Agenda do dia, confirmação via WhatsApp, faturamento diário, lembretes de retorno e gaveta de atendimento clínico.',
                  file: 'src/components/DashboardView.tsx',
                },
                {
                  title: 'Pacientes & Prontuário CRM',
                  route: '/crm/registration?ai=true',
                  view: 'crm' as const,
                  crmTab: 'registration' as const,
                  desc: 'Lista de pacientes, ficha cadastral, histórico clínico, odontograma 2D/3D, galeria de fotos, anamnese e receitas.',
                  file: 'src/components/DentalCRMView.tsx',
                },
                {
                  title: 'Mapeamento & Odontograma Visual',
                  route: '/crm/editor?ai=true',
                  view: 'crm' as const,
                  crmTab: 'editor' as const,
                  desc: 'Marcação interativa de procedimentos sobre fotos das arcadas (Superior, Inferior, Sorriso, Panorâmica) e modelo 3D.',
                  file: 'src/components/PhotoEditor.tsx',
                },
                {
                  title: 'Negociação & Orçamentos PDF',
                  route: '/crm/negotiation?ai=true',
                  view: 'crm' as const,
                  crmTab: 'negotiation' as const,
                  desc: 'Simulador financeiro (PIX, Cartão em até 12x), versão de orçamentos, script de vendas IA e apresentação em 2ª tela.',
                  file: 'src/components/NegotiationTab.tsx',
                },
                {
                  title: 'Painel Financeiro',
                  route: '/financeiro?ai=true',
                  view: 'financeiro' as const,
                  desc: 'Controle de receitas pagas e pendentes, deduplicação automática de lançamentos e filtro por método de pagamento.',
                  file: 'src/components/FinancialView.tsx',
                },
                {
                  title: 'Agenda FullCalendar',
                  route: '/calendar?ai=true',
                  view: 'calendar' as const,
                  desc: 'Visualização mensal/semanal/diária sincronizada com Google Calendar (emulada no modo Sandbox) e criação de eventos.',
                  file: 'src/components/CalendarView.tsx',
                },
              ].map((item) => (
                <div
                  key={item.title}
                  className="p-4 rounded-xl border border-zinc-200 hover:border-[#8B0000] bg-[#FAF8F5]/50 hover:bg-white transition-all flex flex-col justify-between gap-3"
                >
                  <div>
                    <div className="flex items-center justify-between gap-2">
                      <h3 className="text-xs font-bold text-zinc-800">{item.title}</h3>
                      <span className="text-[10px] font-mono px-2 py-0.5 rounded bg-zinc-100 text-zinc-600">
                        {item.route}
                      </span>
                    </div>
                    <p className="text-[11px] text-zinc-600 mt-1.5 leading-relaxed">{item.desc}</p>
                  </div>
                  <div className="flex items-center justify-between pt-2 border-t border-zinc-100">
                    <button
                      onClick={() => {
                        setSelectedFilePath(item.file);
                        setActiveSection('source');
                      }}
                      className="text-[11px] font-mono text-zinc-500 hover:text-[#8B0000] underline cursor-pointer"
                    >
                      {item.file}
                    </button>
                    <button
                      onClick={() => onNavigateView && onNavigateView(item.view, item.crmTab)}
                      className="inline-flex items-center gap-1 px-2.5 py-1 rounded-lg bg-[#8B0000] text-white text-[11px] font-semibold hover:bg-[#6B0000] transition-colors cursor-pointer"
                    >
                      Abrir Tela
                      <ArrowRight className="w-3 h-3" />
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Architecture & API Reference */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <div className="bg-white rounded-2xl border border-[#E6DEC9] p-5 shadow-2xs space-y-3">
              <h3 className="text-sm font-bold text-zinc-800 flex items-center gap-2">
                <Database className="w-4 h-4 text-[#8B0000]" />
                Arquitetura de Estado & Banco de Dados
              </h3>
              <div className="text-xs text-zinc-600 space-y-2 leading-relaxed">
