  setCurrentFileId
}: {
  onLoadPatientData?: (data: any) => void;
  onNewProposal?: (patientName: string) => void;
  onChangeView?: (view: any) => void;
  clinicSettings?: any;
  setClinicSettings?: (s: any) => void;
  onNewAppointment?: (patientName: string) => void;
  initialPatientName?: string;
  onClearInitialPatient?: () => void;
  initialNewPatientData?: { name: string; phone: string; email: string };
  onClearInitialNewPatientData?: () => void;
  procedures?: any;
  setProcedures?: (p: any) => void;
  currentFileId?: string | null;
  setCurrentFileId?: (id: string | null) => void;
  isMobile?: boolean;
} = {}) {
  // Navigation
  const [activeSubTab, setActiveSubTab] = useState<'import' | 'crm'>('crm'); // Default directly to CRM for quick review!
  
  const [patients, setPatients] = useState<CRMPatient[]>([]);

  // Use PatientContext for global state
  const {
    selectedPatient, setSelectedPatient,
    appointments, setAppointments,
    clinicalHistory, setClinicalHistory,
    communications, setCommunications,
    anamneseList, setAnamneseList,
    avisosList, setAvisosList,
    documentosList, setDocumentosList,
    galeriaList, setGaleriaList,
    pagamentosList, setPagamentosList,
    tratamentosList, setTratamentosList,
    odontogramaList, setOdontogramaList,
    activeSections, setActiveSections,
    activeProposal, setActiveProposal,
    saveContextToSupabase,
    isSavingToSupabase,
    refreshPatientSubModules
  } = usePatientContext();

  const [activeDetailTab, setActiveDetailTabState] = useState<'info' | 'appointments' | 'anamnesis' | 'clinical' | 'communication' | 'financial' | 'docs_gallery' | 'drive_records' | 'treatment_plan' | 'plan_editor' | 'plan_negotiation' | 'plan_documents'>(() => {
    if (typeof window !== 'undefined') {
      const savedTab = localStorage.getItem('agnaldo_dent_crm_detail_tab');
      const validTabs = ['info', 'appointments', 'anamnesis', 'clinical', 'communication', 'financial', 'docs_gallery', 'drive_records', 'treatment_plan', 'plan_editor', 'plan_negotiation', 'plan_documents'];
      if (savedTab && validTabs.includes(savedTab)) {
        return savedTab as any;
      }
    }
    return 'info';
  });

  const setActiveDetailTab = (tab: 'info' | 'appointments' | 'anamnesis' | 'clinical' | 'communication' | 'financial' | 'docs_gallery' | 'drive_records' | 'treatment_plan' | 'plan_editor' | 'plan_negotiation' | 'plan_documents') => {
    setActiveDetailTabState(tab);
    if (typeof window !== 'undefined') {
      try {
        localStorage.setItem('agnaldo_dent_crm_detail_tab', tab);
      } catch (_) {}
    }
  };

  // Supabase integration states
  const [driveFolderId, setSupabaseFolderId] = useState<string | null>(null);
  const [driveProposals, setSupabaseProposals] = useState<any[]>([]);
  const [isLoadingSupabaseProposals, setIsLoadingSupabaseProposals] = useState(false);
  const [driveImages, setSupabaseImages] = useState<any[]>([]);
  const [isLoadingSupabaseImages, setIsLoadingSupabaseImages] = useState(false);
  const [isSupabaseUploading, setIsSupabaseUploading] = useState(false);

  // Avulso Procedure State
  const [showAvulsoModal, setShowAvulsoModal] = useState(false);
  const [avulsoProcName, setAvulsoProcName] = useState('');
  const [avulsoProcPrice, setAvulsoProcPrice] = useState<number | string>('');

  const [isImportingBudget, setIsImportingBudget] = useState(false);

  // Batch Photos State
  const [showBatchPhotoModal, setShowBatchPhotoModal] = useState(false);
  const [batchGalleryPhotos, setBatchGalleryPhotos] = useState<any[]>([]);
  const [selectedBatchPhotos, setSelectedBatchPhotos] = useState<string[]>([]);
  const [loadingBatchGallery, setLoadingBatchGallery] = useState(false);
  const [processingBatchSelection, setProcessingBatchSelection] = useState(false);

  // Avulsa Photo State (Planning/Budget)
  const [showAddAvulsoPhotoModal, setShowAddAvulsoPhotoModal] = useState(false);
  const [avulsoPhotoTitle, setAvulsoPhotoTitle] = useState('');
  const [avulsoPhotoDesc, setAvulsoPhotoDesc] = useState('');
  const [avulsoPhotoDataUrl, setAvulsoPhotoDataUrl] = useState<string | null>(null);
  const [isProcessingAvulsoPhoto, setIsProcessingAvulsoPhoto] = useState(false);
  const [mappingViewMode, setMappingViewMode] = useState<'arch_2d' | 'classic_photos'>('arch_2d');

  const handleOpenBatchPhotos = async () => {
    setShowBatchPhotoModal(true);
    if (selectedPatient) {
      setLoadingBatchGallery(true);
      try {
        const patientPath = driveFolderId || selectedPatient.name;
        const files = await listPatientFilesFromSupabase(driveFolderId || selectedPatient?.id || "", selectedPatient?.name);
        const photos = files.filter((f: any) => f.mimeType?.startsWith('image/') || f.name.match(/\.(jpg|jpeg|png|webp|heic)$/i));
        setBatchGalleryPhotos(photos);
      } catch (e) {
        console.error("Erro ao carregar fotos da galeria:", e);
      } finally {
        setLoadingBatchGallery(false);
      }
    }
  };
  const handleImportBudget = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files || e.target.files.length === 0) return;
    const file = e.target.files[0];
    
    // Validate file type
    if (!file.type.startsWith('image/') && file.type !== 'application/pdf') {
      alert('Por favor, selecione uma imagem ou arquivo PDF válido.');
      e.target.value = '';
      return;
    }
    
    setIsImportingBudget(true);
    try {
      let extractedItems: any[] = [];
      let isInternalBudget = false;

      // 1. Tentar leitura nativa e determinística se for PDF (Zero IA, instantâneo, zero custo)
      if (file.type === 'application/pdf' || file.name.toLowerCase().endsWith('.pdf')) {
        try {
          let rawText = '';
          try {
            const buffer = await file.arrayBuffer();
            rawText = new TextDecoder('latin1').decode(buffer);
          } catch {
            rawText = await file.text();
          }
          const parsedInternal = parseInternalBudgetPdf(rawText);
          if (parsedInternal && parsedInternal.items && parsedInternal.items.length > 0) {
            extractedItems = parsedInternal.items;
            isInternalBudget = true;
          }
        } catch (readErr) {
          console.warn("Tentativa de leitura nativa de PDF falhou, prosseguindo com extração por IA:", readErr);
        }
      }

      // 2. Se não for PDF interno do sistema, recorrer à API com IA (para fotos e documentos externos)
      if (!isInternalBudget) {
        let dataUrl = '';
        
        if (file.type.startsWith('image/')) {
          try {
            dataUrl = await compressFileToDataUrl(file, 1200, 0.8);
          } catch (compressError) {
            console.warn("Compression failed, using original file", compressError);
            dataUrl = await new Promise<string>((resolve, reject) => {
              const reader = new FileReader();
              reader.onload = () => resolve(reader.result as string);
              reader.onerror = reject;
              reader.readAsDataURL(file);
            });
          }
        } else {
          dataUrl = await new Promise<string>((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = () => resolve(reader.result as string);
            reader.onerror = reject;
            reader.readAsDataURL(file);
          });
        }
        
        const response = await fetch('/api/extract-budget-vision', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ imageBase64: dataUrl })
        });
        
        if (!response.ok) {
          const errData = await response.json().catch(() => ({}));
          throw new Error(errData.details || errData.error || 'Falha ao processar a imagem do orçamento.');
        }
        
        const data = await response.json();
        extractedItems = data.items || [];
      }

      if (!extractedItems || extractedItems.length === 0) {
        throw new Error("Nenhum procedimento pôde ser identificado no documento.");
      }
      
      // 3. Proteção e confirmação com o usuário antes de alterar procedimentos em tela
      const existingMarkersCount = (activeSections || []).reduce((acc, s) => acc + (s.markers?.length || 0), 0);
      let shouldReplace = false;

      if (existingMarkersCount > 0) {
        shouldReplace = window.confirm(
          `Identificados ${extractedItems.length} procedimento(s) no orçamento.\n\n` +
          `Deseja SUBSTITUIR os procedimentos atuais desta tela por este orçamento?\n\n` +
          `• Clique em "OK" para SUBSTITUIR (manter apenas o orçamento importado).\n` +
          `• Clique em "Cancelar" para SOMAR (manter os procedimentos atuais e adicionar os novos).`
        );
      }

      // Process items and map to activeSections
      let newSections = shouldReplace
        ? (activeSections || []).map(s => ({ ...s, markers: [] }))
        : [...(activeSections || [])];
      
      // Ensure upper and lower exist
      if (!newSections.find(s => s.id === 'upper')) {
        newSections.push({ id: 'upper', title: 'Arcada Superior', subtitle: 'Dentes Posteriores e Anteriores Superiores', image: null, markers: [] });
      }
      if (!newSections.find(s => s.id === 'lower')) {
        newSections.push({ id: 'lower', title: 'Arcada Inferior', subtitle: 'Dentes Posteriores e Anteriores Inferiores', image: null, markers: [] });
      }
      
      extractedItems.forEach((item: any) => {
        if (!item.procedureName) return;
        
        let proc = procedures?.find((p: any) => p.name.toLowerCase().includes(item.procedureName.toLowerCase()) || item.procedureName.toLowerCase().includes(p.name.toLowerCase()));
        const effectivePrice = Number(item.price) || (proc?.price ? Number(proc.price) : 0);
        
        if (!proc) {
           proc = {
             id: 'imp-' + Date.now() + Math.random().toString(36).substr(2, 5),
             name: item.procedureName + (isInternalBudget ? '' : ' (Importado)'),
             price: effectivePrice,
             color: '#8B0000'
           };
           if (setProcedures) {
             setProcedures((prev: any) => {
               // Prevent duplicates in rapid succession
               if (prev.find((p: any) => p.name === proc.name)) return prev;
               return [...prev, proc];
             });
           }
        }
        
        const tooth = item.toothNumber;
        let targetSectionId = 'upper'; // fallback
        
        if (tooth) {
           if ((tooth >= 31 && tooth <= 38) || (tooth >= 41 && tooth <= 48)) {
             targetSectionId = 'lower';
           }
        }
        
        const sectionIdx = newSections.findIndex(s => s.id === targetSectionId);
        if (sectionIdx !== -1) {
           let marker = newSections[sectionIdx].markers.find((m: any) => m.toothNumber === tooth);
           if (!marker && tooth) {
             const defPos = getDefaultToothCoordinates(tooth, targetSectionId);
             marker = { id: `${targetSectionId}-${tooth}`, toothNumber: tooth, x: defPos.x, y: defPos.y, procedures: [], procedureInstances: [] };
             newSections[sectionIdx].markers.push(marker);
           } else if (!marker && !tooth) {
             marker = { id: `${targetSectionId}-gen-${Date.now()}-${Math.random()}`, toothNumber: 0, x: 50, y: 50, procedures: [], procedureInstances: [] };
             newSections[sectionIdx].markers.push(marker);
           }
           
           if (marker && proc) {
             if (!marker.procedures) marker.procedures = [];
             if (!marker.procedures.includes(proc.id)) {
               marker.procedures.push(proc.id);
             }
             if (!marker.procedureInstances) marker.procedureInstances = [];
             marker.procedureInstances.push({
               id: `inst-${marker.id}-${proc.id}-${Date.now()}-${Math.random()}`,
               procedureId: proc.id,
               name: proc.name,
               price: effectivePrice > 0 ? effectivePrice : proc.price,
               includeFinancial: true,
               status: 'A realizar',
               date: '',
               dentist: '',
               faces: [],
               observation: ''
             });
           }
        }
      });
      
      setActiveSections(newSections);
      alert(isInternalBudget ? 'Orçamento do sistema importado com sucesso (100% dos dentes e valores restaurados)!' : 'Orçamento importado com sucesso via IA!');
      
    } catch (error: any) {
      console.error(error);
      alert(`Erro ao importar orçamento: ${error?.message || 'Verifique se o formato do arquivo é válido e se a API está online.'}`);
    } finally {
      setIsImportingBudget(false);
      e.target.value = '';
    }
  };

  const handleAddAvulsoProcedure = () => {
    if (!avulsoProcName.trim()) return;
    const parsedPrice = typeof avulsoProcPrice === 'number' ? avulsoProcPrice : parseFloat(String(avulsoProcPrice)) || 0;
    
    const newInstId = `inst-geral-${Date.now()}`;
    const newInstance = {
      id: newInstId,
      procedureId: `custom-avulso-${Date.now()}`,
      name: avulsoProcName,
      price: parsedPrice,
      includeFinancial: true,
      status: 'A realizar' as const,
      date: '',
      dentist: '',
      faces: [],
      observation: '',
    };
    
    let updatedSections = [...activeSections];
    if (updatedSections.length === 0) {
       updatedSections = [{ id: 'geral', title: 'Geral', subtitle: 'Procedimentos sem dente associado', image: null, markers: [] }];
    }
    
    const targetSection = updatedSections[0];
    let geralMarker = targetSection.markers.find(m => m.id === 'marker-geral');
    if (!geralMarker) {
      geralMarker = {
        id: 'marker-geral',
        toothNumber: undefined as any,
        x: -100,
        y: -100,
        procedures: [],
        procedureInstances: []
      };
      targetSection.markers.push(geralMarker);
    }
    
    if (!geralMarker.procedureInstances) geralMarker.procedureInstances = [];
    geralMarker.procedureInstances.push(newInstance);
    
    setActiveSections(updatedSections);
    setShowAvulsoModal(false);
    setAvulsoProcName('');
    setAvulsoProcPrice('');
  };

  // Helper functions for planning
  const getSectionsWithInstallments = () => {
    return activeSections.map(sec => ({
      ...sec,
      installments: sec.installments || 1
    }));
  };

  const updateSectionInstallments = (sectionId: string, installments: number) => {
    setActiveSections(prev => 
      prev.map(sec => sec.id === sectionId ? { ...sec, installments } : sec)
    );
  };

  const [driveError, setSupabaseError] = useState<string | null>(null);
  const [editingProposalId, setEditingProposalId] = useState<string | null>(null);
  const [editingProposalName, setEditingProposalName] = useState<string>('');
  const [isLoadingProposalAction, setIsLoadingProposalAction] = useState<string | null>(null);

  // Treatment Plan states
  const [activeTreatmentPlan, setActiveTreatmentPlan] = useState<any | null>(null);
  const [selectedProposalId, setSelectedProposalIdState] = useState<string>(() => {
    if (typeof window !== 'undefined' && selectedPatient?.id) {
      return localStorage.getItem(`agnaldo_dent_selected_proposal_${selectedPatient.id}`) || '';
    }
    return '';
  });

  const setSelectedProposalId = (id: string | null) => {
    const cleanId = id || '';
    setSelectedProposalIdState(cleanId);
    if (typeof window !== 'undefined' && selectedPatient?.id) {
      try {
        if (cleanId) {
          localStorage.setItem(`agnaldo_dent_selected_proposal_${selectedPatient.id}`, cleanId);
        } else {
          localStorage.removeItem(`agnaldo_dent_selected_proposal_${selectedPatient.id}`);
        }
      } catch (_) {}
    }
  };

  const [selectedProposalData, setSelectedProposalData] = useState<any | null>(null);
  const [isLoadingPlanData, setIsLoadingPlanData] = useState(false);

  // Feedback visual de salvamento de status (orçamento e procedimentos individuais)
  const [savingStatusMap, setSavingStatusMap] = useState<Record<string, 'saving' | 'saved' | 'error'>>({});

  const markStatusSaving = (key: string) => {
    setSavingStatusMap(prev => ({ ...prev, [key]: 'saving' }));
  };

  const markStatusSaved = (key: string) => {
    setSavingStatusMap(prev => ({ ...prev, [key]: 'saved' }));
    setTimeout(() => {
      setSavingStatusMap(prev => {
        const next = { ...prev };
        if (next[key] === 'saved') delete next[key];
        return next;
      });
    }, 2800);
  };

  const markStatusError = (key: string) => {
    setSavingStatusMap(prev => ({ ...prev, [key]: 'error' }));
  };

  // Cache local instantâneo para garantir que F5 ou troca de aba nunca perca status alterado
  const getProposalCacheKey = (patientId: string, propIdOrName: string) => {
    const baseName = (propIdOrName || '').split('/').pop() || propIdOrName;
    return `agnaldo_dent_prop_override_${patientId}_${baseName}`;
  };

  const saveProposalOverrideLocally = (patientId: string, propId: string, propName: string, content: any) => {
    if (typeof window === 'undefined' || !patientId) return;
    try {
      const sanitized = JSON.parse(JSON.stringify(content));
      if (Array.isArray(sanitized.sections)) {
        sanitized.sections = sanitized.sections.map((sec: any) => {
          if (sec?.image && typeof sec.image === 'string' && sec.image.length > 50000 && sec.image.startsWith('data:')) {
            return { ...sec, image: null };
          }
          return sec;
        });
      }
      const payload = JSON.stringify({
        updatedAtMs: Date.now(),
        content: sanitized
      });
      localStorage.setItem(getProposalCacheKey(patientId, propId), payload);
      if (propName && propName !== propId) {
        localStorage.setItem(getProposalCacheKey(patientId, propName), payload);
      }
    } catch (e) {
      console.warn('Aviso ao gravar cache local de orçamento:', e);
    }
  };

  const applyLocalOverrideToProposal = (patientId: string, propId: string, propName: string, remoteContent: any) => {
    if (typeof window === 'undefined' || !patientId) return remoteContent;
    try {
      const raw = localStorage.getItem(getProposalCacheKey(patientId, propId)) ||
                  localStorage.getItem(getProposalCacheKey(patientId, propName));
      if (!raw) return remoteContent;
      const parsed = JSON.parse(raw);
      if (!parsed || !parsed.content) return remoteContent;

      // Mescla preservando imagens originais do remoto se o cache local tiver sanitizado imagens pesadas
      const localContent = parsed.content;
      const mergedSections = Array.isArray(remoteContent?.sections)
        ? remoteContent.sections.map((rSec: any) => {
            const lSec = (localContent.sections || []).find((s: any) => s.id === rSec.id);
            if (!lSec) return rSec;
            return {
              ...rSec,
              ...lSec,
              image: lSec.image || rSec.image
            };
          })
        : (localContent.sections || []);

      return {
        ...remoteContent,
        ...localContent,
        proposal: {
          ...(remoteContent?.proposal || {}),
          ...(localContent.proposal || {})
        },
        sections: mergedSections
      };
    } catch (_) {
      return remoteContent;
    }
  };

  // Timeline & Before/After Photo states & helpers
  const [isTimelineModalOpen, setIsTimelineModalOpen] = useState(false);
  const [isUploadingTimelinePhoto, setIsUploadingTimelinePhoto] = useState(false);
  const [timelineSignedUrls, setTimelineSignedUrls] = useState<Record<string, string>>({});

  const resolveTimelineSignedUrls = async (instances: any[]) => {
    if (!driveFolderId) return;
    const pendingUrls = { ...timelineSignedUrls };
    let updated = false;
    for (const inst of instances) {
      if (inst.photoAntesUrl && !pendingUrls[inst.photoAntesUrl]) {
        try {
          const url = await getPatientFileUrlFromSupabase(driveFolderId, inst.photoAntesUrl);
          if (url) {
            pendingUrls[inst.photoAntesUrl] = url;
            updated = true;
          }
        } catch (e) {
          console.warn("Failed to get signed URL for " + inst.photoAntesUrl, e);
        }
      }
      if (inst.photoDepoisUrl && !pendingUrls[inst.photoDepoisUrl]) {
        try {
          const url = await getPatientFileUrlFromSupabase(driveFolderId, inst.photoDepoisUrl);
          if (url) {
            pendingUrls[inst.photoDepoisUrl] = url;
            updated = true;
          }
        } catch (e) {
          console.warn("Failed to get signed URL for " + inst.photoDepoisUrl, e);
        }
      }
    }
    if (updated) {
      setTimelineSignedUrls(pendingUrls);
    }
  };

  // Auto-sync completed procedures with financial records (self-healing)
  useEffect(() => {
    if (!selectedPatient || driveProposals.length === 0) return;

    let updatedLocal = false;
    const localList = [...pagamentosList];

    // Load global finance
    const globalFinanceStr = localStorage.getItem('agnaldo_dent_financeiro');
    let globalFinance: any[] = [];
    if (globalFinanceStr) {
      try {
        globalFinance = JSON.parse(globalFinanceStr);
      } catch (e) {
        console.error(e);
      }
    }
    let updatedGlobal = false;

    // Scan all proposals
    const proposalsToScan = [...driveProposals];
    if (selectedProposalData && !proposalsToScan.some(p => p.id === selectedProposalId)) {
      proposalsToScan.push({
        id: selectedProposalId,
        name: driveProposals.find(p => p.id === selectedProposalId)?.name || 'orcamento.json',
        content: selectedProposalData
      });
    }

    proposalsToScan.forEach(prop => {
      const data = prop.content;
      if (!data) return;
      const instances = getProcedureInstancesFromProposal(data, prop.id, prop.name);
      
      instances.forEach(inst => {
        const cleanStatus = (inst.status || '').toLowerCase().trim();
        const isDone = cleanStatus === 'executado' || cleanStatus === 'realizado';
        const rawInstId = String(inst.instanceId || '');
        const cleanProcId = rawInstId.replace(/^(pay-proc-|pay-|proc-)+/, '');
        const payId = `pay-proc-${cleanProcId}`;

        if (isDone) {
          const methodVal = data.proposal?.paymentMethod || 'PIX';
          const priceVal = inst.price || 0;
          // Check local pagamentosList
          const hasLocal = localList.some(p => p.id === payId);
          if (!hasLocal) {
            localList.push({
              id: payId,
              patientId: selectedPatient.id,
              date: inst.updatedAt || inst.date || new Date().toISOString().split('T')[0],
              method: methodVal,
              paymentMethod: methodVal,
              description: `${inst.name} (${inst.toothNumber ? `Dente ${inst.toothNumber}` : 'Geral'}) - Executado`,
              value: priceVal,
              amount: priceVal,
              status: 'Pago'
            });
            updatedLocal = true;
          }

          // Check global finance list
          const hasGlobal = globalFinance.some(p => p.id === payId);
          if (!hasGlobal) {
            globalFinance.unshift({
              id: payId,
              patientId: selectedPatient.id,
              patientName: selectedPatient.name,
              date: inst.date || new Date().toISOString(),
              amount: priceVal,
              value: priceVal,
              paymentMethod: methodVal,
              method: methodVal,
              status: 'Pago',
              description: `${inst.name} (${inst.toothNumber ? `Dente ${inst.toothNumber}` : 'Geral'}) - Executado`
            });
            updatedGlobal = true;
          }
        }
      });
    });

    if (updatedLocal) {
      setPagamentosList(localList);
      setTimeout(() => {
        saveContextToSupabase();
      }, 500);
    }

    if (updatedGlobal) {
      localStorage.setItem('agnaldo_dent_financeiro', JSON.stringify(globalFinance));
      window.dispatchEvent(new Event('storage'));
    }
  }, [driveProposals, pagamentosList, selectedPatient, selectedProposalData, selectedProposalId]);

  const handleUploadTimelinePhoto = async (
    proposalName: string,
    instanceId: string,
    type: 'antes' | 'depois',
    file: File
  ) => {
    if (!driveFolderId) return;
    setIsUploadingTimelinePhoto(true);
    try {
      const extension = file.name.split('.').pop() || 'jpg';
      const storageFilename = `timeline_${instanceId}_${type}_${Date.now()}.${extension}`;
      await uploadPatientFileToSupabase(driveFolderId, file, storageFilename);

      const url = await getPatientFileUrlFromSupabase(driveFolderId, proposalName);
      if (!url) throw new Error("Não foi possível carregar a URL do orçamento.");
      const response = await fetch(url);
      if (!response.ok) throw new Error("Erro ao baixar o orçamento do Supabase.");
      const proposalData = await response.json();

      let found = false;
      proposalData.sections?.forEach((sec: any) => {
        sec.markers?.forEach((marker: any) => {
          marker.procedureInstances?.forEach((inst: any) => {
            if (inst.id === instanceId) {
              if (type === 'antes') {
                inst.photoAntesUrl = storageFilename;
              } else {
                inst.photoDepoisUrl = storageFilename;
              }
              inst.updatedAt = new Date().toLocaleDateString('pt-BR');
              found = true;
            }
          });
        });
      });

      if (!found) throw new Error("Procedimento não encontrado no orçamento.");

