  // Helper to extract procedure instances from a saved proposal JSON
  const getProcedureInstancesFromProposal = (proposalData: any, proposalId: string = '', proposalName: string = '') => {
    if (!proposalData || !proposalData.sections) return [];
    const instances: {
      sectionId: string;
      sectionTitle: string;
      markerId: string;
      toothNumber: number;
      instanceId: string;
      procedureId: string;
      name: string;
      price: number;
      status: string;
      updatedAt?: string;
      date?: string;
      photoAntesUrl?: string;
      photoDepoisUrl?: string;
      proposalId?: string;
      proposalName?: string;
    }[] = [];

    proposalData.sections.forEach((sec: any) => {
      if (!sec.markers) return;
      sec.markers.forEach((marker: any) => {
        if (marker.procedureInstances && marker.procedureInstances.length > 0) {
          marker.procedureInstances.forEach((inst: any) => {
            instances.push({
              sectionId: sec.id,
              sectionTitle: sec.title,
              markerId: marker.id,
              toothNumber: marker.toothNumber,
              instanceId: inst.id,
              procedureId: inst.procedureId,
              name: inst.name,
              price: inst.price,
              status: inst.status || 'não realizado',
              updatedAt: inst.updatedAt || inst.date || '',
              date: inst.date,
              photoAntesUrl: inst.photoAntesUrl || '',
              photoDepoisUrl: inst.photoDepoisUrl || '',
              proposalId,
              proposalName
            });
          });
        } else if (marker.procedures && marker.procedures.length > 0) {
          marker.procedures.forEach((procId: string) => {
            const procDetails = proposalData.procedures?.find((p: any) => p.id === procId);
            instances.push({
              sectionId: sec.id,
              sectionTitle: sec.title,
              markerId: marker.id,
              toothNumber: marker.toothNumber,
              instanceId: `${marker.id}-${procId}`,
              procedureId: procId,
              name: procDetails?.name || 'Procedimento',
              price: procDetails?.price || 0,
              status: 'não realizado',
              updatedAt: '',
              date: '',
              photoAntesUrl: '',
              photoDepoisUrl: '',
              proposalId,
              proposalName
            });
          });
        }
      });
    });

    return instances;
  };

  // Handler to update the status of a procedure and save it to Supabase
  const handleUpdateProcedureStatus = async (
    proposalData: any,
    sectionId: string,
    markerId: string,
    instanceId: string,
    newStatus: 'executado' | 'em andamento' | 'não realizado'
  ) => {
    if (!proposalData || !selectedPatient) return;

    // Deep clone proposal
    const updatedData = JSON.parse(JSON.stringify(proposalData));
    const nowStr = new Date().toLocaleString('pt-BR');

    let found = false;
    let targetInst: any = null;

    updatedData.sections = updatedData.sections.map((sec: any) => {
      if (sec.id !== sectionId) return sec;
      sec.markers = sec.markers.map((marker: any) => {
        if (marker.id !== markerId) return marker;
        
        if (!marker.procedureInstances) {
          marker.procedureInstances = [];
        }
        
        let inst = marker.procedureInstances.find((i: any) => i.id === instanceId);
        if (inst) {
          inst.status = newStatus === 'executado' ? 'Realizado' : newStatus === 'em andamento' ? 'Em andamento' : 'A realizar';
          inst.updatedAt = nowStr;
          inst.date = nowStr;
          targetInst = { ...inst, toothNumber: marker.toothNumber };
          found = true;
        } else {
          const parts = instanceId.split('-');
          const procId = parts[parts.length - 1];
          const procDetails = updatedData.procedures?.find((p: any) => p.id === procId);
          const newInst = {
            id: instanceId,
            procedureId: procId,
            name: procDetails?.name || 'Procedimento',
            price: procDetails?.price || 0,
            includeFinancial: true,
            status: newStatus === 'executado' ? 'Realizado' : newStatus === 'em andamento' ? 'Em andamento' : 'A realizar',
            date: nowStr,
            updatedAt: nowStr,
            dentist: clinicSettings?.doctorName || 'Dentista'
          };
          marker.procedureInstances.push(newInst);
          targetInst = { ...newInst, toothNumber: marker.toothNumber };
          found = true;
        }
        return marker;
      });
      return sec;
    });

    if (!found || !targetInst) return;

    // Auto-update proposal status when procedures progress
    const allInsts = getProcedureInstancesFromProposal(updatedData);
    const totalCount = allInsts.length;
    const doneCount = allInsts.filter(i => {
      const s = (i.status || '').toLowerCase().trim();
      return s === 'executado' || s === 'realizado';
    }).length;
    const inProgCount = allInsts.filter(i => (i.status || '').toLowerCase().trim() === 'em andamento').length;

    if (totalCount > 0 && updatedData.proposal) {
      if (doneCount === totalCount) {
        updatedData.proposal.status = 'Concluído';
      } else if ((doneCount > 0 || inProgCount > 0) && updatedData.proposal.status === 'Aberto (paciente não pagou)') {
        updatedData.proposal.status = 'Em Andamento';
      }
    }

    const currentPropObj = driveProposals.find(p => p.id === selectedProposalId);
    const propName = currentPropObj?.name || selectedProposalId;
    const statusKey = `proc-${instanceId}`;
    const cardStatusKey = `prop-${selectedProposalId}`;

    markStatusSaving(statusKey);
    markStatusSaving(cardStatusKey);

    // 1. Update local state & localStorage override immediately (0ms - F5 safe!)
    saveProposalOverrideLocally(selectedPatient.id, selectedProposalId, propName, updatedData);
    setSelectedProposalData(updatedData);
    setSupabaseProposals(prev => prev.map(p => p.id === selectedProposalId ? {
      ...p,
      content: updatedData,
      appProperties: {
        ...(p.appProperties || {}),
        status: updatedData.proposal?.status || p.appProperties?.status || 'Aberto'
      }
    } : p));

    if (driveProposals.length > 0 && selectedProposalId === driveProposals[0].id) {
      setActiveTreatmentPlan(updatedData);
    }
    if (updatedData.sections) {
      setActiveSections(updatedData.sections);
    }
    if (updatedData.proposal) {
      setActiveProposal(updatedData.proposal);
    }

    // 2. Sync financial records (Patient local and global)
    const rawInstId = String(instanceId || '');
    const cleanProcId = rawInstId.replace(/^(pay-proc-|pay-|proc-)+/, '');
    const payId = `pay-proc-${cleanProcId}`;
    const methodVal = proposalData.proposal?.paymentMethod || 'PIX';
    const priceVal = targetInst.price || 0;
    if (newStatus === 'executado') {
      // 1. Add to local pagamentosList (for patient's individual financial tab)
      const hasLocal = pagamentosList.some(p => p.id === payId);
      if (!hasLocal) {
        const newLocalPayment = {
          id: payId,
          patientId: selectedPatient.id,
          date: new Date().toISOString().split('T')[0], // YYYY-MM-DD
          method: methodVal,
          paymentMethod: methodVal,
          description: `${targetInst.name} (${targetInst.toothNumber ? `Dente ${targetInst.toothNumber}` : 'Geral'}) - Executado`,
          value: priceVal,
          amount: priceVal,
          status: 'Pago'
        };
        setPagamentosList([...pagamentosList, newLocalPayment]);
      }

      // 2. Add to global agnaldo_dent_financeiro (for lateral financial tab)
      const globalFinanceStr = localStorage.getItem('agnaldo_dent_financeiro');
      let globalFinance: any[] = [];
      if (globalFinanceStr) {
        try {
          globalFinance = JSON.parse(globalFinanceStr);
        } catch (e) {
          console.error(e);
        }
      }
      const hasGlobal = globalFinance.some(p => p.id === payId);
      if (!hasGlobal) {
        const newGlobalPayment = {
          id: payId,
          patientId: selectedPatient.id,
          patientName: selectedPatient.name,
          date: new Date().toISOString(),
          amount: priceVal,
          value: priceVal,
          paymentMethod: methodVal,
          method: methodVal,
          status: 'Pago',
          description: `${targetInst.name} (${targetInst.toothNumber ? `Dente ${targetInst.toothNumber}` : 'Geral'}) - Executado`
        };
        const updatedGlobal = [newGlobalPayment, ...globalFinance];
        localStorage.setItem('agnaldo_dent_financeiro', JSON.stringify(updatedGlobal));
        window.dispatchEvent(new Event('storage'));
      }
    } else {
      // ponytail: do not delete registered payments per user business rule
      console.log(`Procedimento desmarcado, mas o lançamento financeiro correspondente (${payId}) foi preservado.`);
    }

    try {
      const targetFolder = driveFolderId || selectedPatient.id;
      await uploadPatientFileToSupabase(
        targetFolder,
        new Blob([JSON.stringify(updatedData)], { type: "application/json" }),
        selectedProposalId
      );
      await saveContextToSupabase();
      markStatusSaved(statusKey);
      markStatusSaved(cardStatusKey);
    } catch (err: any) {
      console.error("Erro ao salvar alteração de status no Supabase:", err);
      markStatusSaved(statusKey); // Salvo localmente no cache com segurança
      markStatusSaved(cardStatusKey);
    }
  };

  const filterSupabaseProposals = (files: any[], patId?: string) => {
    const targetPatId = patId || selectedPatient?.id || '';
    return (files || [])
      .filter(f => f.name.toLowerCase().endsWith('.json'))
      .map(f => {
        if (targetPatId && f.content) {
          const mergedContent = applyLocalOverrideToProposal(targetPatId, f.id, f.name, f.content);
          return {
            ...f,
            content: mergedContent,
            appProperties: {
              ...(f.appProperties || {}),
              status: mergedContent?.proposal?.status || f.appProperties?.status || 'Aberto'
            }
          };
        }
        return f;
      });
  };

  const filterSupabaseImages = (files: any[]) => {
    return (files || []).filter(f => f.name && !f.name.startsWith('.'));
  };

  const syncGoogleSupabaseDataForPatient = async (patient: any) => {
    setSupabaseError(null);
    setSupabaseFolderId(null);
    setSupabaseProposals([]);
    setSupabaseImages([]);
    
    try {
      setIsLoadingSupabaseProposals(true);
      setIsLoadingSupabaseImages(true);
      
      const folderId = patient?.id || "Unknown";
      setSupabaseFolderId(folderId);
      
      // Load proposals
      try {
        const proposals = await listPatientFilesFromSupabase(folderId, patient.name);
        setSupabaseProposals(filterSupabaseProposals(proposals, patient?.id));
      } catch (err: any) {
        console.warn("Failed to load proposals for folder:", folderId, err);
      } finally {
        setIsLoadingSupabaseProposals(false);
      }

      // Load images
      try {
        const images = await listPatientFilesFromSupabase(folderId, patient.name);
        setSupabaseImages(filterSupabaseImages(images));
      } catch (err: any) {
        console.warn("Failed to load images for folder:", folderId, err);
      } finally {
        setIsLoadingSupabaseImages(false);
      }
    } catch (err: any) {
      console.warn("Supabase folder sync failed", err);
      setSupabaseError("Não foi possível conectar com o Supabase para este paciente.");
      setIsLoadingSupabaseProposals(false);
      setIsLoadingSupabaseImages(false);
    }
  };

  const uploadSupabaseFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const targetFolder = driveFolderId || selectedPatient?.id || selectedPatient?.name;
    if (!e.target.files || e.target.files.length === 0) return;
    if (!targetFolder) {
      alert("Por favor, selecione um paciente para enviar fotos para a pasta Cloud Drive.");
      return;
    }
    try {
      setIsSupabaseUploading(true);
      const files = Array.from(e.target.files);
      for (const file of files) {
        const uniqueName = `${Date.now()}_${file.name.replace(/\s+/g, '_')}`;
        await uploadPatientFileToSupabase(targetFolder, file, uniqueName);
      }
      // Refresh
      const images = await listPatientFilesFromSupabase(targetFolder, selectedPatient?.name);
      setSupabaseImages(filterSupabaseImages(images));
    } catch (err: any) {
      alert("Erro ao enviar imagem para a pasta Cloud Drive: " + (err?.message || err));
    } finally {
      setIsSupabaseUploading(false);
      e.target.value = '';
    }
  };

  const deleteSupabaseFile = async (fileId: string) => {
    if (!window.confirm("Deseja realmente excluir este arquivo?")) return;
    try {
      setIsSupabaseUploading(true);
      const targetFolder = driveFolderId || selectedPatient?.id || selectedPatient?.name || "Unknown";
      await deletePatientFileFromSupabase(targetFolder, fileId);
      const images = await listPatientFilesFromSupabase(targetFolder, selectedPatient?.name);
      setSupabaseImages(filterSupabaseImages(images));
    } catch (err: any) {
      alert("Erro ao excluir arquivo: " + (err.message || err));
    } finally {
      setIsSupabaseUploading(false);
    }
  };

  const deleteSupabaseProposalFile = async (fileId: string) => {
    if (!window.confirm("Deseja realmente excluir este orçamento/projeto do Supabase?")) return;
    try {
      setIsLoadingSupabaseProposals(true);
      const targetFolder = driveFolderId || selectedPatient?.id || selectedPatient?.name || "Unknown";
      await deletePatientFileFromSupabase(targetFolder, fileId, 'Orcamentos');
      const folderToLoad = driveFolderId || selectedPatient?.id;
      if (folderToLoad) {
        const proposals = await listPatientFilesFromSupabase(folderToLoad, selectedPatient?.name);
        setSupabaseProposals(filterSupabaseProposals(proposals));
      }
      if (selectedProposalId === fileId) {
        setSelectedProposalId(null);
        setSelectedProposalData(null);
      }
    } catch (err: any) {
      alert("Erro ao excluir orçamento: " + (err.message || err));
    } finally {
      setIsLoadingSupabaseProposals(false);
    }
  };

  const renameSupabaseProposalFile = async (fileId: string, currentName: string) => {
    const cleanCurrentName = currentName
      .replace(/^Orcamentos\//, '')
      .replace(/\.json$/i, '')
      .replace(/^orcamento_salvo_/, '')
      .replace(/^orcamento_salvo/, '')
      .replace(/^orcamento_ativo/, 'Orçamento Ativo')
      .replace(/_/g, ' ')
      .trim();

    const newNameInput = window.prompt("Digite o novo nome para o orçamento:", cleanCurrentName);
    if (!newNameInput || newNameInput.trim() === '' || newNameInput.trim() === cleanCurrentName) return;
    
    // Format to safe filename
    const safeBaseName = newNameInput
      .trim()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .toLowerCase()
      .replace(/[^a-z0-9_-]/g, '_')
      .replace(/_+/g, '_')
      .replace(/^_|_$/g, '');

    const newFilename = `orcamento_salvo_${safeBaseName || 'custom'}.json`;
    
    try {
      setIsLoadingSupabaseProposals(true);
      const targetFolder = driveFolderId || selectedPatient?.id || selectedPatient?.name || "Unknown";
      await renamePatientFileInSupabase(targetFolder, fileId, newFilename, 'Orcamentos');
      
      const folderToLoad = driveFolderId || selectedPatient?.id;
      if (folderToLoad) {
        const proposals = await listPatientFilesFromSupabase(folderToLoad, selectedPatient?.name);
        const filtered = filterSupabaseProposals(proposals);
        setSupabaseProposals(filtered);
        
        // Update selected proposal ID if it was renamed (P2: preserve active selection)
        const wasCurrentSelected = selectedProposalId === fileId;
        const found = filtered.find(p => p.name === newFilename || p.name === `Orcamentos/${newFilename}` || p.id.endsWith(`/${newFilename}`));
        if (found && (wasCurrentSelected || !selectedProposalId)) {
          setSelectedProposalId(found.id);
        }
      }
    } catch (err: any) {
      alert("Erro ao renomear orçamento: " + (err.message || err));
    } finally {
      setIsLoadingSupabaseProposals(false);
    }
  };

  const handleLoadProposalIntoWorkspace = async (fileId: string) => {
    if (!onLoadPatientData) return;
    try {
      setIsLoadingProposalAction(fileId);
      const data = await (async () => { 
        const url = await getPatientFileUrlFromSupabase(driveFolderId || '', fileId); 
        if (!url) throw new Error("Arquivo não encontrado ou sem permissão de leitura.");
        const r = await fetch(url); 
        if (!r.ok) throw new Error("Falha ao baixar o arquivo.");
        return await r.json(); 
      })();
      onLoadPatientData(data);
      setActiveDetailTab('plan_editor');
    } catch (err: any) {
      alert("Erro ao carregar planejamento no espaço de trabalho: " + err.message);
    } finally {
      setIsLoadingProposalAction(null);
    }
  };

  // HTML5 Camera controls
  const startCamera = async () => {
    setCameraError(null);
    setIsCameraActive(true);
    setCameraZoom(1);
    setCameraExposure(1.0);
    setFocusLocked(false);
    setFlashOn(false);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: facingMode }
      });
      activeStreamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.play();

        try {
          const track = stream.getVideoTracks()[0];
          const capabilities = track.getCapabilities ? track.getCapabilities() : {} as any;
          setHasFlash(!!capabilities.torch);
        } catch (e) {
          console.warn('Flash capability check failed in CRM', e);
        }
      }
    } catch (err: any) {
      console.error("Camera access error", err);
      setCameraError("Não foi possível acessar a câmera do dispositivo.");
    }
  };

  const stopCameraStream = () => {
    if (activeStreamRef.current) {
      activeStreamRef.current.getTracks().forEach((track) => track.stop());
      activeStreamRef.current = null;
    }
    setFlashOn(false);
    setHasFlash(false);
  };

  const toggleCameraFacingMode = async () => {
    const nextMode = facingMode === 'user' ? 'environment' : 'user';
    setFacingMode(nextMode);
    stopCameraStream();
    setFlashOn(false);
    setHasFlash(false);
    // Restart stream
    setTimeout(async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: nextMode }
        });
        activeStreamRef.current = stream;
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.play();

          try {
            const track = stream.getVideoTracks()[0];
            const capabilities = track.getCapabilities ? track.getCapabilities() : {} as any;
            setHasFlash(!!capabilities.torch);
          } catch (e) {
            console.warn('Flash capability check failed in CRM switch', e);
          }
        }
      } catch (err) {
        setCameraError("Falha ao inverter câmera");
      }
    }, 100);
  };

  const toggleCameraZoom = async () => {
    const nextZoom: 1 | 2 = cameraZoom === 1 ? 2 : 1;
    setCameraZoom(nextZoom);
    if (activeStreamRef.current) {
      const track = activeStreamRef.current.getVideoTracks()[0];
      try {
        const capabilities = track.getCapabilities ? track.getCapabilities() : {} as any;
        if (capabilities.zoom) {
          const val = nextZoom === 2 ? Math.min(capabilities.zoom.max || 2.0, 2.0) : 1.0;
          await track.applyConstraints({ advanced: [{ zoom: val }] } as any);
        }
      } catch (e) {
        console.warn('Hardware zoom adjustment failed in CRM', e);
      }
    }
  };

  const handleExposureChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    setCameraExposure(val);
    if (activeStreamRef.current) {
      const track = activeStreamRef.current.getVideoTracks()[0];
      try {
        const expCompensation = (val - 1.0) * 4.0;
        await track.applyConstraints({
          advanced: [{ exposureMode: 'manual', exposureCompensation: expCompensation }]
        } as any);
      } catch (err) {
        // Fallback is CSS filter
      }
    }
  };

  const toggleFocusLock = async () => {
    if (activeStreamRef.current) {
      const track = activeStreamRef.current.getVideoTracks()[0];
      const nextFocusLock = !focusLocked;
      setFocusLocked(nextFocusLock);
      try {
        await track.applyConstraints({
          advanced: [{ focusMode: nextFocusLock ? 'manual' : 'continuous' }]
        } as any);
      } catch (e) {
        console.warn('Focus lock constraint not supported by hardware/browser in CRM', e);
      }
    }
  };

  // Gallery Image Edit handlers
  const handleEditGalleryImage = async (imgId: string) => {
    try {
      setIsDownloadingForEdit(imgId);
      const img = driveImages.find(i => i.id === imgId);
      if (!img || !img.thumbnailLink) throw new Error('URL da imagem não encontrada');
      
      let dataUrl = '';
      try {
        const r = await fetch(img.thumbnailLink);
        const blob = await r.blob();
        dataUrl = await new Promise<string>((resolve) => {
          const reader = new FileReader();
          reader.onloadend = () => resolve(reader.result as string);
          reader.readAsDataURL(blob);
        });
      } catch (err) {
        console.warn('Direct fetch failed for Drive image, trying via CORS proxy...', err);
        const proxyUrl = `https://images.weserv.nl/?url=${encodeURIComponent(img.thumbnailLink)}`;
        const r = await fetch(proxyUrl);
        const blob = await r.blob();
        dataUrl = await new Promise<string>((resolve) => {
          const reader = new FileReader();
          reader.onloadend = () => resolve(reader.result as string);
          reader.readAsDataURL(blob);
        });
      }

      setEditingGalleryImageId(imgId);
      setEditingGalleryImageUrl(dataUrl);
      setEditingImageSource('drive');
    } catch (err: any) {
      alert('Erro ao carregar imagem para edição: ' + err.message);
    } finally {
      setIsDownloadingForEdit(null);
    }
  };

  const handleEditFirestoreImage = async (imgId: string) => {
    try {
      setIsDownloadingForEdit(imgId);
      const img = galeriaList.find(g => g.id === imgId);
      if (!img || !img.url) throw new Error('URL da imagem não encontrada');
      
      if (img.url.startsWith('data:')) {
        setEditingGalleryImageId(imgId);
        setEditingGalleryImageUrl(img.url);
        setEditingImageSource('firestore');
      } else {
        let dataUrl = '';
        try {
          const r = await fetch(img.url);
          const blob = await r.blob();
          dataUrl = await new Promise<string>((resolve) => {
            const reader = new FileReader();
            reader.onloadend = () => resolve(reader.result as string);
            reader.readAsDataURL(blob);
          });
        } catch (err) {
          console.warn('Direct fetch failed for Firestore image, trying via CORS proxy...', err);
          const proxyUrl = `https://images.weserv.nl/?url=${encodeURIComponent(img.url)}`;
          const r = await fetch(proxyUrl);
          const blob = await r.blob();
          dataUrl = await new Promise<string>((resolve) => {
            const reader = new FileReader();
            reader.onloadend = () => resolve(reader.result as string);
            reader.readAsDataURL(blob);
          });
        }

        setEditingGalleryImageId(imgId);
        setEditingGalleryImageUrl(dataUrl);
        setEditingImageSource('firestore');
      }
    } catch (err: any) {
      alert('Erro ao carregar imagem para edição: ' + err.message);
    } finally {
      setIsDownloadingForEdit(null);
    }
  };

  const handleSaveEditedGalleryImage = async (editedImage: string) => {
    if (editingImageSource === 'firestore') {
      if (!selectedPatient) return;
      try {
        setIsSupabaseUploading(true);
        setEditingGalleryImageUrl(null);
        setEditingGalleryImageId(null);
        setEditingImageSource(null);

        const originalItem = galeriaList.find(g => g.id === editingGalleryImageId);
        const newGalleryItem = {
          id: `gal-edited-${Date.now()}`,
          patientId: selectedPatient.id,
          url: editedImage,
          description: `Editada: ${originalItem?.description || 'Imagem'}`,
          date: new Date().toISOString()
        };

        const updatedList = [...galeriaList, newGalleryItem];
        setGaleriaList(updatedList);

        const crmData = await getSupabaseCRMDatabase();
        crmData.galeria = [...(crmData.galeria || []).filter((g: any) => g.patientId !== selectedPatient.id), ...updatedList];
        await saveSupabaseCRMDatabase(crmData);
        alert('Imagem editada salva com sucesso na galeria do paciente!');
      } catch (err: any) {
        alert('Erro ao salvar imagem editada: ' + err.message);
      } finally {
        setIsSupabaseUploading(false);
      }
      return;
    }

    if (!driveFolderId) return;
    try {
      setIsSupabaseUploading(true);
      setEditingGalleryImageUrl(null);
      setEditingGalleryImageId(null);
      setEditingImageSource(null);

      const arr = editedImage.split(',');
      const mime = arr[0].match(/:(.*?);/)?.[1] || 'image/jpeg';
      const bstr = atob(arr[1]);
      let n = bstr.length;
      const u8arr = new Uint8Array(n);
      while (n--) {
        u8arr[n] = bstr.charCodeAt(n);
      }
      const blob = new Blob([u8arr], { type: mime });
      const filename = `edited-${new Date().getTime()}.jpg`;
