                    className={`px-2 py-3 text-[9px] sm:text-[10px] md:text-[11px] font-bold uppercase tracking-wider focus:outline-none cursor-pointer transition-all border-r border-b border-zinc-200 flex items-center justify-center text-center ${
                      activeDetailTab === 'docs_gallery'
                        ? 'bg-[#8B0000] text-[#FAF8F5]'
                        : 'text-zinc-600 hover:bg-zinc-100 hover:text-zinc-900'
                    }`}
                  >
                    📂 Arquivos ({documentosList.length + galeriaList.length})
                  </button>

                  <button
                    type="button"
                    onClick={() => setActiveDetailTab('financial')}
                    className={`px-2 py-3 text-[9px] sm:text-[10px] md:text-[11px] font-bold uppercase tracking-wider focus:outline-none cursor-pointer transition-all border-r border-b border-zinc-200 flex items-center justify-center text-center ${
                      activeDetailTab === 'financial'
                        ? 'bg-[#8B0000] text-[#FAF8F5]'
                        : 'text-zinc-600 hover:bg-zinc-100 hover:text-zinc-900'
                    }`}
                  >
                    💵 Financeiro ({pagamentosList.length})
                  </button>
                  <button
                    type="button"
                    onClick={() => setActiveDetailTab('drive_records')}
                    className={`px-2 py-3 text-[9px] sm:text-[10px] md:text-[11px] font-bold uppercase tracking-wider focus:outline-none cursor-pointer transition-all border-r border-b border-zinc-200 flex items-center justify-center text-center ${
                      activeDetailTab === 'drive_records'
                        ? 'bg-[#8B0000] text-[#FAF8F5]'
                        : 'text-zinc-600 hover:bg-zinc-100 hover:text-zinc-900 bg-amber-500/5 text-amber-900 font-semibold'
                    }`}
                  >
                    ☁️ Cloud Drive ({isLoadingSupabaseProposals || isLoadingSupabaseImages ? '...' : driveProposals.length + driveImages.length})
                  </button>
                </div>

                {/* Sub Tab View Panels */}
                <div className="p-6 space-y-6 flex-1 bg-white">

                  {/* Panel A: Demographics and Core Patient Data */}
                  {activeDetailTab === 'info' && (
                    <div className="space-y-6">
                      <div className="border-b border-zinc-100 pb-3 flex justify-between items-end">
                        <div>
                          <span className="text-[10px] uppercase font-bold text-amber-800 tracking-wider font-mono">DADOS DO PACIENTE</span>
                          <h4 className="font-serif font-bold text-lg text-[#8B0000] mt-0.5">Ficha Cadastral Geral consolidada</h4>
                        </div>
                        <button
                          type="button"
                          onClick={handleOpenEditPatient}
                          className="flex items-center gap-1.5 px-4 py-2 bg-[#8B0000] hover:bg-[#6d0000] text-white text-[11px] font-bold rounded-xl uppercase tracking-wide transition-all cursor-pointer shadow-sm"
                          title="Editar dados cadastrais do paciente"
                        >
                          <Pencil className="w-3.5 h-3.5" />
                          <span>Editar Cadastro</span>
                        </button>
                      </div>

                      {/* Dashboard de Tratamento */}
                      {treatmentProgress ? (
                        <div className="bg-gradient-to-br from-[#8B0000] to-[#5a0000] text-white p-5 rounded-2xl border border-[#C09553]/40 shadow-sm space-y-4">
                          <div className="flex justify-between items-center border-b border-white/10 pb-2.5">
                            <div className="space-y-0.5">
                              <span className="text-[9px] uppercase font-extrabold text-[#C09553] tracking-widest font-mono">ACOMPANHAMENTO CLÍNICO</span>
                              <h5 className="font-serif font-bold text-sm">Painel de Evolução do Tratamento</h5>
                            </div>
                            <span className="bg-[#C09553] text-[#8B0000] text-[10px] font-extrabold px-2.5 py-1 rounded-full uppercase tracking-wider">
                              {treatmentProgress.percent}% Concluído
                            </span>
                          </div>

                          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                            {/* Progresso Geral */}
                            <div className="space-y-2">
                              <div className="flex justify-between text-xs font-semibold text-white/80">
                                <span>Progresso dos Procedimentos</span>
                                <span className="font-mono">{treatmentProgress.completed} de {treatmentProgress.total}</span>
                              </div>
                              <div className="w-full bg-white/15 h-2.5 rounded-full overflow-hidden border border-white/5">
                                <div 
                                  className="bg-gradient-to-r from-[#C09553] to-amber-300 h-full rounded-full transition-all duration-500"
                                  style={{ width: `${treatmentProgress.percent}%` }}
                                />
                              </div>
                              <div className="flex gap-3 text-[10px] text-white/60">
                                <span>🟢 Executados: {treatmentProgress.completed}</span>
                                <span>🟡 Em andamento: {treatmentProgress.inProgress}</span>
                                <span>⚪ Pendentes: {treatmentProgress.total - treatmentProgress.completed - treatmentProgress.inProgress}</span>
                              </div>
                            </div>

                            {/* Próximo Passo */}
                            <div className="bg-black/15 p-3 rounded-xl border border-white/5 flex flex-col justify-center">
                              <span className="text-[9px] uppercase font-bold text-[#C09553] tracking-wider font-mono">Próximo Passo Recomendado</span>
                              {treatmentProgress.nextStep ? (
                                <div className="mt-1">
                                  <p className="text-xs font-bold text-white truncate">
                                    {treatmentProgress.nextStep.name}
                                  </p>
                                  <p className="text-[10px] text-[#C09553] mt-0.5">
                                    Localização: {treatmentProgress.nextStep.toothNumber ? `Dente ${treatmentProgress.nextStep.toothNumber}` : 'Geral'} • Status: <span className="underline italic uppercase tracking-wider text-[8px] font-extrabold">{treatmentProgress.nextStep.status === 'Realizado' ? 'Executado' : treatmentProgress.nextStep.status === 'Em andamento' ? 'Em andamento' : 'Não realizado'}</span>
                                  </p>
                                </div>
                              ) : (
                                <p className="text-xs font-semibold text-emerald-300 mt-1 flex items-center gap-1">
                                  ✨ Todos os procedimentos foram concluídos!
                                </p>
                              )}
                            </div>
                          </div>
                          
                          <div className="flex justify-end pt-2 border-t border-white/10">
                            <button
                              type="button"
                              onClick={() => {
                                setIsTimelineModalOpen(true);
                                if (treatmentProgress?.allInstances) {
                                  resolveTimelineSignedUrls(treatmentProgress.allInstances);
                                }
                              }}
                              className="px-4 py-2 bg-white/15 hover:bg-white/25 text-[#FAF8F5] text-[11px] font-bold uppercase rounded-xl border border-white/20 transition-all flex items-center gap-1.5 cursor-pointer"
                            >
                              📸 Detalhes & Timeline Antes/Depois
                            </button>
                          </div>
                        </div>

                      ) : (
                        <div className="bg-[#FAF8F5] p-4 rounded-xl border border-dashed border-[#E6DEC9] text-center text-xs text-zinc-500">
                          ℹ️ Nenhum orçamento ou plano de tratamento ativo localizado para esta paciente no Supabase. 
                          Para gerar um plano, abra o planejador 3D e salve um novo orçamento.
                        </div>
                      )}

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6 text-xs text-zinc-600">
                        <div className="space-y-3 bg-[#FAF8F5] p-4 rounded-xl border border-[#E6DEC9]/45">
                          <h5 className="font-bold text-zinc-800 uppercase tracking-wide text-[9px] border-b pb-1">Identificação Pessoal</h5>
                          <div className="flex justify-between items-center">
                            <span className="font-semibold text-zinc-400">CPF:</span>
                            <span className="font-mono text-zinc-800 font-semibold">{selectedPatient.cpf || 'Não registrado'}</span>
                          </div>
                          <div className="flex justify-between items-center">
                            <span className="font-semibold text-zinc-400">Data de Nascimento:</span>
                            <span className="font-mono text-zinc-850 font-semibold">{normalizeDateDisplay(selectedPatient.birthDate || '') || 'Não informada'}</span>
                          </div>
                          <div className="flex justify-between items-center">
                            <span className="font-semibold text-zinc-400">Sexo:</span>
                            <span className="font-semibold text-zinc-800">{selectedPatient.gender || 'Não informado'}</span>
                          </div>
                          <div className="flex justify-between items-center">
                            <span className="font-semibold text-zinc-400">Estado Civil:</span>
                            <span className="font-semibold text-zinc-800">{selectedPatient.maritalStatus || 'Não informado'}</span>
                          </div>
                          <div className="flex justify-between items-center">
                            <span className="font-semibold text-zinc-400">Prontuário Médico Nº:</span>
                            <span className="font-mono bg-[#8B0000]/5 px-2 py-0.5 rounded text-[#8B0000] font-bold">{selectedPatient.medicalRecord || 'Gerado Manual'}</span>
                          </div>
                        </div>

                        <div className="space-y-3 bg-[#FAF8F5] p-4 rounded-xl border border-[#E6DEC9]/45">
                          <h5 className="font-bold text-zinc-800 uppercase tracking-wide text-[9px] border-b pb-1">Canais de Contato</h5>
                          <div className="flex justify-between items-center">
                            <span className="font-semibold text-zinc-400">📱 Telefone / WhatsApp:</span>
                            {selectedPatient.mobile ? (
                              <a
                                href={`https://wa.me/${selectedPatient.mobile.replace(/\D/g, '').length === 10 || selectedPatient.mobile.replace(/\D/g, '').length === 11 ? '55' + selectedPatient.mobile.replace(/\D/g, '') : selectedPatient.mobile.replace(/\D/g, '')}`}
                                target="_blank"
                                rel="noopener noreferrer"
                                className="text-emerald-750 font-bold hover:underline hover:text-emerald-600 flex items-center gap-1 cursor-pointer"
                                title="Clique para enviar WhatsApp"
                              >
                                {selectedPatient.mobile}
                              </a>
                            ) : (
                              <span className="text-zinc-500">Não informado</span>
                            )}
                          </div>
                          <div className="flex justify-between items-center">
                            <span className="font-semibold text-zinc-400">E-mail pessoal:</span>
                            <span className="font-semibold text-zinc-800 truncate max-w-[150px]">{selectedPatient.email || 'Não informado'}</span>
                          </div>
                          <div className="flex justify-between items-start">
                            <span className="font-semibold text-zinc-400 shrink-0">Localidade:</span>
                            <span className="font-semibold text-zinc-850 text-right ml-4">
                              {selectedPatient.street
                                ? `${selectedPatient.street}, Nº ${selectedPatient.number || 'S/N'}${selectedPatient.neighborhood ? ` - Bairro ${selectedPatient.neighborhood}` : ''}, ${selectedPatient.city || 'Salgado'}/${selectedPatient.state || 'SE'}`
                                : 'Sem endereço registrado'}
                            </span>
                          </div>
                        </div>
                      </div>

                      {/* Observations Alert */}
                      <div className="bg-[#FAF8F5]/80 border-2 border-dashed border-[#C09553]/35 p-5 rounded-xl space-y-2">
                        <span className="text-[10px] font-bold text-[#8B0000] uppercase tracking-widest flex items-center gap-1.5">
                          <FileText className="w-4 h-4 text-[#C09553]" />
                          Observações Diagnósticas e Recomendação Geral
                        </span>
                        <p className="text-xs text-zinc-600 leading-relaxed italic font-medium">
                          {selectedPatient.observations ? `"${selectedPatient.observations}"` : 'Tudo limpo no cadastro. Nenhuma recomendação médica de alergia ou restrição cardíaca anexada ao paciente.'}
                        </p>
                      </div>

                      {/* ── Modal de Edição de Cadastro ──────────────────── */}
                      {isEditingPatient && (
                        <div className="fixed inset-0 z-[130] bg-black/50 backdrop-blur-sm flex items-center justify-center p-4" onClick={() => setIsEditingPatient(false)}>
                          <div className="bg-white rounded-2xl w-full max-w-3xl max-h-[90vh] overflow-hidden shadow-2xl border border-zinc-200 flex flex-col" onClick={e => e.stopPropagation()}>
                            {/* Header */}
                            <div className="bg-[#8B0000] text-white px-6 py-4 flex justify-between items-center shrink-0">
                              <div className="flex items-center gap-2">
                                <Pencil className="w-4.5 h-4.5 text-[#C09553]" />
                                <h3 className="font-serif font-bold text-base">Editar Cadastro de Paciente</h3>
                              </div>
                              <button type="button" onClick={() => setIsEditingPatient(false)} className="text-white/60 hover:text-white transition-colors p-1 cursor-pointer">
                                <X className="w-5 h-5" />
                              </button>
                            </div>

                            {/* Form Body */}
                            <div className="flex-1 overflow-y-auto p-6 space-y-6">

                              {/* Section 1: Identificação Pessoal */}
                              <div className="space-y-4">
                                <h4 className="text-[10px] uppercase font-extrabold text-[#8B0000] tracking-widest border-b border-[#E6DEC9] pb-1 flex items-center gap-1.5">
                                  <User className="w-3.5 h-3.5 text-[#C09553]" />
                                  Identificação Pessoal
                                </h4>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-xs">
                                  <div className="md:col-span-2">
                                    <label className="block text-zinc-500 font-semibold mb-1">Nome Completo *</label>
                                    <input type="text" value={editPatientData.name || ''} onChange={e => setEditPatientData(prev => ({ ...prev, name: e.target.value.toUpperCase() }))} className="w-full bg-[#FAF8F5] border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] transition-all" />
                                  </div>
                                  <div>
                                    <label className="block text-zinc-500 font-semibold mb-1">CPF</label>
                                    <input type="text" placeholder="000.000.000-00" value={editPatientData.cpf || ''} onChange={e => setEditPatientData(prev => ({ ...prev, cpf: e.target.value }))} className="w-full bg-[#FAF8F5] border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] transition-all" />
                                  </div>
                                  <div>
                                    <label className="block text-zinc-500 font-semibold mb-1">Data de Nascimento</label>
                                    <input type="date" value={editPatientData.birthDate || ''} onChange={e => setEditPatientData(prev => ({ ...prev, birthDate: e.target.value }))} className="w-full bg-[#FAF8F5] border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] transition-all" />
                                  </div>
                                  <div>
                                    <label className="block text-zinc-500 font-semibold mb-1">Sexo</label>
                                    <select value={editPatientData.gender || ''} onChange={e => setEditPatientData(prev => ({ ...prev, gender: e.target.value }))} className="w-full bg-[#FAF8F5] border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] transition-all">
                                      <option value="">Selecione</option>
                                      <option value="Feminino">Feminino</option>
                                      <option value="Masculino">Masculino</option>
                                      <option value="Outro">Outro</option>
                                    </select>
                                  </div>
                                  <div>
                                    <label className="block text-zinc-500 font-semibold mb-1">Estado Civil</label>
                                    <select value={editPatientData.maritalStatus || ''} onChange={e => setEditPatientData(prev => ({ ...prev, maritalStatus: e.target.value }))} className="w-full bg-[#FAF8F5] border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] transition-all">
                                      <option value="">Selecione</option>
                                      <option value="Solteiro(a)">Solteiro(a)</option>
                                      <option value="Casado(a)">Casado(a)</option>
                                      <option value="Divorciado(a)">Divorciado(a)</option>
                                      <option value="Viúvo(a)">Viúvo(a)</option>
                                    </select>
                                  </div>
                                  <div>
                                    <label className="block text-zinc-500 font-semibold mb-1">RG</label>
                                    <input type="text" value={editPatientData.rg || ''} onChange={e => setEditPatientData(prev => ({ ...prev, rg: e.target.value }))} className="w-full bg-[#FAF8F5] border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] transition-all" />
                                  </div>
                                  <div>
                                    <label className="block text-zinc-500 font-semibold mb-1">Órgão Emissor/UF</label>
                                    <input type="text" value={editPatientData.rgIssuer || ''} onChange={e => setEditPatientData(prev => ({ ...prev, rgIssuer: e.target.value }))} className="w-full bg-[#FAF8F5] border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] transition-all" />
                                  </div>
                                  <div>
                                    <label className="block text-zinc-500 font-semibold mb-1">Prontuário</label>
                                    <input type="text" value={editPatientData.medicalRecord || ''} onChange={e => setEditPatientData(prev => ({ ...prev, medicalRecord: e.target.value }))} className="w-full bg-[#FAF8F5] border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] transition-all" />
                                  </div>
                                  <div>
                                    <label className="block text-zinc-500 font-semibold mb-1">Situação</label>
                                    <select value={editPatientData.status || 'ATIVO'} onChange={e => setEditPatientData(prev => ({ ...prev, status: e.target.value }))} className="w-full bg-[#FAF8F5] border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] transition-all">
                                      <option value="ATIVO">ATIVO</option>
                                      <option value="INATIVO">INATIVO</option>
                                    </select>
                                  </div>
                                  <div>
                                    <label className="block text-zinc-500 font-semibold mb-1">Como conheceu a clínica?</label>
                                    <select value={editPatientData.howKnewClinic || ''} onChange={e => setEditPatientData(prev => ({ ...prev, howKnewClinic: e.target.value }))} className="w-full bg-[#FAF8F5] border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] transition-all">
                                      <option value="">Selecione</option>
                                      <option value="Indicação">Indicação</option>
                                      <option value="Redes Sociais">Redes Sociais</option>
                                      <option value="Google">Google</option>
                                      <option value="Outros">Outros</option>
                                    </select>
                                  </div>
                                  <div>
                                    <label className="block text-zinc-500 font-semibold mb-1">Código do Paciente</label>
                                    <input type="text" value={editPatientData.codigo_paciente || ''} onChange={e => setEditPatientData(prev => ({ ...prev, codigo_paciente: e.target.value }))} className="w-full bg-[#FAF8F5] border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] transition-all" />
                                  </div>
                                </div>
                              </div>

                              {/* Section 2: Canais de Contato */}
                              <div className="space-y-4">
                                <h4 className="text-[10px] uppercase font-extrabold text-[#8B0000] tracking-widest border-b border-[#E6DEC9] pb-1 flex items-center gap-1.5">
                                  <MessageSquare className="w-3.5 h-3.5 text-[#C09553]" />
                                  Canais de Contato
                                </h4>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-xs">
                                  <div className="md:col-span-2">
                                    <label className="block text-zinc-500 font-semibold mb-1">📱 Telefone / WhatsApp</label>
                                    <input type="text" placeholder="(00) 00000-0000" value={editPatientData.mobile || ''} onChange={e => setEditPatientData(prev => ({ ...prev, mobile: e.target.value, phone: e.target.value }))} className="w-full bg-[#FAF8F5] border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] transition-all" />
                                  </div>
                                  <div className="md:col-span-2">
                                    <label className="block text-zinc-500 font-semibold mb-1">E-mail</label>
                                    <input type="email" value={editPatientData.email || ''} onChange={e => setEditPatientData(prev => ({ ...prev, email: e.target.value }))} className="w-full bg-[#FAF8F5] border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] transition-all" />
                                  </div>
                                  <div className="md:col-span-2">
                                    <label className="block text-zinc-500 font-semibold mb-1">Observações</label>
                                    <textarea rows={3} value={editPatientData.observations || ''} onChange={e => setEditPatientData(prev => ({ ...prev, observations: e.target.value }))} className="w-full bg-[#FAF8F5] border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] transition-all resize-y" />
                                  </div>
                                </div>
                              </div>

                              {/* Section 3: Endereço */}
                              <div className="space-y-4">
                                <h4 className="text-[10px] uppercase font-extrabold text-[#8B0000] tracking-widest border-b border-[#E6DEC9] pb-1 flex items-center gap-1.5">
                                  <ExternalLink className="w-3.5 h-3.5 text-[#C09553]" />
                                  Endereço
                                </h4>
                                <div className="grid grid-cols-1 md:grid-cols-4 gap-4 text-xs">
                                  <div>
                                    <label className="block text-zinc-500 font-semibold mb-1 flex items-center justify-between">
                                      <span>CEP</span>
                                      {isLoadingCep && (
                                        <span className="text-[10px] text-[#8B0000] font-normal flex items-center gap-1 animate-pulse">
                                          <Loader2 className="w-3 h-3 animate-spin" /> Buscando...
                                        </span>
                                      )}
                                    </label>
                                    <input 
                                      type="text" 
                                      placeholder="00000-000" 
                                      maxLength={9}
                                      value={editPatientData.cep || ''} 
                                      onChange={e => handleCepLookup(e.target.value)} 
                                      onBlur={e => handleCepLookup(e.target.value)}
                                      className="w-full bg-[#FAF8F5] border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] transition-all" 
                                    />
                                  </div>
                                  <div className="md:col-span-3">
                                    <label className="block text-zinc-500 font-semibold mb-1">Logradouro</label>
                                    <input type="text" value={editPatientData.street || ''} onChange={e => setEditPatientData(prev => ({ ...prev, street: e.target.value }))} className="w-full bg-[#FAF8F5] border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] transition-all" />
                                  </div>
                                  <div>
                                    <label className="block text-zinc-500 font-semibold mb-1">Número</label>
                                    <input type="text" value={editPatientData.number || ''} onChange={e => setEditPatientData(prev => ({ ...prev, number: e.target.value }))} className="w-full bg-[#FAF8F5] border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] transition-all" />
                                  </div>
                                  <div className="md:col-span-3">
                                    <label className="block text-zinc-500 font-semibold mb-1">Complemento</label>
                                    <input type="text" value={editPatientData.complement || ''} onChange={e => setEditPatientData(prev => ({ ...prev, complement: e.target.value }))} className="w-full bg-[#FAF8F5] border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] transition-all" />
                                  </div>
                                  <div className="md:col-span-2">
                                    <label className="block text-zinc-500 font-semibold mb-1">Bairro</label>
                                    <input type="text" value={editPatientData.neighborhood || ''} onChange={e => setEditPatientData(prev => ({ ...prev, neighborhood: e.target.value }))} className="w-full bg-[#FAF8F5] border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] transition-all" />
                                  </div>
                                  <div>
                                    <label className="block text-zinc-500 font-semibold mb-1">Cidade</label>
                                    <input type="text" value={editPatientData.city || ''} onChange={e => setEditPatientData(prev => ({ ...prev, city: e.target.value }))} className="w-full bg-[#FAF8F5] border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] transition-all" />
                                  </div>
                                  <div>
                                    <label className="block text-zinc-500 font-semibold mb-1">Estado</label>
                                    <input type="text" value={editPatientData.state || ''} onChange={e => setEditPatientData(prev => ({ ...prev, state: e.target.value }))} className="w-full bg-[#FAF8F5] border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] transition-all" />
                                  </div>
                                </div>
                              </div>

                              {/* Section 4: Convênio */}
                              <div className="space-y-4">
                                <h4 className="text-[10px] uppercase font-extrabold text-[#8B0000] tracking-widest border-b border-[#E6DEC9] pb-1 flex items-center gap-1.5">
                                  <ClipboardList className="w-3.5 h-3.5 text-[#C09553]" />
                                  Convênio
                                </h4>
                                <div className="grid grid-cols-1 md:grid-cols-3 gap-4 text-xs">
                                  <div>
                                    <label className="block text-zinc-500 font-semibold mb-1">Convênio</label>
                                    <select value={editPatientData.healthInsurance || 'PARTICULAR'} onChange={e => setEditPatientData(prev => ({ ...prev, healthInsurance: e.target.value }))} className="w-full bg-[#FAF8F5] border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] transition-all">
                                      <option value="PARTICULAR">PARTICULAR</option>
                                      <option value="BRADESCO">BRADESCO SAÚDE</option>
                                      <option value="SULAMERICA">SULAMÉRICA</option>
                                      <option value="AMIL">AMIL</option>
                                      <option value="UNIMED">UNIMED</option>
                                      <option value="OUTRO">OUTRO</option>
                                    </select>
                                  </div>
                                  <div>
                                    <label className="block text-zinc-500 font-semibold mb-1">Carteira</label>
                                    <input type="text" value={editPatientData.healthInsuranceCard || ''} onChange={e => setEditPatientData(prev => ({ ...prev, healthInsuranceCard: e.target.value }))} className="w-full bg-[#FAF8F5] border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] transition-all" />
                                  </div>
                                  <div>
                                    <label className="block text-zinc-500 font-semibold mb-1">Validade</label>
                                    <input type="text" placeholder="MM/AAAA" value={editPatientData.healthInsuranceValidity || ''} onChange={e => setEditPatientData(prev => ({ ...prev, healthInsuranceValidity: e.target.value }))} className="w-full bg-[#FAF8F5] border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] transition-all" />
                                  </div>
                                </div>
                              </div>

                              {/* Section 5: Dados do Responsável */}
                              <div className="space-y-4">
                                <h4 className="text-[10px] uppercase font-extrabold text-[#8B0000] tracking-widest border-b border-[#E6DEC9] pb-1 flex items-center gap-1.5">
                                  <User className="w-3.5 h-3.5 text-[#C09553]" />
                                  Dados do Responsável
                                </h4>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-xs">
                                  <div>
                                    <label className="block text-zinc-500 font-semibold mb-1">Nome do Responsável</label>
                                    <input type="text" value={editPatientData.respName || ''} onChange={e => setEditPatientData(prev => ({ ...prev, respName: e.target.value }))} className="w-full bg-[#FAF8F5] border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] transition-all" />
                                  </div>
                                  <div>
                                    <label className="block text-zinc-500 font-semibold mb-1">Nascimento</label>
                                    <input type="date" value={editPatientData.respBirthDate || ''} onChange={e => setEditPatientData(prev => ({ ...prev, respBirthDate: e.target.value }))} className="w-full bg-[#FAF8F5] border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] transition-all" />
                                  </div>
                                  <div>
                                    <label className="block text-zinc-500 font-semibold mb-1">Telefone</label>
                                    <input type="text" value={editPatientData.respPhone || ''} onChange={e => setEditPatientData(prev => ({ ...prev, respPhone: e.target.value }))} className="w-full bg-[#FAF8F5] border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] transition-all" />
                                  </div>
                                  <div>
                                    <label className="block text-zinc-500 font-semibold mb-1">Celular</label>
                                    <input type="text" value={editPatientData.respMobile || ''} onChange={e => setEditPatientData(prev => ({ ...prev, respMobile: e.target.value }))} className="w-full bg-[#FAF8F5] border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] transition-all" />
                                  </div>
                                  <div>
                                    <label className="block text-zinc-500 font-semibold mb-1">CPF do Responsável</label>
                                    <input type="text" value={editPatientData.respCpf || ''} onChange={e => setEditPatientData(prev => ({ ...prev, respCpf: e.target.value }))} className="w-full bg-[#FAF8F5] border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] transition-all" />
                                  </div>
                                  <div>
                                    <label className="block text-zinc-500 font-semibold mb-1">Profissão</label>
                                    <input type="text" value={editPatientData.respProfession || ''} onChange={e => setEditPatientData(prev => ({ ...prev, respProfession: e.target.value }))} className="w-full bg-[#FAF8F5] border border-zinc-200 rounded-lg px-3 py-2 outline-none focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] transition-all" />
                                  </div>
                                </div>
                              </div>

                            </div>

                            {/* Footer Actions */}
                            <div className="bg-zinc-50 px-6 py-4 border-t border-zinc-200 flex justify-between items-center shrink-0">
                              <span className="text-[10px] text-zinc-400 font-mono">Última atualização: {editPatientData.updatedAt ? new Date(editPatientData.updatedAt).toLocaleString('pt-BR') : 'N/D'}</span>
                              <div className="flex gap-2.5">
                                <button
                                  type="button"
                                  onClick={() => setIsEditingPatient(false)}
                                  className="px-4 py-2 border border-zinc-300 text-zinc-600 text-xs font-bold rounded-xl uppercase tracking-wide hover:bg-zinc-100 transition-colors cursor-pointer"
                                >
                                  Cancelar
                                </button>
                                <button
                                  type="button"
                                  onClick={handleSaveEditPatient}
                                  disabled={isSavingEdit || !editPatientData.name}
                                  className="px-5 py-2 bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-bold rounded-xl uppercase tracking-wide transition-colors flex items-center gap-1.5 shadow-sm cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed"
                                >
                                  {isSavingEdit ? (
                                    <>
                                      <Loader2 className="w-3.5 h-3.5 animate-spin" />
                                      Salvando...
                                    </>
                                  ) : (
                                    <>
                                      <Save className="w-3.5 h-3.5" />
                                      Salvar Alterações
                                    </>
                                  )}
                                </button>
                              </div>
                            </div>
                          </div>
                        </div>
                      )}
                    </div>
                  )}

                  {/* Panel B: Appointments list */}
                  {activeDetailTab === 'appointments' && (
                    <div className="space-y-4">
                      <div className="border-b border-zinc-100 pb-3 flex justify-between items-center">
                        <div>
                          <span className="text-[10px] uppercase font-bold text-amber-800 tracking-wider font-mono">DURANTE TODA A HISTÓRIA</span>
                          <h4 className="font-serif font-bold text-lg text-[#8B0000]">Histórico de Consultas e Agendamentos</h4>
                        </div>
                        <span className="bg-[#8B0000] text-[#FAF8F5] px-2.5 py-0.5 rounded-full text-[10px] font-mono font-semibold uppercase">{appointments.length} Sessões</span>
                      </div>

                      {appointments.length === 0 ? (
                        <div className="p-10 text-center border-2 border-dashed border-zinc-200 rounded-xl">
                          <p className="text-xs text-zinc-400 italic">Nenhum evento registrado no histórico da agenda deste paciente.</p>
                        </div>
                      ) : (
                        <div className="overflow-x-auto border border-zinc-150 rounded-xl">
                          <table className="w-full text-left text-[11px] font-sans">
                            <thead className="bg-[#FAF8F5] text-zinc-500 font-bold uppercase text-[9px] tracking-wider border-b border-zinc-200">
                              <tr>
                                <th className="p-2.5">Data/Horário</th>
                                <th className="p-2.5">Dentista / Especialidade</th>
                                <th className="p-2.5">Sala/Clinica</th>
                                <th className="p-2.5">Situação</th>
                                <th className="p-2.5">Notas do dia</th>
                              </tr>
                            </thead>
                            <tbody className="divide-y divide-zinc-100 text-zinc-700">
                              {appointments.map((a) => (
                                <tr key={a.id} className="hover:bg-zinc-50/50">
                                  <td className="p-2.5 whitespace-nowrap">
                                    <div className="font-semibold font-mono text-zinc-900">{normalizeDateDisplay(a.date)}</div>
                                    <div className="text-[9px] text-zinc-400 font-semibold flex items-center gap-0.5"><Clock className="w-3 h-3" /> {a.time}</div>
                                  </td>
                                  <td className="p-2.5 md:max-w-[150px] truncate">
                                    <div className="font-bold text-zinc-800">{a.dentist}</div>
                                    <div className="text-[9px] text-amber-700 font-medium">{a.specialty}</div>
                                  </td>
                                  <td className="p-2.5">
                                    <div>{a.clinic || 'Clínica Principal'}</div>
                                    {a.room && <div className="text-[9px] text-zinc-400">Consultório {a.room}</div>}
                                  </td>
                                  <td className="p-2.5">
                                    <span className={`px-2 py-0.5 text-[8px] font-bold rounded-full uppercase ${
                                      a.status === 'Confirmado' ? 'bg-blue-50 text-blue-700 border border-blue-100' :
                                      a.status === 'Atendido' ? 'bg-emerald-50 text-emerald-700 border border-emerald-100' :
                                      a.status === 'Faltou' ? 'bg-amber-50 text-amber-700 border border-amber-100' :
                                      a.status === 'Cancelado' ? 'bg-rose-50 text-rose-700 border border-rose-100' :
                                      'bg-zinc-100 text-zinc-600'
                                    }`}>
                                      {a.status}
                                    </span>
                                  </td>
                                  <td className="p-2.5 max-w-[180px] break-words whitespace-normal text-zinc-500" title={a.observations}>
                                    {a.observations || <span className="text-zinc-300">-</span>}
                                  </td>
                                </tr>
                              ))}
                            </tbody>
                          </table>
                        </div>
                      )}
                    </div>
                  )}

                  {/* Panel C: Anamnesis details */}
                  {activeDetailTab === 'anamnesis' && (
                    <div className="space-y-4">
                      <div className="border-b border-zinc-100 pb-3 flex flex-col sm:flex-row justify-between sm:items-center gap-3">
                        <div>
                          <span className="text-[10px] uppercase font-bold text-amber-800 tracking-wider font-mono">DADOS MÉDICOS</span>
                          <h4 className="font-serif font-bold text-lg text-[#8B0000]">Questionário Médico de Anamnese</h4>
                        </div>
                        <div className="flex flex-wrap items-center gap-2">
                          {Object.keys(groupedAnamnese).length > 1 && (
                            <select
                              value={selectedAnamnesisDate}
                              onChange={(e) => setSelectedAnamnesisDate(e.target.value)}
                              className="px-3 py-1.5 text-xs font-bold border border-zinc-200 rounded-lg bg-white text-zinc-700 focus:outline-none"
                            >
                              {Object.keys(groupedAnamnese).sort((a, b) => b.localeCompare(a)).map(dateStr => (
                                <option key={dateStr} value={dateStr}>
                                  Ficha de: {normalizeDateDisplay(dateStr)}
                                </option>
                              ))}
                            </select>
                          )}
                          {selectedAnamnesisDate && (
                            <button
                              type="button"
                              onClick={() => handleDownloadAnamnesisPdf(selectedAnamnesisDate, groupedAnamnese[selectedAnamnesisDate] || [], (groupedAnamnese[selectedAnamnesisDate] || []).find(a => a.signature)?.signature || '')}
                              className="px-3 py-1.5 bg-zinc-800 hover:bg-zinc-700 text-white text-[11px] font-bold rounded-lg uppercase transition-all duration-200 cursor-pointer flex items-center gap-1.5 shadow-sm active:scale-95"
                            >
                              <Download className="w-3.5 h-3.5" />
                              Baixar PDF
                            </button>
                          )}
                          <button
                            type="button"
                            onClick={handleSendAnamnesisLink}
                            className="px-3 py-1.5 bg-[#C09553] hover:bg-[#B48C4D] text-white text-[11px] font-bold rounded-lg uppercase transition-colors cursor-pointer flex items-center gap-1 shadow-sm"
                          >
                            Enviar Anamnese Digital
                          </button>
                          <button
                            type="button"
                            onClick={() => syncAnamnesisFromFirestore(selectedPatient.id)}
                            disabled={syncingAnamnesis}
                            className="p-1.5 text-zinc-550 hover:text-[#8B0000] border border-zinc-200 hover:border-[#8B0000] rounded-lg transition-all cursor-pointer bg-white"
                            title="Buscar respostas preenchidas pelo paciente"
                          >
                            <RefreshCw className={`w-3.5 h-3.5 ${syncingAnamnesis ? 'animate-spin' : ''}`} />
                          </button>
                          <span className="bg-[#8B0000] text-[#FAF8F5] px-2.5 py-0.5 rounded-full text-[10px] font-mono font-semibold uppercase">
                            {Object.keys(groupedAnamnese).length} {Object.keys(groupedAnamnese).length === 1 ? 'Versão' : 'Versões'}
                          </span>
                        </div>
                      </div>

                      {anamneseList.length === 0 ? (
                        <div className="p-10 text-center border-2 border-dashed border-zinc-200 rounded-xl bg-[#FAF8F5] flex flex-col items-center justify-center space-y-3">
                          <p className="text-xs text-zinc-400 italic">Nenhum check clínico de anamnese registrado. Clique em 'Enviar Anamnese Digital' para mandar o link ao paciente responder.</p>
                          <button
                            type="button"
                            onClick={handleSendAnamnesisLink}
                            className="px-4 py-2 bg-[#8B0000] hover:bg-[#6c1b26] text-white text-xs font-bold rounded-xl transition-all cursor-pointer shadow-sm"
                          >
                            Enviar Link por WhatsApp
                          </button>
                        </div>
                      ) : (
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                          {(groupedAnamnese[selectedAnamnesisDate] || []).map((a) => (
                            <div key={a.id} className="bg-[#FAF8F5] border border-[#E6DEC9]/65 p-4 rounded-xl space-y-2 relative overflow-hidden">
                              <div className="absolute right-2 top-2 bg-amber-50 rounded text-[8px] font-mono p-1 text-amber-800 font-bold">Q&A Check</div>
                              <span className="text-[10px] uppercase font-bold text-zinc-400 block tracking-wider">Pergunta Clínica:</span>
                              <p className="font-serif font-bold text-xs text-zinc-900 leading-snug">{a.question}</p>
                              <div className="bg-white border text-xs text-zinc-700 p-2.5 rounded-md font-semibold font-mono flex items-start gap-1">
                                <span className="text-emerald-700">➜ Resposta:</span>
                                <span>{a.answer || 'Não informada'}</span>
                              </div>
                            </div>
                          ))}
                          
                          {/* If a signature exists for this version, show it */}
                          {(groupedAnamnese[selectedAnamnesisDate] || []).some(a => a.signature) && (
                            <div className="md:col-span-2 bg-[#FAF8F5] border border-[#E6DEC9] p-4 rounded-xl space-y-3 relative overflow-hidden">
                              <span className="text-[10px] uppercase font-bold text-zinc-400 block tracking-wider">Assinatura Eletrônica do Paciente:</span>
                              <div className="bg-white border border-[#E6DEC9] p-3 rounded-lg flex flex-col items-center justify-center">
                                <img 
                                  alt="Assinatura Eletrônica"
                                  src={(groupedAnamnese[selectedAnamnesisDate] || []).find(a => a.signature)?.signature || ''} 
                                  className="max-h-24 bg-white select-none pointer-events-none" 
                                />
                                <span className="text-[10px] text-zinc-500 mt-2 font-mono">
                                  Assinado digitalmente em: {normalizeDateDisplay(selectedAnamnesisDate)}
                                </span>
                              </div>
                            </div>
                          )}
                        </div>
                      )}
                    </div>
                  )}

                  {/* Panel D: Clinical and Odontograma (Unified Timeline) */}
                  {activeDetailTab === 'clinical' && (
                    <div className="space-y-6">
                      <div className="border-b border-zinc-100 pb-3 flex justify-between items-center">
                        <div>
                          <span className="text-[10px] uppercase font-bold text-amber-800 tracking-wider font-mono">TIMELINE CLÍNICA</span>
                          <h4 className="font-serif font-bold text-md text-[#8B0000] uppercase">Histórico Unificado do Paciente</h4>
                        </div>
                      </div>

                      {(() => {
                        const handleDeleteHistoryEvent = async (e: React.MouseEvent, event: any) => {
                          e.stopPropagation();
                          if (!window.confirm('Deseja realmente apagar este registro?')) return;
                          
                          if (event.type === 'clinical') {
                            const updated = (clinicalHistory || []).filter(i => i.id !== event.data.id && i.date !== event.data.date);
                            setClinicalHistory(updated);
                            setTimeout(() => saveContextToSupabase(), 100);
                          } else if (event.type === 'odontograma') {
                            const updated = (odontogramaList || []).filter(i => i.id !== event.data.id && i.date !== event.data.date);
                            setOdontogramaList(updated);
                            setTimeout(() => saveContextToSupabase(), 100);
                          } else if (event.type === 'tratamento') {
                            const updated = (tratamentosList || []).filter(i => i.id !== event.data.id && i.date !== event.data.date);
                            setTratamentosList(updated);
                            setTimeout(() => saveContextToSupabase(), 100);
                          } else if (event.type === 'anamnese') {
                            const updated = (anamneseList || []).filter(i => i.id !== event.data.id && i.date !== event.data.date);
                            setAnamneseList(updated);
                            setTimeout(() => saveContextToSupabase(), 100);
                          } else if (event.type === 'galeria') {
                            const updated = (galeriaList || []).filter(i => i.id !== event.data.id && i.date !== event.data.date);
                            setGaleriaList(updated);
                            setTimeout(() => saveContextToSupabase(), 100);
                          }
                        };

                        const safeClinicalHistory = clinicalHistory || [];
                        const safeOdontogramaList = odontogramaList || [];
                        const safeTratamentosList = tratamentosList || [];
                        const safeAnamneseList = anamneseList || [];
                        const safeGaleriaList = galeriaList || [];

                        const timelineEvents = [
                          ...safeClinicalHistory.filter(i=>i).map(item => ({ type: 'clinical', date: item.date || new Date().toISOString(), data: item })),
                          ...safeOdontogramaList.filter(i=>i).map(item => ({ type: 'odontograma', date: item.date || new Date().toISOString(), data: item })),
                          ...safeTratamentosList.filter(i=>i).map(item => ({ type: 'tratamento', date: item.date || new Date().toISOString(), data: item })),
                          ...safeAnamneseList.filter(i=>i).map(item => ({ type: 'anamnese', date: item.date || new Date().toISOString(), data: item })),
                          ...safeGaleriaList.filter(i=>i).map(item => ({ type: 'galeria', date: item.date || item.createdTime || new Date().toISOString(), data: item })),
                        ].sort((a, b) => {
                          const timeA = new Date(a.date).getTime() || 0;
                          const timeB = new Date(b.date).getTime() || 0;
                          return timeB - timeA;
                        });

                        if (timelineEvents.length === 0) {
                          return <p className="text-[11px] text-zinc-400 italic">Nenhum evento registrado no histórico do paciente.</p>;
                        }

                        return (
                          <div className="relative border-l-2 border-[#E6DEC9]/50 ml-3 pl-5 space-y-6">
                            {timelineEvents.map((event, index) => {
                              let Icon = Activity;
                              let iconBg = 'bg-zinc-100 text-zinc-500';
                              
                              if (event.type === 'clinical') { Icon = ClipboardList; iconBg = 'bg-blue-100 text-blue-600'; }
                              if (event.type === 'odontograma') { Icon = Plus; iconBg = 'bg-[#8B0000] text-white'; }
                              if (event.type === 'tratamento') { Icon = Activity; iconBg = 'bg-emerald-100 text-emerald-600'; }
                              if (event.type === 'anamnese') { Icon = FileText; iconBg = 'bg-amber-100 text-amber-600'; }
                              if (event.type === 'galeria') { Icon = ImageIcon; iconBg = 'bg-teal-100 text-teal-600'; }

                              return (
                                <div key={`tl-${index}`} className="relative">
                                  {/* Timeline Marker */}
                                  <div className={`absolute -left-[30px] w-6 h-6 rounded-full flex items-center justify-center border-2 border-white shadow-sm ${iconBg}`}>
                                    <Icon className="w-3 h-3" />
                                  </div>

                                    <div className="bg-white border border-[#E6DEC9]/60 p-3 rounded-xl shadow-sm text-xs space-y-2 group">
                                      <div className="flex justify-between items-center border-b border-zinc-100 pb-2 mb-2 text-[10px] font-bold font-mono">
                                        <div className="flex gap-2">
                                          <span className="text-[#8B0000]">{normalizeDateDisplay(event.date)}</span>
                                          <span className="text-zinc-400 uppercase tracking-wider">{event.type}</span>
                                        </div>
                                        <button
                                          onClick={(e) => handleDeleteHistoryEvent(e, event)}
                                          className="text-zinc-300 hover:text-red-600 transition-colors opacity-0 group-hover:opacity-100 p-1 rounded-md hover:bg-red-50"
                                          title="Apagar Registro"
                                        >
                                          <Trash2 className="w-3.5 h-3.5" />
                                        </button>
                                      </div>

                                    {/* Clinical Render */}
                                    {event.type === 'clinical' && (
                                      <div className="space-y-1">
                                        {event.data.proceduresPerformed && <p><strong>Procedimento:</strong> {event.data.proceduresPerformed}</p>}
                                        <p className="text-zinc-600 italic">"{event.data.treatmentEvolution || 'Sem evolução'}"</p>
                                        {event.data.recalls && <p className="text-amber-700 font-bold mt-1">🔁 Retorno em: {event.data.recalls}</p>}
                                      </div>
                                    )}

                                    {/* Odontograma Render */}
                                    {event.type === 'odontograma' && (
                                      <div className="flex items-center gap-3">
                                        {event.data.tooth ? (
                                          <div className="w-8 h-8 rounded-full bg-[#8B0000] text-white flex items-center justify-center font-bold text-xs">
                                            🦷 {event.data.tooth}
                                          </div>
                                        ) : (
                                          <div className="w-8 h-8 rounded-full bg-zinc-100 text-zinc-500 flex items-center justify-center">🦷</div>
                                        )}
                                        <div>
                                          <p className="font-bold">{event.data.procedure || 'Mapeamento Atualizado'}</p>
                                          {event.data.situation && <p className="text-[10px] text-zinc-500 uppercase">{event.data.situation}</p>}
                                        </div>
                                      </div>
                                    )}

                                    {/* Tratamento Render */}
                                    {event.type === 'tratamento' && (
                                      <div>
                                        <p className="font-bold">{event.data.name || 'Orçamento / Plano Atualizado'}</p>
                                        <div className="flex gap-2 mt-1">
                                          <span className="px-2 py-0.5 bg-emerald-50 text-emerald-700 rounded-full text-[9px] font-bold uppercase">{event.data.status || 'Aberto'}</span>
                                        </div>
                                      </div>
                                    )}

                                    {/* Anamnese Render */}
                                    {event.type === 'anamnese' && (
                                      <div>
                                        <p className="font-bold">Formulário de Anamnese Respondido</p>
                                        <p className="text-zinc-500 text-[10px]">{Object.keys(event.data.answers || {}).length} respostas registradas.</p>
                                      </div>
                                    )}

                                    {/* Galeria Render */}
                                    {event.type === 'galeria' && (
                                      <div className="flex gap-3 items-center">
                                        <div className="w-12 h-12 bg-zinc-100 rounded-lg overflow-hidden border border-zinc-200">
                                          {event.data.url && <img src={event.data.url} alt="Galeria" className="w-full h-full object-cover" />}
                                        </div>
                                        <div>
                                          <p className="font-bold">Mídia Adicionada</p>
                                          {event.data.description && <p className="text-zinc-500 text-[10px]">{event.data.description}</p>}
                                        </div>
                                      </div>
                                    )}

                                  </div>
                                </div>
                              );
                            })}
                          </div>
                        );
                      })()}
                    </div>
                  )}

                  {/* Panel: Orçamentos — Card-based budget management */}
                  {activeDetailTab === 'treatment_plan' && (
                    <div className="space-y-6 animate-fade-in-up">
                      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-zinc-100 pb-4">
                        <div>
                          <span className="text-[10px] uppercase font-bold text-amber-800 tracking-wider font-mono">GESTÃO DE ORÇAMENTOS</span>
                          <h4 className="font-serif font-bold text-lg text-[#8B0000] mt-0.5">Orçamentos do Paciente</h4>
                        </div>
                        <button
                          onClick={() => {
                            if (onNewProposal) {
                              onNewProposal(selectedPatient.name);
                              setActiveDetailTab('plan_editor');
                            }
                          }}
                          className="px-4 py-2 bg-[#8B0000] hover:bg-[#a32c3d] text-[#FAF8F5] text-xs font-bold uppercase rounded-lg transition-colors cursor-pointer flex items-center gap-1.5"
                        >
                          <Plus className="w-3.5 h-3.5" /> Novo Orçamento
                        </button>
                      </div>

                      {driveProposals.length === 0 ? (
                        <div className="p-8 text-center bg-[#FAF8F5] border border-dashed rounded-2xl border-zinc-200">
                          <p className="text-xs text-zinc-555 italic">Nenhum orçamento localizado para esta paciente.</p>
                          <p className="text-[10px] text-zinc-400 mt-1">Crie um novo orçamento pelo botão acima ou pela aba Planejamento.</p>
                        </div>
                      ) : (
                        <div className="space-y-4">
                          {driveProposals.map((prop) => {
                            // Compute progress from loaded data or cache
                            const propData = prop.content || (selectedProposalId === prop.id ? selectedProposalData : null);
                            const instances = propData ? getProcedureInstancesFromProposal(propData) : [];
                            const total = instances.length;
                            const completed = instances.filter((i: any) => { const s = (i.status || '').toLowerCase().trim(); return s === 'executado' || s === 'realizado'; }).length;
                            const percent = total > 0 ? Math.round((completed / total) * 100) : 0;
                            const lastCompleted = instances
                              .filter((i: any) => { const s = (i.status || '').toLowerCase().trim(); return s === 'executado' || s === 'realizado'; })
                              .sort((a: any, b: any) => (b.updatedAt || '').localeCompare(a.updatedAt || ''))[0];
                            const proposalStatus = propData?.proposal?.status || 'Aguardando Aprovação';
                            const createdDate = new Date(prop.createdTime || prop.modifiedTime).toLocaleDateString('pt-BR');
                            const totalValue = instances.reduce((sum: number, i: any) => sum + (i.price || 0), 0);
                            const paidOrExecutedValue = instances
                              .filter((i: any) => {
                                const s = (i.status || '').toLowerCase().trim();
                                return s === 'executado' || s === 'realizado' || i.paid === true;
                              })
                              .reduce((sum: number, i: any) => sum + (i.price || 0), 0);
                            const openValue = totalValue - paidOrExecutedValue;

                            const statusConfig: Record<string, { emoji: string; bg: string; text: string; border: string }> = {
                              'Aberto (paciente não pagou)': { emoji: '🔴', bg: 'bg-rose-50', text: 'text-rose-800', border: 'border-rose-200' },
                              'Aprovado (paciente pagou)': { emoji: '🟢', bg: 'bg-emerald-50', text: 'text-emerald-800', border: 'border-emerald-200' },
                              'Aguardando Aprovação': { emoji: '⏳', bg: 'bg-amber-50', text: 'text-amber-800', border: 'border-amber-200' },
                              'Em Andamento': { emoji: '🔄', bg: 'bg-blue-50', text: 'text-blue-800', border: 'border-blue-200' },
                              'Concluído': { emoji: '✅', bg: 'bg-emerald-50', text: 'text-emerald-800', border: 'border-emerald-200' },
                              'Arquivado': { emoji: '📁', bg: 'bg-zinc-50', text: 'text-zinc-600', border: 'border-zinc-200' },
                            };
                            const sc = statusConfig[proposalStatus] || statusConfig['Aguardando Aprovação'];

                            return (
                              <div key={prop.id} className={`bg-white border rounded-2xl shadow-sm overflow-hidden transition-all hover:shadow-md ${selectedProposalId === prop.id ? 'ring-2 ring-[#8B0000]/30' : 'border-[#E6DEC9]'}`}>
                                {/* Card Header */}
                                <div className="p-5 space-y-3">
                                  <div className="flex flex-col sm:flex-row justify-between sm:items-start gap-3">
                                    <div className="space-y-1 flex-1 min-w-0">
                                      <div className="flex items-center gap-2">
                                        <h5 className="font-serif font-bold text-sm text-[#8B0000] truncate capitalize" title={prop.name}>
                                          {prop.name.replace(/^Orcamentos\//, '').replace(/\.json$/i, '').replace(/^orcamento_salvo_/, '').replace(/^orcamento_salvo/, '').replace(/^orcamento_ativo/, 'Orçamento Ativo').replace(/_/g, ' ').trim() || 'Orçamento'}
                                        </h5>
                                        <button
                                          type="button"
                                          onClick={() => renameSupabaseProposalFile(prop.id, prop.name)}
                                          className="text-zinc-400 hover:text-[#8B0000] p-1 transition-colors cursor-pointer"
                                          title="Editar nome do orçamento"
                                        >
                                          <Pencil className="w-3.5 h-3.5" />
                                        </button>
                                      </div>
                                      <div className="flex flex-wrap gap-x-4 gap-y-1.5 text-[10px] text-zinc-500">
                                        <span>📅 Criado: <strong className="text-zinc-700">{createdDate}</strong></span>
                                        {lastCompleted && <span>⏱️ Última baixa: <strong className="text-zinc-700">{lastCompleted.updatedAt || '—'}</strong></span>}
                                        {total > 0 && <span>🦷 <strong className="text-zinc-700">{total}</strong> procedimentos</span>}
                                        <span>💰 Total: <strong className="text-zinc-800">{formatBRL(totalValue)}</strong></span>
                                        <span>🟢 Pago/Executado: <strong className="text-emerald-700">{formatBRL(paidOrExecutedValue)}</strong></span>
                                        <span>🔴 Em aberto: <strong className="text-rose-750">{formatBRL(openValue)}</strong></span>
                                      </div>
                                    </div>

                                    {/* Status Selector + Visual Feedback */}
                                    <div className="flex items-center gap-2 shrink-0">
                                      {savingStatusMap[`prop-${prop.id}`] === 'saving' && (
                                        <span className="inline-flex items-center gap-1 text-[10px] font-bold text-amber-700 bg-amber-50 border border-amber-200 px-2.5 py-1 rounded-full animate-pulse">
                                          <Loader2 className="w-3 h-3 animate-spin" /> Salvando...
                                        </span>
                                      )}
                                      {savingStatusMap[`prop-${prop.id}`] === 'saved' && (
                                        <span className="inline-flex items-center gap-1 text-[10px] font-bold text-emerald-700 bg-emerald-50 border border-emerald-200 px-2.5 py-1 rounded-full transition-all">
                                          ✓ Salvo
                                        </span>
                                      )}
                                      <select
                                        value={proposalStatus}
                                        onChange={async (e) => {
                                          const baseProposalData = prop.content || (selectedProposalId === prop.id ? selectedProposalData : null) || { proposal: {} };
                                          const newStatus = e.target.value;
                                          let paymentMethodSelected = baseProposalData.proposal?.paymentMethod || 'PIX';

                                          if (newStatus === 'Aprovado (paciente pagou)') {
                                            const allowedMethods = ['PIX', 'Dinheiro', 'Cartão de Crédito', 'Cartão de Débito'];
                                            const methodInput = window.prompt(
                                              "Confirmar pagamento do orçamento.\nSelecione a forma de pagamento (PIX, Dinheiro, Cartão de Crédito, Cartão de Débito):",
                                              paymentMethodSelected
                                            );
                                            if (methodInput === null) {
                                              // Cancel the selection change
                                              return;
                                            }
                                            const cleanedInput = methodInput.trim().replace(/[^a-zA-Z0-9 ]/g, '');
                                            const matched = allowedMethods.find(
                                              m => m.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "") ===
                                                   cleanedInput.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "")
                                            );
                                            if (matched) {
                                              paymentMethodSelected = matched as any;
                                            } else {
                                              alert("Método de pagamento inválido. Usando PIX como padrão.");
                                              paymentMethodSelected = 'PIX';
                                            }
                                          }

                                          const updated = {
                                            ...baseProposalData,
                                            proposal: {
                                              ...(baseProposalData.proposal || {}),
                                              status: newStatus,
                                              paymentMethod: paymentMethodSelected
                                            }
                                          };

                                          const cardStatusKey = `prop-${prop.id}`;
                                          markStatusSaving(cardStatusKey);

                                          // 1. Grava instantaneamente no cache local (0ms) para sobreviver a F5 imediato
                                          if (selectedPatient?.id) {
                                            saveProposalOverrideLocally(selectedPatient.id, prop.id, prop.name, updated);
                                          }
                                          
                                          // 2. Atualiza estados da tela imediatamente
                                          setSelectedProposalId(prop.id);
                                          setSelectedProposalData(updated);
                                          setActiveTreatmentPlan(updated);
                                          setActiveProposal(updated.proposal);
                                          
                                          // 3. Atualiza lista de propostas em memória
                                          setSupabaseProposals(prev => prev.map(p => p.id === prop.id ? {
                                            ...p,
                                            content: updated,
                                            appProperties: { ...(p.appProperties || {}), status: newStatus }
                                          } : p));

                                          // Finance integration: only insert, do not delete if status is changed away (per user request)
                                          if (newStatus === 'Aprovado (paciente pagou)' && selectedPatient) {
                                            const budgetPayId = 'pay-budget-' + prop.id.replace(/[^a-zA-Z0-9-]/g, '_');
                                            
                                            // Calculate total budget value
                                            let totalAmount = 0;
                                            if (updated.simulations && updated.selectedPlanIndex !== undefined && updated.simulations[updated.selectedPlanIndex]) {
                                              totalAmount = updated.simulations[updated.selectedPlanIndex].custoTotal || 0;
                                            } else {
                                              const sections = updated.sections || [];
                                              const procedures = updated.procedures || [];
                                              sections.forEach((sec: any) => {
                                                sec.markers?.forEach((marker: any) => {
                                                  if (marker.procedureInstances && marker.procedureInstances.length > 0) {
                                                    marker.procedureInstances.forEach((inst: any) => {
                                                      totalAmount += (inst.includeFinancial !== false ? (inst.price || 0) : 0);
                                                    });
                                                  } else if (marker.procedures) {
                                                    marker.procedures.forEach((pid: any) => {
                                                      const proc = procedures.find((p: any) => p.id === pid);
                                                      totalAmount += (proc ? (proc.price || 0) : 0);
                                                    });
                                                  }
                                                });
                                              });
                                            }

                                            const description = `Orçamento: ${prop.name.replace('.json', '').replace('orcamento_salvo', 'Orçamento').replace(/_/g, ' ')} - Aprovado e Pago`;

                                            // 1. Add to patient's individual pagamentosList if not already present
                                            const hasLocal = pagamentosList.some((p: any) => p.id === budgetPayId);
                                            let updatedLocalList = [...pagamentosList];
                                            if (!hasLocal) {
                                              const newLocalPayment = {
                                                id: budgetPayId,
                                                patientId: selectedPatient.id,
                                                date: new Date().toISOString().split('T')[0],
                                                method: paymentMethodSelected,
                                                paymentMethod: paymentMethodSelected,
                                                description: description,
                                                value: totalAmount,
                                                amount: totalAmount,
                                                status: 'Pago'
                                              };
                                              updatedLocalList.push(newLocalPayment);
                                              setPagamentosList(updatedLocalList);
                                            }

                                            // 2. Add to global agnaldo_dent_financeiro in LocalStorage
                                            const globalFinanceStr = localStorage.getItem('agnaldo_dent_financeiro');
                                            let globalFinance: any[] = [];
                                            if (globalFinanceStr) {
                                              try {
                                                globalFinance = JSON.parse(globalFinanceStr);
                                              } catch (e) {
                                                console.error(e);
                                              }
                                            }
                                            const hasGlobal = globalFinance.some((p: any) => p.id === budgetPayId);
                                            if (!hasGlobal) {
                                              globalFinance.unshift({
                                                id: budgetPayId,
                                                patientId: selectedPatient.id,
                                                patientName: selectedPatient.name,
                                                date: new Date().toISOString(),
                                                amount: totalAmount,
                                                paymentMethod: paymentMethodSelected,
                                                status: 'Pago',
                                                description: description
                                              });
                                              localStorage.setItem('agnaldo_dent_financeiro', JSON.stringify(globalFinance));
                                              window.dispatchEvent(new Event('local-storage'));
                                              window.dispatchEvent(new Event('storage'));
                                            }
                                          }

                                          try {
                                            const targetFolder = driveFolderId || selectedPatient?.id;
                                            if (targetFolder) {
                                              await uploadPatientFileToSupabase(
                                                targetFolder,
                                                new Blob([JSON.stringify(updated)], { type: 'application/json' }),
                                                prop.id
                                              );
                                            }
                                            await saveContextToSupabase();
                                            markStatusSaved(cardStatusKey);
                                          } catch (err) {
                                            console.error('Error saving status:', err);
                                            markStatusSaved(cardStatusKey);
                                          }
                                        }}
                                        className={`text-[10px] font-bold px-3 py-1.5 rounded-full border cursor-pointer focus:outline-none transition-colors ${sc.bg} ${sc.text} ${sc.border}`}
                                      >
                                        <option value="Aberto (paciente não pagou)">🔴 Aberto</option>
                                        <option value="Aprovado (paciente pagou)">🟢 Aprovado</option>
                                        <option value="Aguardando Aprovação">⏳ Aguardando</option>
                                        <option value="Em Andamento">🔄 Em Andamento</option>
                                        <option value="Concluído">✅ Concluído</option>
                                        <option value="Arquivado">📁 Arquivado</option>
                                      </select>
                                    </div>
                                  </div>

                                  {/* Progress Bar */}
                                  {total > 0 && (
                                    <div className="space-y-1.5">
                                      <div className="flex justify-between text-[10px] font-semibold text-zinc-500">
                                        <span>Progresso</span>
                                        <span className="font-mono text-[#8B0000]">{percent}% ({completed}/{total}) - Faltam {100 - percent}%</span>
                                      </div>
                                      <div className="w-full bg-zinc-100 h-2 rounded-full overflow-hidden">
                                        <div
                                          className={`h-full rounded-full transition-all duration-500 ${percent === 100 ? 'bg-emerald-500' : percent > 50 ? 'bg-[#C09553]' : 'bg-[#8B0000]'}`}
                                          style={{ width: `${percent}%` }}
                                        />
                                      </div>
                                    </div>
                                  )}
                                </div>

                                {/* Card Actions Footer */}
                                <div className="bg-[#FAF8F5] px-5 py-3 border-t border-[#E6DEC9]/50 flex items-center gap-2">
                                  <button
                                    type="button"
                                    onClick={() => {
                                      setSelectedProposalId(prop.id);
                                      if (prop.content) {
                                        setSelectedProposalData(prop.content);
                                      }
                                    }}
                                    className={`px-3 py-1.5 text-[10px] font-bold rounded-lg transition-colors cursor-pointer ${selectedProposalId === prop.id ? 'bg-[#8B0000] text-white' : 'bg-white border border-zinc-200 text-zinc-700 hover:bg-zinc-50'}`}
                                  >
                                    {selectedProposalId === prop.id ? '✓ Selecionado' : 'Visualizar'}
                                  </button>
                                  <button
                                    type="button"
                                    onClick={() => {
                                      setSelectedProposalId(prop.id);
                                      if (prop.content) {
                                        setSelectedProposalData(prop.content);
                                      }
                                      setActiveDetailTab('plan_editor');
                                    }}
                                    className="px-3 py-1.5 text-[10px] font-bold rounded-lg bg-white border border-[#C09553]/30 text-[#8B0000] hover:border-[#C09553] transition-colors cursor-pointer"
                                  >
                                    Abrir no Planejador
                                  </button>
                                </div>
                              </div>
                            );
                          })}
                        </div>
                      )}

                      {/* Expanded Proposal Detail (when selected) */}
                      {selectedProposalData && (
                        <div className="border-t border-zinc-200 pt-6 space-y-4">
                          <div className="flex flex-col sm:flex-row justify-between sm:items-center gap-3">
                            <h5 className="font-bold text-xs text-zinc-800 uppercase tracking-wider font-serif">Procedimentos do Orçamento Selecionado</h5>
                            {(() => {
                              const instances = getProcedureInstancesFromProposal(selectedProposalData);
                              const totalValue = instances.reduce((sum: number, i: any) => sum + (i.price || 0), 0);
                              const paidOrExecutedValue = instances
                                .filter((i: any) => {
                                  const s = (i.status || '').toLowerCase().trim();
                                  return s === 'executado' || s === 'realizado' || i.paid === true;
                                })
                                .reduce((sum: number, i: any) => sum + (i.price || 0), 0);
                              const openValue = totalValue - paidOrExecutedValue;
                              return (
                                <div className="flex flex-wrap gap-3 text-[10px] bg-zinc-50 border border-zinc-200 rounded-xl px-3 py-1.5 font-semibold text-zinc-650">
                                  <span>Total: <strong className="text-zinc-800">{formatBRL(totalValue)}</strong></span>
                                  <span>Pago/Executado: <strong className="text-emerald-700">{formatBRL(paidOrExecutedValue)}</strong></span>
                                  <span>Em aberto: <strong className="text-rose-700">{formatBRL(openValue)}</strong></span>
                                </div>
                              );
                            })()}
                          </div>
                          
                          {(() => {
                            const instances = getProcedureInstancesFromProposal(selectedProposalData);
                            if (instances.length === 0) return <p className="text-xs text-zinc-400 italic">Nenhum procedimento assinalado.</p>;
                            return (
                              <div className="divide-y divide-zinc-100 border rounded-xl overflow-hidden bg-white shadow-2xs">
                                {instances.map((item) => {
                                  const cleanStatus = (item.status || '').toLowerCase().trim();
                                  const isDone = cleanStatus === 'executado' || cleanStatus === 'realizado';
                                  const isInProgress = cleanStatus === 'em andamento';
                                  const procSaveState = savingStatusMap[`proc-${item.instanceId}`];
                                  return (
                                    <div key={item.instanceId} className="p-3.5 flex items-center gap-3">
                                      <div className={`w-2.5 h-2.5 rounded-full shrink-0 ${isDone ? 'bg-emerald-500' : isInProgress ? 'bg-amber-400' : 'bg-zinc-300'}`} />
                                      <div className="flex-1 min-w-0">
                                        <div className="flex items-center gap-2">
                                          <span className="bg-[#8B0000] text-white text-[8px] font-bold px-1.5 py-0.5 rounded">{item.toothNumber ? `D${item.toothNumber}` : 'Geral'}</span>
                                          <span className="text-xs font-bold text-zinc-800 truncate">{item.name}</span>
                                        </div>
                                        {item.updatedAt && <p className="text-[9px] text-zinc-400 mt-0.5">Atualizado: {item.updatedAt}</p>}
                                      </div>
                                      <span className="text-xs font-mono font-bold text-zinc-600 shrink-0 mr-2">{formatBRL(item.price)}</span>
                                      
                                      {procSaveState === 'saving' && (
                                        <span className="inline-flex items-center gap-1 text-[9px] font-bold text-amber-700 bg-amber-50 border border-amber-200 px-2 py-0.5 rounded-full animate-pulse shrink-0">
                                          <Loader2 className="w-2.5 h-2.5 animate-spin" /> Salvando...
                                        </span>
                                      )}
                                      {procSaveState === 'saved' && (
                                        <span className="inline-flex items-center gap-1 text-[9px] font-bold text-emerald-700 bg-emerald-50 border border-emerald-200 px-2 py-0.5 rounded-full shrink-0 transition-all">
                                          ✓ Salvo
                                        </span>
                                      )}

                                      {/* Interactive Status Selector Dropdown */}
                                      <select
                                        value={isDone ? 'executado' : isInProgress ? 'em andamento' : 'não realizado'}
                                        onChange={(e) => handleUpdateProcedureStatus(
                                          selectedProposalData,
                                          item.sectionId,
                                          item.markerId,
                                          item.instanceId,
                                          e.target.value as any
                                        )}
                                        className={`text-[9px] font-bold px-3 py-1 rounded-full uppercase cursor-pointer border outline-none ${
                                          isDone 
                                            ? 'bg-emerald-50 text-emerald-700 border-emerald-250' 
                                            : isInProgress 
                                              ? 'bg-amber-50 text-amber-700 border-amber-250' 
                                              : 'bg-zinc-50 text-zinc-500 border-zinc-250'
                                        }`}
                                      >
                                        <option value="não realizado">Pendente</option>
                                        <option value="em andamento">Em andamento</option>
                                        <option value="executado">Executado</option>
                                      </select>
                                    </div>
                                  );
                                })}
                              </div>
                            );
                          })()}
                        </div>
                      )}
                    </div>
                  )}

                  {/* Panel: Planejamento Unificado (Mapeamento + Orçamento) */}
                  {(activeDetailTab === 'plan_editor' || activeDetailTab === 'plan_negotiation') && (
                    <div className="space-y-4">
                      {/* Sub-tab navigation */}
                      <div className="flex gap-0 border-b border-zinc-200">
                        <button
                          type="button"
                          onClick={() => setActiveDetailTab('plan_editor')}
                          className={`px-5 py-2.5 text-xs font-bold uppercase tracking-wider transition-all cursor-pointer border-b-2 ${
                            activeDetailTab === 'plan_editor'
                              ? 'text-[#8B0000] border-[#8B0000] bg-[#FAF8F5]'
                              : 'text-zinc-500 border-transparent hover:text-zinc-700 hover:border-zinc-300'
                          }`}
                        >
                          ✨ Mapeamento Clínico
                        </button>
                        <button
                          type="button"
                          onClick={() => setActiveDetailTab('plan_negotiation')}
                          className={`px-5 py-2.5 text-xs font-bold uppercase tracking-wider transition-all cursor-pointer border-b-2 ${
                            activeDetailTab === 'plan_negotiation'
                              ? 'text-[#8B0000] border-[#8B0000] bg-[#FAF8F5]'
                              : 'text-zinc-500 border-transparent hover:text-zinc-700 hover:border-zinc-300'
                          }`}
                        >
                          💰 Emissão de Orçamento
                        </button>
                      </div>

                      {/* Sub-panel: Mapeamento Clínico */}
                      <div className={activeDetailTab === 'plan_editor' ? 'space-y-4 block' : 'hidden'}>
                      {activeSections && activeSections.length > 0 ? (
