                                          </div>
                                          {sec.description && (
                                            <p className="text-[10.5px] text-zinc-600 line-clamp-2">
                                              {sec.description}
                                            </p>
                                          )}
                                        </div>
                                      ))}
                                  </div>
                                )}
                              </div>
                            </div>
                          ) : null}

                          {mappingViewMode === 'classic_photos' && activeSections.map((section, idx) => (
                            <PhotoEditor
                              key={section.id}
                              section={section}
                              procedures={procedures || []}
                              onUpdateSection={(updatedSection) => {
                                const newSections = [...activeSections];
                                newSections[idx] = updatedSection;
                                setActiveSections(newSections);
                              }}
                              onDeleteSection={(section.isExtra || section.id.startsWith('extra-')) ? (secId) => {
                                if (window.confirm(`Deseja realmente remover a foto "${section.title}" do planejamento?`)) {
                                  setActiveSections((prevSections) => prevSections.filter((sec) => sec.id !== secId));
                                }
                              } : undefined}
                              patientName={selectedPatient?.name || ''}
                              driveFolderId={driveFolderId || ''}
                              onAddProcedure={setProcedures ? (newProc) => {
                                setProcedures((prev: any) => [...prev, newProc]);
                              } : undefined}
                              onEditProcedure={setProcedures ? (updatedProc) => {
                                setProcedures((prev: any[]) => prev.map((p) => p.id === updatedProc.id ? updatedProc : p));
                              } : undefined}
                              onDeleteProcedure={setProcedures ? (procId) => {
                                setProcedures((prev: any[]) => prev.filter((p) => p.id !== procId));
                                setActiveSections((prevSections) => prevSections.map((sec) => ({
                                  ...sec,
                                  markers: sec.markers.map((m) => ({
                                    ...m,
                                    procedures: m.procedures.filter((id) => id !== procId)
                                  }))
                                })));
                              } : undefined}
                            />
                          ))}

                          {/* Campo para editar as observações do orçamento */}
                          <div className="bg-white border border-[#E6DEC9] rounded-2xl p-6 shadow-sm mt-6">
                            <h4 className="font-bold text-sm text-[#8B0000] uppercase mb-2 flex items-center gap-2">
                              <FileText className="w-4 h-4 text-[#C09553]" />
                              Observações do Orçamento
                            </h4>
                            <p className="text-xs text-zinc-500 mb-3">Este texto aparecerá no rodapé do documento de proposta de tratamento.</p>
                            <textarea
                              value={activeProposal?.notes || ''}
                              onChange={(e) => {
                                const val = e.target.value;
                                setActiveProposal((prev: any) => {
                                  if (prev) return { ...prev, notes: val };
                                  return { 
                                    patientName: selectedPatient?.name || '', 
                                    status: 'Em Andamento', 
                                    notes: val, 
                                    discountPercent: 5, 
                                    pixDiscountLabel: '5% DESCONTO NO PIX', 
                                    installments: 12, 
                                    installmentsLabel: 'Parcelamento em até 12x (com taxas)', 
                                    customDiscountAmount: 0, 
                                    showTotalBySection: false 
                                  };
                                });
