                            />
                          </div>

                        </div>
                      ) : (
                        <div className="text-center py-16 text-zinc-400">
                          <p className="text-sm">Nenhuma seção de foto disponível.</p>
                          <p className="text-xs mt-1">Selecione um paciente para iniciar o mapeamento clínico.</p>
                        </div>
                      )}
                      </div>

                      {/* Sub-panel: Emissão de Orçamento */}
                      <div className={activeDetailTab === 'plan_negotiation' ? 'block' : 'hidden'}>
                      <NegotiationTab
                        sections={activeSections || []}
                        onUpdateSections={setActiveSections}
                        procedures={procedures || []}
                        proposal={activeProposal || { patientName: selectedPatient?.name || '', status: 'Em Andamento', notes: '', discountPercent: 5, pixDiscountLabel: '5% DESCONTO NO PIX', installments: 12, installmentsLabel: 'Parcelamento em até 12x (com taxas)', customDiscountAmount: 0, showTotalBySection: false }}
                        setProposal={setActiveProposal}
                        clinicSettings={clinicSettings || {}}
                        currentFileId={currentFileId}
                        setCurrentFileId={setCurrentFileId}
                      />
                      </div>
                    </div>
                  )}

                  {/* Panel: Contratos & Termos (PatientDocumentsTab) */}
                  {activeDetailTab === 'plan_documents' && (
                    <div>
                      <PatientDocumentsTab
                        proposal={activeProposal || { patientName: selectedPatient?.name || '', status: 'Em Andamento', notes: '', discountPercent: 5, pixDiscountLabel: '5% DESCONTO NO PIX', installments: 12, installmentsLabel: 'Parcelamento em até 12x (com taxas)', customDiscountAmount: 0, showTotalBySection: false }}
                        clinicSettings={clinicSettings || {}}
                        setClinicSettings={setClinicSettings || (() => {})}
                      />
                    </div>
                  )}

                  {/* Panel E: Communications and warning logs */}
                  {activeDetailTab === 'communication' && (
                    <div className="space-y-6">
                      
                      {/* Envio de WhatsApp e Confirmador com IA */}
                      {selectedPatient && (
                        <AIAssistedWhatsApp 
                          patientName={selectedPatient.name} 
                          patientPhone={selectedPatient.mobile || selectedPatient.phone || ''} 
                        />
                      )}

