                          </p>
                        </div>
                        {driveFolderId && (
                          <span className="text-[10px] font-mono font-semibold text-[#C09553] uppercase border border-[#C09553]/40 px-2 py-0.5 rounded-md bg-white">
                            ID: {driveFolderId}
                          </span>
