export default function MedicalDocumentModal({
  type,
  patientName,
  patientData,
  clinicSettings,
  onClose,
  onEmit,
  initialArrivalTime,
  initialDepartureTime
}: MedicalDocumentModalProps) {
  const [content, setContent] = useState('');
  const [daysOfRest, setDaysOfRest] = useState('1');
  const [atestadoOptions, setAtestadoOptions] = useState({
    retornarAtividades: false,
    repousoHoje: false,
    repousoDias: true,
    acompanhante: false
  });
  const [cid, setCid] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [procedureInput, setProcedureInput] = useState('');
  const [isSuggesting, setIsSuggesting] = useState(false);
  const [aiError, setAiError] = useState('');
  const [arrivalTime, setArrivalTime] = useState(initialArrivalTime || '');
  const [departureTime, setDepartureTime] = useState(initialDepartureTime || '');
  
  // Estilo do documento: 'oficial' (timbre idêntico à clínica), 'economico' (texto simples para economizar tinta), 'pre_impresso' (sem timbre para bloco da gráfica)
  const [docStyle, setDocStyle] = useState<'oficial' | 'economico' | 'pre_impresso'>('oficial');
  const [includeDigitalSignature, setIncludeDigitalSignature] = useState(true);
  const [printTwoCopies, setPrintTwoCopies] = useState(false);

  const COMMON_CIDS = [
    { code: 'K01.1', label: 'Siso / Dente Incluso (K01.1)' },
    { code: 'K04.0', label: 'Pulpite / Canal (K04.0)' },
    { code: 'K04.7', label: 'Abscesso Periapical (K04.7)' },
    { code: 'K05.3', label: 'Periodontite (K05.3)' },
    { code: 'Z01.2', label: 'Consulta de Rotina (Z01.2)' },
    { code: 'Z54.0', label: 'Pós-Cirúrgico (Z54.0)' }
  ];

  const setNowAsDeparture = () => {
    const now = new Date();
    const hh = String(now.getHours()).padStart(2, '0');
    const mm = String(now.getMinutes()).padStart(2, '0');
    setDepartureTime(`${hh}:${mm}`);
  };

  const setArrivalFromDeparture = (minutesAgo: number) => {
    let baseDate = new Date();
    if (departureTime && departureTime.includes(':')) {
      const [h, m] = departureTime.split(':').map(Number);
      if (!isNaN(h) && !isNaN(m)) {
        baseDate = new Date();
        baseDate.setHours(h, m, 0, 0);
      }
    } else {
      setNowAsDeparture();
    }
    const arrivalDate = new Date(baseDate.getTime() - minutesAgo * 60000);
    const hh = String(arrivalDate.getHours()).padStart(2, '0');
    const mm = String(arrivalDate.getMinutes()).padStart(2, '0');
    setArrivalTime(`${hh}:${mm}`);
  };

  const setQuickRestDays = (days: number, isToday?: boolean) => {
    if (days === 0) {
      setAtestadoOptions({
        retornarAtividades: true,
        repousoHoje: false,
        repousoDias: false,
        acompanhante: false
      });
    } else if (isToday) {
      setDaysOfRest('1');
      setAtestadoOptions({
        retornarAtividades: false,
        repousoHoje: true,
        repousoDias: false,
        acompanhante: false
      });
    } else {
      setDaysOfRest(String(days));
      setAtestadoOptions({
        retornarAtividades: false,
        repousoHoje: false,
        repousoDias: true,
        acompanhante: false
      });
    }
  };

  const handleSuggestPrescription = async () => {
    if (!procedureInput) return;
    setIsSuggesting(true);
    setAiError('');
    try {
      const resp = await fetch("/api/suggest-prescription", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ procedure: procedureInput })
      });
      const data = await resp.json();
      if (data.suggestion) {
        setContent(data.suggestion);
      } else {
        setAiError(data.error || "Falha ao gerar sugestão.");
      }
    } catch (err) {
      console.error(err);
      setAiError("Erro ao conectar com a IA. Tente novamente mais tarde.");
    } finally {
      setIsSuggesting(false);
    }
  };

  const generatePDF = async () => {
    setIsGenerating(true);
    try {
      const doc = new jsPDF({
        orientation: 'p',
        unit: 'mm',
        format: 'a4'
      });

      // Carrega o fundo timbrado oficial em alta definição apenas se o modo oficial estiver ativo
      let letterheadImg = '';
      if (docStyle === 'oficial') {
        letterheadImg = await new Promise<string>((resolve) => {
          const img = new Image();
          img.crossOrigin = "Anonymous";
          img.onload = () => {
            const canvas = document.createElement('canvas');
            canvas.width = img.naturalWidth || img.width;
            canvas.height = img.naturalHeight || img.height;
            const ctx = canvas.getContext('2d');
            if (ctx) {
              ctx.drawImage(img, 0, 0);
              resolve(canvas.toDataURL('image/png'));
            } else {
              resolve('');
            }
          };
          img.onerror = () => {
            const fallbackImg = new Image();
            fallbackImg.crossOrigin = "Anonymous";
            fallbackImg.onload = () => {
              const canvas = document.createElement('canvas');
              canvas.width = fallbackImg.naturalWidth || fallbackImg.width;
              canvas.height = fallbackImg.naturalHeight || fallbackImg.height;
              const ctx = canvas.getContext('2d');
              if (ctx) {
                ctx.drawImage(fallbackImg, 0, 0);
                resolve(canvas.toDataURL('image/png'));
              } else {
                resolve('');
              }
            };
            fallbackImg.onerror = () => resolve('');
            fallbackImg.src = '/receituario_template_a4.png';
          };
          img.src = letterheadTemplateA4 || '/receituario_template_a4.png';
        });
      }

      const renderDocumentPage = (viaLabel?: string) => {
        const isEco = docStyle === 'economico';
        const isOfficial = docStyle === 'oficial';

        // 1. Fundo do Timbre Oficial da Clínica
        if (isOfficial && letterheadImg) {
          doc.addImage(letterheadImg, 'PNG', 0, 0, 210, 297, undefined, 'FAST');
        }

        // 1.1 Cabeçalho e Rodapé Econômicos em Texto Normal (Economia de Tinta)
        if (isEco) {
          // Cabeçalho simples e limpo
          doc.setFont('helvetica', 'bold');
          doc.setFontSize(15);
          doc.setTextColor(30, 30, 30);
          const docName = clinicSettings.doctorName || 'DR. AGNALDO FERREIRA';
          doc.text(docName.toUpperCase(), 105, 25, { align: 'center', charSpace: 0.5 });

          doc.setFont('helvetica', 'normal');
          doc.setFontSize(9.5);
          doc.setTextColor(70, 70, 70);
          doc.text(`${(clinicSettings.doctorRole || 'CIRURGIÃO DENTISTA').toUpperCase()}  •  ${clinicSettings.cro || 'CRO-MG 58714'}`, 105, 31, { align: 'center' });

          doc.setLineWidth(0.2);
          doc.setDrawColor(200, 200, 200);
          doc.line(24, 36, 186, 36);

          // Rodapé simples com todos os dados do consultório
          doc.setLineWidth(0.2);
          doc.setDrawColor(200, 200, 200);
          doc.line(24, 274, 186, 274);

          doc.setFont('helvetica', 'bold');
          doc.setFontSize(8.5);
          doc.setTextColor(50, 50, 50);
          doc.text(`Consultório Odontológico ${clinicSettings.doctorName || 'Dr. Agnaldo Ferreira'}`, 105, 279, { align: 'center' });

          doc.setFont('helvetica', 'normal');
          doc.setFontSize(7.5);
          doc.setTextColor(90, 90, 90);
          doc.text(clinicSettings.address || 'Rua dos Goitacazes, 375 - Sala 1001 - Centro, Belo Horizonte - MG, 30190-050', 105, 283.5, { align: 'center' });
          doc.text('Tel: (31) 98513-1303   |   E-mail: dragnaldof@gmail.com   |   Instagram: @dr.agnaldoferreira', 105, 287.5, { align: 'center' });
        }

        // 2. Indicador de Via (1ª Via / 2ª Via)
        if (viaLabel) {
          doc.setFontSize(8);
          doc.setFont("helvetica", "bold");
          doc.setTextColor(140, 140, 140);
          doc.text(`[ ${viaLabel} ]`, 185, isEco ? 22 : 14, { align: 'right' });
        }

        // 3. Título Centralizado do Documento
        const titleY = isEco ? 52 : 96;
        doc.setFontSize(18);
        doc.setFont("helvetica", "bold");
        doc.setTextColor(20, 20, 20);
        if (type === 'atestado') {
          doc.text('ATESTADO', 105, titleY, { align: 'center', charSpace: 2 });
        } else if (type === 'declaracao') {
          doc.setFontSize(15);
          doc.text('DECLARAÇÃO DE COMPARECIMENTO', 105, titleY, { align: 'center', charSpace: 1 });
        } else {
          doc.text('RECEITUÁRIO', 105, titleY, { align: 'center', charSpace: 2 });
        }

        if (type === 'atestado' || type === 'declaracao') {
          const bodyY = isEco ? 68 : 115;
          doc.setFontSize(12);
          doc.setFont("helvetica", "normal");
          doc.setTextColor(30, 30, 30);
          const prefix = type === 'atestado' ? 'Atesto que o(a) paciente ' : 'Declaro que o(a) paciente ';
          const today = new Date().toLocaleDateString('pt-BR');
          const paragraphText = `${prefix}${patientName || '__________________________________________'}, esteve neste consultório recebendo atendimento odontológico no período das ${arrivalTime || '___:___'} às ${departureTime || '___:___'} horas, do dia ${today}${type === 'declaracao' ? ' devendo retornar as suas atividades normais.' : '.'}`;
          
          const splitParagraph = doc.splitTextToSize(paragraphText, 158);
          doc.text(splitParagraph, 24, bodyY, { lineHeightFactor: 1.4 });

          if (type === 'atestado') {
            const boxYStart = bodyY + (splitParagraph.length * 7) + 12;
            const boxSize = 3.5;
            
            doc.setLineWidth(0.35);
            doc.setDrawColor(40, 40, 40);
            
            // Retornar as atividades normais.
            if (atestadoOptions.retornarAtividades) {
              doc.setFillColor(30, 30, 30);
              doc.rect(24, boxYStart, boxSize, boxSize, 'F');
            } else {
              doc.rect(24, boxYStart, boxSize, boxSize);
            }
            doc.text('Retornar as atividades normais.', 30, boxYStart + 2.8);
            
            // Permanecer em repouso hoje.
            if (atestadoOptions.repousoHoje) {
              doc.setFillColor(30, 30, 30);
              doc.rect(24, boxYStart + 10, boxSize, boxSize, 'F');
            } else {
              doc.rect(24, boxYStart + 10, boxSize, boxSize);
            }
            doc.text('Permanecer em repouso hoje.', 30, boxYStart + 12.8);
            
            // Permanecer em repouso ___ dias
            if (atestadoOptions.repousoDias) {
              doc.setFillColor(30, 30, 30);
              doc.rect(24, boxYStart + 20, boxSize, boxSize, 'F');
            } else {
              doc.rect(24, boxYStart + 20, boxSize, boxSize);
            }
            const parsedDays = parseInt(daysOfRest) || 0;
            doc.text(`Permanecer em repouso ${parsedDays > 0 ? parsedDays : '___'} dias a partir desta data.`, 30, boxYStart + 22.8);
            
            // Acompanhante.
            if (atestadoOptions.acompanhante) {
              doc.setFillColor(30, 30, 30);
              doc.rect(24, boxYStart + 30, boxSize, boxSize, 'F');
            } else {
              doc.rect(24, boxYStart + 30, boxSize, boxSize);
            }
            doc.text('Acompanhante.', 30, boxYStart + 32.8);
    
            doc.text(`CID: ${cid || '________________'}`, 24, boxYStart + 48);
          }

        } else {
          // Identificação do Paciente no Receituário
          const patientY = isEco ? 68 : 110;
          doc.setFontSize(12);
          doc.setFont("helvetica", "bold");
          doc.setTextColor(20, 20, 20);
          doc.text("Para: ", 24, patientY);

          const prefixWidth = doc.getTextWidth("Para: ");
          const patientText = (patientName || '__________________________________________').toUpperCase();
          const splitPatient = doc.splitTextToSize(patientText, 158 - prefixWidth);
          doc.text(splitPatient, 24 + prefixWidth, patientY);

          if (isEco) {
            doc.setLineWidth(0.15);
            doc.setDrawColor(220, 220, 220);
            doc.line(24, patientY + (splitPatient.length * 6), 186, patientY + (splitPatient.length * 6));
          }

          // Conteúdo da receita (medicamentos e posologia)
          doc.setFontSize(11);
          doc.setFont("helvetica", "normal");
          doc.setTextColor(30, 30, 30);
          const contentStartY = patientY + (splitPatient.length * 6) + (isEco ? 8 : 6);
          const splitContent = doc.splitTextToSize(content || '', 158);
          doc.text(splitContent, 24, contentStartY, { lineHeightFactor: 1.35 });
        }

        // 4. Assinatura e Carimbo Centralizados
        const bottomY = isEco ? 222 : 232;
        doc.setLineWidth(0.35);
        doc.setDrawColor(120, 120, 120);
        doc.line(65, bottomY, 145, bottomY);
        
        const todayStr = new Date().toLocaleDateString('pt-BR');
        if (includeDigitalSignature) {
          doc.setFontSize(10.5);
          doc.setFont("helvetica", "bold");
          doc.setTextColor(40, 40, 40);
          doc.text(clinicSettings.doctorName || 'Dr. Agnaldo Ferreira', 105, bottomY + 5.5, { align: 'center' });
          doc.setFontSize(8.5);
          doc.setFont("helvetica", "normal");
          doc.setTextColor(90, 90, 90);
          doc.text(`${clinicSettings.doctorRole || 'Cirurgião Dentista'} • ${clinicSettings.cro || 'CRO-MG 58714'}`, 105, bottomY + 10, { align: 'center' });
          doc.setFontSize(8);
          doc.setTextColor(130, 130, 130);
          doc.text(`Data: ${todayStr}`, 105, bottomY + 14.5, { align: 'center' });
        } else {
          doc.setFontSize(10);
          doc.setFont("helvetica", "normal");
          doc.setTextColor(80, 80, 80);
          doc.text("Assinatura e Carimbo", 105, bottomY + 5.5, { align: 'center' });
          doc.setFontSize(8);
          doc.setTextColor(130, 130, 130);
          doc.text(`Data: ${todayStr}`, 105, bottomY + 10, { align: 'center' });
        }
      };

      // Renderiza 1ª Via
      renderDocumentPage(printTwoCopies ? '1ª VIA - PACIENTE' : undefined);

      // Se selecionou 2 Vias, gera a segunda página
      if (printTwoCopies) {
        doc.addPage();
        renderDocumentPage(type === 'receituario' ? '2ª VIA - FARMÁCIA / CLÍNICA' : '2ª VIA - CLÍNICA / ARQUIVO');
      }

      // Output Blob
      const pdfBlob = doc.output('blob');
      const url = URL.createObjectURL(pdfBlob);
      const filename = `${type === 'receituario' ? 'Receituario' : type === 'atestado' ? 'Atestado' : 'Declaracao'}_${patientName.replace(/\s+/g, '_')}.pdf`;

      return { blob: pdfBlob, url, filename };

    } catch (err) {
      console.error("PDF Gen Error:", err);
      throw err;
    } finally {
      setIsGenerating(false);
    }
  };

  // Impressão Direta na Impressora do Consultório (1 Clique)
  const handleDirectPrint = async () => {
    setIsGenerating(true);
    try {
      const { blob } = await generatePDF();
      const blobUrl = URL.createObjectURL(blob);

      let printIframe = document.getElementById('print-doc-iframe') as HTMLIFrameElement;
      if (!printIframe) {
        printIframe = document.createElement('iframe');
        printIframe.id = 'print-doc-iframe';
        printIframe.style.position = 'fixed';
        printIframe.style.right = '0';
        printIframe.style.bottom = '0';
        printIframe.style.width = '0';
        printIframe.style.height = '0';
        printIframe.style.border = '0';
        document.body.appendChild(printIframe);
      }

      printIframe.src = blobUrl;
      printIframe.onload = () => {
        setTimeout(() => {
          try {
            printIframe.contentWindow?.focus();
            printIframe.contentWindow?.print();
          } catch (e) {
            window.open(blobUrl, '_blank')?.print();
          }
        }, 300);
      };

      if (type === 'declaracao' && onEmit) {
        onEmit({ arrivalTime, departureTime });
      }
    } catch (err) {
      console.error("Print Error:", err);
      alert("Erro ao enviar para impressão. Tente novamente.");
    } finally {
      setIsGenerating(false);
    }
  };

  const handleDownload = async () => {
    const { url, filename } = await generatePDF();
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    if (type === 'declaracao' && onEmit) {
      onEmit({ arrivalTime, departureTime });
    }
  };

  const handleSendWhatsApp = async () => {
    const { url, filename, blob } = await generatePDF();
    
    if (type === 'declaracao' && onEmit) {
      onEmit({ arrivalTime, departureTime });
    }

    const docDesc = type === 'receituario' ? 'receituário' : type === 'atestado' ? 'atestado' : 'declaração de comparecimento';

    // Attempt Web Share api on Mobile
    if (navigator.share && navigator.canShare && navigator.canShare({ files: [new File([blob], filename, { type: 'application/pdf' })] })) {
      try {
        await navigator.share({
          title: `Documento Odontológico - ${patientName}`,
          text: `Segue sua ${docDesc}.`,
          files: [new File([blob], filename, { type: 'application/pdf' })]
        });
        return;
      } catch (err) {
        console.error("Share failed", err);
      }
    }

    // Fallback: Download and open WhatsApp Web with text
    const link = document.createElement('a');
    link.href = url;
    link.download = filename;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);

    // After triggering download, open whatsapp
    const cleanNumber = (patientData.mobile || patientData.phone || '').replace(/\D/g, '');
    const message = `Olá ${patientName}, segue seu/sua ${docDesc} em anexo! (Envie o arquivo PDF baixado)`;
    const waUrl = cleanNumber && cleanNumber.length >= 10
      ? `https://wa.me/55${cleanNumber}?text=${encodeURIComponent(message)}`
      : `https://wa.me/?text=${encodeURIComponent(message)}`;

    setTimeout(() => {
       window.open(waUrl, '_blank');
    }, 500);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-zinc-950/75 backdrop-blur-xs">
      <div className={`bg-white rounded-3xl shadow-2xl flex flex-col overflow-hidden font-sans border border-zinc-200 w-full ${type === 'receituario' ? 'max-w-6xl h-[90vh]' : 'max-w-2xl max-h-[90vh]'}`}>
        <div className="flex items-center justify-between px-6 py-4 border-b border-zinc-100 bg-[#FAF8F5]">
          <h2 className="text-xl font-bold text-[#4E1119] flex items-center gap-2">
            <FileText className="w-5 h-5" />
            {type === 'receituario' ? 'Emitir Receituário' : type === 'atestado' ? 'Emitir Atestado' : 'Emitir Declaração'}
          </h2>
          <button
            onClick={onClose}
            className="p-2 text-zinc-400 hover:text-red-500 hover:bg-red-50 rounded-full transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className={`flex-1 ${type === 'receituario' ? 'overflow-hidden' : 'overflow-y-auto'} p-6 space-y-6 flex flex-col min-h-0`}>
          <div className="bg-zinc-50 p-4 rounded-xl border border-zinc-200 shrink-0">
             <p className="text-sm font-semibold text-zinc-700">Paciente: <span className="font-bold text-[#4E1119]">{patientName || 'NÃO INFORMADO'}</span></p>
             <p className="text-xs text-zinc-500 mt-1">
               Contato: {patientData.mobile || patientData.phone || 'Nenhum contato salvo'}
             </p>
          </div>

          {type === 'atestado' || type === 'declaracao' ? (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <div className="flex items-center justify-between mb-1">
                    <label className="block text-xs font-bold text-zinc-500 uppercase">Horário de Chegada</label>
                  </div>
                  <input
                    type="time"
                    value={arrivalTime}
                    onChange={(e) => setArrivalTime(e.target.value)}
                    className="w-full p-2.5 rounded-xl border border-zinc-300 focus:border-[#C09553] focus:ring focus:ring-[#C09553]/20 text-sm font-semibold"
                  />
                  <div className="flex flex-wrap items-center gap-1.5 mt-2">
                    <button
                      type="button"
                      onClick={() => setArrivalFromDeparture(30)}
                      className="px-2 py-0.5 bg-zinc-100 hover:bg-[#C09553]/20 text-zinc-700 hover:text-[#4E1119] rounded text-[11px] font-semibold border border-zinc-200 transition-colors"
                      title="Chegou 30 minutos antes"
                    >
                      -30 min
                    </button>
                    <button
                      type="button"
                      onClick={() => setArrivalFromDeparture(60)}
                      className="px-2 py-0.5 bg-zinc-100 hover:bg-[#C09553]/20 text-zinc-700 hover:text-[#4E1119] rounded text-[11px] font-semibold border border-zinc-200 transition-colors"
                      title="Chegou 1 hora antes"
                    >
                      -1 hora
                    </button>
                    <button
                      type="button"
                      onClick={() => setArrivalFromDeparture(120)}
                      className="px-2 py-0.5 bg-zinc-100 hover:bg-[#C09553]/20 text-zinc-700 hover:text-[#4E1119] rounded text-[11px] font-semibold border border-zinc-200 transition-colors"
                      title="Chegou 2 horas antes"
                    >
                      -2 horas
                    </button>
                  </div>
                </div>
                <div>
                  <div className="flex items-center justify-between mb-1">
                    <label className="block text-xs font-bold text-zinc-500 uppercase">Horário de Saída</label>
                  </div>
                  <input
                    type="time"
                    value={departureTime}
                    onChange={(e) => setDepartureTime(e.target.value)}
                    className="w-full p-2.5 rounded-xl border border-zinc-300 focus:border-[#C09553] focus:ring focus:ring-[#C09553]/20 text-sm font-semibold"
                  />
                  <div className="flex items-center gap-1.5 mt-2">
                    <button
                      type="button"
                      onClick={setNowAsDeparture}
                      className="px-2.5 py-0.5 bg-[#4E1119] hover:bg-[#380c12] text-white rounded text-[11px] font-bold transition-colors shadow-2xs"
                      title="Definir horário atual como saída"
                    >
                      Agora
                    </button>
                  </div>
                </div>
              </div>

              {type === 'atestado' && (
                <>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mt-4">
                    <div>
                      <label className="block text-xs font-bold text-zinc-500 uppercase mb-1">Dias de Repouso</label>
                      <input
                        type="number"
                        min="0"
                        value={daysOfRest}
                        onChange={(e) => setDaysOfRest(e.target.value)}
                        className="w-full p-2.5 rounded-xl border border-zinc-300 focus:border-[#C09553] focus:ring focus:ring-[#C09553]/20 text-sm font-semibold"
                      />
                      {/* Chips de Repouso Rápido */}
                      <div className="flex flex-wrap gap-1.5 mt-2">
                        {[
                          { label: 'Hoje', days: 1, isToday: true },
                          { label: '1 dia', days: 1 },
                          { label: '2 dias', days: 2 },
                          { label: '3 dias', days: 3 },
                          { label: '5 dias', days: 5 },
                          { label: '7 dias', days: 7 },
                          { label: '14 dias', days: 14 }
                        ].map((chip, idx) => (
                          <button
                            key={idx}
                            type="button"
                            onClick={() => setQuickRestDays(chip.days, chip.isToday)}
                            className="px-2 py-0.5 bg-zinc-100 hover:bg-[#4E1119] text-zinc-700 hover:text-white rounded text-[11px] font-bold border border-zinc-200 transition-colors cursor-pointer"
                          >
                            {chip.label}
                          </button>
                        ))}
                      </div>
                    </div>
                    <div>
                      <label className="block text-xs font-bold text-zinc-500 uppercase mb-1">CID (Opcional)</label>
                      <input
                        type="text"
                        placeholder="Ex: K04.0"
                        value={cid}
                        onChange={(e) => setCid(e.target.value)}
                        className="w-full p-2.5 rounded-xl border border-zinc-300 focus:border-[#C09553] focus:ring focus:ring-[#C09553]/20 text-sm font-semibold"
                      />
                      {/* Chips de CIDs Odontológicos Comuns */}
                      <div className="flex flex-wrap gap-1 mt-2">
                        {COMMON_CIDS.map(c => (
                          <button
                            key={c.code}
                            type="button"
                            onClick={() => setCid(c.code)}
                            className={`px-1.5 py-0.5 rounded text-[10px] font-semibold border transition-colors cursor-pointer ${cid === c.code ? 'bg-[#4E1119] text-white border-[#4E1119]' : 'bg-zinc-100 text-zinc-700 border-zinc-200 hover:bg-[#C09553]/20'}`}
                            title={c.label}
                          >
                            {c.code}
                          </button>
                        ))}
                      </div>
                    </div>
                  </div>
                  
                  <div className="bg-zinc-50 p-4 rounded-xl border border-zinc-200 mt-4">
                     <label className="block text-xs font-bold text-zinc-500 uppercase mb-3">Opções do Atestado</label>
                     <div className="space-y-3">
                       <label className="flex items-center gap-3 cursor-pointer">
                         <input type="checkbox" checked={atestadoOptions.retornarAtividades} onChange={e => setAtestadoOptions(prev => ({...prev, retornarAtividades: e.target.checked}))} className="w-5 h-5 text-[#C09553] rounded focus:ring-[#C09553]" />
                         <span className="text-sm font-medium text-zinc-700">Retornar as atividades normais.</span>
                       </label>
                       <label className="flex items-center gap-3 cursor-pointer">
                         <input type="checkbox" checked={atestadoOptions.repousoHoje} onChange={e => setAtestadoOptions(prev => ({...prev, repousoHoje: e.target.checked}))} className="w-5 h-5 text-[#C09553] rounded focus:ring-[#C09553]" />
                         <span className="text-sm font-medium text-zinc-700">Permanecer em repouso hoje.</span>
                       </label>
                       <label className="flex items-center gap-3 cursor-pointer">
                         <input type="checkbox" checked={atestadoOptions.repousoDias} onChange={e => setAtestadoOptions(prev => ({...prev, repousoDias: e.target.checked}))} className="w-5 h-5 text-[#C09553] rounded focus:ring-[#C09553]" />
                         <span className="text-sm font-medium text-zinc-700">Permanecer em repouso ({daysOfRest}) dias a partir desta data.</span>
                       </label>
                       <label className="flex items-center gap-3 cursor-pointer">
                         <input type="checkbox" checked={atestadoOptions.acompanhante} onChange={e => setAtestadoOptions(prev => ({...prev, acompanhante: e.target.checked}))} className="w-5 h-5 text-[#C09553] rounded focus:ring-[#C09553]" />
                         <span className="text-sm font-medium text-zinc-700">Acompanhante.</span>
                       </label>
                     </div>
                  </div>
                </>
              )}
            </div>
          ) : (
            <div className="flex flex-col lg:flex-row gap-6 h-full flex-1 min-h-0 overflow-hidden">
              {/* Left Panel - Protocolos e Fármacos */}
              <div className="w-full lg:w-1/3 flex flex-col gap-4 overflow-y-auto pr-2">
                <div className="bg-white border border-zinc-200 rounded-xl p-4 shadow-sm">
                  <h3 className="text-xs font-bold text-[#4E1119] uppercase mb-3">Protocolos Clínicos</h3>
                  <div className="space-y-2">
                    {PROTOCOLS.map((prot, idx) => (
                      <button
                        key={idx}
                        onClick={() => setContent(prev => prev + (prev ? '\n\n' : '') + prot.items.join('\n'))}
                        className="w-full text-left p-2.5 rounded-lg border border-zinc-200 hover:border-[#C09553] hover:bg-[#FAF8F5] transition-all group flex items-start justify-between"
                      >
                        <span className="text-[11px] font-bold text-zinc-700">{prot.name}</span>
                        <Plus className="w-3.5 h-3.5 text-zinc-400 group-hover:text-[#C09553]" />
                      </button>
                    ))}
                  </div>
                </div>

                <div className="bg-white border border-zinc-200 rounded-xl p-4 shadow-sm">
                  <h3 className="text-xs font-bold text-[#4E1119] uppercase mb-3">Adicionar Fármaco</h3>
                  <div className="space-y-2">
                    {DRUGS.map((drug, idx) => (
                      <button
                        key={'d'+idx}
                        onClick={() => {
                           const drugLine = `${drug.name} --------------------------- 1 cx\n${drug.posology}`;
                           setContent(prev => prev + (prev ? '\n\n' : '') + drugLine);
                        }}
                        className="w-full relative text-left p-2.5 rounded-lg border border-zinc-200 hover:border-[#C09553] hover:bg-[#FAF8F5] transition-all flex flex-col gap-1 group"
                      >
                        <div className="flex items-start justify-between w-full">
                           <span className="text-[11px] font-bold text-zinc-800">{drug.name}</span>
                           <Plus className="w-3.5 h-3.5 text-zinc-400 group-hover:text-[#C09553] flex-shrink-0" />
                        </div>
                        <span className="text-[9px] font-semibold text-zinc-400 uppercase">{drug.class}</span>
                        <span className="text-[10px] text-zinc-500 leading-tight">{drug.posology}</span>
                      </button>
                    ))}
                  </div>
                </div>

                <div className="bg-[#FAF8F5] p-4 rounded-xl border border-[#C09553]/30 flex flex-col gap-3">
                  <label className="block text-xs font-bold text-[#4E1119] uppercase">Gerar com IA</label>
                  <div className="flex flex-col gap-2">
                    <input
                      type="text"
                      placeholder="Ex: Extração siso inferior direito"
                      value={procedureInput}
                      onChange={(e) => setProcedureInput(e.target.value)}
                      className="w-full px-3 py-2 text-xs rounded-lg border border-zinc-300 focus:border-[#C09553] focus:ring focus:ring-[#C09553]/20"
                    />
                    <button
                      onClick={handleSuggestPrescription}
                      disabled={isSuggesting || !procedureInput}
                      className="px-3 py-2 w-full bg-[#4E1119] text-white text-xs font-bold rounded-lg hover:bg-[#3a0c12] transition-colors flex items-center justify-center gap-2 disabled:opacity-50"
                    >
                      {isSuggesting ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Sparkles className="w-3.5 h-3.5" />}
                      Sugerir
                    </button>
                  </div>
                  {aiError && (
                    <p className="text-red-600 text-xs font-medium">{aiError}</p>
                  )}
                </div>
              </div>

              {/* Right Panel - Receita Viewer */}
              <div className="w-full lg:w-2/3 flex flex-col h-full bg-zinc-100 rounded-xl overflow-hidden border border-zinc-200">
                <div className="bg-zinc-200 py-2 px-4 shadow-inner border-b border-zinc-300 flex items-center justify-between z-10">
                   <div className="flex items-center gap-2">
                     <span className="text-[10px] font-bold text-zinc-600 uppercase tracking-wider">Visualização em Tempo Real (Folha A4)</span>
                     {docStyle === 'oficial' && (
                       <span className="px-1.5 py-0.5 bg-[#4E1119] text-white text-[9px] font-bold rounded">Timbre Oficial</span>
                     )}
                     {docStyle === 'economico' && (
                       <span className="px-1.5 py-0.5 bg-emerald-700 text-white text-[9px] font-bold rounded">Modo Econômico</span>
                     )}
                     {docStyle === 'pre_impresso' && (
                       <span className="px-1.5 py-0.5 bg-zinc-700 text-white text-[9px] font-bold rounded">Papel da Gráfica</span>
                     )}
                   </div>
                   <button onClick={() => setContent('')} className="text-[10px] font-bold text-red-600 hover:underline cursor-pointer">Limpar</button>
                </div>
                
                <div className="flex-1 overflow-y-auto p-4 flex justify-center items-start bg-zinc-200/60">
                  <div 
                    className="w-full max-w-[210mm] shadow-xl relative rounded-xs border border-zinc-300 transition-all select-none overflow-hidden" 
                    style={{
                      aspectRatio: '210 / 297',
                      backgroundImage: docStyle === 'oficial' ? `url(${letterheadTemplateA4 || '/receituario_template_a4.png'})` : 'none',
                      backgroundColor: '#ffffff',
                      backgroundSize: '100% 100%',
                      backgroundRepeat: 'no-repeat'
                    }}
                  >
                    {/* Header Econômico (em texto simples) */}
                    {docStyle === 'economico' && (
                      <div className="absolute top-[4%] left-[8%] right-[8%] pb-2.5 border-b border-zinc-300 text-center pointer-events-none">
                        <h1 className="text-sm sm:text-base md:text-lg font-bold text-zinc-800 tracking-wide uppercase">
                          {clinicSettings.doctorName || 'DR. AGNALDO FERREIRA'}
                        </h1>
                        <p className="text-[10px] sm:text-xs text-zinc-500 font-medium tracking-wide mt-0.5 uppercase">
                          {clinicSettings.doctorRole || 'CIRURGIÃO DENTISTA'} • {clinicSettings.cro || 'CRO-MG 58714'}
                        </p>
                      </div>
                    )}

                    {/* Badge do Papel da Gráfica */}
                    {docStyle === 'pre_impresso' && (
                      <div className="absolute top-4 left-6 text-[10px] text-zinc-400 font-mono">
                        [Modo Folha Pré-Impressa da Gráfica - Sem fundo nem cabeçalho]
                      </div>
                    )}

                    {/* Título Centralizado */}
                    <div 
                      className="absolute left-0 right-0 text-center pointer-events-none"
                      style={{ top: docStyle === 'economico' ? '16.5%' : '32.3%' }}
                    >
                      <h2 className="text-base sm:text-lg md:text-xl font-black text-zinc-800 tracking-[0.2em] uppercase">
                        RECEITUÁRIO
                      </h2>
                    </div>

                    {/* Identificação da Paciente */}
                    <div 
                      className="absolute left-[11.5%] right-[13.5%] pointer-events-none"
                      style={{ top: docStyle === 'economico' ? '22%' : '37%' }}
                    >
                      <div className={`text-xs sm:text-sm font-bold text-zinc-900 flex items-baseline gap-1 ${docStyle === 'economico' ? 'pb-1 border-b border-zinc-200' : ''}`}>
                        <span>Para:</span>
                        <span className="font-extrabold underline uppercase tracking-wide truncate">
                          {patientName || '________________________'}
                        </span>
                      </div>
                    </div>

                    {/* Caixa de Texto do Receituário */}
                    <div 
                      className="absolute left-[11.5%] right-[13.5%] flex flex-col"
                      style={{
                        top: docStyle === 'economico' ? '26.5%' : '41.5%',
                        bottom: docStyle === 'economico' ? '25%' : '23%'
                      }}
                    >
                      <textarea
                        className="w-full h-full resize-none border-none focus:ring-0 bg-transparent py-0 px-0 text-xs sm:text-sm font-medium text-zinc-800 leading-relaxed placeholder:text-zinc-400 placeholder:italic select-text cursor-text"
                        placeholder="Selecione um protocolo ou fármaco à esquerda, ou digite livremente a prescrição aqui..."
                        value={content}
                        onChange={(e) => setContent(e.target.value)}
                      />
                    </div>

                    {/* Bloco de Assinatura Centralizado */}
                    <div 
                      className="absolute left-0 right-0 flex justify-center pointer-events-none"
                      style={{ bottom: docStyle === 'economico' ? '15%' : '17%' }}
                    >
                      <div className="text-center w-56 sm:w-64 pt-1.5 border-t border-zinc-400">
                        {includeDigitalSignature ? (
                          <>
                            <p className="text-[11px] sm:text-xs font-bold text-zinc-800 leading-tight">
                              {clinicSettings.doctorName || 'Dr. Agnaldo Ferreira'}
                            </p>
                            <p className="text-[9px] sm:text-[10px] text-zinc-600 leading-tight mt-0.5">
                              {clinicSettings.doctorRole || 'Cirurgião Dentista'} • {clinicSettings.cro || 'CRO-MG 58714'}
                            </p>
                            <p className="text-[8px] sm:text-[9px] text-zinc-400 mt-0.5">
                              Data: {new Date().toLocaleDateString('pt-BR')}
                            </p>
                          </>
                        ) : (
                          <p className="text-[10px] sm:text-[11px] text-zinc-500 font-medium">Assinatura e Carimbo</p>
                        )}
                      </div>
                    </div>

                    {/* Rodapé Econômico (em texto simples) */}
                    {docStyle === 'economico' && (
                      <div className="absolute bottom-[3.5%] left-[8%] right-[8%] pt-2 border-t border-zinc-200 text-center pointer-events-none text-zinc-600">
                        <p className="text-[9px] sm:text-[10px] font-bold text-zinc-700">
                          Consultório Odontológico {clinicSettings.doctorName || 'Dr. Agnaldo Ferreira'}
                        </p>
                        <p className="text-[8px] sm:text-[9px] text-zinc-500 mt-0.5">
                          {clinicSettings.address || 'Rua dos Goitacazes, 375 - Sala 1001 - Centro, Belo Horizonte - MG, 30190-050'}
                        </p>
                        <p className="text-[8px] sm:text-[9px] text-zinc-400 mt-0.5">
                          Tel: (31) 98513-1303 | E-mail: dragnaldof@gmail.com | Instagram: @dr.agnaldoferreira
                        </p>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Barra de Opções para Impressão Física no Consultório */}
        <div className="px-6 py-2.5 bg-[#FAF8F5] border-t border-zinc-200 flex flex-wrap items-center justify-between gap-4 text-xs shrink-0">
          <div className="flex flex-wrap items-center gap-4">
            {/* Seletor de Estilo */}
            <div className="flex items-center gap-1.5 bg-zinc-200/80 p-1 rounded-xl">
              <button
                type="button"
                onClick={() => setDocStyle('oficial')}
                className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all flex items-center gap-1.5 cursor-pointer ${
                  docStyle === 'oficial'
                    ? 'bg-[#4E1119] text-white shadow-xs'
                    : 'text-zinc-700 hover:text-zinc-900 hover:bg-zinc-100'
                }`}
                title="Timbre oficial idêntico ao modelo da clínica (logo AF, marcas d'água laterais e rodapé bordô)"
              >
                <span>Timbre Oficial</span>
              </button>

              <button
                type="button"
                onClick={() => setDocStyle('economico')}
                className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all flex items-center gap-1.5 cursor-pointer ${
                  docStyle === 'economico'
                    ? 'bg-emerald-700 text-white shadow-xs'
                    : 'text-zinc-700 hover:text-zinc-900 hover:bg-zinc-100'
                }`}
                title="Economiza tinta com fonte normal e layout limpo, com todos os dados do consultório"
              >
                <span>Econômico (Sem Imagens)</span>
              </button>

              <button
                type="button"
                onClick={() => setDocStyle('pre_impresso')}
                className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all flex items-center gap-1.5 cursor-pointer ${
                  docStyle === 'pre_impresso'
                    ? 'bg-zinc-800 text-white shadow-xs'
                    : 'text-zinc-700 hover:text-zinc-900 hover:bg-zinc-100'
                }`}
                title="Apenas texto (para quem coloca a folha do bloco físico da gráfica na impressora)"
              >
                <span>Papel da Gráfica</span>
              </button>
            </div>

            <label className="flex items-center gap-2 cursor-pointer font-medium text-zinc-700 select-none hover:text-zinc-900">
              <input
                type="checkbox"
                checked={includeDigitalSignature}
                onChange={(e) => setIncludeDigitalSignature(e.target.checked)}
                className="w-4 h-4 text-[#4E1119] rounded focus:ring-[#4E1119] cursor-pointer"
              />
              <span>Assinatura/Carimbo inclusos</span>
            </label>

            <label className="flex items-center gap-2 cursor-pointer font-medium text-zinc-700 select-none hover:text-zinc-900">
              <input
                type="checkbox"
                checked={printTwoCopies}
                onChange={(e) => setPrintTwoCopies(e.target.checked)}
                className="w-4 h-4 text-[#4E1119] rounded focus:ring-[#4E1119] cursor-pointer"
              />
              <span>Imprimir em 2 Vias</span>
            </label>
          </div>
          <span className="text-[11px] text-zinc-500 font-medium bg-zinc-100 px-2.5 py-1 rounded-md border border-zinc-200">Formato: Folha A4 (210 x 297 mm)</span>
        </div>

        <div className="p-4 border-t border-zinc-200 bg-white flex flex-col sm:flex-row items-center gap-3 justify-end shrink-0">
          <button
            type="button"
            onClick={handleDirectPrint}
            disabled={isGenerating}
            className="w-full sm:w-auto px-6 py-2.5 bg-[#4E1119] text-white font-bold rounded-xl hover:bg-[#380c12] transition-all shadow-sm hover:shadow flex items-center justify-center gap-2 cursor-pointer disabled:opacity-50"
            title="Enviar diretamente para a impressora do consultório"
          >
            {isGenerating ? <Loader2 className="w-4 h-4 animate-spin" /> : <Printer className="w-4 h-4 text-[#C09553]" />}
            Imprimir Agora
          </button>

          <button
            type="button"
            onClick={handleDownload}
            disabled={isGenerating}
            className="w-full sm:w-auto px-4 py-2.5 bg-zinc-100 text-zinc-700 font-bold rounded-xl hover:bg-zinc-200 border border-zinc-300 transition-colors flex items-center justify-center gap-2 cursor-pointer"
          >
            {isGenerating ? <Loader2 className="w-4 h-4 animate-spin" /> : <Download className="w-4 h-4" />}
            Baixar PDF
          </button>

          <button
            type="button"
            onClick={handleSendWhatsApp}
            disabled={isGenerating}
            className="w-full sm:w-auto px-4 py-2.5 bg-[#25D366] text-white font-bold rounded-xl hover:bg-[#128C7E] transition-colors flex items-center justify-center gap-2 cursor-pointer"
          >
            {isGenerating ? <Loader2 className="w-4 h-4 animate-spin" /> : <Smartphone className="w-4 h-4" />}
            WhatsApp
          </button>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { 
  Camera, 
  Check, 
  Loader2, 
  Calendar, 
  User, 
  Plus, 
  Clock, 
  Phone, 
  ArrowRight, 
  Upload, 
  Trash2, 
  SwitchCamera, 
  Zap, 
  Sparkles, 
  ChevronRight, 
  ImageIcon, 
  Smartphone, 
  MessageCircle,
  FileText,
  BookmarkCheck,
  AlertCircle,
  Scissors,
  Focus,
  LayoutGrid
} from 'lucide-react';
import { createCalendarEvent } from '../lib/calendar';
import { uploadPatientFileToSupabase } from '../lib/storage';
import { compressImage, compressFileToDataUrl } from '../lib/imageUtils';
import { PhotoSection, Procedure, TreatmentProposal, ClinicSettings } from '../types';
import { getDefaultToothCoordinates } from '../constants';
import { format, parseISO, addMinutes } from 'date-fns';

interface MobileWorkspaceProps {
  sections: PhotoSection[];
  onUpdateSection: (updated: PhotoSection) => void;
  procedures: Procedure[];
  proposal: TreatmentProposal;
  setProposal: React.Dispatch<React.SetStateAction<TreatmentProposal>>;
  clinicSettings: ClinicSettings;
  onExitMobile: () => void;
  onNewProposalForPatient: (name: string) => void;
}

interface QuickLead {
  id: string;
  name: string;
  phone: string;
  date: string;
  time: string;
  status: 'Pendente' | 'Criado';
  createdTime: number;
}

export default function MobileWorkspace({
  sections,
  onUpdateSection,
  procedures,
  proposal,
  setProposal,
  clinicSettings,
  onExitMobile,
  onNewProposalForPatient,
}: MobileWorkspaceProps) {
  const [activeTab, setActiveTab] = useState<'leads' | 'camera'>('leads');

  // --- TAB 1: QUICK LEAD / REGISTER FORM ---
  const [leadName, setLeadName] = useState('');
  const [leadPhone, setLeadPhone] = useState('');
  const [leadDate, setLeadDate] = useState(format(new Date(), 'yyyy-MM-dd'));
  const [leadTime, setLeadTime] = useState(format(new Date(), 'HH:mm'));
  const [leadNotes, setLeadNotes] = useState('Consulta de avaliação clínica rápida realizada via Celular.');
  const [isSubmitingLead, setIsSubmitingLead] = useState(false);
  const [successLeadMsg, setSuccessLeadMsg] = useState<string | null>(null);
  const [lastCreatedWhatsAppUrl, setLastCreatedWhatsAppUrl] = useState<string | null>(null);

  // Local list of quick leads (persisted in localStorage for convenience)
  const [quickLeads, setQuickLeads] = useState<QuickLead[]>(() => {
    const cached = localStorage.getItem('ag_dent_quick_leads');
    return cached ? JSON.parse(cached) : [];
  });

  useEffect(() => {
    localStorage.setItem('ag_dent_quick_leads', JSON.stringify(quickLeads));
  }, [quickLeads]);

  const handleDeleteQuickLead = (id: string, name: string) => {
    if (window.confirm(`Deseja cancelar o cadastro provisório de ${name}?`)) {
      setQuickLeads(prev => prev.filter(lead => lead.id !== id));
    }
  };

  const handleQuickLeadSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!leadName.trim()) return;

    setIsSubmitingLead(true);
    setSuccessLeadMsg(null);
    setLastCreatedWhatsAppUrl(null);

    const formattedName = leadName.trim().toUpperCase();
    const phoneClean = leadPhone.replace(/[^\d]/g, '');

    try {
      // 1. Create Google Calendar event
      const startDateTime = new Date(`${leadDate}T${leadTime}:00`).toISOString();
      const endDateTime = new Date(`${leadDate}T${leadTime}:00`);
      endDateTime.setMinutes(endDateTime.getMinutes() + 30);
      
      const calendarDescription = `Consulta agendada pelo WhatsApp (via Mobile rápido).\n\nWhatsApp: ${leadPhone}\nNotas: ${leadNotes}`;
      
      await createCalendarEvent({
        summary: `📍 [CELULAR] ${formattedName}`,
        description: calendarDescription,
        start: { dateTime: startDateTime, timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone },
        end: { dateTime: endDateTime.toISOString(), timeZone: Intl.DateTimeFormat().resolvedOptions().timeZone },
      });

      // 2. Initialize Patient Profile in Supabase (auto-create by saving dummy state)
      const stateToSave = {
        proposal: {
          ...proposal,
          patientName: formattedName,
          notes: leadNotes
        },
        sections,
        procedures
      };
      
      const jsonStr = JSON.stringify(stateToSave);
      const fileBlob = new Blob([jsonStr], { type: 'application/json' });
      await uploadPatientFileToSupabase((proposal.patientData as any)?.id || formattedName, fileBlob, 'orcamento_mobile.json');

      // 3. Set active patient in flow
      setProposal(prev => ({
        ...prev,
        patientName: formattedName,
        notes: leadNotes
      }));

      // 4. Generate WhatsApp Confirm URL
      const dateFormatted = format(new Date(`${leadDate}T${leadTime}:00`), "dd/MM/yyyy 'às' HH:mm");
      const msg = `Olá, ${formattedName}! Confirmamos o seu agendamento no consultório do ${clinicSettings.doctorName} para o dia ${dateFormatted}.\n\n📍 Local: ${clinicSettings.address}\n\nFicamos no aguardo de sua confirmação!`;
      const waUrl = `https://wa.me/${phoneClean ? phoneClean : '55'}?text=${encodeURIComponent(msg)}`;
      setLastCreatedWhatsAppUrl(waUrl);

      // Save to local leads list
      const newLead: QuickLead = {
        id: `lead-${Date.now()}`,
        name: formattedName,
        phone: leadPhone,
        date: leadDate,
        time: leadTime,
        status: 'Criado',
        createdTime: Date.now()
      };
      setQuickLeads(prev => [newLead, ...prev]);

      // Reset form fields
      setLeadName('');
      setLeadPhone('');
      setSuccessLeadMsg(`Paciente ${formattedName} cadastrado com sucesso! Pasta criada no Google Drive e agendamento salvo.`);

    } catch (err: any) {
      console.error(err);
      alert('Erro ao processar cadastro rápido: ' + err.message);
    } finally {
      setIsSubmitingLead(false);
    }
  };

  const handleApplyPresetTime = (minutesOffset: number) => {
    const target = new Date();
    target.setMinutes(target.getMinutes() + minutesOffset);
    setLeadDate(format(target, 'yyyy-MM-dd'));
    setLeadTime(format(target, 'HH:mm'));
  };

  // --- TAB 2: EXCLUSIVE LIVE SCAN CAMERA OVERLAY ---
  const [activeCameraSection, setActiveCameraSection] = useState<'upper' | 'smile' | 'lower'>('upper');
  const [isCameraActive, setIsCameraActive] = useState(false);
  const [facingMode, setFacingMode] = useState<'environment' | 'user'>('environment');
  const [torchOn, setTorchOn] = useState(false);
  const [cameraError, setCameraError] = useState<string | null>(null);
  const [capturing, setCapturing] = useState(false);

  const [cameraZoom, setCameraZoom] = useState<1 | 2>(1);
  const [cameraExposure, setCameraExposure] = useState<number>(1.0);
  const [focusLocked, setFocusLocked] = useState(false);
  const [showCameraGuide, setShowCameraGuide] = useState(true);

  // Refs for tracking streams
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const startLiveCamera = async (mode = facingMode) => {
    setCameraError(null);
    setIsCameraActive(true);
    setTorchOn(false);
    setCameraZoom(1);
    setCameraExposure(1.0);
    setFocusLocked(false);

    if (streamRef.current) {
      streamRef.current.getTracks().forEach(t => t.stop());
    }

    setTimeout(async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: mode, width: { ideal: 1280 }, height: { ideal: 960 } }
        });
        streamRef.current = stream;
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          videoRef.current.play();
        }
      } catch (err: any) {
        console.error(err);
        setCameraError('Permissão para utilizar câmera foi negada ou não disponível.');
      }
    }, 200);
  };

  const stopLiveCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(t => t.stop());
      streamRef.current = null;
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
    setIsCameraActive(false);
  };

  const handleToggleTorch = async () => {
    if (streamRef.current) {
      const track = streamRef.current.getVideoTracks()[0];
      const nextTorch = !torchOn;
      try {
        await track.applyConstraints({
          advanced: [{ torch: nextTorch }]
        } as any);
        setTorchOn(nextTorch);
      } catch (e) {
        console.warn('Torch not supported on this lens or browser:', e);
      }
    }
  };

  const toggleCameraZoom = async () => {
    const nextZoom: 1 | 2 = cameraZoom === 1 ? 2 : 1;
    setCameraZoom(nextZoom);
    if (streamRef.current) {
      const track = streamRef.current.getVideoTracks()[0];
      try {
        const capabilities = track.getCapabilities ? track.getCapabilities() : {} as any;
        if (capabilities.zoom) {
          const val = nextZoom === 2 ? Math.min(capabilities.zoom.max || 2.0, 2.0) : 1.0;
          await track.applyConstraints({ advanced: [{ zoom: val }] } as any);
        }
      } catch (e) {
        console.warn('Hardware zoom adjustment failed on mobile', e);
      }
    }
  };

  const handleExposureChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = parseFloat(e.target.value);
    setCameraExposure(val);
    if (streamRef.current) {
      const track = streamRef.current.getVideoTracks()[0];
      try {
        const expCompensation = (val - 1.0) * 4.0;
        await track.applyConstraints({
          advanced: [{ exposureMode: 'manual', exposureCompensation: expCompensation }]
        } as any);
      } catch (err) {
        // Fallback is CSS filter
      }
    }
  };

  const toggleFocusLock = async () => {
    if (streamRef.current) {
      const track = streamRef.current.getVideoTracks()[0];
      const nextFocusLock = !focusLocked;
      setFocusLocked(nextFocusLock);
      try {
        await track.applyConstraints({
          advanced: [{ focusMode: nextFocusLock ? 'manual' : 'continuous' }]
        } as any);
      } catch (e) {
        console.warn('Focus lock constraint not supported by hardware/browser on mobile', e);
      }
    }
  };

  const handleCapturePhoto = () => {
    if (videoRef.current && canvasRef.current) {
      const video = videoRef.current;
      const canvas = canvasRef.current;
      
      if (video.videoWidth) {
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.save();
          ctx.filter = `brightness(${cameraExposure})`;

          // Mirror frame if user camera is active
          if (facingMode === 'user') {
            ctx.translate(canvas.width, 0);
            ctx.scale(-1, 1);
          }

          const track = streamRef.current?.getVideoTracks()[0];
          const capabilities = track?.getCapabilities ? track.getCapabilities() : {} as any;
          const isHardwareZoomActive = capabilities.zoom && cameraZoom > 1;

          if (facingMode === 'user') {
            if (cameraZoom === 2 && !isHardwareZoomActive) {
              const sw = video.videoWidth / 2;
              const sh = video.videoHeight / 2;
              const sx = (video.videoWidth - sw) / 2;
              const sy = (video.videoHeight - sh) / 2;
              ctx.drawImage(video, sx, sy, sw, sh, -video.videoWidth, 0, video.videoWidth, video.videoHeight);
            } else {
              ctx.drawImage(video, -video.videoWidth, 0, video.videoWidth, video.videoHeight);
            }
          } else {
            if (cameraZoom === 2 && !isHardwareZoomActive) {
              const sw = video.videoWidth / 2;
              const sh = video.videoHeight / 2;
              const sx = (video.videoWidth - sw) / 2;
              const sy = (video.videoHeight - sh) / 2;
              ctx.drawImage(video, sx, sy, sw, sh, 0, 0, video.videoWidth, video.videoHeight);
            } else {
              ctx.drawImage(video, 0, 0, video.videoWidth, video.videoHeight);
            }
          }
          
          ctx.restore();
          const rawDataUrl = canvas.toDataURL('image/jpeg', 0.9);
          const targetSectionId = activeCameraSection === 'smile' ? 'smile' : activeCameraSection;
          
          compressImage(rawDataUrl, 1024, 0.7).then((dataUrl) => {
            // Locate section and update image
            const targetSection = sections.find((s) => s.id === targetSectionId);
            if (targetSection) {
              const updatedMarkers = (targetSection.markers || []).map((m) => {
                if (!m.x || !m.y || (m.x === 50 && (m.y === 50 || m.y === 60))) {
                  const defaultPos = getDefaultToothCoordinates(m.toothNumber, targetSection.id);
                  return { ...m, ...defaultPos };
                }
                return m;
              });
              onUpdateSection({
                ...targetSection,
                image: dataUrl,
                markers: updatedMarkers,
              });
            }

            stopLiveCamera();
            setCapturing(true);
            setTimeout(() => setCapturing(false), 800);
          });

          // Upload to Google Drive patient folder in the background
          const pName = proposal.patientName;
          if (pName) {
            canvas.toBlob(async (blob) => {
              if (blob) {
                try {
                  const filename = `${targetSectionId}_capture_${Date.now()}.jpg`;
                  await uploadPatientFileToSupabase((proposal.patientData as any)?.id || pName, blob, filename);
                  console.log(`Mobile webcam capture saved to patient ${pName} on Supabase`);
                } catch (err) {
                  console.warn("Failed to upload mobile webcam snapshot to Supabase:", err);
                }
              }
            }, 'image/jpeg', 0.9);
          }
        }
      }
    }
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      const dataUrl = await compressFileToDataUrl(file, 1024, 0.7);
      if (dataUrl) {
        const targetSectionId = activeCameraSection === 'smile' ? 'smile' : activeCameraSection;
        const targetSection = sections.find((s) => s.id === targetSectionId);
        if (targetSection) {
          const updatedMarkers = (targetSection.markers || []).map((m) => {
            if (!m.x || !m.y || (m.x === 50 && (m.y === 50 || m.y === 60))) {
              const defaultPos = getDefaultToothCoordinates(m.toothNumber, targetSection.id);
              return { ...m, ...defaultPos };
            }
            return m;
          });
          onUpdateSection({
            ...targetSection,
            image: dataUrl,
            markers: updatedMarkers,
          });
        }

        // Upload to Google Drive patient folder in the background
        const pName = proposal.patientName;
        if (pName) {
          const filename = `${targetSectionId}_upload_${Date.now()}_${file.name}`;
          uploadPatientFileToSupabase((proposal.patientData as any)?.id || pName, file, filename).then(() => {
            console.log(`Mobile upload saved to patient ${pName} on Supabase`);
          }).catch(err => {
            console.warn("Failed to upload mobile image upload to Supabase:", err);
          });
        }
      }
    } catch (err) {
      console.error(err);
    }
  };

  const [syncsLoading, setSyncsLoading] = useState<Record<string, boolean>>({});
  const [syncsSuccess, setSyncsSuccess] = useState<Record<string, boolean>>({});

  const handleUploadToDrive = async (sectionId: string) => {
    let pName = proposal.patientName || (proposal.patientData as any)?.name;
    if (!pName || pName.trim() === '') {
      const promptName = window.prompt('Informe o nome do paciente para enviar esta foto à pasta Cloud Drive:');
      if (promptName && promptName.trim() !== '') {
        pName = promptName.trim();
        setProposal(prev => ({ ...prev, patientName: pName }));
      } else {
        alert('Você precisa definir um paciente ativo para enviar imagens à pasta do Drive.');
        return;
      }
    }

    const sec = sections.find(s => s.id === sectionId);
    if (!sec || !sec.image) {
      alert('Nenhuma foto capturada neste slot para enviar.');
      return;
    }

    setSyncsLoading(prev => ({ ...prev, [sectionId]: true }));
    try {
      // 1. Convert DataUrl to Blob
      const arr = sec.image.split(',');
      const mime = arr[0].match(/:(.*?);/)?.[1] || 'image/jpeg';
      const bstr = atob(arr[1]);
      let n = bstr.length;
      const u8arr = new Uint8Array(n);
      while (n--) {
        u8arr[n] = bstr.charCodeAt(n);
      }
      const blob = new Blob([u8arr], { type: mime });

      // 2. Upload to Supabase Storage / Cloud Drive
      const d = format(new Date(), 'yyyy-MM-dd_HH-mm-ss');
      const filename = `${sectionId}_capture_${d}.jpeg`;
      const targetId = (proposal.patientData as any)?.id || pName;
      await uploadPatientFileToSupabase(targetId, blob, filename);

      setSyncsSuccess(prev => ({ ...prev, [sectionId]: true }));
      setTimeout(() => {
        setSyncsSuccess(prev => ({ ...prev, [sectionId]: false }));
      }, 3000);
    } catch (err: any) {
      console.error(err);
      alert('Erro ao enviar imagem ao Supabase: ' + (err?.message || err));
    } finally {
      setSyncsLoading(prev => ({ ...prev, [sectionId]: false }));
    }
  };

  const handleRemovePhoto = (sectionId: string) => {
    const targetSection = sections.find(s => s.id === sectionId);
    if (targetSection) {
      onUpdateSection({
        ...targetSection,
        image: null,
      });
    }
  };

  return (
    <div className="w-full bg-[#FAF8F5] pb-24 font-sans animate-fade-in text-zinc-800">
      
      {/* EXCLUSIVE MOBILE WORKSPACE HEADER */}
      <div className="bg-[#8B0000] text-[#FAF8F5] p-5 shadow-lg border-b border-[#C09553]/30 rounded-t-2xl">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-full bg-[#FAF8F5]/10 flex items-center justify-center border border-[#C09553]/30">
              <Smartphone className="w-5 h-5 text-[#C09553]" />
            </div>
            <div>
              <h1 className="text-base font-serif font-bold text-[#FAF8F5] tracking-wide">AVALIAÇÃO RÁPIDA MOBILE</h1>
              <p className="text-[10px] text-zinc-300 tracking-wider">MODO CONSULTÓRIO PORTÁTIL</p>
            </div>
          </div>
          <button 
            type="button"
            onClick={onExitMobile}
            className="text-xs bg-[#FAF8F5] text-[#8B0000] font-bold px-3 py-1.5 rounded-lg border border-[#C09553] hover:bg-[#F3EFE9] transition-all cursor-pointer shadow-sm active:scale-95"
          >
            Sair do Celular
          </button>
        </div>

        {proposal.patientName ? (
          <div className="mt-4 bg-[#FAF8F5]/10 border border-[#C09553]/20 rounded-xl p-3 flex items-center justify-between">
            <div className="space-y-0.5">
              <p className="text-[10px] text-[#C09553] font-bold tracking-wider uppercase">Paciente Ativo no Celular</p>
              <p className="text-xs font-bold text-white tracking-tight">{proposal.patientName}</p>
            </div>
            <button 
              onClick={() => onNewProposalForPatient('')}
              className="text-[10px] text-zinc-300 hover:text-white underline cursor-pointer"
            >
              Trocar
            </button>
          </div>
        ) : (
          <div className="mt-4 bg-[#FAF8F5]/5 border border-dashed border-[#C09553]/30 rounded-xl p-3 text-center">
            <p className="text-[11px] text-[#C09553] font-medium">Nenhum paciente selecionado. Use o formulário abaixo!</p>
          </div>
        )}
      </div>

      {/* MOBILE NAV TABS */}
      <div className="grid grid-cols-2 bg-white border-b border-[#E6DEC9] sticky top-0 z-40 shadow-xs">
        <button
          onClick={() => {
            stopLiveCamera();
            setActiveTab('leads');
          }}
          className={`py-3.5 text-xs font-bold uppercase tracking-wider transition-all border-b-2 flex items-center justify-center gap-2 ${
            activeTab === 'leads'
              ? 'border-[#8B0000] text-[#8B0000] bg-[#FAF8F5]/50'
              : 'border-transparent text-zinc-400 hover:text-zinc-600'
          }`}
        >
          <Calendar className="w-4 h-4 text-[#C09553]" />
          <span>Agendar & Cadastrar</span>
        </button>
        <button
          onClick={() => {
            setActiveTab('camera');
          }}
          className={`py-3.5 text-xs font-bold uppercase tracking-wider transition-all border-b-2 flex items-center justify-center gap-2 ${
            activeTab === 'camera'
              ? 'border-[#8B0000] text-[#8B0000] bg-[#FAF8F5]/50'
              : 'border-transparent text-zinc-400 hover:text-zinc-600'
          }`}
        >
          <Camera className="w-4 h-4 text-[#C09553]" />
          <span>📸 Câmera da Arcada</span>
        </button>
      </div>

      <div className="max-w-md mx-auto p-4 space-y-6">

        {/* CONTAINER TAB 1: QUICK LEAD REGISTRATION & WHATSAPP APPOINTMENT */}
        {activeTab === 'leads' && (
          <div className="space-y-6">
            
            <div className="bg-[#8B0000]/5 border border-[#C09553]/20 p-4 rounded-xl flex items-start gap-3">
              <Sparkles className="w-5 h-5 text-[#C09553] mt-0.5 flex-shrink-0" />
              <div>
                <p className="text-xs font-bold text-[#8B0000] uppercase tracking-wide">Cadastro Exclusivo via WhatsApp</p>
                <p className="text-[11.5px] text-zinc-600 leading-relaxed mt-0.5">
                  Recebeu um lead ou contato no WhatsApp e precisa salvar agora? Digite o nome, escolha o horário e gere o lembrete de confirmação de forma ultra rápida.
                </p>
              </div>
            </div>

            {successLeadMsg && (
              <div className="bg-emerald-50 border border-emerald-200 rounded-xl p-4 text-xs text-emerald-800 space-y-3 shadow-xs animate-fade-in">
                <div className="flex items-center gap-2">
                  <Check className="w-4 h-4 text-emerald-600" />
                  <span className="font-bold">{successLeadMsg}</span>
                </div>
                {lastCreatedWhatsAppUrl && (
                  <a
                    href={lastCreatedWhatsAppUrl}
                    target="_blank"
                    rel="noreferrer"
                    className="w-full flex items-center justify-center gap-2 bg-emerald-600 text-white font-bold py-2.5 px-4 rounded-lg hover:bg-emerald-700 transition-colors shadow-sm text-center"
                  >
                    <MessageCircle className="w-4.5 h-4.5 fill-current" />
                    <span>Enviar Lembrete no WhatsApp</span>
                  </a>
                )}
              </div>
            )}

            {/* QUICK LEAD FORM */}
            <form onSubmit={handleQuickLeadSubmit} className="bg-white border border-[#E6DEC9] rounded-2xl p-5 shadow-sm space-y-4">
              <h2 className="text-sm font-bold text-[#8B0000] uppercase tracking-wide border-b border-[#FAF8F5] pb-2 flex items-center gap-2">
                <User className="w-4 h-4 text-[#C09553]" />
                Ficha de Cadastro Rápido
              </h2>

              <div className="space-y-1.5">
                <label className="text-[10px] font-bold text-zinc-400 uppercase tracking-wider">Nome Completo</label>
                <div className="relative">
                  <span className="absolute left-3.5 top-1/2 -translate-y-1/2 text-zinc-400">
                    <User className="w-4 h-4" />
                  </span>
                  <input
                    type="text"
                    required
                    placeholder="Ex: AGNALDO FERREIRA FILHO"
                    value={leadName}
                    onChange={(e) => setLeadName(e.target.value.toUpperCase())}
                    className="w-full bg-[#FAF8F5] border border-[#D5CBB3] focus:border-[#8B0000] focus:ring-1 focus:ring-[#8B0000] rounded-xl pl-10 pr-3.5 py-3 text-sm font-medium focus:outline-none transition-all placeholder:text-zinc-400"
                  />
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="text-[10px] font-bold text-zinc-400 uppercase tracking-wider">WhatsApp com DDD (Ex: 11999998888)</label>
                <div className="relative">
                  <span className="absolute left-3.5 top-1/2 -translate-y-1/2 text-zinc-400">
                    <Phone className="w-4 h-4" />
                  </span>
                  <input
                    type="tel"
                    placeholder="Ex: 5511999998888"
                    value={leadPhone}
                    onChange={(e) => setLeadPhone(e.target.value)}
                    className="w-full bg-[#FAF8F5] border border-[#D5CBB3] focus:border-[#8B0000] focus:ring-1 focus:ring-[#8B0000] rounded-xl pl-10 pr-3.5 py-3 text-sm focus:outline-none transition-all placeholder:text-zinc-400"
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-bold text-zinc-400 uppercase tracking-wider">Data</label>
                  <div className="relative">
                    <span className="absolute left-3 top-1/2 -translate-y-1/2 text-[#C09553] pointer-events-none">
                      <Calendar className="w-3.5 h-3.5" />
                    </span>
                    <input
                      type="date"
                      required
                      value={leadDate}
                      onChange={(e) => setLeadDate(e.target.value)}
                      className="w-full bg-[#FAF8F5] border border-[#D5CBB3] focus:border-[#8B0000] rounded-xl pl-8 pr-2 py-2.5 text-xs focus:outline-none"
                    />
                  </div>
                </div>

                <div className="space-y-1.5">
                  <label className="text-[10px] font-bold text-zinc-400 uppercase tracking-wider">Horário</label>
                  <div className="relative">
                    <span className="absolute left-3 top-1/2 -translate-y-1/2 text-[#C09553] pointer-events-none">
                      <Clock className="w-3.5 h-3.5" />
                    </span>
                    <input
                      type="time"
                      required
                      value={leadTime}
                      onChange={(e) => setLeadTime(e.target.value)}
                      className="w-full bg-[#FAF8F5] border border-[#D5CBB3] focus:border-[#8B0000] rounded-xl pl-8 pr-2 py-2.5 text-xs focus:outline-none"
                    />
                  </div>
                </div>
              </div>

              {/* QUICK TIMES PRESET BUTTONS */}
              <div className="space-y-1">
                <span className="text-[9px] font-bold text-zinc-400 uppercase tracking-wider block">Atalhos rápidos de horário</span>
                <div className="flex flex-wrap gap-1.5">
                  <button
                    type="button"
                    onClick={() => handleApplyPresetTime(0)}
                    className="px-2.5 py-1 bg-zinc-100 hover:bg-zinc-200 text-[10px] font-semibold rounded-md text-zinc-600"
                  >
                    Agora Mesmo
                  </button>
                  <button
                    type="button"
                    onClick={() => handleApplyPresetTime(30)}
                    className="px-2.5 py-1 bg-zinc-100 hover:bg-zinc-200 text-[10px] font-semibold rounded-md text-zinc-600"
                  >
                    Em 30 min
                  </button>
                  <button
                    type="button"
                    onClick={() => handleApplyPresetTime(60)}
                    className="px-2.5 py-1 bg-zinc-100 hover:bg-zinc-200 text-[10px] font-semibold rounded-md text-zinc-600"
                  >
                    Em 1 hora
                  </button>
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="text-[10px] font-bold text-zinc-400 uppercase tracking-wider">Observações / Anotação de Triagem</label>
                <textarea
                  rows={2}
                  value={leadNotes}
                  onChange={(e) => setLeadNotes(e.target.value)}
                  className="w-full bg-[#FAF8F5] border border-[#D5CBB3] focus:border-[#8B0000] rounded-xl p-3 text-xs focus:outline-none font-medium text-zinc-600"
                />
              </div>

              <button
                type="submit"
                disabled={isSubmitingLead}
                className="w-full flex items-center justify-center gap-2 bg-[#8B0000] text-white font-bold py-3 px-4 rounded-xl shadow-md cursor-pointer transition-colors hover:bg-[#6c1b26] disabled:opacity-50 text-sm mt-3"
              >
                {isSubmitingLead ? (
                  <>
                    <Loader2 className="w-4 h-4 animate-spin text-white" />
                    <span>Salvando dados...</span>
                  </>
                ) : (
                  <>
                    <BookmarkCheck className="w-4 h-4" />
                    <span>Agendar e Criar Pasta</span>
                  </>
                )}
              </button>
            </form>

            {/* RECENT LEADS HISTORY */}
            {quickLeads.length > 0 && (
              <div className="bg-white border border-[#E6DEC9] rounded-2xl p-5 shadow-sm space-y-3">
                <div className="flex items-center justify-between border-b border-[#FAF8F5] pb-2">
                  <h3 className="text-xs font-bold text-[#8B0000] uppercase tracking-wider flex items-center gap-1.5">
                    <Clock className="w-4 h-4 text-[#C09553]" />
                    Leads Recorrentes / Recentes
                  </h3>
                  <button
                    onClick={() => {
                      if (confirm('Deseja limpar histórico local de leads rápida?')) setQuickLeads([]);
                    }}
                    className="text-[9px] hover:text-rose-600 text-zinc-400 font-semibold uppercase tracking-wider"
                  >
                    Limpar
                  </button>
                </div>

                <div className="divide-y divide-zinc-50 max-h-60 overflow-y-auto pr-1 space-y-2">
                  {quickLeads.map((item) => {
                    const waNumClean = item.phone.replace(/[^\d]/g, '');
                    const dFormat = item.date.split('-').reverse().join('/');
                    const waRemUrl = `https://wa.me/${waNumClean ? waNumClean : '55'}?text=${encodeURIComponent(`Olá ${item.name}! Lembramos da sua consulta agendada para ${dFormat} às ${item.time}. Ficamos no aguardo!`)}`;

                    return (
                      <div key={item.id} className="pt-2 flex items-center justify-between text-xs gap-2">
                        <div className="space-y-0.5 min-w-0">
                          <p className="font-bold text-zinc-800 truncate">{item.name}</p>
                          <div className="flex items-center gap-2 text-[10px] text-zinc-500 font-medium">
                            <span className="flex items-center gap-0.5">
                              <Calendar className="w-3 h-3 text-[#C09553]" />
                              {dFormat}
                            </span>
                            <span className="flex items-center gap-0.5">
                              <Clock className="w-3 h-3 text-[#C09553]" />
                              {item.time}
                            </span>
                          </div>
                        </div>
                        <div className="flex items-center gap-1.5 flex-shrink-0">
                          <button
                            onClick={() => {
                              onNewProposalForPatient(item.name);
                              setActiveTab('camera');
                            }}
                            className="bg-[#FAF8F5] text-zinc-700 hover:text-[#8B0000] border border-zinc-200 p-1.5 rounded-lg active:scale-95 transition-all cursor-pointer"
                            title="Tirar foto para este paciente"
                          >
                            <Camera className="w-3.5 h-3.5" />
                          </button>
                          {item.phone && (
                            <a
                              href={waRemUrl}
                              target="_blank"
                              rel="noreferrer"
                              className="bg-[#FAF8F5] text-zinc-600 hover:text-emerald-600 border border-zinc-200 p-1.5 rounded-lg active:scale-95 transition-all text-center inline-flex"
                              title="Enviar convite"
                            >
                              <MessageCircle className="w-3.5 h-3.5 fill-current text-emerald-600" />
                            </a>
                          )}
                          <button
                            onClick={() => handleDeleteQuickLead(item.id, item.name)}
                            className="bg-[#FAF8F5] text-zinc-400 hover:text-red-600 border border-zinc-200 p-1.5 rounded-lg active:scale-95 transition-all cursor-pointer ml-1"
                            title="Apagar este lead rápido"
                          >
                            <Trash2 className="w-3.5 h-3.5" />
                          </button>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            )}

          </div>
        )}

        {/* CONTAINER TAB 2: Live camera photo capture and evaluation templates */}
        {activeTab === 'camera' && (
          <div className="space-y-6">

            <div className="bg-white border border-[#E6DEC9] rounded-2xl p-4 shadow-sm">
              <h3 className="text-xs font-bold text-zinc-400 uppercase tracking-widest text-center">Filtro de Arcada para Fotos</h3>
              <div className="grid grid-cols-3 gap-1.5 mt-3">
                <button
                  onClick={() => {
                    stopLiveCamera();
                    setActiveCameraSection('upper');
                  }}
                  className={`py-2 px-1 text-[10px] font-bold rounded-lg border uppercase tracking-wider text-center transition-all cursor-pointer ${
                    activeCameraSection === 'upper'
                      ? 'bg-[#8B0000] text-white border-[#8B0000] shadow-xs'
                      : 'bg-zinc-50 text-zinc-600 border-zinc-200'
                  }`}
                >
                  Superior
                </button>
                <button
                  onClick={() => {
                    stopLiveCamera();
                    setActiveCameraSection('smile');
                  }}
                  className={`py-2 px-1 text-[10px] font-bold rounded-lg border uppercase tracking-wider text-center transition-all cursor-pointer ${
                    activeCameraSection === 'smile'
                      ? 'bg-[#8B0000] text-white border-[#8B0000] shadow-xs'
                      : 'bg-zinc-50 text-zinc-600 border-zinc-200'
                  }`}
                >
                  Anterior
                </button>
                <button
                  onClick={() => {
                    stopLiveCamera();
                    setActiveCameraSection('lower');
                  }}
                  className={`py-2 px-1 text-[10px] font-bold rounded-lg border uppercase tracking-wider text-center transition-all cursor-pointer ${
                    activeCameraSection === 'lower'
                      ? 'bg-[#8B0000] text-white border-[#8B0000] shadow-xs'
                      : 'bg-zinc-50 text-zinc-600 border-zinc-200'
                  }`}
                >
                  Inferior
                </button>
              </div>
            </div>

            {/* LIVE CAMERA OVERVIEW OR SLOT PREVIEW */}
            <div className="relative bg-zinc-900 aspect-video rounded-3xl overflow-hidden border border-[#E6DEC9] shadow-inner flex flex-col justify-center items-center">
              
              {isCameraActive ? (
                <>
                  <video
                    ref={videoRef}
                    playsInline
                    muted
                    className="w-full h-full object-cover transition-all duration-200"
                    style={{ 
                      transform: `scale(${cameraZoom}) ${facingMode === 'user' ? 'scaleX(-1)' : ''}`,
                      filter: `brightness(${cameraExposure})`
                    }}
                  />

                  {/* SVG Alignment Guides based on showCameraGuide */}
                  {showCameraGuide && (
                    <div className="absolute inset-0 pointer-events-none flex items-center justify-center z-10">
                      {activeCameraSection === 'upper' && (
                        <svg viewBox="0 0 400 300" className="w-full h-full text-yellow-500/35 fill-none" stroke="currentColor" strokeWidth="2" strokeDasharray="5 5">
                          <path d="M 80 220 C 80 80, 320 80, 320 220" />
                        </svg>
                      )}
                      {activeCameraSection === 'lower' && (
                        <svg viewBox="0 0 400 300" className="w-full h-full text-yellow-500/35 fill-none" stroke="currentColor" strokeWidth="2" strokeDasharray="5 5">
                          <path d="M 80 80 C 80 220, 320 220, 320 80" />
                        </svg>
                      )}
                      {activeCameraSection === 'smile' && (
                        <svg viewBox="0 0 400 300" className="w-full h-full text-yellow-500/35 fill-none" stroke="currentColor" strokeWidth="2" strokeDasharray="5 5">
                          <ellipse cx="200" cy="150" rx="95" ry="48" />
                        </svg>
                      )}
                    </div>
                  )}

                  {/* Horizontal and vertical center notches */}
                  <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
                    <div className="absolute left-0 right-0 h-[1px] bg-red-400/20" />
                    <div className="absolute top-0 bottom-0 w-[1px] bg-red-400/20" />
                  </div>

                  {/* Camera overlay tools panel */}
                  <div className="absolute top-3 right-3 flex flex-col gap-2 z-20">
                    <button
                      type="button"
                      onClick={handleToggleTorch}
                      className={`w-9 h-9 rounded-full flex items-center justify-center bg-zinc-900/60 shadow-lg text-white border border-[#EAE4D9]/20 transition-all ${torchOn ? 'text-amber-400 bg-zinc-950/95' : 'text-zinc-200'}`}
                      title="Ativar Lanterna Flash"
                    >
                      <Zap className={`w-4.5 h-4.5 ${torchOn ? 'fill-current' : ''}`} />
                    </button>
                    <button
                      type="button"
                      onClick={() => {
                        const nextMod = facingMode === 'environment' ? 'user' : 'environment';
                        setFacingMode(nextMod);
                        startLiveCamera(nextMod);
                      }}
                      className="w-9 h-9 rounded-full flex items-center justify-center bg-zinc-900/60 shadow-lg text-white border border-[#EAE4D9]/20 transition-all"
                      title="Inverter Câmera"
                    >
                      <SwitchCamera className="w-4.5 h-4.5" />
                    </button>

                    {/* Zoom preset */}
                    <button
                      type="button"
                      onClick={toggleCameraZoom}
                      className={`w-9 h-9 rounded-full flex items-center justify-center bg-zinc-900/60 shadow-lg border border-[#EAE4D9]/20 text-white font-bold text-xs transition-all cursor-pointer ${cameraZoom === 2 ? 'bg-[#C09553] text-black border-[#C09553]' : ''}`}
                      title="Alternar Zoom"
                    >
                      {cameraZoom}x
                    </button>

                    {/* Focus Lock */}
                    <button
                      type="button"
                      onClick={toggleFocusLock}
                      className={`w-9 h-9 rounded-full flex items-center justify-center bg-zinc-900/60 shadow-lg border border-[#EAE4D9]/20 text-white transition-all cursor-pointer ${focusLocked ? 'bg-indigo-600 text-white border-indigo-600' : ''}`}
                      title="Travar Foco"
                    >
                      <Focus className="w-4 h-4" />
                    </button>

                    {/* Guide Lines */}
                    <button
                      type="button"
                      onClick={() => setShowCameraGuide(prev => !prev)}
                      className={`w-9 h-9 rounded-full flex items-center justify-center bg-zinc-900/60 shadow-lg border border-[#EAE4D9]/20 transition-all cursor-pointer ${showCameraGuide ? 'bg-emerald-600 text-white border-emerald-600' : 'text-zinc-400'}`}
                      title="Guia de Alinhamento"
                    >
                      <LayoutGrid className="w-4 h-4" />
                    </button>
                  </div>

                  {/* Exposure/Brightness adjustment overlay slider */}
                  <div className="absolute bottom-20 left-1/2 transform -translate-x-1/2 z-20 bg-black/60 backdrop-blur rounded-2xl px-4 py-1.5 border border-white/10 flex items-center gap-3 w-[80%] max-w-[280px]">
                    <span className="text-[9px] text-zinc-300 font-bold uppercase tracking-wider min-w-[40px]">Brilho</span>
                    <input 
                      type="range" 
                      min="0.5" 
                      max="1.5" 
                      step="0.05" 
                      value={cameraExposure} 
                      onChange={handleExposureChange}
                      className="flex-1 accent-[#C09553] h-1 cursor-pointer"
                    />
                  </div>

                  {/* BOTTOM ACTION RAIL */}
                  <div className="absolute bottom-4 left-0 right-0 flex justify-between px-6 items-center">
                    <button
                      type="button"
                      onClick={stopLiveCamera}
                      className="text-xs font-bold text-white bg-zinc-950/60 transition-all border border-zinc-200/20 px-3 py-1.5 rounded-full active:scale-95 cursor-pointer"
                    >
                      Voltar
                    </button>

                    <button
                      type="button"
                      onClick={handleCapturePhoto}
                      className="w-16 h-16 rounded-full border-4 border-white bg-white/45 flex justify-center items-center active:scale-95 transition-all shadow-md cursor-pointer"
                      title="Capturar snap!"
                    >
                      <div className="w-12 h-12 rounded-full bg-white flex items-center justify-center">
                        <Camera className="w-6 h-6 text-[#8B0000]" />
                      </div>
                    </button>

                    <div className="w-14" /> {/* spacer for symmetry */}
                  </div>
                </>
              ) : (
                <div className="absolute inset-0 flex flex-col items-center justify-center p-6 bg-zinc-950/30 text-center text-white space-y-3">
                  {(() => {
                    const sec = sections.find(s => s.id === (activeCameraSection === 'smile' ? 'smile' : activeCameraSection));
                    if (sec && sec.image) {
                      return (
                        <>
                          <img src={sec.image} alt="Live snap" className="w-full h-full object-cover absolute inset-0 rounded-2xl" referrerPolicy="no-referrer" />
                          <div className="absolute top-3 left-3 bg-zinc-950/70 border border-[#C09553]/35 text-[#FAF8F5] text-[10px] font-bold px-2.5 py-1 rounded-full uppercase tracking-wider shadow-md">
                            💡 Foto Atual Capturada
                          </div>
                          
                          <div className="absolute bottom-3 left-0 right-0 flex justify-center gap-2 px-4">
                            <button
                              onClick={() => startLiveCamera()}
                              className="bg-[#8B0000] hover:bg-[#6c1b26] border border-[#C09553] text-[#FAF8F5] text-[11px] font-bold px-3.5 py-2 rounded-xl flex items-center gap-1.5 shadow-lg active:scale-95 transition-all cursor-pointer"
                            >
                              <Camera className="w-3.5 h-3.5" />
                              <span>Deletar e Refazer</span>
                            </button>
                            <button
                              onClick={() => handleRemovePhoto(sec.id)}
                              className="bg-zinc-950/90 text-zinc-300 hover:text-rose-400 border border-zinc-700 text-[11px] font-semibold px-3 py-2 rounded-xl flex items-center gap-1.5 shadow-lg active:scale-95 transition-all cursor-pointer"
                            >
                              <Trash2 className="w-3.5 h-3.5" />
                            </button>
                          </div>
                        </>
                      );
                    } else {
                      return (
                        <div className="space-y-4 animate-fade-in">
                          <picture className="w-14 h-14 rounded-full bg-[#8B0000] text-white flex items-center justify-center mx-auto border border-[#C09553]/40 shadow-md">
                            <Camera className="w-6 h-6 text-[#C09553]" />
                          </picture>
                          <div>
                            <p className="text-sm font-semibold uppercase tracking-wider text-[#FAF8F5]">
                              Slot: {activeCameraSection === 'upper' ? 'Arcada Superior' : activeCameraSection === 'lower' ? 'Arcada Inferior' : 'Estética / Anterior'}
                            </p>
                            <p className="text-[10px] text-zinc-300 max-w-xs mt-1">
                              Foque os dentes e aperte abaixo para disparar o obturador ou escolha uma imagem da galeria local.
                            </p>
                          </div>

                          <div className="flex justify-center gap-2 pt-2 flex-wrap">
                            <label className="bg-[#8B0000] hover:bg-[#6c1b26] border border-[#C09553] text-white font-bold py-2.5 px-4 text-xs rounded-xl flex items-center gap-2 hover:scale-105 active:scale-95 transition-all cursor-pointer shadow-md">
                              <Camera className="w-4 h-4 text-[#C09553]" />
                              <span>Câmera do Celular</span>
                              <input
                                type="file"
                                accept="image/*"
                                capture="environment"
                                onChange={handleFileChange}
                                className="hidden"
                              />
                            </label>
                            <button
                              type="button"
                              onClick={() => startLiveCamera()}
                              className="bg-zinc-900 hover:bg-zinc-800 border border-zinc-700 text-zinc-200 font-bold py-2.5 px-3.5 text-xs rounded-xl flex items-center gap-2 transition-all cursor-pointer"
                            >
                              <Smartphone className="w-4 h-4 text-[#C09553]" />
                              <span>Webcam Ao Vivo</span>
                            </button>
                            <label className="bg-zinc-950 text-zinc-200 border border-zinc-700 font-bold py-2.5 px-3.5 text-xs rounded-xl flex items-center gap-2 cursor-pointer hover:bg-zinc-800 transition-colors">
                              <Upload className="w-4 h-4 text-zinc-400" />
                              <span>Galeria</span>
                              <input
                                type="file"
                                accept="image/*"
                                onChange={handleFileChange}
                                className="hidden"
                              />
                            </label>
                          </div>
                        </div>
                      );
                    }
                  })()}
                </div>
              )}
              {/* Dummy absolute hidden canvas for snapping */}
              <canvas ref={canvasRef} className="hidden" />
            </div>

            {/* SYNC TO GOOGLE DRIVE STATUS PANEL */}
            {(() => {
              const secId = activeCameraSection === 'smile' ? 'smile' : activeCameraSection;
              const hasImg = !!sections.find(s => s.id === secId)?.image;
              
              if (hasImg) {
                const isLoading = syncsLoading[secId];
                const isSuccess = syncsSuccess[secId];

