  }).format(val);
};

const drawMarkersOnImage = (sec: PhotoSection, procedures: Procedure[]): Promise<string> => {
  return new Promise((resolve) => {
    if (!sec.image) {
      resolve('');
      return;
    }
    if (!sec.markers || sec.markers.length === 0) {
      resolve(sec.image);
      return;
    }
    const img = new Image();
    img.crossOrigin = 'anonymous'; // Evita problemas com canvas poluído
    img.onload = () => {
      const canvas = document.createElement('canvas');
      const width = img.naturalWidth || 800;
      const height = img.naturalHeight || 450;
      canvas.width = width;
      canvas.height = height;

      const ctx = canvas.getContext('2d');
      if (!ctx) {
        resolve('');
        return;
      }

      ctx.drawImage(img, 0, 0, width, height);

      const markerSize = width * 0.04; 
      const radius = markerSize / 2;

      sec.markers.forEach((marker) => {
        const markerX = (marker.x / 100) * width;
        const markerY = (marker.y / 100) * height;

        // Círculo branco do dente
        ctx.beginPath();
        ctx.arc(markerX, markerY, radius, 0, 2 * Math.PI);
        ctx.fillStyle = '#ffffff';
        ctx.fill();
        ctx.lineWidth = Math.max(1, width * 0.002);
        ctx.strokeStyle = '#d4d4d8';
        ctx.stroke();

        // Número do dente
        ctx.fillStyle = '#09090b';
        ctx.font = `bold ${Math.round(radius * 0.9)}px Helvetica, Arial, sans-serif`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(marker.toothNumber.toString(), markerX, markerY);

        // Pontos de cores dos procedimentos no canto inferior direito
        if (marker.procedures && marker.procedures.length > 0) {
          const dotRadius = radius * 0.3;
          const dotSpacing = dotRadius * 2.2;
          
          const validProcedures = marker.procedures
            .map(pid => procedures.find(p => p.id === pid))
            .filter((p): p is Procedure => !!p);
          
          const totalDots = validProcedures.length;
          const startX = markerX + radius * 0.7;
          const startY = markerY + radius * 0.7;

          validProcedures.forEach((proc, idx) => {
            const dotX = startX - (totalDots - 1 - idx) * dotSpacing;
            const dotY = startY;

            ctx.beginPath();
            ctx.arc(dotX, dotY, dotRadius, 0, 2 * Math.PI);
            ctx.fillStyle = proc.color || '#3b82f6';
            ctx.fill();
            ctx.lineWidth = Math.max(0.5, width * 0.001);
            ctx.strokeStyle = '#ffffff';
            ctx.stroke();
          });
        }
      });

      resolve(canvas.toDataURL('image/jpeg', 0.85));
    };
    img.onerror = () => {
      resolve('');
    };
    img.src = sec.image;
  });
};

export default function NegotiationTab({
  sections,
  onUpdateSections,
  procedures,
  proposal,
  setProposal,
  clinicSettings,
  currentFileId,
  setCurrentFileId
}: NegotiationTabProps) {
  const { 
    selectedPatient, 
    activeSections, 
    setActiveSections, 
    pagamentosList, 
    setPagamentosList, 
    clinicalHistory,
    setClinicalHistory,
    saveContextToSupabase 
  } = usePatientContext();

  const handleUpdateAllSections = useCallback((newSections: PhotoSection[]) => {
    setActiveSections(newSections);
    if (onUpdateSections) {
      onUpdateSections(newSections);
    }
  }, [setActiveSections, onUpdateSections]);

  // Estados para importação de fotos avulsas e identificação/descrição no orçamento
  const [showAddAvulsaModal, setShowAddAvulsaModal] = useState(false);
  const [avulsaTitle, setAvulsaTitle] = useState('');
  const [avulsaDescription, setAvulsaDescription] = useState('');
  const [avulsaDataUrl, setAvulsaDataUrl] = useState<string | null>(null);
  const [isProcessingAvulsaPhoto, setIsProcessingAvulsaPhoto] = useState(false);
  const [editingTitleSectionId, setEditingTitleSectionId] = useState<string | null>(null);
  const [editingTitleText, setEditingTitleText] = useState('');
  const patientName = selectedPatient ? selectedPatient.name : (proposal.patientName || '');
  const pd = selectedPatient || proposal.patientData || {};
  
  // Local state for the machine fees options
  const [salesVolume, setSalesVolume] = useState<'under_3' | 'between_3_6'>(() => {
    const cached = localStorage.getItem('ag_neg_sales_volume');
    return (cached as 'under_3' | 'between_3_6') || 'under_3';
  });

  const [cardBrand, setCardBrand] = useState<'visa_master' | 'elo_amex'>(() => {
    const cached = localStorage.getItem('ag_neg_card_brand');
    return (cached as 'visa_master' | 'elo_amex') || 'visa_master';
  });

  // Etapas clínicas do orçamento (Urgência, Reabilitação, Estética)
  const activeStages = useMemo(() => {
    if (Array.isArray(proposal?.stages) && proposal.stages.length > 0) {
      return proposal.stages;
    }
    return DEFAULT_CLINICAL_STAGES;
  }, [proposal?.stages]);

  const handleUpdateStages = useCallback(
    (nextStages: typeof DEFAULT_CLINICAL_STAGES) => {
      setProposal((prev) => ({
        ...prev,
        stages: nextStages,
      }));
    },
    [setProposal]
  );

  // Maquininha ativa (Ton vs InfiniteTap) e tabela de taxas validada
  const [acquirerRates, setAcquirerRates] = useState<Record<AcquirerId, AcquirerRateTable>>(() =>
    loadAcquirerRates()
  );
  const selectedAcquirer: AcquirerId = proposal?.selectedAcquirer || 'ton';
  const handleSelectAcquirer = useCallback(
    (acq: AcquirerId) => {
      setProposal((prev) => ({
        ...prev,
        selectedAcquirer: acq,
      }));
    },
    [setProposal]
  );

  const [isSyncingRates, setIsSyncingRates] = useState(false);
  const [syncRatesMessage, setSyncRatesMessage] = useState('');

  const handleSyncRatesWithAI = useCallback(async () => {
    setIsSyncingRates(true);
    setSyncRatesMessage('');
    try {
      const result = await syncAcquirerRatesWithAI(selectedAcquirer, acquirerRates);
      setAcquirerRates(result.updatedRates);
      setSyncRatesMessage(
        `Taxas de ${result.updatedRates[selectedAcquirer].name} sincronizadas e validadas (${result.source}).`
      );
      setTimeout(() => setSyncRatesMessage(''), 6000);
    } finally {
      setIsSyncingRates(false);
    }
  }, [selectedAcquirer, acquirerRates]);

  // Lista unificada de todos os procedimentos mapeados com status de Etapa e Inclusão Individual
  const resolvedBudgetItems = useMemo<ResolvedBudgetProcedureItem[]>(() => {
    const items: ResolvedBudgetProcedureItem[] = [];
    const stageEnabledMap = new Map<string, boolean>();
    activeStages.forEach((st) => stageEnabledMap.set(st.id, st.enabled !== false));

    (sections || []).forEach((sec) => {
      (sec.markers || []).forEach((marker) => {
        const excludedSet = new Set(marker.excludedProcedures || []);
        (marker.procedures || []).forEach((pid) => {
          const proc = procedures.find((p) => p.id === pid);
          if (!proc) return;
          const inst = marker.procedureInstances?.find((i) => i.procedureId === pid);
          const price =
            marker.customPrices?.[pid] !== undefined
              ? marker.customPrices[pid]
              : inst?.price !== undefined
              ? inst.price
              : proc.price;
          const stageId =
            marker.procedureStages?.[pid] ||
            inst?.stageId ||
            proc.defaultStageId ||
            getDefaultStageForProcedure(proc.name, proc.id);
          const stageEnabled = stageEnabledMap.get(stageId) ?? true;
          const itemIncluded =
            !excludedSet.has(pid) && (inst ? inst.includeFinancial !== false : true);

          items.push({
            sectionId: sec.id,
            markerId: marker.id,
            toothNumber: marker.toothNumber || 0,
            procedureId: pid,
            procedureName: proc.name,
            price,
            stageId,
            stageEnabled,
            itemIncluded,
            effectiveIncluded: stageEnabled && itemIncluded,
          });
        });
      });
    });

    return items;
  }, [sections, procedures, activeStages]);

  const activeStageGrossTotal = useMemo(
    () =>
      resolvedBudgetItems
        .filter((i) => i.effectiveIncluded)
        .reduce((acc, i) => acc + i.price, 0),
    [resolvedBudgetItems]
  );

  const deferredStagesTotal = useMemo(
    () =>
      resolvedBudgetItems
        .filter((i) => !i.effectiveIncluded)
        .reduce((acc, i) => acc + i.price, 0),
    [resolvedBudgetItems]
  );

  // Calculate procedure list total sum for default liquid amount (legacy below kept for safety, overridden by activeStageGrossTotal)
  const calculatedGrossTotal = useMemo(() => {
    return sections.reduce((secSum, sec) => {
      return secSum + sec.markers.reduce((markSum, marker) => {
        if (marker.procedureInstances && marker.procedureInstances.length > 0) {
          return markSum + marker.procedureInstances.reduce((procSum, inst) => {
            return procSum + (inst.includeFinancial !== false ? inst.price : 0);
          }, 0);
        }
        return markSum + marker.procedures.reduce((procSum, pid) => {
          const proc = procedures.find((p) => p.id === pid);
          return procSum + (proc ? proc.price : 0);
        }, 0);
      }, 0);
    }, 0);
  }, [sections, procedures, resolvedBudgetItems, activeStages]);

  // If user wants to manually adjust the base Valor Líquido Desejado, fallback to calculated total
  const customNetKey = selectedPatient?.id ? `ag_neg_custom_net_${selectedPatient.id}` : 'ag_neg_custom_net';
  const [customNetDesired, setCustomNetDesired] = useState<number | null>(() => {
    const cached = localStorage.getItem(customNetKey);
    return cached ? parseFloat(cached) : null;
  });

  // Reset customNetDesired when selected patient changes to allow calculatedGrossTotal to drive new budgets
  useEffect(() => {
    if (selectedPatient?.id) {
      const cached = localStorage.getItem(`ag_neg_custom_net_${selectedPatient.id}`);
      setCustomNetDesired(cached ? parseFloat(cached) : null);
    }
  }, [selectedPatient?.id]);

  const desiredNet = customNetDesired !== null ? customNetDesired : activeStageGrossTotal;

  const [boxEntradas, setBoxEntradas] = useState<number[]>(() => {
    const cached = localStorage.getItem('ag_neg_box_entradas');
    return cached ? JSON.parse(cached) : [0, 0, 0, 0];
  });

  const [boxMethods, setBoxMethods] = useState<('pix' | 'pix_5' | 'debito' | 'credito_vista' | 'credito_parcelado')[]>(() => {
    const cached = localStorage.getItem('ag_neg_box_methods');
    return cached ? JSON.parse(cached) : ['pix', 'credito_parcelado', 'credito_parcelado', 'credito_parcelado'];
  });

  const [boxInstallments, setBoxInstallments] = useState<number[]>(() => {
    const cached = localStorage.getItem('ag_neg_box_installments');
    return cached ? JSON.parse(cached) : [1, 12, 12, 12];
  });

  useEffect(() => {
    if (desiredNet > 0) {
      setBoxEntradas(prev => {
        if (prev.every(v => v === 0)) {
          return [desiredNet, desiredNet * 0.3, desiredNet * 0.5, 500];
        }
        return prev;
      });
    }
  }, [desiredNet]);

  // Index of the chosen simulation to apply in the final printed PDF (0 = À Vista, 1 = Sim 1, 2 = Sim 2, 3 = Patient Offer)
  const [selectedPlanIndices, setSelectedPlanIndices] = useState<number[]>(() => {
    const cached = localStorage.getItem('ag_neg_selected_plans');
    if (cached) {
      try {
        const parsed = JSON.parse(cached);
        if (Array.isArray(parsed) && parsed.length > 0) return parsed;
      } catch (e) {}
    }
    const oldCached = localStorage.getItem('ag_neg_selected_plan');
    return oldCached ? [parseInt(oldCached)] : [0];
  });

  const [showInPatientScreen, setShowInPatientScreen] = useState<boolean[]>(() => {
    const cached = localStorage.getItem('ag_neg_show_patient_sims');
    if (cached) {
      try {
        return JSON.parse(cached);
      } catch {
        return [true, false, false, false];
      }
    }
    return [true, false, false, false];
  });

  // Help iframe print alert state
  const [showIframeHelp, setShowIframeHelp] = useState(false);
  const [isSavingDrive, setIsSavingDrive] = useState(false);
  const [saveSuccessMsg, setSaveSuccessMsg] = useState('');

  const [aiSalesScript, setAiSalesScript] = useState('');
  const [customAiInstruction, setCustomAiInstruction] = useState('');
  const [isGeneratingScript, setIsGeneratingScript] = useState(false);

  // Sync to localStorage
  useEffect(() => {
    localStorage.setItem('ag_neg_sales_volume', salesVolume);
    localStorage.setItem('ag_neg_card_brand', cardBrand);
    localStorage.setItem('ag_neg_box_entradas', JSON.stringify(boxEntradas));
    localStorage.setItem('ag_neg_box_methods', JSON.stringify(boxMethods));
    localStorage.setItem('ag_neg_box_installments', JSON.stringify(boxInstallments));
    localStorage.setItem('ag_neg_selected_plans', JSON.stringify(selectedPlanIndices));
    localStorage.setItem('ag_neg_show_patient_sims', JSON.stringify(showInPatientScreen));
    if (customNetDesired !== null) {
      localStorage.setItem(customNetKey, customNetDesired.toString());
      localStorage.setItem('ag_neg_custom_net', customNetDesired.toString());
    } else {
      localStorage.removeItem(customNetKey);
      localStorage.removeItem('ag_neg_custom_net');
    }
  }, [salesVolume, cardBrand, boxEntradas, boxMethods, boxInstallments, selectedPlanIndices, customNetDesired, showInPatientScreen, customNetKey]);

  // Is app in inside iframe constraint
  const isInsideIframe = useMemo(() => {
    try {
      return window.self !== window.top;
    } catch {
      return true;
    }
  }, []);



  // Max allowed installments by rule
  const maxInstallmentsRule = useMemo(() => {
    let baseMax = 6;
    if (desiredNet <= 500) baseMax = 1;
    else if (desiredNet <= 1000) baseMax = 3;
    else if (desiredNet <= 2000) baseMax = 4;
    
    // O consultório nunca deve absorver taxas maiores que 14%
    // Find the maximum installment where the rate is <= 14%
    const activeRates = acquirerRates[selectedAcquirer]?.tiers?.[salesVolume]?.credit?.[cardBrand] || TON_RATES[salesVolume][cardBrand];
    let maxInstallmentsByRate = 12;
    for (let i = 0; i < 12; i++) {
      if (activeRates[i] > 14) {
        maxInstallmentsByRate = i > 0 ? i : 1;
        break;
      }
    }

    return Math.min(baseMax, maxInstallmentsByRate);
  }, [desiredNet, salesVolume, cardBrand, acquirerRates, selectedAcquirer]);

  // Compile calculations for each of the 4 columns
  const simulations = useMemo(() => {
    return [0, 1, 2, 3].map(i => {
      const bEntrada = boxEntradas[i] === undefined ? 0 : boxEntradas[i];
      const bMethod = boxMethods[i] || 'credito_parcelado';
      const bInst = boxInstallments[i] || 12;

      const e = Math.min(desiredNet, Math.max(0, bEntrada));
      const r = desiredNet - e;

      let optionFeeDecimal = 0;
      let instCount = 1;

      if (bMethod === 'pix' || bMethod === 'pix_5') {
        optionFeeDecimal = 0;
        instCount = 1;
      } else if (bMethod === 'debito') {
        optionFeeDecimal = ((acquirerRates[selectedAcquirer]?.tiers?.[salesVolume]?.debit?.[cardBrand] ?? DEBIT_RATES[salesVolume]?.[cardBrand]) || 0) / 100;
        instCount = 1;
      } else if (bMethod === 'credito_vista') {
        optionFeeDecimal = ((acquirerRates[selectedAcquirer]?.tiers?.[salesVolume]?.credit?.[cardBrand]?.[0] ?? TON_RATES[salesVolume]?.[cardBrand]?.[0]) || 0) / 100;
        instCount = 1;
      } else if (bMethod === 'credito_parcelado') {
        const activeCreditTable = acquirerRates[selectedAcquirer]?.tiers?.[salesVolume]?.credit?.[cardBrand] || TON_RATES[salesVolume][cardBrand];
        const machineFeePercent = activeCreditTable[Math.min(11, Math.max(0, bInst - 1))];
        optionFeeDecimal = machineFeePercent / 100;
        instCount = bInst;
      }

      const isExceeded = instCount > maxInstallmentsRule && bMethod === 'credito_parcelado';
      const effectiveFeeDecimal = isExceeded ? optionFeeDecimal : 0;
      
      const t0Ref = desiredNet / (1 - effectiveFeeDecimal);

      const isPixDiscount = bMethod === 'pix_5';
      const pixDiscountVal = isPixDiscount ? (e === 0 ? desiredNet * 0.05 : r * 0.05) : 0;

      const ch = isPixDiscount ? (r - pixDiscountVal) : (r / (1 - effectiveFeeDecimal));
      const taxa = isPixDiscount ? 0 : (ch - r);
      const taxaAbsorvida = (!isExceeded && !isPixDiscount && bMethod !== 'pix') ? r * optionFeeDecimal : 0;
      const instVal = instCount > 0 ? ch / instCount : 0;
      const t = e + ch;

      const recebimentoLiquido = isPixDiscount ? t : (e + ch * (1 - optionFeeDecimal));

      let label = bMethod.toUpperCase();
      if (bMethod === 'pix_5') label = 'PIX (-5%)';
      if (bMethod === 'credito_parcelado') label = `CRÉDITO ${instCount}X`;
      if (bMethod === 'credito_vista') label = `CRÉDITO 1X`;

