        ['PAC032', 'Antônio Marcos Souza', '5511955554444', 'antonio@example.com', '240.00', 'Extração dente 18', 'Receita'],
        ['PAC043', 'Beatriz Silva Dias', '5511944443333', 'beatriz@example.com', '120.00', 'Limpeza Periódica', 'Receita']
