             custoTotal: 1500,
             descricao: `Dossiê clínico migrado de backup para o paciente ${patName}`
           }
         ]
      };

      const jsonStr = JSON.stringify(mockTreatmentState);
      const fileBlob = new Blob([jsonStr], { type: 'application/json' });
      await uploadPatientFileToSupabase((pd as any)?.id || patName, fileBlob, 'orcamento_quickaction.json');
      
      setDriveSyncStatuses(prev => ({ ...prev, [patName]: 'synced' }));
      
      const actionId = Math.random().toString(36).substring(7);
      setQuickActionsHistory(prev => [{
        id: actionId,
        file: selectedQuickFile || 'Backup Importado',
        type: 'Supabase',
        summary: `Ficha e prontuário de ${patName} arquivado estruturado no Supabase`,
        timestamp: new Date().toLocaleTimeString('pt-BR')
      }, ...prev]);

      setActionSuccessMessage(`Pasta clinica de ${patName} estruturada com sucesso no Supabase!`);
