                            <th className="px-4 py-2">Paciente</th>
                            <th className="px-4 py-2">Email</th>
                            <th className="px-4 py-2 flex justify-end">Ação Integrada</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-zinc-100">
                          {rawData.slice(1).map((row, idx) => {
                            const idxName = headers.findIndex(h => {
                              const hL = String(h || '').toLowerCase().trim();
                              return hL === 'nome_paciente' || hL === 'paciente' || hL === 'nome_completo' || hL === 'cliente' || hL === 'nome';
                            });
                            const name = idxName !== -1 ? String(row[idxName] || '').trim() : '';
                            if (!name) return null;

                            let emailVal = mappings.email !== -1 ? row[mappings.email] : '';
                            if (!emailVal) {
                              const idxEmail = headers.findIndex(h => String(h || '').toLowerCase().includes('email'));
                              if (idxEmail !== -1) emailVal = row[idxEmail];
                            }

                            const status = driveSyncStatuses[name] || 'idle';

                            return (
                              <tr key={idx} className="hover:bg-zinc-50 text-xs">
                                <td className="px-4 py-2 text-zinc-900 font-bold">{name}</td>
                                <td className="px-4 py-2 font-serif text-zinc-500">{emailVal || 'Não Mapeado'}</td>
                                <td className="px-4 py-2 flex justify-end">
                                  <button
                                    type="button"
                                    onClick={() => handleSaveDriveQuickAction(name)}
                                    className={`px-3 py-1 rounded-lg font-bold text-[10px] uppercase transition flex items-center gap-1 ${
                                      status === 'synced'
                                        ? 'bg-emerald-50 text-emerald-800 border border-emerald-200'
                                        : status === 'syncing'
                                        ? 'bg-zinc-100 text-zinc-500 font-medium'
                                        : 'bg-zinc-900 text-white hover:bg-zinc-800'
                                    }`}
                                  >
                                    {status === 'synced' && <Check className="w-3 h-3 text-emerald-700" />}
                                    {status === 'syncing' && <Loader2 className="w-3 h-3 animate-spin text-zinc-500" />}
                                    {status === 'synced' ? 'Sincronizado ✓' : status === 'syncing' ? 'Sincronizando...' : 'Salvar no Supabase'}
                                  </button>
                                </td>
                              </tr>
                            );
                          })}
                        </tbody>
                      </table>
                    </div>
                  </div>
                )}
              </div>
            ) : (
              <div className="py-6 border-2 border-dashed border-zinc-200 rounded-xl text-center text-zinc-500 font-medium">
                Clique em uma das opções de arquivos de backup acima para liberar as Ações Rápidas integradas de forma automática! ⚡
              </div>
            )}

            {/* Quick Actions Executed Stream History */}
            {quickActionsHistory.length > 0 && (
              <div className="border border-zinc-150 rounded-xl bg-[#FAF8F5]/30 p-3.5 space-y-2">
                <span className="block text-zinc-600 font-bold text-[11px] uppercase tracking-wider font-mono">⏱️ Log e Histórico de Execuções Recentes da Sessão</span>
                <div className="space-y-1.5 max-h-24 overflow-y-auto">
                  {quickActionsHistory.map(act => (
                    <div key={act.id} className="flex items-center justify-between text-[11px] bg-white border border-zinc-100 p-2 rounded-lg leading-none">
                      <div className="flex items-center gap-2">
                        <span className={`px-1.5 py-0.5 rounded text-[9px] font-bold uppercase ${
                          act.type === 'WhatsApp' 
                            ? 'bg-emerald-50 text-emerald-700 border border-emerald-200' 
                            : act.type === 'Google Calendar' 
                            ? 'bg-red-50 text-[#8B0000] border border-red-200' 
                            : 'bg-zinc-100 text-zinc-800 border border-zinc-300'
                        }`}>
                          {act.type}
                        </span>
                        <span className="text-zinc-700 font-serif font-bold">{act.summary}</span>
                        <span className="text-zinc-400 italic font-medium">({act.file})</span>
                      </div>
                      <span className="font-mono text-zinc-400 text-[10px]">{act.timestamp}</span>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* Area para Upload foi migrada para o CRM */}
          <div className="border border-[#D5CBB3] bg-[#FAF8F5] rounded-xl p-8 text-center flex flex-col items-center justify-center gap-4">
            <div className="w-14 h-14 bg-[#8B0000]/10 text-[#8B0000] rounded-full flex items-center justify-center">
              <Database className="w-7 h-7 text-[#C09553]" />
            </div>
            <div>
              <h3 className="text-[#8B0000] font-bold text-lg font-serif">A Central de Importação Mudou!</h3>
              <p className="text-zinc-500 mt-2 max-w-lg mx-auto text-sm leading-relaxed">
                Para melhorar o vínculo de pacientes, unificamos a ferramenta de importação avançada. Agora você pode importar seus backups (Excel, CSV, PDF, Textos) com segurança diretamente na aba <b>"CRM Odontológico & Central Inteligente"</b>.
              </p>
            </div>
            {/* The user can navigate manually using the main apps tabs above */}
          </div>

          {/* Planilha Carregada - Visual Configurações e Mapeamentos de Colunas */}
          {(importStatus === 'loaded' || importStatus === 'running' || importStatus === 'success' || importStatus === 'done') && importFile && (
            <div className="space-y-6">
              {detectedTemplate === 'bluedental' && (
                <div className="bg-[#8B0000]/5 border-2 border-[#C09553] p-4 rounded-xl flex items-start gap-3">
                  <div className="bg-[#8B0000] text-[#C09553] px-3 py-1 rounded font-bold text-[10px] uppercase font-mono tracking-wider shrink-0 mt-0.5">
                    BlueDental
                  </div>
                  <div>
                    <h4 className="font-bold text-zinc-900 text-xs">✨ Backup 'BlueDental Pacientes' Reconhecido com Sucesso!</h4>
                    <p className="text-zinc-600 font-medium text-[11px] mt-1 leading-relaxed">
                      Detectamos automaticamente <strong>todas as 53 colunas</strong> de cadastro técnico da sua clínica! Nosso migrador inteligente fará a transferência completa sem perda de dados: CPFs, RGs, Endereços Completos, Telefones (Fixo, Celular e WhatsApp), Histórico de Observações, Dados de Responsável, Planos de Convênio (Planos, Carteira e Validade) e até mesmo os Links Originais das Fotos de Perfil foram mapeados e serão salvos no Supabase!
                    </p>
                  </div>
                </div>
              )}
              {/* Informações básicas do arquivo carregado */}
              <div className="bg-zinc-50 border border-zinc-200 rounded-xl p-3 flex flex-wrap items-center justify-between gap-3 text-xs">
                <div className="flex items-center gap-3">
                  <div className="p-2 bg-green-50 text-green-700 rounded-lg">
                    <Check className="w-4 h-4" />
                  </div>
                  <div>
                    <h4 className="font-bold text-zinc-900">{importFile.name}</h4>
                    <p className="text-zinc-500">{(importFile.size / 1024).toFixed(1)} KB • {rawData.length} linhas analisadas</p>
                  </div>
                </div>
                
                {sheetNames.length > 1 && importStatus === 'loaded' && (
                  <div className="flex items-center gap-2">
                    <span className="font-semibold text-zinc-500">Aba ativa:</span>
                    <select 
                      value={selectedSheet} 
                      onChange={(e) => handleSheetChange(e.target.value)} 
                      className="border border-zinc-300 rounded p-1.5 focus:border-[#C09553] focus:outline-none font-medium bg-white"
                    >
                      {sheetNames.map((name) => (
                        <option key={name} value={name}>{name}</option>
                      ))}
                    </select>
                  </div>
                )}

                {importStatus === 'loaded' && (
                  <button 
                    onClick={() => {
                      setImportFile(null);
                      setWorkbook(null);
                      setRawData([]);
                      setHeaders([]);
                      setImportStatus('idle');
                    }}
                    className="text-xs text-red-700 font-semibold hover:underline"
                  >
                    Trocar arquivo
                  </button>
                )}
              </div>

              {/* Seletor de Categoria do Arquivo Clinico Importado */}
              <div className="bg-[#FAF8F5] border border-[#D5CBB3] rounded-xl p-4 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                <div className="flex items-start gap-2.5">
                  <div className="p-2 bg-[#8B0000]/5 text-[#C09553] rounded-lg mt-0.5">
                    <FolderOpen className="w-4 h-4" />
                  </div>
                  <div>
                    <h5 className="font-serif font-bold text-zinc-900 text-xs text-left">📂 Categoria e Organização Inteligente de Documentação</h5>
                    <p className="text-[11px] text-zinc-500 mt-0.5 leading-relaxed text-left">
                      Identificar e rotular estes dados automatiza a triagem no Supabase e a roteirização do atendimento clínico do Dr. Agnaldo Ferreira.
                    </p>
                  </div>
                </div>
                <div className="flex items-center gap-2 shrink-0">
                  <span className="text-zinc-600 font-bold text-xs uppercase font-mono">Categoria:</span>
                  <select
                    value={fileCategories[importFile.name] || 'Prontuário'}
                    onChange={(e) => {
                      const selectedCat = e.target.value;
                      setFileCategories(prev => ({
                        ...prev,
                        [importFile.name]: selectedCat
                      }));
                      // Also select it in Quick Actions if match
                      setSelectedQuickFile(importFile.name);
                    }}
                    className="border border-[#D5CBB3] rounded-lg p-2 font-bold text-xs bg-white text-zinc-800 focus:border-[#C09553] focus:outline-none focus:ring-1 focus:ring-[#C09553]/25 cursor-pointer shadow-xs"
                  >
                    <option value="Prontuário">📖 Prontuário</option>
                    <option value="Exames">🔬 Exames</option>
                    <option value="Orçamentos">💰 Orçamentos</option>
                    <option value="Outros">📁 Outros</option>
                  </select>
                </div>
              </div>

              {/* Mapeador de Colunas */}
              {importStatus === 'loaded' && (
                <div className="border border-zinc-200 rounded-xl bg-white p-4 space-y-4">
                  <div className="flex items-center gap-1.5 pb-2 border-b border-zinc-100">
                    <Layers className="w-4 h-4 text-[#C09553]" />
                    <h4 className="font-serif font-bold text-zinc-800 text-sm">Definir Mapeamento de Colunas</h4>
                  </div>
                  <p className="text-zinc-500">Selecione qual coluna do seu Excel corresponde a cada campo no nosso sistema clínico:</p>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {/* Campo Nome */}
                    <div>
                      <label className="block text-zinc-700 font-bold mb-1">
                        Nome do Paciente <span className="text-red-700">*</span>
                      </label>
                      <select 
                        value={mappings.name} 
                        onChange={(e) => handleMappingChange('name', parseInt(e.target.value))}
                        className={`w-full border rounded p-2 focus:border-[#C09553] focus:outline-none ${mappings.name === -1 ? 'border-red-300 bg-red-50/20' : 'border-zinc-300 bg-white'}`}
                      >
                        <option value={-1}>-- Selecionar Coluna --</option>
                        {headers.map((h, i) => (
                          <option key={i} value={i}>Coluna: {h}</option>
                        ))}
                      </select>
                    </div>

                    {/* Campo Contato */}
                    <div>
                      <label className="block text-[#8B0000] font-bold mb-1">WhatsApp / Celular</label>
                      <select 
                        value={mappings.phone} 
                        onChange={(e) => handleMappingChange('phone', parseInt(e.target.value))}
                        className="w-full border border-zinc-300 bg-white rounded p-2 focus:outline-none focus:border-[#C09553]"
                      >
                        <option value={-1}>-- Ignorar / Não Mapeado --</option>
                        {headers.map((h, i) => (
                          <option key={i} value={i}>Coluna: {h}</option>
                        ))}
                      </select>
                    </div>

                    {/* Campo Email */}
                    <div>
                      <label className="block text-zinc-700 font-bold mb-1">E-mail</label>
                      <select 
                        value={mappings.email} 
                        onChange={(e) => handleMappingChange('email', parseInt(e.target.value))}
                        className="w-full border border-zinc-300 bg-white rounded p-2 focus:outline-none focus:border-[#C09553]"
                      >
                        <option value={-1}>-- Ignorar / Não Mapeado --</option>
                        {headers.map((h, i) => (
                          <option key={i} value={i}>Coluna: {h}</option>
                        ))}
                      </select>
                    </div>

                    {/* Observacoes */}
                    <div>
                      <label className="block text-zinc-700 font-bold mb-1">Observações / Prontuário</label>
                      <select 
                        value={mappings.notes} 
                        onChange={(e) => handleMappingChange('notes', parseInt(e.target.value))}
                        className="w-full border border-zinc-300 bg-white rounded p-2 focus:outline-none focus:border-[#C09553]"
                      >
                        <option value={-1}>-- Ignorar / Não Mapeado --</option>
                        {headers.map((h, i) => (
                          <option key={i} value={i}>Coluna: {h}</option>
                        ))}
                      </select>
                    </div>

                    {/* Data do agendamento */}
                    <div>
                      <label className="block text-zinc-700 font-bold mb-1 flex items-center gap-1">
                        <Calendar className="w-3.5 h-3.5 text-[#C09553]" />
                        Data da Consulta
                      </label>
                      <select 
                        value={mappings.date} 
                        onChange={(e) => handleMappingChange('date', parseInt(e.target.value))}
                        className="w-full border border-zinc-300 bg-white rounded p-2 focus:outline-none focus:border-[#C09553]"
                      >
                        <option value={-1}>-- Ignorar / Sem Agendamento --</option>
                        {headers.map((h, i) => (
                          <option key={i} value={i}>Coluna: {h}</option>
                        ))}
                      </select>
                    </div>

                    {/* Hora do agendamento */}
                    <div>
                      <label className="block text-zinc-700 font-bold mb-1 flex items-center gap-1">
                        <Clock className="w-3.5 h-3.5 text-[#C09553]" />
                        Horário da Consulta
                      </label>
                      <select 
                        value={mappings.time} 
                        onChange={(e) => handleMappingChange('time', parseInt(e.target.value))}
                        className="w-full border border-zinc-300 bg-white rounded p-2 focus:outline-none focus:border-[#C09553]"
                      >
                        <option value={-1}>-- Ignorar / Usar Padrão 09:00 --</option>
                        {headers.map((h, i) => (
                          <option key={i} value={i}>Coluna: {h}</option>
                        ))}
                      </select>
                    </div>
                  </div>

                  {/* Configurações Adicionais */}
                  <div className="pt-2 flex flex-col sm:flex-row gap-4 border-t border-zinc-100">
                    <label className="flex items-center gap-2 cursor-pointer text-zinc-700 select-none">
                      <input 
                        type="checkbox" 
                        checked={skipDuplicates} 
                        onChange={(e) => setSkipDuplicates(e.target.checked)} 
                        className="rounded border-zinc-300 text-[#8B0000] focus:ring-[#C09553]"
                      />
                      <span>Prevenir registros duplicados (vincular ao prontuário se já existir no Supabase)</span>
                    </label>
                    <label className="flex items-center gap-2 cursor-pointer text-zinc-700 select-none">
                      <input 
                        type="checkbox" 
                        checked={createCalendarAppts} 
                        onChange={(e) => setCreateCalendarAppts(e.target.checked)} 
                        disabled={mappings.date === -1}
                        className="rounded border-zinc-300 text-[#8B0000] focus:ring-[#C09553] disabled:opacity-50"
                      />
                      <span className={mappings.date === -1 ? 'text-zinc-400' : ''}>Marcar consultas no Google Agenda</span>
                    </label>
                  </div>
                </div>
              )}

              {/* SELETOR DE MODO DE VISUALIZAÇÃO CLÍNICA / HISTÓRICOS EM DETALHE */}
              {importStatus === 'loaded' && getDetectedDataType() !== 'paciente' && (
                <div id="workspace-mode-selector" className="flex items-center justify-between p-3 bg-zinc-50 border border-zinc-200 rounded-xl mb-4 print:hidden gap-4">
                  <div className="space-y-0.5">
                    <h4 className="font-serif font-bold text-zinc-800 text-xs flex items-center gap-1.5">
                      <Sparkles className="w-4 h-4 text-[#C09553] animate-pulse" />
                      Banco de Dados Clínico Reconhecido ({getDetectedDataType().toUpperCase()})
                    </h4>
                    <p className="text-[10px] text-zinc-500 font-medium">Selecione como quer gerenciar os dados carregados do seu backup.</p>
                  </div>
                  <div className="flex bg-zinc-200/60 p-1 rounded-lg shrink-0">
                    <button
                      type="button"
                      onClick={() => setActiveViewMode('workspace')}
                      className={`px-3 py-1.5 rounded-md text-[11px] font-bold transition-all cursor-pointer ${
                        activeViewMode === 'workspace'
                          ? 'bg-[#8B0000] text-[#FAF8F5] shadow-xs'
                          : 'text-zinc-600 hover:text-[#8B0000] hover:bg-zinc-100'
                      }`}
                    >
                      👁️ Workspace UX
                    </button>
                    <button
                      type="button"
                      onClick={() => setActiveViewMode('legacy')}
                      className={`px-3 py-1.5 rounded-md text-[11px] font-bold transition-all cursor-pointer ${
                        activeViewMode === 'legacy'
                          ? 'bg-[#8B0000] text-[#FAF8F5] shadow-xs'
                          : 'text-zinc-600 hover:text-[#8B0000] hover:bg-zinc-100'
                      }`}
                    >
                      📋 Importador Antigo
                    </button>
                  </div>
                </div>
              )}

              {/* MODO WORKSPACE CLÍNICO INTERATIVO DE ALTA FIDELIDADE */}
              {importStatus === 'loaded' && activeViewMode === 'workspace' && getDetectedDataType() !== 'paciente' && (
                <div id="rich-clinical-workspace" className="space-y-6">
                  {/* WORKSPACE FINANÇAS / LANÇAMENTOS */}
                  {getDetectedDataType() === 'financeiro' && (() => {
                    // Extract financial indices dynamically
                    const idxVal = headers.findIndex(h => ['valor_realizado', 'valor_previsto', 'valor'].includes(h.toLowerCase().trim()));
                    const idxType = headers.findIndex(h => ['tipo_categoria', 'tipo'].includes(h.toLowerCase().trim()));
                    const idxCategory = headers.findIndex(h => ['nome_categoria', 'nome_conta_financeira', 'categoria'].includes(h.toLowerCase().trim()));
                    const idxPatient = headers.findIndex(h => ['nome_paciente', 'paciente', 'cliente'].includes(h.toLowerCase().trim()));
                    const idxDesc = headers.findIndex(h => ['descricao', 'num_documento'].includes(h.toLowerCase().trim()));
                    const idxDate = headers.findIndex(h => ['data_lancamento', 'data_pagamento', 'data_vencimento'].includes(h.toLowerCase().trim()));
                    const idxMethod = headers.findIndex(h => ['nome_forma_pagamento', 'forma_pagamento'].includes(h.toLowerCase().trim()));

                    let totalInflow = 0;
                    let totalOutflow = 0;
                    let pendingRowsCount = 0;

                    const financialRows = rawData.slice(1).map(row => {
                      const rawVal = idxVal !== -1 ? parseFloat(String(row[idxVal] || '0').replace(/[^\d\.]/g, '')) || 0 : 0;
                      const categoryName = idxCategory !== -1 ? String(row[idxCategory] || '').trim() : '';
                      const typeStr = idxType !== -1 ? String(row[idxType] || '').toLowerCase() : '';
                      const isRealizado = row[headers.findIndex(h => h.toLowerCase() === 'realizado')] !== false;

                      // Smart category classifier
                      const isExpense = typeStr === 'despesa' || 
                        categoryName.toLowerCase().includes('pagamento executado') ||
                        categoryName.toLowerCase().includes('aluguel') ||
                        categoryName.toLowerCase().includes('condominio') ||
                        categoryName.toLowerCase().includes('material') ||
                        categoryName.toLowerCase().includes('despesa') ||
                        categoryName.toLowerCase().includes('itau') ||
                        categoryName.toLowerCase().includes('energia') ||
                        categoryName.toLowerCase().includes('vale');

                      if (isExpense) {
                        totalOutflow += rawVal;
                      } else {
                        totalInflow += rawVal;
                      }

                      if (!isRealizado || String(row[headers.findIndex(h => h.toLowerCase() === 'descricao_status')]).toLowerCase().includes('pendente')) {
                        pendingRowsCount++;
                      }

                      return {
                        id: idxVal !== -1 ? String(row[headers.findIndex(h => h.toLowerCase() === 'codigo_lancamento')] || Math.random()) : '',
                        patient: idxPatient !== -1 ? String(row[idxPatient] || 'Clínica Geral') : 'Clínica Geral',
                        category: categoryName,
                        amount: rawVal,
                        isExpense,
                        description: idxDesc !== -1 ? String(row[idxDesc] || '') : '',
                        date: idxDate !== -1 ? String(row[idxDate] || '').split(' ')[0] : '',
                        method: idxMethod !== -1 ? String(row[idxMethod] || 'PIX') : 'PIX',
                        status: isRealizado ? 'Realizado' : 'Pendente'
                      };
                    });

                    const filteredFinancial = financialRows.filter(item => {
                      if (!dashboardSearch) return true;
                      const s = dashboardSearch.toLowerCase();
                      return item.patient.toLowerCase().includes(s) || 
                             item.category.toLowerCase().includes(s) || 
                             item.description.toLowerCase().includes(s) ||
                             item.method.toLowerCase().includes(s);
                    });

                    const balance = totalInflow - totalOutflow;

                    // Get dynamic SVG chart coordinates
                    const chartData = getFinancialChartData();
                    const maxAmount = Math.max(...chartData.map(d => Math.max(d.income, d.expense)), 500);

                    return (
                      <div className="space-y-6">
                        {/* Financial Ledger Highlights Widgets */}
                        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                          <div className="bg-emerald-50 border border-emerald-200/50 rounded-xl p-4 flex flex-col justify-between">
                            <span className="text-[10px] font-bold text-emerald-800 uppercase tracking-widest font-mono">Receitas Conciliadas</span>
                            <h3 className="text-xl font-bold font-serif text-emerald-950 mt-1">R$ {totalInflow.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</h3>
                            <p className="text-[10px] text-emerald-600 font-medium mt-1">Total acumulado de tratamentos concluídos</p>
                          </div>
                          <div className="bg-rose-50 border border-rose-200/50 rounded-xl p-4 flex flex-col justify-between">
                            <span className="text-[10px] font-bold text-rose-800 uppercase tracking-widest font-mono">Despesas Operacionais</span>
                            <h3 className="text-xl font-bold font-serif text-rose-950 mt-1">R$ {totalOutflow.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</h3>
                            <p className="text-[10px] text-rose-600 font-medium mt-1">Aluguel, fornecedores e insumos clínicos</p>
                          </div>
                          <div className={`border rounded-xl p-4 flex flex-col justify-between ${balance >= 0 ? 'bg-zinc-900 text-white border-zinc-800' : 'bg-red-950 text-white border-red-900'}`}>
                            <span className="text-[10px] font-bold text-[#C09553] uppercase tracking-widest font-mono">Saldo Consolidado</span>
                            <h3 className="text-xl font-bold font-serif text-[#FAF8F5] mt-1">R$ {balance.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</h3>
                            <p className="text-[10px] text-zinc-400 font-medium mt-1">Margem líquida residual com dados atuais</p>
                          </div>
                        </div>

                        {/* Interactive Vector Cashflow Flow chart */}
                        {chartData.length > 0 && (
                          <div className="bg-white border border-zinc-200 rounded-2xl p-4 space-y-4">
                            <div className="flex items-center justify-between">
                              <h4 className="font-serif font-bold text-zinc-800 text-xs uppercase flex items-center gap-1.5">
                                <Database className="w-4 h-4 text-[#C09553]" />
                                Histograma de Fluxo de Caixa Recente (SVG Nativo)
                              </h4>
                              <span className="text-[10px] text-zinc-400 bg-zinc-100 px-2 py-0.5 rounded font-mono">Max: R$ {maxAmount.toLocaleString()}</span>
                            </div>
                            <div className="w-full overflow-x-auto">
                              <div className="min-w-[500px] h-[160px] relative flex flex-col justify-end pb-6 px-4">
                                <svg className="w-full h-full" viewBox="0 0 500 130">
                                  {/* Gridlines */}
                                  <line x1="0" y1="0" x2="500" y2="0" stroke="#f4f4f5" strokeWidth="1" />
                                  <line x1="0" y1="40" x2="500" y2="40" stroke="#f4f4f5" strokeWidth="1" />
                                  <line x1="0" y1="80" x2="500" y2="80" stroke="#f4f4f5" strokeWidth="1" strokeDasharray="3,3" />
                                  <line x1="0" y1="120" x2="500" y2="120" stroke="#FAF8F5" strokeWidth="1" />

                                  {/* Render double columns grouped by interval */}
                                  {chartData.map((d, index) => {
                                    const colWidth = 24;
                                    const spacing = 500 / chartData.length;
                                    const x = index * spacing + spacing / 4;
                                    
                                    const hIn = (d.income / maxAmount) * 110;
                                    const hEx = (d.expense / maxAmount) * 110;

                                    return (
                                      <g key={index} className="group cursor-pointer">
                                        {/* Income Bar */}
                                        <rect 
                                          x={x} 
                                          y={120 - hIn} 
                                          width={colWidth / 2} 
                                          height={Math.max(hIn, 2)} 
                                          fill="#10b981" 
                                          rx="2"
                                          opacity="0.85"
                                          className="hover:opacity-100 transition-opacity"
                                        />
                                        {/* Expense Bar */}
                                        <rect 
                                          x={x + colWidth / 2 + 2} 
                                          y={120 - hEx} 
                                          width={colWidth / 2} 
                                          height={Math.max(hEx, 2)} 
                                          fill="#f43f5e" 
                                          rx="2"
                                          opacity="0.85"
                                          className="hover:opacity-100 transition-opacity"
                                        />
                                        {/* Labels */}
                                        <text 
                                          x={x + colWidth / 2} 
                                          y="130" 
                                          fill="#71717a" 
                                          fontSize="8" 
                                          fontFamily="monospace"
                                          textAnchor="middle"
                                        >
                                          {d.date}
                                        </text>
                                        {/* Dynamic Tooltip Mock values */}
                                        <title>
                                          {`Sessão/Período: ${d.date}\nEntradas: R$ ${d.income.toFixed(2)}\nSaídas: R$ ${d.expense.toFixed(2)}`}
                                        </title>
                                      </g>
                                    );
                                  })}
                                </svg>
                              </div>
                            </div>
                            <div className="flex gap-4 justify-center items-center text-[10px] text-zinc-500 font-medium">
                              <span className="flex items-center gap-1"><span className="w-2.5 h-2.5 rounded bg-emerald-500" /> Receitas</span>
                              <span className="flex items-center gap-1"><span className="w-2.5 h-2.5 rounded bg-rose-500" /> Despesas / Custos</span>
                            </div>
                          </div>
                        )}

                        {/* Financial search and ledger list container */}
                        <div className="bg-white border border-zinc-200 rounded-2xl overflow-hidden shadow-xs">
                          <div className="p-4 border-b border-zinc-100 bg-[#FAF8F5]/30 flex flex-col sm:flex-row justify-between items-center gap-4">
                            <div className="relative w-full sm:max-w-md">
                              <Search className="absolute left-3 top-2.5 w-4 h-4 text-[#C09553]" />
                              <input 
                                type="text"
                                placeholder="Filtrar por paciente, categoria, método de pagamento..."
                                value={dashboardSearch}
                                onChange={e => setDashboardSearch(e.target.value)}
                                className="w-full bg-white border border-zinc-300 rounded-lg pl-9 pr-4 py-2 focus:outline-none focus:border-[#C09553] text-[11px]"
                              />
                            </div>
                            
                            <button
                              type="button"
                              onClick={async () => {
                                setIsRunningImport(true);
                                alert("Exportando lote de "+ filteredFinancial.length +" recibos em PDF para sua pasta '/Faturamento' do Supabase...");
                                setTimeout(() => {
                                  setIsRunningImport(false);
                                  alert("Lote arquivado com sucesso!");
                                }, 1500);
                              }}
                              className="w-full sm:w-auto px-4 py-2 border border-[#D5CBB3] rounded-lg bg-white hover:bg-zinc-50 font-bold text-[#8B0000] flex items-center justify-center gap-1.5 self-stretch sm:self-auto cursor-pointer"
                            >
                              <Printer className="w-4 h-4 text-[#C09553]" />
                              Emitir Lote no Supabase
                            </button>
                          </div>

                          <div className="overflow-x-auto">
                            <table className="w-full text-left text-zinc-600 text-[11px]">
                              <thead className="bg-[#FAF8F5] border-b border-zinc-200 text-zinc-500 font-bold uppercase">
                                <tr>
                                  <th className="px-4 py-3">Código</th>
                                  <th className="px-4 py-3">Data</th>
                                  <th className="px-4 py-3">Paciente</th>
                                  <th className="px-4 py-3">Categoria</th>
                                  <th className="px-4 py-3">Forma</th>
                                  <th className="px-4 py-3">Status</th>
                                  <th className="px-4 py-3 text-right">Valor</th>
                                  <th className="px-4 py-3 text-center">Cobrança</th>
                                </tr>
                              </thead>
                              <tbody className="divide-y divide-zinc-100 font-medium">
                                {filteredFinancial.slice(0, 30).map((item, idx) => (
                                  <tr key={idx} className="hover:bg-zinc-50/50">
                                    <td className="px-4 py-2.5 font-mono text-zinc-400">#{item.id.split('.')[0]}</td>
                                    <td className="px-4 py-2.5 text-zinc-500">{item.date || '---'}</td>
                                    <td className="px-4 py-2.5 text-zinc-900 font-bold">{item.patient}</td>
                                    <td className="px-4 py-2.5 text-zinc-600 font-semibold">{item.category}</td>
                                    <td className="px-4 py-2.5 font-mono text-[10px] bg-zinc-50/50 px-2 rounded-md inline-block mt-2.5">{item.method}</td>
                                    <td className="px-4 py-2.5">
                                      <span className={`px-2 py-0.5 rounded text-[10px] font-bold ${item.status === 'Realizado' ? 'bg-emerald-50 text-emerald-700 border border-emerald-200' : 'bg-amber-50 text-amber-700 border border-amber-200'}`}>
                                        {item.status}
                                      </span>
                                    </td>
                                    <td className={`px-4 py-2.5 text-right font-bold text-xs ${item.isExpense ? 'text-rose-700' : 'text-emerald-700'}`}>
                                      {item.isExpense ? '-' : ''}R$ {item.amount.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                                    </td>
                                    <td className="px-4 py-2.5 text-center">
                                      {item.status === 'Pendente' ? (
                                        <button
                                          type="button"
                                          onClick={() => {
                                            const text = `Olá, *${item.patient}*! Lembramos do vencimento da sua guia de parcelamento no valor de *R$ ${item.amount.toFixed(2)}* referente a ${item.category}. Segue chave PIX do consultório: ${clinicSettings.cro}. Qualquer dúvida, estamos aqui!`;
                                            window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, '_blank');
                                          }}
                                          className="text-[10px] font-bold text-amber-800 hover:text-amber-900 bg-amber-50 hover:bg-amber-100 border border-amber-200 px-2 py-1 rounded inline-flex items-center gap-1 cursor-pointer transition-colors"
                                        >
                                          <Send className="w-3 h-3 text-[#C09553]" />
                                          Lembrete
                                        </button>
                                      ) : (
                                        <button
                                          type="button"
                                          onClick={() => {
                                            const text = `Olá, *${item.patient}*! Confirmamos o recebimento e conciliação do seu pagamento no valor de *R$ ${item.amount.toFixed(2)}* via ${item.method} pelo procedimento de ${item.category}. Seu recibo digital está anexado na sua pasta virtual. Obrigado pela confiança!`;
                                            window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, '_blank');
                                          }}
                                          className="text-[10px] font-bold text-emerald-800 hover:text-emerald-950 bg-emerald-50 hover:bg-emerald-100 border border-emerald-200 px-2 py-1 rounded inline-flex items-center gap-1 cursor-pointer transition-colors"
                                        >
                                          <Check className="w-3 h-3 text-emerald-600" />
                                          Recibo
                                        </button>
                                      )}
                                    </td>
                                  </tr>
                                ))}
                                {filteredFinancial.length === 0 && (
                                  <tr>
                                    <td colSpan={8} className="px-4 py-8 text-center text-zinc-400">Nenhum lançamento corresponde ao filtro.</td>
                                  </tr>
                                )}
                              </tbody>
                            </table>
                          </div>
                        </div>
                      </div>
                    );
                  })()}

                  {/* WORKSPACE ODONTOGRAMA / PROCEDIMENTOS */}
                  {getDetectedDataType() === 'odontograma' && (() => {
                    // Extract column indices
                    const idxDente = headers.findIndex(h => ['codigo_dente', 'dente', 'num_dente'].includes(h.toLowerCase().trim()));
                    const idxProc = headers.findIndex(h => ['descricao_procedimento', 'procedimento', 'descricao'].includes(h.toLowerCase().trim()));
                    const idxVal = headers.findIndex(h => ['valor', 'preco'].includes(h.toLowerCase().trim()));
                    const idxPatient = headers.findIndex(h => ['nome_paciente', 'paciente', 'cliente'].includes(h.toLowerCase().trim()));
                    const idxDentist = headers.findIndex(h => ['nome_dentista', 'dentista', 'profissional'].includes(h.toLowerCase().trim()));
                    const idxStatus = headers.findIndex(h => ['descricao_situacao', 'situacao', 'status'].includes(h.toLowerCase().trim()));
                    const idxArcada = headers.findIndex(h => ['nome_arcada', 'arcada'].includes(h.toLowerCase().trim()));
                    const idxDate = headers.findIndex(h => ['data_realizado', 'data_criacao_odontograma', 'created_at'].includes(h.toLowerCase().trim()));

                    const patientsList = getUniquePatientNames();
                    const activePatient = selectedPatientFilter || patientsList[0] || '';

                    // Filter calculations for the active patient
                    const records = rawData.slice(1).filter(row => {
                      if (!activePatient) return true;
                      const nameVal = idxPatient !== -1 ? String(row[idxPatient] || '').trim() : '';
                      return nameVal === activePatient;
                    });

                    // Build formatted procedures
                    const patientProcs = records.map(p => {
                      const denteNum = idxDente !== -1 ? parseInt(p[idxDente]) || 0 : 0;
                      const valNum = idxVal !== -1 ? parseFloat(String(p[idxVal]).replace(/[^\d\.]/g, '')) || 0 : 0;
                      const procStatus = idxStatus !== -1 ? String(p[idxStatus]).trim() : '';
                      return {
                        tooth: denteNum,
                        name: idxProc !== -1 ? String(p[idxProc] || 'Tratamento') : 'Tratamento',
                        price: valNum,
                        status: procStatus,
                        dentist: idxDentist !== -1 ? String(p[idxDentist] || 'Dr. Agnaldo Ferreira') : 'Dr. Agnaldo Ferreira',
                        arcada: idxArcada !== -1 ? String(p[idxArcada] || 'SUPERIOR') : 'SUPERIOR',
                        date: idxDate !== -1 ? String(p[idxDate] || '').split(' ')[0] : ''
                      };
                    });

                    const totalValue = patientProcs.reduce((acc, curr) => acc + curr.price, 0);
                    const doneValue = patientProcs.filter(p => p.status.toLowerCase().includes('realiz')).reduce((acc, curr) => acc + curr.price, 0);
                    const pendingValue = totalValue - doneValue;

                    // Tooth index set
                    const teethStats: Record<number, string> = {};
                    patientProcs.forEach(p => {
                      if (p.tooth) {
                        teethStats[p.tooth] = p.status;
                      }
                    });

                    return (
                      <div className="space-y-6">
                        {/* Upper Bar With Patient Selector */}
                        <div className="bg-[#8B0000]/5 border border-[#C09553]/30 rounded-xl p-4 flex flex-col sm:flex-row justify-between items-center gap-4">
                          <div className="space-y-1">
                            <label className="block text-zinc-600 font-bold text-[10px] uppercase font-mono tracking-wider">Selecione o Prontuário do Paciente</label>
                            <select 
                              value={activePatient}
                              onChange={(e) => setSelectedPatientFilter(e.target.value)}
                              className="border border-[#D5CBB3] bg-white rounded-lg p-2 font-serif text-sm font-bold focus:outline-none focus:border-[#C09553] text-[#8B0000]"
                            >
                              {patientsList.map(name => (
                                <option key={name} value={name}>{name}</option>
                              ))}
                            </select>
                          </div>

                          <div className="flex gap-2 self-stretch sm:self-auto">
                            <button
                              type="button"
                              onClick={() => handleShareProceduresWhatsApp(activePatient)}
                              className="flex-1 sm:flex-none px-4 py-2 border border-[#D5CBB3] rounded-lg bg-emerald-50 hover:bg-emerald-100 font-bold text-emerald-800 text-xs flex items-center justify-center gap-1.5 cursor-pointer transition-colors"
                            >
                              <Send className="w-3.5 h-3.5 text-emerald-600" />
                              Enviar p/ WhatsApp
                            </button>
                            <button
                              type="button"
                              onClick={async () => {
                                setIsRunningImport(true);
                                alert("Salvando histórico de tratamento clínico de '"+ activePatient +"' diretamente como prontuário cronológico certificado no Supabase...");
                                setTimeout(() => {
                                  setIsRunningImport(false);
                                  alert("Sincronização concluída com sucesso!");
                                }, 1500);
                              }}
                              className="flex-1 sm:flex-none px-4 py-2 border border-[#D5CBB3] rounded-lg bg-white hover:bg-zinc-50 font-bold text-[#8B0000] text-xs flex items-center justify-center gap-1.5 cursor-pointer transition-colors"
                            >
                              <Printer className="w-3.5 h-3.5 text-[#C09553]" />
                              Gravar Prontuário Drive
                            </button>
                          </div>
                        </div>

                        {/* Interactive Oral Charting Canvas Map */}
                        <div className="bg-white border border-zinc-200 rounded-2xl p-6 text-center space-y-4 shadow-sm">
                          <h4 className="font-serif font-bold text-[#8B0000] text-xs uppercase tracking-wide flex items-center justify-center gap-1.5">
                            <Layers className="w-4 h-4 text-[#C09553]" />
                            Mapeamento Visual de Tratamentos (Odontograma Clínico)
                          </h4>
                          <p className="text-zinc-500 text-[11px] leading-relaxed">Representação interativa de dentes com tratamentos localizados da planilha de backup. Passe o mouse ou clique para ver os detalhes clínicos.</p>
                          
                          <div className="flex flex-wrap justify-center items-center gap-2 max-w-4xl mx-auto py-4">
                            {/* Superior arch */}
                            <div className="w-full flex justify-center gap-1.5 flex-wrap">
                              <span className="w-10 text-[10px] text-zinc-400 font-serif font-semibold self-center uppercase pr-2 text-right">SUP:</span>
                              {[18, 17, 16, 15, 14, 13, 12, 11, 21, 22, 23, 24, 25, 26, 27, 28].map(toothNum => {
                                const status = teethStats[toothNum];
                                let colorClass = 'bg-zinc-100 hover:bg-zinc-200 border-zinc-300 text-zinc-700';
                                if (status) {
                                  if (status.toLowerCase().includes('realiz')) {
                                    colorClass = 'bg-emerald-500 hover:bg-emerald-600 border-emerald-600 text-white animate-pulse-slow';
                                  } else {
                                    colorClass = 'bg-amber-500 hover:bg-amber-600 border-amber-600 text-white';
                                  }
                                }
                                return (
                                  <div 
                                    key={toothNum}
                                    title={status ? `Dente ${toothNum}: ${status}` : `Dente ${toothNum}: Saudável / Sem intervenção`}
                                    className={`w-9 h-12 flex flex-col justify-between items-center p-1 rounded border text-[11px] font-bold cursor-pointer transition-all ${colorClass}`}
                                  >
                                    <span>{toothNum}</span>
                                    <span className="text-[7.5px] uppercase font-mono">{status ? (status.toLowerCase().includes('realiz') ? 'OK' : 'PND') : 'S'}</span>
                                  </div>
                                );
                              })}
                            </div>

                            {/* Inferior arch */}
                            <div className="w-full flex justify-center gap-1.5 flex-wrap mt-2">
                              <span className="w-10 text-[10px] text-zinc-400 font-serif font-semibold self-center uppercase pr-2 text-right">INF:</span>
                              {[48, 47, 46, 45, 44, 43, 42, 41, 31, 32, 33, 34, 35, 36, 37, 38].map(toothNum => {
                                const status = teethStats[toothNum];
                                let colorClass = 'bg-zinc-100 hover:bg-zinc-200 border-zinc-300 text-zinc-700';
                                if (status) {
                                  if (status.toLowerCase().includes('realiz')) {
                                    colorClass = 'bg-emerald-500 hover:bg-emerald-600 border-emerald-600 text-white';
                                  } else {
                                    colorClass = 'bg-amber-500 hover:bg-amber-600 border-amber-600 text-white';
                                  }
                                }
                                return (
                                  <div 
                                    key={toothNum}
                                    title={status ? `Dente ${toothNum}: ${status}` : `Dente ${toothNum}: Sem alterações`}
                                    className={`w-9 h-12 flex flex-col justify-between items-center p-1 rounded border text-[11px] font-bold cursor-pointer transition-all ${colorClass}`}
                                  >
                                    <span>{toothNum}</span>
                                    <span className="text-[7.5px] uppercase font-mono">{status ? (status.toLowerCase().includes('realiz') ? 'OK' : 'PND') : 'S'}</span>
                                  </div>
                                );
                              })}
                            </div>
                          </div>

                          <div className="flex gap-4 justify-center items-center text-[10px] text-zinc-400 font-mono">
                            <span className="flex items-center gap-1"><span className="w-2.5 h-2.5 rounded bg-emerald-500" /> Realizado / Concluído</span>
                            <span className="flex items-center gap-1"><span className="w-2.5 h-2.5 rounded bg-amber-500" /> Planejado / À Realizar</span>
                            <span className="flex items-center gap-1"><span className="w-2.5 h-2.5 rounded bg-zinc-100 border border-zinc-300" /> Ausente ou Sem Tratamento</span>
                          </div>
                        </div>

                        {/* Interactive procedure detail cards widgets */}
                        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                          <div className="bg-zinc-50 border border-zinc-200 rounded-xl p-4 flex flex-col justify-between text-xs">
                            <span className="text-zinc-500 font-bold uppercase font-mono">Valor Total</span>
                            <h3 className="text-base font-bold text-zinc-900 mt-1">R$ {totalValue.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</h3>
                          </div>
                          <div className="bg-emerald-50 border border-emerald-100 rounded-xl p-4 flex flex-col justify-between text-xs">
                            <span className="text-emerald-700 font-bold uppercase font-mono">Concluído</span>
                            <h3 className="text-base font-bold text-emerald-900 mt-1">R$ {doneValue.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</h3>
                          </div>
                          <div className="bg-amber-50 border border-amber-100 rounded-xl p-4 flex flex-col justify-between text-xs">
                            <span className="text-amber-700 font-bold uppercase font-mono">Pendente</span>
                            <h3 className="text-base font-bold text-amber-900 mt-1">R$ {pendingValue.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</h3>
                          </div>
                        </div>

                        {/* List Procedures Ledger */}
                        <div className="bg-white border border-zinc-200 rounded-2xl overflow-hidden shadow-xs">
                          <div className="bg-zinc-50 px-4 py-3 border-b border-zinc-200">
                            <span className="font-serif font-bold text-zinc-800 text-xs uppercase">Relação Cronológica de Procedimentos ({patientProcs.length} no backup)</span>
                          </div>
                          <div className="overflow-x-auto">
                            <table className="w-full text-left text-zinc-600 text-[11px] font-medium">
                              <thead className="bg-[#FAF8F5] border-b border-zinc-200 text-zinc-500 font-bold uppercase">
                                <tr>
                                  <th className="px-4 py-3">Dente</th>
                                  <th className="px-4 py-3">Arcada</th>
                                  <th className="px-4 py-3">Procedimento</th>
                                  <th className="px-4 py-3">Estágio</th>
                                  <th className="px-4 py-3">Dentista Executante</th>
                                  <th className="px-4 py-3 text-right">Preço</th>
                                </tr>
                              </thead>
                              <tbody className="divide-y divide-zinc-100">
                                {patientProcs.map((item, idx) => (
                                  <tr key={idx} className="hover:bg-zinc-50/50">
                                    <td className="px-4 py-2.5 font-bold text-[#8B0000] text-xs">Dente {item.tooth || 'Geral'}</td>
                                    <td className="px-4 py-2.5 font-mono text-[10px] text-zinc-400 uppercase">{item.arcada}</td>
                                    <td className="px-4 py-2.5 text-zinc-900 font-bold">{item.name}</td>
                                    <td className="px-4 py-2.5">
                                      <span className={`px-1.5 py-0.5 rounded text-[10px] font-bold ${
                                        item.status.toLowerCase().includes('realiz') ? 'bg-emerald-50 text-emerald-700' : 'bg-amber-50 text-amber-700'
                                      }`}>
                                        {item.status}
                                      </span>
                                    </td>
                                    <td className="px-4 py-2.5 text-zinc-500">{item.dentist}</td>
                                    <td className="px-4 py-2.5 text-right font-bold text-zinc-800">R$ {item.price.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</td>
                                  </tr>
                                ))}
                                {patientProcs.length === 0 && (
                                  <tr>
                                    <td colSpan={6} className="px-4 py-8 text-center text-zinc-400">Nenhum procedimento mapeado para este paciente neste backup.</td>
                                  </tr>
                                )}
                              </tbody>
                            </table>
                          </div>
                        </div>
                      </div>
                    );
                  })()}

                  {/* WORKSPACE AGENDAMENTOS */}
                  {getDetectedDataType() === 'agendamentos' && (() => {
                    // Extract column indices
                    const idxPatient = headers.findIndex(h => ['nome_paciente', 'paciente', 'cliente'].includes(h.toLowerCase().trim()));
                    const idxDate = headers.findIndex(h => ['data_agendamento', 'data', 'data_consulta'].includes(h.toLowerCase().trim()));
                    const idxTime = headers.findIndex(h => ['hora_agendamento', 'hora', 'horario'].includes(h.toLowerCase().trim()));
                    const idxStatus = headers.findIndex(h => ['nome_status', 'status', 'situacao'].includes(h.toLowerCase().trim()));
                    const idxRoom = headers.findIndex(h => ['nome_sala', 'sala'].includes(h.toLowerCase().trim()));
                    const idxConv = headers.findIndex(h => ['nome_convenio', 'convenio'].includes(h.toLowerCase().trim()));
                    const idxDentist = headers.findIndex(h => ['nome_dentista', 'dentista'].includes(h.toLowerCase().trim()));

                    const appointments = rawData.slice(1).map((row, idx) => {
                      const dateVal = idxDate !== -1 ? row[idxDate] : '';
                      const timeVal = idxTime !== -1 ? row[idxTime] : '';
                      const dateObj = parseExcelDateTime(dateVal, timeVal);
                      
                      return {
                        id: row[headers.findIndex(h => h.toLowerCase() === 'codigo_agendamento')] || idx.toString(),
                        patient: idxPatient !== -1 ? String(row[idxPatient] || 'Geral') : 'Geral',
                        dateRaw: dateVal,
                        timeRaw: timeVal,
                        dateObj,
                        status: idxStatus !== -1 ? String(row[idxStatus] || '') : 'Agendado',
                        room: idxRoom !== -1 ? String(row[idxRoom] || '') : 'Consultório 1',
                        dentist: idxDentist !== -1 ? String(row[idxDentist] || '') : 'Dr. Agnaldo Ferreira',
                        convenio: idxConv !== -1 ? String(row[idxConv] || 'PARTICULAR') : 'PARTICULAR',
                        phone: row[headers.findIndex(h => h.toLowerCase() === 'fone1_agendamento')] || ''
                      };
                    }).sort((a,b) => (b.dateObj?.getTime() || 0) - (a.dateObj?.getTime() || 0));

                    const filteredEvents = appointments.filter(appt => {
                      if (!dashboardSearch) return true;
                      const s = dashboardSearch.toLowerCase();
                      return appt.patient.toLowerCase().includes(s) || 
                             appt.status.toLowerCase().includes(s) || 
                             appt.dentist.toLowerCase().includes(s);
                    });

                    // Stats calculation
                    const totalCount = appointments.length;
                    const attendedCount = appointments.filter(a => a.status.toLowerCase().includes('atend') || a.status.toLowerCase().includes('realiz')).length;
                    const pendingCount = appointments.filter(a => a.status.toLowerCase() === 'agendado' || a.status.toLowerCase() === 'confirmado').length;

                    return (
                      <div className="space-y-6">
                        {/* Metrics summary widgets */}
                        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                          <div className="bg-[#FAF8F5] border border-[#D5CBB3] rounded-xl p-4 flex flex-col justify-between text-xs">
                            <span className="text-zinc-500 font-bold uppercase font-mono">Total Agendamentos</span>
                            <h3 className="text-base font-bold text-[#8B0000] mt-1">{totalCount} no backup</h3>
                          </div>
                          <div className="bg-emerald-50 border border-emerald-200/50 rounded-xl p-4 flex flex-col justify-between text-xs">
                            <span className="text-emerald-700 font-bold uppercase font-mono">Atendidos / Concluídos</span>
                            <h3 className="text-base font-bold text-emerald-950 mt-1">{attendedCount} consultas</h3>
                          </div>
                          <div className="bg-sky-50 border border-blue-200/50 rounded-xl p-4 flex flex-col justify-between text-xs">
                            <span className="text-sky-700 font-bold uppercase font-mono">Pendentes / Confirmados</span>
                            <h3 className="text-base font-bold text-sky-950 mt-1">{pendingCount} consultas</h3>
                          </div>
                        </div>

                        {/* Search and sync master operations panel */}
                        <div className="bg-white border border-zinc-200 rounded-2xl overflow-hidden shadow-xs">
                          <div className="p-4 border-b border-zinc-100 bg-[#FAF8F5]/30 flex flex-col sm:flex-row justify-between items-center gap-4">
                            <div className="relative w-full sm:max-w-md">
                              <Search className="absolute left-3 top-2.5 w-4 h-4 text-[#C09553]" />
                              <input 
                                type="text"
                                placeholder="Filtrar por paciente, status, dentista..."
                                value={dashboardSearch}
                                onChange={e => setDashboardSearch(e.target.value)}
                                className="w-full bg-white border border-zinc-300 rounded-lg pl-9 pr-4 py-2 focus:outline-none focus:border-[#C09553] text-[11px]"
                              />
                            </div>
                            
                            <button
                              type="button"
                              onClick={async () => {
                                setIsRunningImport(true);
                                alert("Carregando lote de agendamentos no Google Calendar integrado via OAuth...");
                                let cnt = 0;
                                for (let s = 0; s < Math.min(filteredEvents.length, 10); s++) {
                                  const ev = filteredEvents[s];
                                  if (ev.dateObj) {
                                    const apptDateIso = ev.dateObj.toISOString();
                                    await createCalendarEvent({
                                      summary: `Consulta Dental: ${ev.patient}`,
                                      description: `Importado via Workspace. Sala: ${ev.room}. Dentista: ${ev.dentist}. Convênio: ${ev.convenio}`,
                                      start: { dateTime: apptDateIso },
                                      end: { dateTime: new Date(ev.dateObj.getTime() + 60*60*1000).toISOString() }
                                    });
                                    cnt++;
                                  }
                                }
                                setIsRunningImport(false);
                                alert("Sincronização realizada! " + cnt + " consultas criadas no Google Agenda!");
                              }}
                              className="w-full sm:w-auto px-4 py-2 bg-[#8B0000] hover:bg-[#340A0F] rounded-lg text-white font-bold text-xs uppercase tracking-wider flex items-center justify-center gap-1.5 cursor-pointer self-stretch sm:self-auto transition-colors"
                            >
                              <Calendar className="w-4 h-4 text-[#C09553]" />
                              Sincronizar c/ Google Agenda
                            </button>
                          </div>

                          <div className="overflow-x-auto">
                            <table className="w-full text-left text-zinc-600 text-[11px] font-medium">
                              <thead className="bg-[#FAF8F5] border-b border-zinc-200 text-zinc-500 font-bold uppercase">
                                <tr>
                                  <th className="px-4 py-3">Consulta</th>
                                  <th className="px-4 py-3">Paciente</th>
                                  <th className="px-4 py-3">Status</th>
                                  <th className="px-4 py-3">Sala / Estúdio</th>
                                  <th className="px-4 py-3">Dentista</th>
                                  <th className="px-4 py-3">Convênio</th>
                                  <th className="px-4 py-3 text-center">G-Cal / iCal</th>
                                  <th className="px-4 py-3 text-center">WhatsApp</th>
                                </tr>
                              </thead>
                              <tbody className="divide-y divide-zinc-100">
                                {filteredEvents.slice(0, 30).map((appt, idx) => (
                                  <tr key={idx} className="hover:bg-zinc-50/50">
                                    <td className="px-4 py-3">
                                      {appt.dateObj ? (
                                        <span className="font-mono text-zinc-900 font-bold bg-[#FAF8F5] border border-[#D5CBB3]/50 px-1.5 py-0.5 rounded text-[10px]">
                                          {appt.dateObj.toLocaleDateString('pt-BR')} {appt.dateObj.toLocaleTimeString('pt-BR', { hour:'2-digit', minute:'2-digit' })}
                                        </span>
                                      ) : (
                                        <span className="text-zinc-400 font-mono">Sem data</span>
                                      )}
                                    </td>
                                    <td className="px-4 py-3 text-zinc-950 font-bold text-xs">{appt.patient}</td>
                                    <td className="px-4 py-3">
                                      <span className={`px-2 py-0.5 rounded text-[9.5px] font-bold ${
                                        appt.status.toLowerCase().includes('atend') || appt.status.toLowerCase().includes('realiz')
                                          ? 'bg-emerald-50 text-emerald-700 border border-emerald-100'
                                          : appt.status.toLowerCase().includes('falt') 
                                          ? 'bg-rose-50 text-rose-700 border border-rose-100'
                                          : 'bg-sky-50 text-sky-700 border border-blue-100'
                                      }`}>
                                        {appt.status}
                                      </span>
                                    </td>
                                    <td className="px-4 py-3 text-zinc-500 font-mono text-[10px]">{appt.room || 'Consultório 1'}</td>
                                    <td className="px-4 py-3 text-zinc-600">{appt.dentist || 'Dr. Agnaldo Ferreira'}</td>
                                    <td className="px-4 py-3 text-zinc-400 text-[10px] font-bold">{appt.convenio}</td>
                                    <td className="px-2 py-3 text-center">
                                      <button
                                        type="button"
                                        onClick={() => downloadIcsFile(appt)}
                                        className="text-[10px] font-bold text-sky-850 hover:text-sky-950 bg-sky-50 hover:bg-sky-100 border border-sky-100 px-2 py-1 rounded inline-flex items-center gap-1 cursor-pointer transition-colors"
                                      >
                                        <Calendar className="w-3.5 h-3.5 text-[#C09553]" />
                                        iCal
                                      </button>
                                    </td>
                                    <td className="px-2 py-3 text-center">
                                      <button
                                        type="button"
                                        onClick={() => {
                                          const text = `Olá, *${appt.patient}*! Dr. Agnaldo Ferreira confirma a sua consulta odontológica agendada no dia *${appt.dateRaw}* às *${appt.timeRaw}* na *${appt.room || 'sala principal'}*. Caso haja qualquer imprevisto que impeça sua vinda, pedimos que nos comunique com 24h de antecedência. Ficamos no aguardo!`;
                                          window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, '_blank');
                                        }}
                                        className="text-[10px] font-bold text-emerald-800 hover:text-emerald-950 bg-emerald-50 hover:bg-emerald-100 border border-emerald-200 px-2 py-1 rounded inline-flex items-center gap-1 cursor-pointer transition-colors"
                                      >
                                        <Send className="w-3 h-3 text-emerald-600" />
                                        Mandar Lembrete
                                      </button>
                                    </td>
                                  </tr>
                                ))}
                                {filteredEvents.length === 0 && (
                                  <tr>
                                    <td colSpan={8} className="px-4 py-8 text-center text-zinc-400">Nenhum agendamento listado no backup para os filtros selecionados.</td>
                                  </tr>
                                )}
                              </tbody>
                            </table>
                          </div>
                        </div>
                      </div>
                    );
                  })()}

                  {/* WORKSPACE ANAMNESE */}
                  {getDetectedDataType() === 'anamnese' && (() => {
                    const idxPatient = headers.findIndex(h => ['nome_paciente', 'paciente', 'cliente'].includes(h.toLowerCase().trim()));
                    const idxHeading = headers.findIndex(h => ['nome_anamnese', 'anamnese'].includes(h.toLowerCase().trim()));
                    const idxQuestion = headers.findIndex(h => ['texto_pergunta', 'pergunta'].includes(h.toLowerCase().trim()));
                    const idxAnswer = headers.findIndex(h => ['resposta', 'valor'].includes(h.toLowerCase().trim()));
                    const idxAdd = headers.findIndex(h => ['texto_adicional', 'justificativa'].includes(h.toLowerCase().trim()));

                    const patientsNamesList = getUniquePatientNames();
                    const activePatient = selectedPatientFilter || patientsNamesList[0] || '';

                    // Filter calculations for the active patient
                    const records = rawData.slice(1).filter(row => {
                      if (!activePatient) return true;
                      const nameVal = idxPatient !== -1 ? String(row[idxPatient] || '').trim() : '';
                      return nameVal === activePatient;
                    });

                    // Build formatted survey answers
                    const surveyData = records.map(p => {
                      return {
                        heading: idxHeading !== -1 ? String(p[idxHeading] || 'Investigação Geral') : 'Anamnese Geral',
                        question: idxQuestion !== -1 ? String(p[idxQuestion]) : 'Pergunta',
                        answer: idxAnswer !== -1 ? String(p[idxAnswer] || '').trim() : 'Não especificado',
                        details: idxAdd !== -1 ? String(p[idxAdd] || '').trim() : ''
                      };
                    });

                    // Screen critical clinical variables for alerts
                    const criticalAlerts: string[] = [];
                    surveyData.forEach(item => {
                      const qLower = item.question.toLowerCase();
                      const ansLower = item.answer.toLowerCase();
                      const detailsLower = item.details.toLowerCase();

                      const isPositive = ansLower === 'sim' || ansLower === 'yes' || (item.details && detailsLower !== 'nan' && detailsLower !== '');

                      if (isPositive) {
                        if (qLower.includes('alergia')) {
                          criticalAlerts.push(`⚠️ ALERGIA: ${item.details || item.answer}`);
                        } else if (qLower.includes('doen') || qLower.includes('crônica') || qLower.includes('hipertensão') || qLower.includes('diabetes')) {
                          criticalAlerts.push(`⚠️ PATOLOGIA CRÔNICA: ${item.details || item.answer}`);
                        } else if (qLower.includes('medicamento') || qLower.includes('remédio')) {
                          criticalAlerts.push(`💊 MEDICAÇÃO CONTÍNUA: ${item.details || item.answer}`);
                        } else if (qLower.includes('grávida') || qLower.includes('gestante')) {
                          criticalAlerts.push(`🤰 PACIENTE GESTANTE! cuidados redobrados com anestésico!`);
                        }
                      }
                    });

                    return (
                      <div className="space-y-6">
                        {/* Top bar control */}
                        <div className="bg-[#8B0000]/5 border border-[#C09553]/30 rounded-xl p-4 flex flex-col sm:flex-row justify-between items-center gap-4">
                          <div className="space-y-1">
                            <label className="block text-zinc-600 font-bold text-[10px] uppercase font-mono tracking-wider">Prontuário de Ficha de Anamnese</label>
                            <select 
                              value={activePatient}
                              onChange={(e) => setSelectedPatientFilter(e.target.value)}
                              className="border border-[#D5CBB3] bg-white rounded-lg p-2 font-serif text-sm font-bold focus:outline-none focus:border-[#C09553] text-[#8B0000]"
                            >
                              {patientsNamesList.map(name => (
                                <option key={name} value={name}>{name}</option>
                              ))}
                            </select>
                          </div>

                          <button
                            type="button"
                            onClick={async () => {
                              setIsRunningImport(true);
                              alert("Armazenando Ficha de Resposta Anamnese de '"+ activePatient +"' na pasta criptografada do prontuário no Supabase...");
                              setTimeout(() => {
                                setIsRunningImport(false);
                                alert("Documento médico encriptado com sucesso!");
                              }, 1200);
                            }}
                            className="w-full sm:w-auto px-4 py-2 border border-[#D5CBB3] rounded-lg bg-zinc-900 hover:bg-zinc-800 font-bold text-white text-xs flex items-center justify-center gap-1.5 cursor-pointer transition-colors"
                          >
                            <Settings className="w-3.5 h-3.5 text-[#C09553]" />
                            Gravar Termo Certificado no Supabase
                          </button>
                        </div>

                        {/* Severe alerts panel */}
                        {criticalAlerts.length > 0 && (
                          <div className="bg-rose-50 border-2 border-rose-300 p-4 rounded-xl space-y-2 animate-fade-in shadow-xs">
                            <h4 className="text-rose-900 font-bold text-xs uppercase flex items-center gap-1.5 font-sans leading-none">
                              <ShieldAlert className="w-4 h-4 text-rose-700 shrink-0" />
                              ⚠️ Alertas Clínicos Críticos Identificados (Anamnese)
                            </h4>
                            <div className="flex flex-wrap gap-2 pt-1">
                              {criticalAlerts.map((alt, i) => (
                                <span key={i} className="bg-rose-200 text-rose-950 px-2.5 py-1 rounded text-[10px] font-bold border border-rose-300 shadow-xs uppercase tracking-wide">
                                  {alt}
                                </span>
                              ))}
                            </div>
                          </div>
                        )}

                        {/* Interactive Questionnaire structure list */}
                        <div className="bg-white border border-zinc-200 rounded-2xl overflow-hidden shadow-xs">
                          <div className="bg-[#FAF8F5] border-b border-zinc-200 px-4 py-3 flex justify-between items-center">
                            <span className="font-serif font-bold text-zinc-800 text-xs sm:text-sm uppercase tracking-wide">Investigação de Anamnese: {activePatient}</span>
                            <span className="text-[10px] text-zinc-400 bg-zinc-200 px-2 py-0.5 rounded font-mono font-bold">{surveyData.length} Mapeamentos</span>
                          </div>

                          <div className="p-4 grid grid-cols-1 md:grid-cols-2 gap-4 bg-[#FAF8F5]/10">
                            {surveyData.map((item, idx) => {
                              const isPositive = item.answer.toLowerCase() === 'sim' || item.answer.toLowerCase() === 'yes';
                              
                              return (
                                <div 
                                  key={idx} 
                                  className={`p-3.5 rounded-xl border flex flex-col justify-between transition-all ${
                                    isPositive 
                                      ? 'bg-amber-50/50 border-amber-200 shadow-xs' 
                                      : 'bg-white border-zinc-200'
                                  }`}
                                >
                                  <div>
                                    <span className="text-[8.5px] font-bold text-zinc-400 font-mono tracking-widest uppercase mb-1.5 block">{item.heading}</span>
                                    <p className="text-zinc-800 text-[11px] font-bold leading-normal">{item.question}</p>
                                  </div>
                                  <div className="mt-3 flex items-center justify-between gap-4 pt-2 border-t border-dashed border-zinc-100">
                                    <span className={`px-2 py-0.5 rounded text-[10px] font-bold ${
                                      isPositive ? 'bg-amber-100 text-amber-900' : 'bg-zinc-100 text-zinc-600'
                                    }`}>
                                      Resposta: {item.answer.toUpperCase()}
                                    </span>
                                    {item.details && item.details !== 'nan' && (
                                      <span className="text-zinc-500 italic text-[10px] font-medium tracking-wide">
                                        Observações: <strong className="text-zinc-700">{item.details}</strong>
                                      </span>
                                    )}
                                  </div>
                                </div>
                              );
                            })}
                            {surveyData.length === 0 && (
                              <div className="col-span-2 py-8 text-center text-zinc-400">Nenhum dado de questionário disponível.</div>
                            )}
                          </div>
                        </div>
                      </div>
                    );
                  })()}

                  {/* WORKSPACE DOCUMENTOS */}
                  {getDetectedDataType() === 'documentos' && (() => {
                    const idxPatient = headers.findIndex(h => ['nome_paciente', 'paciente', 'cliente'].includes(h.toLowerCase().trim()));
                    const idxContent = headers.findIndex(h => ['conteudo_documento', 'conteudo', 'texto'].includes(h.toLowerCase().trim()));
                    const idxType = headers.findIndex(h => ['nome_tipo_documento', 'tipo_documento', 'tipo'].includes(h.toLowerCase().trim()));
                    const idxDate = headers.findIndex(h => ['data_documento', 'data', 'created_at'].includes(h.toLowerCase().trim()));

                    const docsList = rawData.slice(1).map((row, idx) => {
                      return {
                        id: idx.toString(),
                        patient: idxPatient !== -1 ? String(row[idxPatient] || 'Geral') : 'Geral',
                        type: idxType !== -1 ? String(row[idxType] || 'Formulário') : 'Formulário',
                        content: idxContent !== -1 ? String(row[idxContent] || '') : '',
                        date: idxDate !== -1 ? String(row[idxDate] || '').split(' ')[0] : ''
                      };
                    });

                    const selectedDocId = selectedPatientFilter || docsList[0]?.id || '';
                    const docObj = docsList.find(d => d.id === selectedDocId) || docsList[0];

                    if (!docObj) return <div className="text-center py-6 text-zinc-400">Sem documentos para exibir.</div>;

                    return (
                      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
                        {/* Selector sidebar */}
                        <div className="lg:col-span-4 bg-white border border-zinc-200 rounded-2xl p-4 space-y-4 shadow-sm">
                          <h4 className="font-serif font-bold text-zinc-800 text-xs uppercase tracking-wide">Documentos Disponíveis ({docsList.length})</h4>
                          <div className="space-y-1.5 max-h-96 overflow-y-auto pr-1">
                            {docsList.map(doc => (
                              <button
                                key={doc.id}
                                onClick={() => setSelectedPatientFilter(doc.id)}
                                className={`w-full text-left p-2.5 rounded-xl border text-[11px] font-medium flex justify-between items-center transition-all ${
                                  selectedDocId === doc.id 
                                    ? 'bg-[#8B0000] border-emerald-950 text-white shadow-sm font-bold' 
                                    : 'bg-zinc-50 border-zinc-200 text-zinc-700 hover:bg-zinc-100/50'
                                }`}
                              >
                                <div>
                                  <div className="truncate pr-2">{doc.patient}</div>
                                  <div className={`mt-0.5 text-[9px] ${selectedDocId === doc.id ? 'text-[#C09553]' : 'text-zinc-400'}`}>{doc.type}</div>
                                </div>
                                <span className="font-mono text-[9.5px] opacity-75">{doc.date}</span>
                              </button>
                            ))}
                          </div>
                        </div>

                        {/* Frame view preview zone */}
                        <div className="lg:col-span-8 bg-white border border-zinc-200 rounded-2xl p-6 space-y-6 shadow-sm flex flex-col justify-between">
                          <div className="flex items-center justify-between border-b border-zinc-100 pb-3">
                            <div>
                              <span className="bg-[#FAF8F5] text-[#C09553] px-2 py-0.5 border border-[#D5CBB3]/40 rounded text-[9.5px] font-bold uppercase tracking-wider">{docObj.type}</span>
                              <h3 className="font-serif font-bold text-zinc-900 text-sm mt-1">Beneficiário: {docObj.patient}</h3>
                            </div>
                            <button
                              type="button"
                              onClick={() => {
                                setIsRunningImport(true);
                                alert("Enviando documento '" + docObj.type + "' formatado para o repositório Supabase do beneficiário...");
                                setTimeout(() => {
                                  setIsRunningImport(false);
                                  alert("Lote salvo com selo certificado!");
                                }, 1200);
                              }}
                              className="px-4 py-2 bg-zinc-900 hover:bg-zinc-800 rounded-lg text-white font-bold text-xs uppercase tracking-wider flex items-center justify-center gap-1.5 cursor-pointer transition-colors"
                            >
                              <Printer className="w-3.5 h-3.5 text-[#C09553]" />
                              Salvar Copiar PDF
                            </button>
                          </div>

                          {/* Raw HTML container frame strictly aligned */}
                          <div className="bg-[#FAF8F5]/30 border border-[#FAF8F5] p-5 rounded-xl text-zinc-700 overflow-y-auto leading-relaxed max-h-[480px]">
                            {docObj.content.startsWith('<') ? (
                              <div dangerouslySetInnerHTML={{ __html: docObj.content }} className="rich-preview-content space-y-2 text-[10.5px]" />
                            ) : (
                              <p className="whitespace-pre-line text-xs font-serif leading-loose">{docObj.content}</p>
                            )}
                          </div>

                          <div className="pt-4 border-t border-zinc-100 flex justify-end gap-3 print:hidden">
                            <button
                              type="button"
                              onClick={() => {
                                const text = `Olá, *${docObj.patient}*! Dr. Agnaldo Ferreira gerou o documento digital correspondente a ${docObj.type}. Segue a cópia assinada digitalmente de forma oficial para seus registros. Qualquer dúvida, conte conosco!`;
                                window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, '_blank');
                              }}
                              className="px-4 py-2 border border-[#D5CBB3] rounded-lg bg-emerald-50 hover:bg-emerald-100 font-bold text-emerald-800 text-xs flex items-center justify-center gap-1.5 cursor-pointer transition-colors"
                            >
                              <Send className="w-3.5 h-3.5 text-emerald-600" />
                              Compartilhar WhatsApp
                            </button>
                          </div>
                        </div>
                      </div>
                    );
                  })()}

                  {/* WORKSPACE PHOTO GALLERY */}
                  {getDetectedDataType() === 'galeria' && (() => {
                    const idxPatient = headers.findIndex(h => ['nome_paciente', 'paciente', 'cliente'].includes(h.toLowerCase().trim()));
                    const idxUrl = headers.findIndex(h => ['url_arquivo', 'arquivo_url', 'download_url'].includes(h.toLowerCase().trim()));
                    const idxGallery = headers.findIndex(h => ['nome_galeria', 'galeria'].includes(h.toLowerCase().trim()));
                    const idxDesc = headers.findIndex(h => ['descricao_arquivo', 'descricao', 'legenda'].includes(h.toLowerCase().trim()));

                    const galleryRecords = rawData.slice(1).map((row, idx) => {
                      return {
                        id: idx.toString(),
                        patient: idxPatient !== -1 ? String(row[idxPatient] || 'Geral') : 'Geral',
                        url: idxUrl !== -1 ? String(row[idxUrl] || '') : '',
                        galeria: idxGallery !== -1 ? String(row[idxGallery] || 'Geral') : 'Geral',
                        label: idxDesc !== -1 ? String(row[idxDesc] || 'Foto Clínica') : 'Foto Clínica'
                      };
                    }).filter(item => item.url && item.url.startsWith('http'));

                    const selectedPatient = selectedPatientFilter || 'Todos';

                    const uniquePatientsList = Array.from(new Set(
                      galleryRecords.map(g => g.patient)
                    )).sort();

                    const filteredPhotos = galleryRecords.filter(p => {
                      if (selectedPatient === 'Todos') return true;
                      return p.patient === selectedPatient;
                    });

                    return (
                      <PatientGallery 
                        photos={filteredPhotos}
                        uniquePatients={uniquePatientsList}
                        selectedPatient={selectedPatient}
                        setSelectedPatient={setSelectedPatientFilter}
                        onSyncDrive={() => {
                          setIsRunningImport(true);
                          alert("Estruturando as galerias dinâmicas dos pacientes no Supabase. Suas fotos S3 originais serão copiadas como arquivos estáticos seguros em tempo de execução...");
                          setTimeout(() => {
                            setIsRunningImport(false);
                            alert("Galeria sincronizada com o Supabase!");
                          }, 1600);
                        }}
                        isRunningImport={isRunningImport}
                      />
                    );
                  })()}
                </div>
              )}

              {/* MODO BACKUP LEGACY DE MAPEAMENTO ORIGINAL */}
              {(getDetectedDataType() === 'paciente' || activeViewMode === 'legacy') && (
                <div id="legacy-patient-preview-zone" className="space-y-6">
                  {/* Tabela de Amostra/Preview */}
                  {importStatus === 'loaded' && mappings.name !== -1 && (
                    <div className="border border-zinc-200 rounded-xl overflow-hidden bg-white">
                      <div className="bg-zinc-50 border-b border-zinc-100 px-4 py-2 flex items-center justify-between">
                        <span className="font-bold text-zinc-800">Resumo da Amostra (Primeiros 4 registros)</span>
                        <span className="text-[10px] text-zinc-400">Verifique se os dados estão alinhados antes de prosseguir</span>
                      </div>
                      <div className="overflow-x-auto">
                        <table className="w-full text-left font-sans text-zinc-600">
                          <thead className="bg-[#FAF8F5] text-zinc-500 font-semibold border-b border-zinc-100">
                            <tr>
                              <th className="px-3 py-2 font-semibold">Nome do Paciente</th>
                              <th className="px-3 py-2 font-semibold">WhatsApp</th>
                              <th className="px-3 py-2 font-semibold">E-mail</th>
                              <th className="px-3 py-2 font-semibold">Consulta Agendada</th>
                            </tr>
                          </thead>
                          <tbody className="divide-y divide-zinc-100">
                            {getPreviewRows().map((row, index) => {
                              const name = mappings.name !== -1 ? String(row[mappings.name] || '') : '';
                              const phone = mappings.phone !== -1 ? String(row[mappings.phone] || '') : '';
                              const email = mappings.email !== -1 ? String(row[mappings.email] || '') : '';
                              const dateVal = mappings.date !== -1 ? row[mappings.date] : null;
                              const timeVal = mappings.time !== -1 ? row[mappings.time] : null;
                              const dateObj = parseExcelDateTime(dateVal, timeVal);
                              
                              return (
                                <tr key={index} className="hover:bg-zinc-50/50 text-[11px]">
                                  <td className="px-3 py-2 text-zinc-900 font-bold">{name || '---'}</td>
                                  <td className="px-3 py-2">{phone || '---'}</td>
                                  <td className="px-3 py-2">{email || '---'}</td>
                                  <td className="px-3 py-2 font-mono">
                                    {dateObj ? (
                                      <span className="bg-blue-50 text-blue-700 px-1.5 py-0.5 rounded text-[10px] font-bold">
                                        {dateObj.toLocaleDateString('pt-BR')} {dateObj.toLocaleTimeString('pt-BR', {hour: '2-digit', minute:'2-digit'})}
                                      </span>
                                    ) : 'Sem agendamento'}
                                  </td>
                                </tr>
                              );
                            })}
                          </tbody>
                        </table>
                      </div>
                    </div>
                  )}

                  {/* Console de Progresso Visual */}
                  {(importStatus === 'running' || importStatus === 'success' || importStatus === 'done') && (
                    <div className="space-y-4">
                      {/* Barra de Progresso Animada */}
                      <div className="border border-zinc-200 bg-white rounded-xl p-4 shadow-xs space-y-2">
                        <div className="flex justify-between items-center text-xs">
                          <span className="font-bold text-zinc-800 flex items-center gap-2">
                            {isRunningImport ? (
                              <>
                                <Loader2 className="w-3.5 h-3.5 animate-spin text-[#C09553]" />
                                Processando migração ativa...
                              </>
                            ) : (
                              <span className="text-[#8B0000] font-serif font-bold uppercase">Migração Concluída!</span>
                            )}
                          </span>
                          <span className="font-mono bg-zinc-100 text-zinc-700 px-2 py-0.5 rounded font-bold">
                            {importProgress.current} / {importProgress.total} ({Math.round(importProgress.total > 0 ? (importProgress.current / importProgress.total) * 100 : 0)}%)
                          </span>
                        </div>

                        <div className="w-full bg-zinc-200 h-2.5 rounded-full overflow-hidden">
                          <div 
                            className="bg-gradient-to-r from-[#8B0000] to-[#C09553] h-full transition-all duration-300"
                            style={{ width: `${importProgress.total > 0 ? (importProgress.current / importProgress.total) * 100 : 0}%` }}
                          />
                        </div>

                        <div className="flex flex-wrap gap-4 text-[11px] font-semibold pt-1">
                          <span className="text-zinc-600">👥 Total na Planilha: <strong className="text-zinc-900">{importProgress.total}</strong></span>
                          <span className="text-emerald-700">✓ Prontuários no Supabase: <strong className="text-emerald-800">{importProgress.successes}</strong></span>
                          <span className="text-amber-700">⤷ Pulados (Já existentes): <strong className="text-amber-800">{importProgress.skipped}</strong></span>
                          {importProgress.errors > 0 && (
                            <span className="text-red-700">✗ Falhas: <strong className="text-red-800">{importProgress.errors}</strong></span>
                          )}
                        </div>
                      </div>

                      {/* Console Log */}
                      <div className="bg-zinc-900 text-zinc-200 font-mono text-[10px] p-3 rounded-xl border border-zinc-800 max-h-48 overflow-y-auto space-y-1">
                        {importLogs.map((log, idx) => {
                          let color = 'text-zinc-300';
                          if (log.startsWith('[OK]')) color = 'text-emerald-300';
                          if (log.startsWith('[ERRO]')) color = 'text-rose-400';
                          if (log.startsWith('[PULADO]')) color = 'text-amber-300';
                          if (log.startsWith('[INFO]')) color = 'text-[#C09553] font-bold';
                          
                          return (
                            <div key={idx} className={`${color} leading-relaxed flex items-start gap-1`}>
                              <span className="select-none text-zinc-600 shrink-0">[{idx+1}]</span>
                              <span>{log}</span>
                            </div>
                          );
                        })}
                        <div ref={logsEndRef} />
                      </div>
                    </div>
                  )}

                  {/* Botões de Ação */}
                  <div className="flex justify-end gap-3 pt-2">
                    {importStatus === 'loaded' && (
                      <button
                        onClick={runDataImport}
                        disabled={mappings.name === -1}
                        className="flex items-center gap-2 px-6 py-3 bg-[#8B0000] text-[#FAF8F5] font-bold rounded-xl text-xs uppercase tracking-wider hover:bg-[#340A0F] active:scale-95 transition-all disabled:opacity-50 cursor-pointer"
                      >
                        Iniciar Importação Rápida ({rawData.length - 1} Pacientes)
                      </button>
                    )}

                    {(importStatus === 'success' || importStatus === 'done') && !isRunningImport && (
                      <button
                        onClick={() => {
                          setImportFile(null);
                          setWorkbook(null);
                          setRawData([]);
                          setHeaders([]);
                          setImportStatus('idle');
                        }}
                        className="flex items-center gap-1.5 px-6 py-3 bg-zinc-800 text-white font-bold rounded-xl text-xs uppercase tracking-wider hover:bg-zinc-700 transition cursor-pointer"
                      >
                        Importar Outro Arquivo
                      </button>
                    )}
                  </div>
                </div>
              )}
              </div>
          )}
        </div>
      </div>
    </div>
  );
}

import React, { useState, useRef, useEffect } from 'react';
import { Eye, Download, ChevronLeft, ChevronRight, X, Image as ImageIcon, RotateCw, Columns, SplitSquareHorizontal, Move } from 'lucide-react';
import html2canvas from 'html2canvas';
import { uploadPatientFileToSupabase } from '../lib/storage';
import PhotoLightboxWithEditor from './PhotoLightboxWithEditor';

export interface GalleryPhoto {
  id: string;
  patient: string;
  url: string;
  galeria: string;
  label: string;
}

interface PatientGalleryProps {
  photos: GalleryPhoto[];
  uniquePatients: string[];
  selectedPatient: string;
  setSelectedPatient: (patient: string) => void;
  onSyncDrive: () => void;
  isRunningImport: boolean;
}

export default function PatientGallery({
  photos,
  uniquePatients,
  selectedPatient,
  setSelectedPatient,
  onSyncDrive,
  isRunningImport
}: PatientGalleryProps) {
  const [lightboxIndex, setLightboxIndex] = useState<number | null>(null);
  
  // Before/After Mode States
  const [isCompareMode, setIsCompareMode] = useState(false);
  const [compareLeft, setCompareLeft] = useState<GalleryPhoto | null>(null);
  const [compareRight, setCompareRight] = useState<GalleryPhoto | null>(null);

  // Lightbox Editor States
  const [rotation, setRotation] = useState(0);
  const [zoomLevel, setZoomLevel] = useState(1);
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const imageRef = useRef<HTMLImageElement>(null);

  // Export Before/After ref
  const compareRef = useRef<HTMLDivElement>(null);

  const activePhoto = lightboxIndex !== null ? photos[lightboxIndex] : null;

  useEffect(() => {
    if (lightboxIndex !== null) {
      setRotation(0);
      setZoomLevel(1);
      setPan({ x: 0, y: 0 });
    }
  }, [lightboxIndex]);

  const handleNext = () => {
    if (lightboxIndex !== null && lightboxIndex < photos.length - 1) {
      setLightboxIndex(lightboxIndex + 1);
    }
  };

  const handlePrev = () => {
    if (lightboxIndex !== null && lightboxIndex > 0) {
      setLightboxIndex(lightboxIndex - 1);
    }
  };

  const handleDownload = async (imageUrl: string, filename: string) => {
    try {
      const response = await fetch(imageUrl);
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = filename || 'foto-paciente.jpg';
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (error) {
      console.error('Download falhou, tentando fallback', error);
      window.open(imageUrl, '_blank');
    }
  };

  const downloadCanvasImage = () => {
    if (!activePhoto) return;
    
    const canvas = document.createElement('canvas');
    const img = new Image();
    img.crossOrigin = 'anonymous';
    
    img.onload = () => {
      // Calculate canvas size based on rotation
      const isRotated = rotation % 180 !== 0;
      canvas.width = isRotated ? img.height : img.width;
      canvas.height = isRotated ? img.width : img.height;
      
      const ctx = canvas.getContext('2d');
      if (ctx) {
        // Draw the main image
        ctx.translate(canvas.width / 2, canvas.height / 2);
        ctx.rotate((rotation * Math.PI) / 180);
        ctx.drawImage(img, -img.width / 2, -img.height / 2);
        
        // Reset transform to draw watermark at absolute coordinates
        ctx.setTransform(1, 0, 0, 1, 0, 0);
        
        // Watermark settings
        ctx.fillStyle = 'rgba(255, 255, 255, 0.5)';
        ctx.font = `bold ${Math.max(20, canvas.width / 30)}px Arial`;
        ctx.textAlign = 'right';
        ctx.textBaseline = 'bottom';
        
        // Add watermark text (e.g., date and clinic name or patient name)
        const watermarkText = `Dr. Agnaldo Ferreira - ${activePhoto.patient}`;
        ctx.shadowColor = 'rgba(0,0,0,0.8)';
        ctx.shadowBlur = 4;
        ctx.fillText(watermarkText, canvas.width - 20, canvas.height - 20);
        
        const dataUrl = canvas.toDataURL('image/jpeg', 0.95);
        const a = document.createElement('a');
        a.href = dataUrl;
        // Salvar como nova (add timestamp to filename to ensure it's a new copy)
        const timestamp = new Date().getTime();
        a.download = `foto_${activePhoto.patient.replace(/\\s+/g, '_')}_editada_${timestamp}.jpg`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
      }
    };
    img.src = activePhoto.url;
  };

  const handleDownloadCompare = async () => {
    if (compareRef.current) {
      try {
        const canvas = await html2canvas(compareRef.current, {
          useCORS: true,
          scale: 2,
          backgroundColor: '#000000'
        });
        const dataUrl = canvas.toDataURL('image/jpeg', 0.9);
        const a = document.createElement('a');
        a.href = dataUrl;
        a.download = `antes_depois_${compareLeft?.patient || 'paciente'}.jpg`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
      } catch (err) {
        alert('Erro ao gerar imagem comparativa.');
      }
    }
  };

  const toggleComparePhoto = (photo: GalleryPhoto) => {
    if (compareLeft?.id === photo.id) {
      setCompareLeft(null);
      return;
    }
    if (compareRight?.id === photo.id) {
      setCompareRight(null);
      return;
    }
    
    if (!compareLeft) setCompareLeft(photo);
    else if (!compareRight) setCompareRight(photo);
    else {
      // If both filled, replace right
      setCompareRight(photo);
    }
  };

  return (
    <div className="space-y-6">
      {/* Selector top filter */}
      <div className="bg-[#8B0000]/5 border border-[#C09553]/30 rounded-xl p-4 flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div className="space-y-1">
          <label className="block text-zinc-600 font-bold text-[10px] uppercase font-mono tracking-wider">Filtrar Galeria de Fotos Clínicas</label>
          <select 
            value={selectedPatient}
            onChange={(e) => setSelectedPatient(e.target.value)}
            className="border border-[#D5CBB3] bg-white rounded-lg p-2 font-serif text-sm font-bold focus:outline-none focus:border-[#C09553] text-[#8B0000]"
          >
            <option value="Todos">Visualizar Todos os Registros ({photos.length} fotos)</option>
            {uniquePatients.map(name => (
              <option key={name} value={name}>{name}</option>
            ))}
          </select>
        </div>

        <div className="flex flex-wrap gap-3 w-full md:w-auto">
          <button
            onClick={() => setIsCompareMode(!isCompareMode)}
            className={`flex-1 md:flex-none px-4 py-2 border rounded-lg font-bold text-xs flex items-center justify-center gap-1.5 transition-colors ${isCompareMode ? 'bg-[#8B0000] border-[#8B0000] text-white' : 'bg-white border-[#D5CBB3] text-[#8B0000] hover:bg-[#8B0000]/5'}`}
          >
            <Columns className="w-3.5 h-3.5" />
            Modo Antes/Depois
          </button>
          <button
            onClick={onSyncDrive}
            disabled={isRunningImport}
            className="flex-1 md:flex-none px-4 py-2 border border-[#D5CBB3] rounded-lg bg-zinc-900 hover:bg-zinc-800 font-bold text-white text-xs flex items-center justify-center gap-1.5 disabled:opacity-50"
          >
            <ImageIcon className="w-3.5 h-3.5 text-[#C09553]" />
            Salvar no Supabase
          </button>
        </div>
      </div>

      {/* Compare Mode Header */}
      {isCompareMode && (
        <div className="bg-zinc-900 rounded-xl p-4 text-white">
          <div className="flex justify-between items-center mb-4">
            <h3 className="font-serif font-bold text-lg text-[#C09553] flex items-center gap-2">
              <SplitSquareHorizontal className="w-5 h-5" />
              Comparativo Antes e Depois
            </h3>
            <button 
              onClick={() => setIsCompareMode(false)}
              className="p-1 hover:bg-white/10 rounded-full"
            >
              <X className="w-5 h-5" />
            </button>
          </div>
          
          {(compareLeft || compareRight) ? (
            <div className="space-y-4">
              <div 
                ref={compareRef}
                className="flex flex-col md:flex-row gap-1 bg-black p-1 rounded-lg"
              >
                <div className="flex-1 bg-zinc-800 aspect-square md:aspect-[4/3] rounded overflow-hidden relative group">
                  {compareLeft ? (
                    <>
                      <img src={compareLeft.url} alt="Foto Antes" className="w-full h-full object-cover" crossOrigin="anonymous" />
                      <div className="absolute top-2 left-2 bg-black/60 px-2 py-1 rounded text-[10px] font-bold text-white">ANTES</div>
                      <button onClick={() => setCompareLeft(null)} className="absolute top-2 right-2 p-1.5 bg-black/50 hover:bg-red-500 rounded-full text-white opacity-0 group-hover:opacity-100 transition-opacity">
                        <X className="w-3 h-3" />
                      </button>
                    </>
                  ) : (
                    <div className="w-full h-full flex items-center justify-center text-zinc-500 text-sm">Selecione uma foto abaixo</div>
                  )}
                </div>
                <div className="flex-1 bg-zinc-800 aspect-square md:aspect-[4/3] rounded overflow-hidden relative group">
                  {compareRight ? (
                    <>
                      <img src={compareRight.url} alt="Foto Depois" className="w-full h-full object-cover" crossOrigin="anonymous" />
                      <div className="absolute top-2 right-2 bg-black/60 px-2 py-1 rounded text-[10px] font-bold text-white">DEPOIS</div>
                      <button onClick={() => setCompareRight(null)} className="absolute top-2 right-2 mt-8 p-1.5 bg-black/50 hover:bg-red-500 rounded-full text-white opacity-0 group-hover:opacity-100 transition-opacity">
                        <X className="w-3 h-3" />
                      </button>
                    </>
                  ) : (
                    <div className="w-full h-full flex items-center justify-center text-zinc-500 text-sm">Selecione uma foto abaixo</div>
                  )}
                </div>
              </div>
              <div className="flex justify-end">
                <button
                  onClick={handleDownloadCompare}
                  disabled={!compareLeft || !compareRight}
                  className="px-4 py-2 bg-[#C09553] hover:bg-[#a67c3b] text-white font-bold rounded-lg text-sm flex items-center gap-2 disabled:opacity-50"
                >
                  <Download className="w-4 h-4" />
                  Baixar Imagem Comparativa
                </button>
              </div>
            </div>
          ) : (
            <div className="text-center py-6 text-zinc-400 text-sm bg-white/5 rounded-lg border border-dashed border-white/20">
              Selecione 2 fotos na galeria abaixo para comparar
            </div>
          )}
        </div>
      )}

      {/* Photograph Grid */}
      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 md:gap-6">
        {photos.map((photo, idx) => {
          const isLeft = compareLeft?.id === photo.id;
          const isRight = compareRight?.id === photo.id;
          const isSelected = isLeft || isRight;

          return (
            <div 
              key={idx} 
              className={`bg-white border rounded-2xl overflow-hidden shadow-sm hover:shadow-md transition-all flex flex-col justify-between group ${isSelected ? 'border-[#C09553] ring-2 ring-[#C09553]/20' : 'border-zinc-200'}`}
            >
              <div 
                className="aspect-[4/3] bg-zinc-100 overflow-hidden relative border-b border-zinc-100 select-none cursor-pointer"
                onClick={() => isCompareMode ? toggleComparePhoto(photo) : setLightboxIndex(idx)}
              >
                <img 
                  src={photo.url} 
                  alt={photo.label}
                  referrerPolicy="no-referrer"
                  className="w-full h-full object-cover group-hover:scale-105 transition-all duration-300"
                  onError={(e) => {
                    e.currentTarget.src = "https://images.unsplash.com/photo-1629909613654-28e377c37b09?w=350&q=80";
                  }}
                />
                <span className="absolute top-2 left-2 bg-[#8B0000]/80 backdrop-blur-xs text-[#C09553] text-[8.5px] px-2 py-0.5 rounded font-bold uppercase font-mono tracking-widest">{photo.galeria}</span>
                
                {isCompareMode && isSelected && (
                  <div className="absolute inset-0 bg-[#C09553]/20 flex items-center justify-center">
                    <div className="bg-[#8B0000] text-white px-3 py-1 rounded-full text-xs font-bold shadow-lg">
                      {isLeft ? 'ANTES' : 'DEPOIS'}
                    </div>
                  </div>
                )}
              </div>
              <div className="p-3 space-y-1.5">
                <h5 className="text-[11.5px] font-bold text-zinc-900 leading-tight truncate">{photo.patient}</h5>
                <p className="text-[10px] text-zinc-500 font-medium italic truncate">{photo.label || 'Foto da consulta'}</p>
                
                {!isCompareMode && (
                  <div className="pt-2 border-t border-zinc-100 flex gap-2">
                    <button 
                      onClick={() => setLightboxIndex(idx)}
                      className="flex-1 py-1.5 bg-zinc-50 hover:bg-zinc-100 rounded-lg text-zinc-700 hover:text-zinc-900 border border-zinc-200 text-[10px] font-bold text-center inline-flex items-center justify-center gap-1"
                    >
                      <Eye className="w-3 h-3 text-[#C09553]" />
                      Zoom / Editar
                    </button>
                  </div>
                )}
              </div>
            </div>
          );
        })}
        {photos.length === 0 && (
          <div className="col-span-full py-12 text-center text-zinc-400">Nenhuma foto no backup corresponde aos critérios.</div>
        )}
      </div>

      {/* Lightbox Modal With Editor Abstraction */}
      {lightboxIndex !== null && photos.length > 0 && (
        <PhotoLightboxWithEditor
          photos={photos.map(p => ({
            url: p.url,
            title: p.patient,
            subtitle: p.label,
            id: p.id
          }))}
          initialIndex={lightboxIndex}
          onClose={() => setLightboxIndex(null)}
          onSaveEdit={async (editedBase64, index) => {
            try {
              const targetPhoto = photos[index];
              const base64Response = await fetch(editedBase64);
              const blob = await base64Response.blob();
              // Upload back to Supabase
              await uploadPatientFileToSupabase(
                targetPhoto.patient,
                blob,
                `edited_${Date.now()}.png`
              );
              alert('Imagem editada salva com sucesso na galeria do paciente!');
              onSyncDrive(); // Trigger refresh
            } catch (err: any) {
              console.error(err);
              alert('Erro ao salvar imagem editada: ' + err.message);
            }
          }}
        />
      )}
    </div>
  );
}

import React, { useEffect } from 'react';
import { TreatmentProposal, PatientData, CRMPatient } from '../types';
import { User, HeartPulse, MapPin, Building2, Save, MessageCircle, Cake, Sparkles, CalendarClock, AlertCircle, Phone, Loader2 } from 'lucide-react';
import { usePatientContext } from '../context/PatientContext';
import { fetchAddressByCep, formatCep } from '../lib/cep';

interface PatientRegistrationTabProps {
  proposal: TreatmentProposal;
  setProposal: React.Dispatch<React.SetStateAction<TreatmentProposal>>;
}

export default function PatientRegistrationTab({ proposal, setProposal }: PatientRegistrationTabProps) {
  const { selectedPatient, setSelectedPatient, saveContextToSupabase, isSavingToSupabase } = usePatientContext();
  
  // Use selectedPatient if available, otherwise fallback to proposal.patientData
  const pd: Partial<CRMPatient> = selectedPatient || proposal.patientData || {};

  const [whatsappMessage, setWhatsappMessage] = React.useState('');
  const [selectedTemplate, setSelectedTemplate] = React.useState('confirmacao');

  // Sync proposal.patientName if selectedPatient changes
  useEffect(() => {
    if (selectedPatient && selectedPatient.name !== proposal.patientName) {
      setProposal(prev => ({ ...prev, patientName: selectedPatient.name, patientData: selectedPatient }));
    }
  }, [selectedPatient, setProposal, proposal.patientName]);

  React.useEffect(() => {
    const name = proposal.patientName || 'Paciente';
    if (selectedTemplate === 'aniversario') {
      const saved = localStorage.getItem('whatsapp_template_aniversario');
      setWhatsappMessage(saved ? saved.replace('[NOME]', name) : `Olá, ${name}! A equipe do Dr. Agnaldo Ferreira deseja a você um feliz aniversário! Que seu dia seja iluminado e repleto de sorrisos! 🎂✨`);
    } else if (selectedTemplate === 'feriado') {
      const saved = localStorage.getItem('whatsapp_template_feriado');
      setWhatsappMessage(saved ? saved.replace('[NOME]', name) : `Olá, ${name}! Desejamos a você e sua família um Feliz Natal e um Próspero Ano Novo! Que o novo ano traga muitas alegrias, saúde e motivos para sorrir! 🎄🎉 - Dr. Agnaldo Ferreira`);
    } else if (selectedTemplate === 'profilaxia') {
      const saved = localStorage.getItem('whatsapp_template_profilaxia');
      setWhatsappMessage(saved ? saved.replace('[NOME]', name) : `Olá, ${name}! Faz 6 meses desde sua última profilaxia (limpeza) com o Dr. Agnaldo Ferreira. É hora de agendar sua revisão periódica para manter seu sorriso saudável! Vamos agendar? 🦷😊`);
    } else if (selectedTemplate === 'confirmacao') {
      const saved = localStorage.getItem('whatsapp_template_confirmacao');
      setWhatsappMessage(saved ? saved.replace('[NOME]', name) : `Olá, ${name}! Gostaríamos de confirmar sua consulta com o Dr. Agnaldo Ferreira no dia [DATA] às [HORÁRIO]. Por favor, responda esta mensagem para confirmar. Qualquer dúvida, estamos à disposição!`);
    }
  }, [selectedTemplate, proposal.patientName]);

  const isBirthdayToday = () => {
    const birthDate = pd.birthDate;
    if (!birthDate) return false;
    const parts = birthDate.split('-');
    if (parts.length !== 3) return false;
    const [year, month, day] = parts;
    const today = new Date();
    return today.getDate() === parseInt(day) && (today.getMonth() + 1) === parseInt(month);
  };

  const isProphylaxisDue = () => {
    const createdAt = pd.createdAt;
    if (!createdAt) return false;
    const createdDate = new Date(createdAt);
    const sixMonthsAgo = new Date();
    sixMonthsAgo.setMonth(sixMonthsAgo.getMonth() - 6);
    return createdDate < sixMonthsAgo;
  };

  const handleBatchUpdate = (updates: Partial<CRMPatient>) => {
    if (selectedPatient) {
      const updatedPatient = { ...selectedPatient, ...updates };
      setSelectedPatient(updatedPatient);
      setProposal(prev => ({
        ...prev,
        patientData: updatedPatient
      }));
    } else {
      setProposal(prev => ({
        ...prev,
        patientData: {
          ...(prev.patientData || {}),
          ...updates
        }
      }));
    }
  };

  const handleUpdate = (field: keyof CRMPatient, value: string) => {
    handleBatchUpdate({ [field]: value });
  };

  const [isLoadingCep, setIsLoadingCep] = React.useState(false);

  const handleCepLookup = async (cepInput: string) => {
    const formatted = formatCep(cepInput);
    handleUpdate('cep', formatted);

    const clean = cepInput.replace(/\D/g, '');
    if (clean.length === 8) {
      setIsLoadingCep(true);
      try {
        const addr = await fetchAddressByCep(clean);
        if (addr) {
          handleBatchUpdate({
            cep: addr.cep || formatted,
            street: addr.street || pd.street || '',
            neighborhood: addr.neighborhood || pd.neighborhood || '',
            city: addr.city || pd.city || '',
            state: addr.state || pd.state || '',
            complement: addr.complement || pd.complement || ''
          });
        }
      } catch (err) {
        console.warn('Erro ao buscar CEP:', err);
      } finally {
        setIsLoadingCep(false);
      }
    }
  };

  const handleNameChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newName = e.target.value.toUpperCase();
    if (selectedPatient) {
      const updatedPatient = { ...selectedPatient, name: newName };
      setSelectedPatient(updatedPatient);
      setProposal(prev => ({ ...prev, patientName: newName, patientData: updatedPatient }));
    } else {
      setProposal(prev => ({ ...prev, patientName: newName }));
    }
  };

  return (
    <div className="bg-white rounded-2xl border border-zinc-200 shadow-sm overflow-hidden font-sans">
      
      {/* 1. Dados Cadastrais */}
      <div className="border-b border-zinc-200">
        <div className="bg-[#8B0000] text-white px-4 py-2.5 flex items-center justify-between border-b border-[#C09553]/30">
          <div className="flex items-center gap-2">
            <User className="w-4 h-4 text-[#C09553]" />
            <h3 className="font-serif font-bold text-sm tracking-wide uppercase">Dados cadastrais</h3>
          </div>
          {selectedPatient && (
            <button
              type="button"
              onClick={saveContextToSupabase}
              disabled={isSavingToSupabase}
              className="flex items-center gap-1.5 px-3 py-1 bg-[#C09553] hover:bg-[#A88248] text-white rounded-lg text-[11px] font-bold shadow-sm transition-colors disabled:opacity-50"
            >
              <Save className="w-3.5 h-3.5" />
              {isSavingToSupabase ? 'Salvando...' : 'Salvar no Supabase'}
            </button>
          )}
        </div>
        <div className="p-4 space-y-4 text-xs bg-[#FAF8F5]/30">
          
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <div className="md:col-span-2">
              <label className="block text-zinc-500 font-semibold mb-1">Nome do paciente *</label>
              <input type="text" value={proposal.patientName} onChange={handleNameChange} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none" />
            </div>
            <div>
              <label className="block text-zinc-500 font-semibold mb-1">Nascimento</label>
              <input type="date" value={pd.birthDate || ''} onChange={e => handleUpdate('birthDate', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none" />
            </div>
            <div className="grid grid-cols-2 gap-2">
              <div>
                <label className="block text-zinc-500 font-semibold mb-1">Sexo</label>
                <select value={pd.gender || ''} onChange={e => handleUpdate('gender', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none">
                  <option value=""></option>
                  <option value="Feminino">Feminino</option>
                  <option value="Masculino">Masculino</option>
                  <option value="Outro">Outro</option>
                </select>
              </div>
              <div>
                <label className="block text-zinc-500 font-semibold mb-1">Situação</label>
                <select value={pd.status || 'ATIVO'} onChange={e => handleUpdate('status', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none">
                  <option value="ATIVO">ATIVO</option>
                  <option value="INATIVO">INATIVO</option>
                </select>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <div>
              <label className="block text-zinc-500 font-semibold mb-1">Estado civil</label>
              <select value={pd.maritalStatus || ''} onChange={e => handleUpdate('maritalStatus', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none">
                <option value=""></option>
                <option value="Solteiro(a)">Solteiro(a)</option>
                <option value="Casado(a)">Casado(a)</option>
                <option value="Divorciado(a)">Divorciado(a)</option>
                <option value="Viúvo(a)">Viúvo(a)</option>
              </select>
            </div>
            <div>
              <label className="block text-zinc-500 font-semibold mb-1">CPF</label>
              <input type="text" placeholder="000.000.000-00" value={pd.cpf || ''} onChange={e => handleUpdate('cpf', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none" />
            </div>
            <div>
              <label className="block text-zinc-500 font-semibold mb-1">RG</label>
              <input type="text" value={pd.rg || ''} onChange={e => handleUpdate('rg', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none" />
            </div>
            <div>
              <label className="block text-zinc-500 font-semibold mb-1">Órgão emissor/UF</label>
              <input type="text" value={pd.rgIssuer || ''} onChange={e => handleUpdate('rgIssuer', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none" />
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <div>
              <label className="block text-zinc-500 font-semibold mb-1">Prontuário</label>
              <input type="text" value={pd.medicalRecord || ''} onChange={e => handleUpdate('medicalRecord', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none" />
            </div>
            <div>
              <label className="block text-zinc-500 font-semibold mb-1">Como conheceu a clínica?</label>
              <select value={pd.howKnewClinic || ''} onChange={e => handleUpdate('howKnewClinic', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none">
                <option value="">Selecione</option>
                <option value="Indicação">Indicação</option>
                <option value="Redes Sociais">Redes Sociais</option>
                <option value="Google">Google</option>
                <option value="Outros">Outros</option>
              </select>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <div>
              <label className="block text-zinc-500 font-semibold mb-1">Telefone</label>
              <input type="text" value={pd.phone || ''} onChange={e => handleUpdate('phone', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none" />
            </div>
            <div>
              <label className="block text-zinc-500 font-semibold mb-1">Celular</label>
              <input type="text" placeholder="(00) 00000-0000" value={pd.mobile || ''} onChange={e => handleUpdate('mobile', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none" />
            </div>
            <div className="md:col-span-2">
              <label className="block text-zinc-500 font-semibold mb-1">E-mail</label>
              <input type="email" value={pd.email || ''} onChange={e => handleUpdate('email', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none" />
            </div>
          </div>

          <div>
            <label className="block text-zinc-500 font-semibold mb-1">Observações</label>
            <textarea rows={3} value={pd.observations || ''} onChange={e => handleUpdate('observations', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none resize-y"></textarea>
          </div>

        </div>
      </div>

      {/* 2. Dados do Responsável */}
      <div className="border-b border-zinc-200">
        <div className="bg-[#8B0000] text-white px-4 py-2.5 flex items-center gap-2 border-b border-[#C09553]/30">
          <HeartPulse className="w-4 h-4 text-[#C09553]" />
          <h3 className="font-serif font-bold text-sm tracking-wide uppercase">Dados do responsável</h3>
        </div>
        <div className="p-4 space-y-4 text-xs bg-[#FAF8F5]/30">
          
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <div className="md:col-span-1">
              <label className="block text-zinc-500 font-semibold mb-1">Nome</label>
              <input type="text" value={pd.respName || ''} onChange={e => handleUpdate('respName', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none" />
            </div>
            <div>
              <label className="block text-zinc-500 font-semibold mb-1">Nascimento</label>
              <input type="date" value={pd.respBirthDate || ''} onChange={e => handleUpdate('respBirthDate', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none" />
            </div>
            <div>
              <label className="block text-zinc-500 font-semibold mb-1">Telefone</label>
              <input type="text" value={pd.respPhone || ''} onChange={e => handleUpdate('respPhone', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none" />
            </div>
            <div>
              <label className="block text-zinc-500 font-semibold mb-1">Celular</label>
              <input type="text" value={pd.respMobile || ''} onChange={e => handleUpdate('respMobile', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none" />
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-5 gap-4">
            <div>
              <label className="block text-zinc-500 font-semibold mb-1">Estado civil</label>
              <select value={pd.respMaritalStatus || ''} onChange={e => handleUpdate('respMaritalStatus', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none">
                <option value=""></option>
                <option value="Solteiro(a)">Solteiro(a)</option>
                <option value="Casado(a)">Casado(a)</option>
                <option value="Divorciado(a)">Divorciado(a)</option>
                <option value="Viúvo(a)">Viúvo(a)</option>
              </select>
            </div>
            <div>
              <label className="block text-zinc-500 font-semibold mb-1">CPF</label>
              <input type="text" value={pd.respCpf || ''} onChange={e => handleUpdate('respCpf', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none" />
            </div>
            <div>
              <label className="block text-zinc-500 font-semibold mb-1">RG</label>
              <input type="text" value={pd.respRg || ''} onChange={e => handleUpdate('respRg', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none" />
            </div>
            <div>
              <label className="block text-zinc-500 font-semibold mb-1">Órgão emissor/UF</label>
              <input type="text" value={pd.respRgIssuer || ''} onChange={e => handleUpdate('respRgIssuer', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none" />
            </div>
            <div>
              <label className="block text-zinc-500 font-semibold mb-1">Profissão</label>
              <input type="text" value={pd.respProfession || ''} onChange={e => handleUpdate('respProfession', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none" />
            </div>
          </div>

        </div>
      </div>

      {/* 3. Endereço */}
      <div className="border-b border-zinc-200">
        <div className="bg-[#8B0000] text-white px-4 py-2.5 flex items-center gap-2 border-b border-[#C09553]/30">
          <MapPin className="w-4 h-4 text-[#C09553]" />
          <h3 className="font-serif font-bold text-sm tracking-wide uppercase">Endereço</h3>
        </div>
        <div className="p-4 space-y-4 text-xs bg-[#FAF8F5]/30">
          
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <div>
              <label className="block text-zinc-500 font-semibold mb-1 flex items-center justify-between">
                <span>CEP</span>
                {isLoadingCep && (
                  <span className="text-[10px] text-[#8B0000] font-normal flex items-center gap-1 animate-pulse">
                    <Loader2 className="w-3 h-3 animate-spin" /> Buscando...
                  </span>
                )}
              </label>
              <input 
                type="text" 
                placeholder="00000-000" 
                maxLength={9}
                value={pd.cep || ''} 
                onChange={e => handleCepLookup(e.target.value)} 
                onBlur={e => handleCepLookup(e.target.value)}
                className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none" 
              />
            </div>
            <div className="md:col-span-3">
              <label className="block text-zinc-500 font-semibold mb-1">Logradouro</label>
              <input type="text" value={pd.street || ''} onChange={e => handleUpdate('street', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none" />
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <div>
              <label className="block text-zinc-500 font-semibold mb-1">Número</label>
              <input type="text" value={pd.number || ''} onChange={e => handleUpdate('number', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none" />
            </div>
            <div className="md:col-span-3">
              <label className="block text-zinc-500 font-semibold mb-1">Complemento</label>
              <input type="text" value={pd.complement || ''} onChange={e => handleUpdate('complement', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none" />
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <div className="md:col-span-2">
              <label className="block text-zinc-500 font-semibold mb-1">Bairro</label>
              <input type="text" value={pd.neighborhood || ''} onChange={e => handleUpdate('neighborhood', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none" />
            </div>
            <div>
              <label className="block text-zinc-500 font-semibold mb-1">Cidade</label>
              <input type="text" value={pd.city || ''} onChange={e => handleUpdate('city', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none" />
            </div>
            <div>
              <label className="block text-zinc-500 font-semibold mb-1">Estado</label>
              <input type="text" value={pd.state || ''} onChange={e => handleUpdate('state', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none" />
            </div>
          </div>

        </div>
      </div>

      {/* 4. Convênio */}
      <div className="border-b border-zinc-200">
        <div className="bg-[#8B0000] text-white px-4 py-2.5 flex items-center gap-2 border-b border-[#C09553]/30">
          <Building2 className="w-4 h-4 text-[#C09553]" />
          <h3 className="font-serif font-bold text-sm tracking-wide uppercase">Convênio</h3>
        </div>
        <div className="p-4 space-y-4 text-xs bg-[#FAF8F5]/30">
          
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="block text-zinc-500 font-semibold mb-1">Convênio *</label>
              <select value={pd.healthInsurance || 'PARTICULAR'} onChange={e => handleUpdate('healthInsurance', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none">
                <option value="PARTICULAR">PARTICULAR</option>
                <option value="BRADESCO">BRADESCO SAÚDE</option>
                <option value="SULAMERICA">SULAMÉRICA</option>
                <option value="AMIL">AMIL</option>
                <option value="UNIMED">UNIMED</option>
                <option value="OUTRO">OUTRO</option>
              </select>
            </div>
            <div>
              <label className="block text-zinc-500 font-semibold mb-1">Carteira</label>
              <input type="text" value={pd.healthInsuranceCard || ''} onChange={e => handleUpdate('healthInsuranceCard', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none" />
            </div>
            <div>
              <label className="block text-zinc-500 font-semibold mb-1">Validade</label>
              <input type="text" placeholder="MM/AAAA" value={pd.healthInsuranceValidity || ''} onChange={e => handleUpdate('healthInsuranceValidity', e.target.value)} className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none" />
            </div>
          </div>

        </div>
      </div>

      {/* 5. WhatsApp & Lembretes */}
      <div className="border-b border-zinc-200">
        <div className="bg-[#8B0000] text-white px-4 py-2.5 flex items-center gap-2 border-b border-[#C09553]/30">
          <MessageCircle className="w-4 h-4 text-[#C09553]" />
          <h3 className="font-serif font-bold text-sm tracking-wide uppercase">WhatsApp & Lembretes</h3>
        </div>
        <div className="p-4 space-y-4 text-xs bg-[#FAF8F5]/30">
          
          {/* Smart Alerts */}
          {(isBirthdayToday() || isProphylaxisDue()) && (
            <div className="space-y-2">
              {isBirthdayToday() && (
                <div className="bg-amber-50 border border-amber-200 text-amber-900 rounded-xl p-3.5 flex items-start gap-2.5 shadow-sm">
                  <Cake className="w-4.5 h-4.5 text-amber-600 shrink-0 mt-0.5" />
                  <div>
                    <span className="font-bold">Aniversariante do Dia!</span>
                    <p className="text-[11px] text-amber-800 mt-0.5">Hoje é aniversário deste paciente. Aproveite para enviar os parabéns e estreitar o relacionamento!</p>
                  </div>
                </div>
              )}
              {isProphylaxisDue() && (
                <div className="bg-red-50 border border-red-200 text-red-900 rounded-xl p-3.5 flex items-start gap-2.5 shadow-sm">
                  <CalendarClock className="w-4.5 h-4.5 text-[#8B0000] shrink-0 mt-0.5" />
                  <div>
                    <span className="font-bold">Lembrete de Profilaxia Semestral</span>
                    <p className="text-[11px] text-red-800 mt-0.5">Já se passaram 6 meses ou mais desde que este paciente foi registrado ou realizou seu tratamento. Convide-o para uma nova limpeza!</p>
                  </div>
                </div>
              )}
            </div>
          )}

          {!pd.mobile ? (
            <div className="bg-zinc-50 border border-zinc-200 text-zinc-500 rounded-xl p-4 text-center">
              <AlertCircle className="w-6 h-6 text-zinc-400 mx-auto mb-2" />
              <p className="font-semibold text-xs">Preencha o campo Celular (nos Dados Cadastrais) para habilitar as mensagens de WhatsApp e lembretes para este paciente.</p>
            </div>
          ) : (
            <div className="space-y-4">
              <div className="space-y-2">
                <label className="block text-zinc-500 font-semibold">Selecione o Modelo de Mensagem</label>
                <div className="flex flex-wrap gap-2">
                  <button
                    type="button"
                    onClick={() => setSelectedTemplate('confirmacao')}
                    className={`px-3 py-1.5 rounded-xl border text-[11px] font-bold transition-all cursor-pointer ${
                      selectedTemplate === 'confirmacao'
                        ? 'bg-[#8B0000] text-white border-[#8B0000]'
                        : 'bg-white text-zinc-600 border-zinc-200 hover:bg-zinc-50'
                    }`}
                  >
                    Confirmar Consulta
                  </button>
                  <button
                    type="button"
                    onClick={() => setSelectedTemplate('aniversario')}
                    className={`px-3 py-1.5 rounded-xl border text-[11px] font-bold transition-all cursor-pointer ${
                      selectedTemplate === 'aniversario'
                        ? 'bg-amber-600 text-white border-amber-600'
                        : 'bg-white text-zinc-600 border-zinc-200 hover:bg-zinc-50'
                    }`}
                  >
                    🎂 Parabéns/Aniversário
                  </button>
                  <button
                    type="button"
                    onClick={() => setSelectedTemplate('profilaxia')}
                    className={`px-3 py-1.5 rounded-xl border text-[11px] font-bold transition-all cursor-pointer ${
                      selectedTemplate === 'profilaxia'
                        ? 'bg-emerald-600 text-white border-emerald-600'
                        : 'bg-white text-zinc-600 border-zinc-200 hover:bg-zinc-50'
                    }`}
                  >
                    🦷 Lembrete de Profilaxia (6 meses)
                  </button>
                  <button
                    type="button"
                    onClick={() => setSelectedTemplate('feriado')}
                    className={`px-3 py-1.5 rounded-xl border text-[11px] font-bold transition-all cursor-pointer ${
                      selectedTemplate === 'feriado'
                        ? 'bg-blue-600 text-white border-blue-600'
                        : 'bg-white text-zinc-600 border-zinc-200 hover:bg-zinc-50'
                    }`}
                  >
                    🎄 Fim de Ano (Natal/Ano Novo)
                  </button>
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="block text-zinc-500 font-semibold">Editar Mensagem antes de Enviar</label>
                <textarea
                  rows={4}
                  value={whatsappMessage}
                  onChange={(e) => setWhatsappMessage(e.target.value)}
                  className="w-full border border-zinc-300 rounded p-2 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none font-sans text-xs resize-y"
                  placeholder="Mensagem..."
                />
              </div>

              <div className="flex justify-end">
                <button
                  type="button"
                  onClick={() => {
                    const digitsOnly = pd.mobile!.replace(/\D/g, '');
                    const cleanNum = (digitsOnly.length === 10 || digitsOnly.length === 11) ? '55' + digitsOnly : digitsOnly;
                    const encodedMsg = encodeURIComponent(whatsappMessage);
                    const url = cleanNum ? `https://wa.me/${cleanNum}?text=${encodedMsg}` : `https://wa.me/?text=${encodedMsg}`;
                    window.open(url, '_blank');
                  }}
                  className="px-5 py-2.5 bg-green-600 hover:bg-green-700 text-white font-bold rounded-xl transition-colors flex items-center justify-center gap-2 shadow-sm cursor-pointer"
                >
                  <MessageCircle className="w-4.5 h-4.5 text-white" />
                  <span>Enviar via WhatsApp ({pd.mobile})</span>
                </button>
              </div>
            </div>
          )}

        </div>
      </div>

    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import { Coins, TrendingUp, CheckCircle2 } from 'lucide-react';
import { PhotoSection, Procedure, TreatmentProposal } from '../types';
import { TON_RATES, DEBIT_RATES } from './NegotiationTab';

const formatCurrency = (val: number) => {
  return new Intl.NumberFormat('pt-BR', {
    style: 'currency',
    currency: 'BRL'
  }).format(val);
};

// Custom hook to reactively track localStorage
function useReactiveLocalStorage<T>(key: string, defaultValue: T): T {
  const getResolvedKey = (k: string) => {
    if (k === 'agnaldo_dent_sections' || k === 'agnaldo_dent_proposal' || k === 'ag_neg_custom_net') {
      const urlParams = new URLSearchParams(window.location.search);
      const patientId = urlParams.get('patientId');
      if (patientId) {
        return `${k}_${patientId}`;
      }
      
      const keys = Object.keys(localStorage);
      const matched = keys.find(item => item.startsWith(`${k}_`));
      if (matched) return matched;
    }
    return k;
  };

  const [value, setValue] = useState<T>(() => {
    const activeKey = getResolvedKey(key);
    const cached = localStorage.getItem(activeKey) || localStorage.getItem(key);
    if (!cached) return defaultValue;
    try { return JSON.parse(cached); } catch { return cached as any; }
  });

  useEffect(() => {
    const channelName = `dental_crm_sync_${key}`;
    const globalChannelName = `dental_crm_sync_global`;
    const channel = new BroadcastChannel(channelName);
    const globalChannel = new BroadcastChannel(globalChannelName);
    
    // As chaves no PatientContext enviam com prefixo, mas podemos escutar pelas globais ou por ID
    const urlParams = new URLSearchParams(window.location.search);
    const patientId = urlParams.get('patientId');
    const specificChannel = patientId ? new BroadcastChannel(`dental_crm_sync_${patientId}`) : null;

    const handleSync = (e: MessageEvent) => {
      if (e.data.type === 'SECTIONS_UPDATE' && key === 'agnaldo_dent_sections') {
        setValue(e.data.payload);
      }
      if (e.data.type === 'PROPOSAL_UPDATE' && key === 'agnaldo_dent_proposal') {
        setValue(e.data.payload);
      }
    };

    channel.onmessage = handleSync;
    globalChannel.onmessage = handleSync;
    if (specificChannel) specificChannel.onmessage = handleSync;

    // Pedir sincronização imediata
    if (specificChannel) specificChannel.postMessage({ type: 'REQUEST_SYNC' });
    else globalChannel.postMessage({ type: 'REQUEST_SYNC' });

    let activeKey = getResolvedKey(key);
    let lastRawValue = localStorage.getItem(activeKey) || localStorage.getItem(key);

    const handleStorage = (e: StorageEvent) => {
      const currentKey = getResolvedKey(key);
      if ((e.key === currentKey || e.key === key) && e.newValue) {
        lastRawValue = e.newValue;
        try { setValue(JSON.parse(e.newValue)); } catch { setValue(e.newValue as any); }
      } else if (e.key === null) {
        const cached = localStorage.getItem(currentKey) || localStorage.getItem(key);
        lastRawValue = cached;
        if (cached) {
          try { setValue(JSON.parse(cached)); } catch { setValue(cached as any); }
        } else {
          setValue(defaultValue);
        }
      }
    };

    window.addEventListener('storage', handleStorage);

    const pollInterval = setInterval(() => {
      const currentKey = getResolvedKey(key);
      const currentRawValue = localStorage.getItem(currentKey) || localStorage.getItem(key);
      if (currentRawValue !== lastRawValue) {
        lastRawValue = currentRawValue;
        if (currentRawValue) {
          try {
            setValue(JSON.parse(currentRawValue));
          } catch {
            setValue(currentRawValue as any);
          }
        } else {
          setValue(defaultValue);
        }
      }
    }, 200);

    return () => {
      window.removeEventListener('storage', handleStorage);
      clearInterval(pollInterval);
      channel.close();
      globalChannel.close();
      if (specificChannel) specificChannel.close();
    };
  }, [key, defaultValue]);

  return value;
}

export default function PatientScreen({ hideSimulation = false, hideProcedures = false }: { hideSimulation?: boolean, hideProcedures?: boolean }) {
  const sections = useReactiveLocalStorage<PhotoSection[]>('agnaldo_dent_sections', []);
  const procedures = useReactiveLocalStorage<Procedure[]>('agnaldo_dent_procedures', []);
  const proposal = useReactiveLocalStorage<TreatmentProposal>('agnaldo_dent_proposal', {} as any);

  const salesVolume = useReactiveLocalStorage<'under_3' | 'between_3_6'>('ag_neg_sales_volume', 'under_3');
  const cardBrand = useReactiveLocalStorage<'visa_master' | 'elo_amex'>('ag_neg_card_brand', 'visa_master');
  const boxEntradas = useReactiveLocalStorage<number[]>('ag_neg_box_entradas', [0, 0, 0, 0]);
  const boxMethods = useReactiveLocalStorage<('pix' | 'pix_5' | 'debito' | 'credito_vista' | 'credito_parcelado')[]>('ag_neg_box_methods', ['pix', 'credito_parcelado', 'credito_parcelado', 'credito_parcelado']);
  const boxInstallments = useReactiveLocalStorage<number[]>('ag_neg_box_installments', [1, 12, 12, 12]);
  const selectedPlanIndices = useReactiveLocalStorage<number[]>('ag_neg_selected_plans', [0]);
  const showInPatientScreen = useReactiveLocalStorage<boolean[]>('ag_neg_show_patient_sims', [true, false, false, false]);
  const customNetDesiredRaw = useReactiveLocalStorage<string | null>('ag_neg_custom_net', null);
  const customNetDesired = customNetDesiredRaw !== null ? parseFloat(customNetDesiredRaw as string) : null;

  // Calculate gross total
  const calculatedGrossTotal = useMemo(() => {
    return sections.reduce((secSum, sec) => {
      return secSum + sec.markers.reduce((markSum, marker) => {
        if (marker.procedureInstances && marker.procedureInstances.length > 0) {
          return markSum + marker.procedureInstances.reduce((procSum, inst) => {
            return procSum + (inst.includeFinancial !== false ? inst.price : 0);
          }, 0);
        }
        return markSum + marker.procedures.reduce((procSum, pid) => {
          const proc = procedures.find((p) => p.id === pid);
          return procSum + (proc ? proc.price : 0);
        }, 0);
      }, 0);
    }, 0);
  }, [sections, procedures]);

  const desiredNet = customNetDesired !== null && !isNaN(customNetDesired) ? customNetDesired : calculatedGrossTotal;

  // Max allowed installments by rule
  const maxInstallmentsRule = useMemo(() => {
    let baseMax = 6;
    if (desiredNet <= 500) baseMax = 1;
    else if (desiredNet <= 1000) baseMax = 3;
    else if (desiredNet <= 2000) baseMax = 4;
    
    if (!TON_RATES[salesVolume]) return baseMax;
    const activeRates = TON_RATES[salesVolume][cardBrand];
    let maxInstallmentsByRate = 12;
    for (let i = 0; i < 12; i++) {
      if (activeRates[i] > 14) {
        maxInstallmentsByRate = i > 0 ? i : 1;
        break;
      }
    }

    return Math.min(baseMax, maxInstallmentsByRate);
  }, [desiredNet, salesVolume, cardBrand]);

  // Compile calculations for each of the 4 columns
  const simulations = useMemo(() => {
    return Array.from({ length: 4 }).map((_, i) => {
      const e = boxEntradas[i] || 0;
      const bMethod = boxMethods[i] || 'pix';
      const bInst = boxInstallments[i] || 1;

      const r = Math.max(0, desiredNet - e);
      let optionFeeDecimal = 0;
      let instCount = 0;

      if (bMethod === 'pix' || bMethod === 'pix_5') {
        optionFeeDecimal = 0;
        instCount = 1;
      } else if (bMethod === 'debito') {
        optionFeeDecimal = (DEBIT_RATES[salesVolume]?.[cardBrand] || 0) / 100;
        instCount = 1;
      } else if (bMethod === 'credito_vista') {
        optionFeeDecimal = (TON_RATES[salesVolume]?.[cardBrand]?.[0] || 0) / 100;
        instCount = 1;
      } else if (bMethod === 'credito_parcelado') {
        const machineFeePercent = TON_RATES[salesVolume][cardBrand][Math.min(11, Math.max(0, bInst - 1))];
        optionFeeDecimal = machineFeePercent / 100;
        instCount = bInst;
      }

      const isExceeded = instCount > maxInstallmentsRule && bMethod === 'credito_parcelado';
      const effectiveFeeDecimal = isExceeded ? optionFeeDecimal : 0;
      
      const t0Ref = desiredNet / (1 - effectiveFeeDecimal);

      const isPixDiscount = bMethod === 'pix_5';
      const pixDiscountVal = isPixDiscount ? (e === 0 ? desiredNet * 0.05 : r * 0.05) : 0;

      const ch = isPixDiscount ? (r - pixDiscountVal) : (r / (1 - effectiveFeeDecimal));
      const instVal = instCount > 0 ? ch / instCount : 0;
      const t = e + ch;

      let label = bMethod.toUpperCase();
      if (bMethod === 'pix_5') label = 'PIX (-5%)';
      if (bMethod === 'credito_parcelado') label = `CRÉDITO ${instCount}X`;
      if (bMethod === 'credito_vista') label = `CRÉDITO 1X`;

      let name = `Opção ${i + 1}`;
      if (i === 1) name = 'Simulação 1';
      if (i === 2) name = 'Simulação 2';
      if (i === 3) name = 'Oferta Paciente';
      if (i === 0 && bMethod === 'pix') name = 'À Vista no Pix';
      if (i === 0 && bMethod === 'pix_5') name = 'À Vista no Pix (-5%)';
      if (i === 0 && bMethod === 'credito_parcelado') name = '100% no Cartão';

      return {
        name,
        label,
        entrada: e,
        cobradoCard: ch,
        pixDiscountVal,
        valorParcela: instVal,
        custoTotal: t,
        economia: isPixDiscount ? pixDiscountVal : Math.max(0, t0Ref - t),
        method: bMethod,
        installments: instCount
      };
    });
  }, [desiredNet, boxEntradas, boxMethods, boxInstallments, maxInstallmentsRule, salesVolume, cardBrand]);

  const visibleSimulationsCount = useMemo(() => {
    const array = Array.isArray(showInPatientScreen) ? showInPatientScreen : [false, true, false, false];
    const checkedCount = array.filter(Boolean).length;
    return checkedCount === 0 ? 1 : checkedCount;
  }, [showInPatientScreen]);

  const isSimVisible = (index: number) => {
    const array = Array.isArray(showInPatientScreen) ? showInPatientScreen : [false, true, false, false];
    const noneChecked = array.every(v => !v);
    if (noneChecked) {
      return selectedPlanIndices.includes(index);
    }
    return !!array[index];
  };

  const proceduresListOnMapeamento = useMemo(() => {
    const list: Array<{
      id: string;
      toothNumber: number;
      procedureName: string;
      price: number;
    }> = [];

    sections.forEach((sec) => {
      sec.markers.forEach((marker) => {
        if (marker.procedureInstances && marker.procedureInstances.length > 0) {
          marker.procedureInstances.forEach((inst) => {
            if (inst.includeFinancial !== false) {
              list.push({
                id: inst.id,
                toothNumber: marker.toothNumber,
                procedureName: inst.name,
                price: inst.price,
              });
            }
          });
        } else {
          marker.procedures.forEach((pid) => {
            const proc = procedures.find((p) => p.id === pid);
            if (proc) {
              list.push({
                id: `${sec.id}-${marker.id}-${pid}`,
                toothNumber: marker.toothNumber,
                procedureName: proc.name,
                price: proc.price,
              });
            }
          });
        }
      });
    });

    return list;
  }, [sections, procedures]);

  // View Helpers
  const getSectionProceduresUsed = (section: PhotoSection) => {
    return procedures.filter((p) =>
      section.markers.some((m) => {
        if (m.procedureInstances && m.procedureInstances.length > 0) {
          return m.procedureInstances.some((inst) => inst.procedureId === p.id);
        }
        return m.procedures.includes(p.id);
      })
    );
  };

  return (
    <div className="min-h-screen bg-[#FAF8F5] text-zinc-800 font-sans p-6 selection:bg-[#4E1119] selection:text-white">
      <div className="max-w-5xl mx-auto space-y-8">
        
        {/* Clinica Logo and Monogram Header Block */}
        <div className="border-b border-[#C09553]/40 pb-6 mb-6 text-center sm:text-left flex flex-col sm:flex-row justify-between items-center sm:items-start gap-4">
          <div className="space-y-1.5">
            <span className="text-[10px] font-extrabold text-[#B48C4D] tracking-widest uppercase">
              DR. AGNALDO FERREIRA — ODONTOLOGIA AVANÇADA
            </span>
            <h2 className="text-2xl font-serif text-[#4E1119] font-bold uppercase tracking-tight leading-tight">
              Plano de Tratamento
            </h2>
            <div className="flex items-center gap-3 mt-2">
              <div className="w-12 h-12 rounded-full overflow-hidden bg-zinc-200 border-2 border-white shadow-sm flex items-center justify-center flex-shrink-0">
                {proposal.patientData?.photoUrl ? (
                  <img src={proposal.patientData.photoUrl} alt="Avatar" className="w-full h-full object-cover" />
                ) : (
                  <span className="text-zinc-400 font-serif text-lg">{proposal.patientName ? proposal.patientName.charAt(0).toUpperCase() : '?'}</span>
                )}
              </div>
              <div className="text-sm text-zinc-600 font-sans">
                Paciente: <br /><strong className="text-zinc-800 text-base">{proposal.patientName || 'Não Informado'}</strong>
              </div>
            </div>
          </div>
          
          <div className="w-16 h-16 rounded-full bg-[#4E1119] flex items-center justify-center border-2 border-[#C09553]/30 flex-shrink-0 shadow-sm">
            <svg viewBox="0 0 100 100" className="w-10 h-10 text-[#FAF8F5]">
              <path d="M 36 75 L 49 31" stroke="currentColor" strokeWidth="6" strokeLinecap="round" strokeLinejoin="round" fill="none" />
              <path d="M 50 34 L 64 75" stroke="currentColor" strokeWidth="6" strokeLinecap="round" strokeLinejoin="round" fill="none" />
              <path d="M 48 31 L 67 31" stroke="currentColor" strokeWidth="6" strokeLinecap="round" strokeLinejoin="round" fill="none" />
              <path d="M 53 49 L 63 49" stroke="currentColor" strokeWidth="6" strokeLinecap="round" strokeLinejoin="round" fill="none" />
              <path d="M 34 55 Q 50 78 67 55" stroke="currentColor" strokeWidth="6" strokeLinecap="round" strokeLinejoin="round" fill="none" />
            </svg>
          </div>
        </div>

        {/* Dynamic List of Active Mapped Quadrants */}
        <div className="space-y-12">
          {sections.map((section) => {
            const hasImg = !!section.image;
            const markers = section.markers;
            const usedProcs = getSectionProceduresUsed(section);

            // Skip rendering if no mapping nor image exists (clean output)
            if (!hasImg && markers.length === 0) return null;

            return (
              <div
                key={section.id}
                className="bg-white border border-[#E6DEC9] rounded-2xl p-6 shadow-sm grid grid-cols-1 md:grid-cols-12 gap-8 items-start"
              >
                {/* Visual Quad Representation (Col Span 6) */}
                <div className="md:col-span-6 space-y-2">
                  <div>
                    <span className="text-[11px] font-bold text-[#B48C4D] uppercase tracking-wider block font-sans">
                      FOTO: {section.title}
                    </span>
                    {section.description && (
                      <p className="text-xs text-zinc-600 font-medium italic mt-0.5">
                        {section.description}
                      </p>
                    )}
                  </div>
                  
                  {/* Absolute visual representation layer matching editor */}
                  <div className="relative w-full aspect-video sm:aspect-[4/3] rounded-2xl overflow-hidden shadow-md border border-[#E6DEC9] bg-zinc-950">
                    {hasImg ? (
                      <>
                        <img
                          src={section.image!}
                          alt={section.title}
                          className="w-full h-full object-cover"
                          referrerPolicy="no-referrer"
                        />

                        {/* Flat tooth markers overlay */}
                        {markers.map((marker) => {
                          const size = proposal.markerSize || 26;
                          const markerProcs = (marker.procedureInstances && marker.procedureInstances.length > 0)
                            ? marker.procedureInstances.map((inst) => inst.procedureId)
                            : marker.procedures;
                          const hasP21 = markerProcs.includes('p_21');

                          return (
                            <div
                              key={marker.id}
                              style={{
                                left: `${marker.x}%`,
                                top: `${marker.y}%`,
                                width: `${size}px`,
                                height: `${size}px`,
                                fontSize: hasP21 ? `${Math.max(8, Math.round(size * 0.35))}px` : `${Math.max(9, Math.round(size * 0.42))}px`,
                                transform: 'translate(-50%, -50%)',
                              }}
                              className="absolute rounded-full border border-zinc-200 bg-white shadow-md flex items-center justify-center font-bold text-zinc-950 select-none z-10"
                            >
                              {hasP21 ? (
                                <div className="flex flex-col items-center justify-center -mt-1">
                                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" className="text-teal-600" style={{ width: `${size * 0.55}px`, height: `${size * 0.55}px` }}>
                                    <path d="M7 5h10M9 9h6M10 13h4M11 17h2M8 5v14a2 2 0 0 0 2 2h4a2 2 0 0 0 2-2V5M12 2v3" />
                                  </svg>
                                  <span className="absolute -bottom-2.5 bg-white border border-teal-600 text-teal-700 px-1 rounded-sm shadow-sm leading-none" style={{ fontSize: `${Math.max(8, Math.round(size * 0.3))}px` }}>
                                    {marker.toothNumber}
                                  </span>
                                </div>
                              ) : (
                                <span>{marker.toothNumber}</span>
                              )}

                              {/* Little color dot badges right on the edge */}
                              {markerProcs.length > 0 && (
                                <div 
                                  className="absolute flex gap-0.5 justify-end"
                                  style={{
                                    bottom: `-${Math.round(size * 0.1)}px`,
                                    right: `-${Math.round(size * 0.1)}px`,
                                    maxWidth: `${size * 1.5}px`,
                                  }}
                                >
                                  {markerProcs.map((procId, idx) => {
                                    const proc = procedures.find((p) => p.id === procId);
                                    if (!proc) return null;
                                    const dotSize = Math.max(5, Math.round(size * 0.3));
                                    return (
                                      <span
                                        key={`${procId}-${idx}`}
                                        className="rounded-full border border-white block"
                                        style={{ 
                                          backgroundColor: proc.color,
                                          width: `${dotSize}px`,
                                          height: `${dotSize}px`,
                                        }}
                                      />
                                    );
                                  })}
                                </div>
                              )}
                            </div>
                          );
                        })}
                      </>
                    ) : (
                      <div className="w-full h-full flex items-center justify-center text-xs text-zinc-400 italic">
                        Ilustração não carregada
                      </div>
                    )}
                  </div>
                </div>

                {/* Legend Side (Col Span 6) */}
                <div className="md:col-span-6 space-y-4">
                  <div>
                    <h3 className="text-base font-serif font-semibold text-[#4E1119] tracking-tight uppercase">
                      {section.title}
                    </h3>
                    <p className="text-[11px] text-[#B48C4D] uppercase tracking-wider font-semibold font-sans mb-3">
                      Gabarito de Procedimentos
                    </p>
                    <div className="h-[1px] bg-gradient-to-r from-[#C29D64] to-transparent w-full" />
                  </div>

                  {/* Legends list matching the original clinical record */}
                  <div className="space-y-2.5">
                    {usedProcs.length === 0 ? (
                      <p className="text-xs text-zinc-400 italic py-2">
                        Nenhum procedimento selecionado neste quadrante.
                      </p>
                    ) : (
                      usedProcs.map((proc) => {
                        // Count how many teeth have this clinical procedure
                        const teethWithThisProc = markers
                          .filter((m) => m.procedures.includes(proc.id))
                          .map((m) => m.toothNumber);

                        return (
                          <div key={proc.id} className="flex justify-between items-start gap-4 text-xs">
                            <div className="flex items-start gap-2.5 truncate">
                              {/* Representative Circle */}
                              <span
                                className="w-3.5 h-3.5 rounded-full mt-0.5 flex-shrink-0"
                                style={{ backgroundColor: proc.color }}
                              />
                              <div className="truncate">
                                <span className="font-medium text-zinc-800">{proc.name} </span>
                                {teethWithThisProc.length > 0 && (
                                  <span className="text-[10px] font-semibold text-[#B48C4D] bg-[#FAF8F5] border border-[#E6DEC9] px-1 py-0.2 rounded-sm font-mono whitespace-nowrap">
                                    Dente(s): {teethWithThisProc.join(', ')}
                                  </span>
                                )}
                              </div>
                            </div>
                            
                            <span className="font-mono text-zinc-700 text-right flex-shrink-0">
                              R$ {proc.price.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                            </span>
                          </div>
                        );
                      })
                    )}
                  </div>
                  
                  {/* Observações de cada dente selecionado */}
                  {(() => {
                    const markersWithNotes = markers.filter((m) => m.notes && m.notes.trim() !== '');
                    if (markersWithNotes.length === 0) return null;
                    return (
                      <div className="pt-2 border-t border-[#E6DEC9]/60 space-y-1.5">
                        <span className="text-[10px] font-bold text-[#B48C4D] uppercase tracking-wider block font-sans">
                          Observações por Dente:
                        </span>
                        <div className="grid grid-cols-1 gap-1.5">
                          {markersWithNotes.map((m) => (
                            <div key={m.id} className="text-xs bg-white border border-[#E6DEC9]/60 p-2 rounded-lg flex items-start gap-2 shadow-2xs">
                              <span className="bg-[#4E1119] text-[#FAF8F5] text-[9px] font-extrabold font-mono w-4 h-4 rounded-full flex items-center justify-center flex-shrink-0 mt-0.5">
                                {m.toothNumber}
                              </span>
                              <div className="space-y-0.5 leading-normal">
                                <span className="font-bold text-zinc-700 block text-[10.5px]">Dente {m.toothNumber}</span>
                                <p className="text-zinc-600 italic text-[11px]">"{m.notes}"</p>
                              </div>
                            </div>
                          ))}
                        </div>
                      </div>
                    );
                  })()}

                </div>
              </div>
            );
          })}
        </div>

        {/* Procedures Table */}
        {!hideProcedures && (
          <div className="bg-white border border-[#E6DEC9] rounded-2xl p-6 shadow-sm">
            <div className="flex justify-between items-center border-b border-zinc-100 pb-3 mb-4">
              <h4 className="text-sm font-bold text-[#4E1119] uppercase tracking-wider">
                Diagnóstico de Mapeamento Clínico
              </h4>
              <span className="text-xs font-mono text-zinc-500 font-bold">
                Total Mapeado: {proceduresListOnMapeamento.length} itens
              </span>
            </div>

            {proceduresListOnMapeamento.length === 0 ? (
