            {/* 2. Parabéns / Aniversário */}
            <div className="space-y-1.5 pt-2">
              <label className="block text-zinc-700 font-bold uppercase tracking-wider text-[10px]">2. Mensagem de Aniversário (Parabéns)</label>
              <textarea
                rows={3}
                value={templateAniversario}
                onChange={(e) => setTemplateAniversario(e.target.value)}
                className="w-full border border-zinc-300 rounded-xl p-3 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none resize-y text-xs font-sans leading-relaxed"
                placeholder="Escreva a mensagem..."
              />
            </div>

            {/* 3. Profilaxia (6 meses) */}
            <div className="space-y-1.5 pt-2">
              <label className="block text-zinc-700 font-bold uppercase tracking-wider text-[10px]">3. Lembrete de Profilaxia (6 meses)</label>
              <textarea
                rows={3}
                value={templateProfilaxia}
                onChange={(e) => setTemplateProfilaxia(e.target.value)}
                className="w-full border border-zinc-300 rounded-xl p-3 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none resize-y text-xs font-sans leading-relaxed"
                placeholder="Escreva a mensagem..."
              />
            </div>

            {/* 4. Feriados / Festas de Fim de Ano */}
            <div className="space-y-1.5 pt-2">
              <label className="block text-zinc-700 font-bold uppercase tracking-wider text-[10px]">4. Feriados Festivos (Natal & Ano Novo)</label>
              <textarea
                rows={3}
                value={templateFeriado}
                onChange={(e) => setTemplateFeriado(e.target.value)}
                className="w-full border border-zinc-300 rounded-xl p-3 focus:border-[#C09553] focus:ring-1 focus:ring-[#C09553] focus:outline-none resize-y text-xs font-sans leading-relaxed"
                placeholder="Escreva a mensagem..."
              />
            </div>
          </div>
        </div>


        {/* Section 3: Data Backup */}
        <div className="bg-white rounded-2xl border border-zinc-200 shadow-sm overflow-hidden">
          <div className="bg-[#8B0000] text-white px-4 py-2.5 flex items-center gap-2 border-b border-[#C09553]/30">
            <Database className="w-4 h-4 text-[#C09553]" />
            <h3 className="font-serif font-bold text-sm tracking-wide uppercase">Gerenciamento de Dados</h3>
          </div>
          
          <div className="p-5 space-y-4 text-xs">
            <p className="text-zinc-500 leading-relaxed mb-2">
              Faça o download de todos os seus dados do CRM em formato JSON para mantê-los seguros como um backup offline.
            </p>
            <button
              type="button"
              disabled={isBackingUp}
              onClick={handleBackup}
              className="px-6 py-3 bg-[#4E1119] hover:bg-[#6c1b26] text-white rounded-xl text-xs font-bold transition-all shadow-md cursor-pointer disabled:opacity-50 flex items-center justify-center gap-2"
            >
              <Download className="w-4 h-4" />
              {isBackingUp ? "Gerando Backup..." : "Fazer Backup Completo (Download)"}
            </button>
          </div>
        </div>

        {/* Actions buttons */}
        <div className="flex items-center gap-3 justify-end pt-2">
          <button
            type="button"
            onClick={handleResetDefaults}
            className="px-4 py-2.5 bg-zinc-100 hover:bg-zinc-200 border border-zinc-300 rounded-xl text-xs font-bold text-zinc-700 transition-all flex items-center gap-2 cursor-pointer"
          >
            <RotateCcw className="w-4 h-4 text-zinc-600" />
            Restaurar Padrão
          </button>
          
          <button
            type="submit"
            className="px-6 py-2.5 bg-[#4E1119] hover:bg-[#6c1b26] text-white rounded-xl text-xs font-bold transition-all flex items-center gap-2 shadow-md cursor-pointer"
          >
            <Save className="w-4 h-4 text-[#C09553]" />
            Salvar Configurações
          </button>
        </div>
      </form>
    </div>
  );
}

import React, { createContext, useContext, useState, useEffect, ReactNode, useCallback, useRef } from 'react';
import { getSupabaseCRMDatabase, saveSupabaseCRMDatabase } from '../lib/supabaseCrm';
import { CRMPatient, CRMAppointment, CRMClinicalHistory, CRMCommunication, PhotoSection, TreatmentProposal } from '../types';
import { DEFAULT_CLINICAL_STAGES } from '../constants';

interface PatientContextData {
  selectedPatient: CRMPatient | null;
  setSelectedPatient: (patient: CRMPatient | null) => void;

  appointments: CRMAppointment[];
  setAppointments: (appointments: CRMAppointment[]) => void;

  clinicalHistory: CRMClinicalHistory[];
  setClinicalHistory: (history: CRMClinicalHistory[]) => void;

  communications: CRMCommunication[];
  setCommunications: (comms: CRMCommunication[]) => void;

  anamneseList: any[];
  setAnamneseList: (list: any[]) => void;

  avisosList: any[];
  setAvisosList: (list: any[]) => void;

  documentosList: any[];
  setDocumentosList: (list: any[]) => void;

  galeriaList: any[];
  setGaleriaList: (list: any[]) => void;

  pagamentosList: any[];
  setPagamentosList: (list: any[]) => void;

  tratamentosList: any[];
  setTratamentosList: (list: any[]) => void;

  odontogramaList: any[];
  setOdontogramaList: (list: any[]) => void;

  // Active Planning Tab states (Odontograma & Orçamento)
  activeSections: PhotoSection[];
  setActiveSections: React.Dispatch<React.SetStateAction<PhotoSection[]>>;
  activeProposal: TreatmentProposal;
  setActiveProposal: React.Dispatch<React.SetStateAction<TreatmentProposal>>;

  // Ações baseadas em "Botões de Salvar"
  saveContextToSupabase: () => Promise<void>;
  isSavingToSupabase: boolean;

  // Função para recarregar tudo do Drive
  refreshPatientSubModules: (patientId: string) => Promise<void>;
}

const PatientContext = createContext<PatientContextData | undefined>(undefined);

// Define default initial states for Planning
const INITIAL_SECTIONS: PhotoSection[] = [
  { id: 'panoramic', title: 'Radiografia Panorâmica', subtitle: 'Planejamento de Implantes e Diagnósticos Gerais', image: null, markers: [] },
  { id: 'upper', title: 'Arcada Superior', subtitle: 'Dentes Posteriores e Anteriores Superiores', image: null, markers: [] },
  { id: 'lower', title: 'Arcada Inferior', subtitle: 'Dentes Posteriores e Anteriores Inferiores', image: null, markers: [] },
  { id: 'smile', title: 'Estética do Sorriso', subtitle: 'Mapeamento de Dentes Anteriores e Estética', image: null, markers: [] },
];

const INITIAL_PROPOSAL: TreatmentProposal = {
  patientName: '',
  status: 'Aberto (paciente não pagou)',
  notes: 'Orçamento feito sem radiografia atual pós trat. de canal, podendo haver alterações posteriores.',
  discountPercent: 5,
  pixDiscountLabel: '5% DESCONTO NO PIX',
  installments: 12,
  installmentsLabel: 'Parcelamento em até 12x (com taxas).',
  customDiscountAmount: 0,
  showTotalBySection: true,
  markerSize: 26,
  stages: DEFAULT_CLINICAL_STAGES,
  selectedAcquirer: 'ton',
};

const isPresentation = typeof window !== 'undefined' && new URLSearchParams(window.location.search).get('view') === 'presentation';

export function PatientProvider({ children }: { children: ReactNode }) {
  const [selectedPatient, setSelectedPatientState] = useState<CRMPatient | null>(() => {
    if (typeof window === 'undefined' || isPresentation) return null;
    try {
      const saved = localStorage.getItem('agnaldo_dent_selected_patient');
      if (saved) {
        const parsed = JSON.parse(saved);
        if (parsed && parsed.id && parsed.name) {
          return parsed;
        }
      }
    } catch (_) {}
    return null;
  });

  const setSelectedPatient = useCallback((patient: CRMPatient | null) => {
    setSelectedPatientState(patient);
    if (typeof window !== 'undefined' && !isPresentation) {
      try {
        if (patient && patient.id) {
          localStorage.setItem('agnaldo_dent_selected_patient', JSON.stringify(patient));
        } else {
          localStorage.removeItem('agnaldo_dent_selected_patient');
        }
      } catch (_) {}
    }
  }, []);

  const [appointments, setAppointments] = useState<CRMAppointment[]>([]);
  const [clinicalHistory, setClinicalHistory] = useState<CRMClinicalHistory[]>([]);
  const [communications, setCommunications] = useState<CRMCommunication[]>([]);
  const [anamneseList, setAnamneseList] = useState<any[]>([]);
  const [avisosList, setAvisosList] = useState<any[]>([]);
  const [documentosList, setDocumentosList] = useState<any[]>([]);
  const [galeriaList, setGaleriaList] = useState<any[]>([]);
  const [pagamentosList, setPagamentosList] = useState<any[]>([]);
  const [tratamentosList, setTratamentosList] = useState<any[]>([]);
  const [odontogramaList, setOdontogramaList] = useState<any[]>([]);
  const [activeSections, setActiveSections] = useState<PhotoSection[]>(INITIAL_SECTIONS);
  const [activeProposal, setActiveProposal] = useState<TreatmentProposal>(INITIAL_PROPOSAL);
  const [isSavingToSupabase, setIsSavingToSupabase] = useState(false);

  // Sync state via BroadcastChannel
  const latestStateRef = useRef({ selectedPatient, activeSections, activeProposal });
  useEffect(() => {
    latestStateRef.current = { selectedPatient, activeSections, activeProposal };
  }, [selectedPatient, activeSections, activeProposal]);

  useEffect(() => {
    const channel = new BroadcastChannel('patient_presentation_channel');

    if (!isPresentation) {
      const handleMessage = (event: MessageEvent) => {
        if (event.data?.type === 'request_initial_state') {
          channel.postMessage({
            type: 'state_sync',
            payload: latestStateRef.current
          });
        } else if (event.data?.type === 'accept_plan') {
          setActiveProposal(prev => ({
            ...prev,
            status: 'Aprovado (paciente pagou)'
          }));
        }
      };
      channel.addEventListener('message', handleMessage);
      return () => {
        channel.removeEventListener('message', handleMessage);
        channel.close();
      };
    } else {
      const handleMessage = (event: MessageEvent) => {
        if (event.data?.type === 'state_sync' && event.data.payload) {
          const { selectedPatient: syncPatient, activeSections: syncSections, activeProposal: syncProposal } = event.data.payload;
          setSelectedPatient(syncPatient);
          setActiveSections(syncSections);
          setActiveProposal(syncProposal);
        }
      };
      channel.addEventListener('message', handleMessage);
      channel.postMessage({ type: 'request_initial_state' });
      return () => {
        channel.removeEventListener('message', handleMessage);
        channel.close();
      };
    }
  }, []);

  useEffect(() => {
    if (!isPresentation) {
      const channel = new BroadcastChannel('patient_presentation_channel');
      channel.postMessage({
        type: 'state_sync',
        payload: { selectedPatient, activeSections, activeProposal }
      });
      return () => {
        channel.close();
      };
    }
  }, [selectedPatient, activeSections, activeProposal]);

  const patientLoadSequence = useRef(0);
  const saveInFlightRef = useRef(false);

  const refreshPatientSubModules = useCallback(async (patientId: string) => {
    if (!patientId) return;
    const currentSeq = ++patientLoadSequence.current;
    try {
      const crmData = await getSupabaseCRMDatabase();
      if (currentSeq !== patientLoadSequence.current) {
        return; // Ignora resposta obsoleta se o usuário trocou rapidamente de paciente
      }

      setAppointments((crmData.appointments || []).filter((a: any) => a.patientId === patientId));
      setClinicalHistory((crmData.clinical_history || []).filter((h: any) => h.patientId === patientId));
      setCommunications((crmData.communications || []).filter((c: any) => c.patientId === patientId));
      setAnamneseList((crmData.anamnese || []).filter((a: any) => a.patientId === patientId));
      setAvisosList((crmData.avisos || []).filter((a: any) => a.patientId === patientId));
      setDocumentosList((crmData.documentos || []).filter((d: any) => d.patientId === patientId));
      setGaleriaList((crmData.galeria || []).filter((g: any) => g.patientId === patientId));
      setPagamentosList((crmData.pagamentos || []).filter((p: any) => p.patientId === patientId).map((p: any) => ({
        ...p,
        amount: typeof p.amount === 'number' ? p.amount : Number(p.value) || 0,
        value: typeof p.value === 'number' ? p.value : Number(p.amount) || 0,
        paymentMethod: p.paymentMethod || p.method || 'Dinheiro',
        method: p.method || p.paymentMethod || 'Dinheiro',
        status: p.status || 'Pago'
      })));
      setTratamentosList((crmData.tratamentos || []).filter((t: any) => t.patientId === patientId));
      setOdontogramaList((crmData.odontograma || []).filter((o: any) => o.patientId === patientId));

      // Auto-load Active Sections and Proposal for this patient
      const savedSections = localStorage.getItem(`agnaldo_dent_sections_${patientId}`);
      if (savedSections) {
        try {
          setActiveSections(JSON.parse(savedSections));
        } catch (e) {
          const latestOdontograma = (crmData.odontograma || []).filter((o: any) => o.patientId === patientId).pop();
          if (latestOdontograma && latestOdontograma.sections) setActiveSections(latestOdontograma.sections);
          else setActiveSections(INITIAL_SECTIONS);
        }
      } else {
        const latestOdontograma = (crmData.odontograma || []).filter((o: any) => o.patientId === patientId).pop();
        if (latestOdontograma && latestOdontograma.sections) {
          setActiveSections(latestOdontograma.sections);
        } else {
          setActiveSections(INITIAL_SECTIONS);
        }
      }

      const savedProposal = localStorage.getItem(`agnaldo_dent_proposal_${patientId}`);
      if (savedProposal) {
        try {
          const parsed = JSON.parse(savedProposal);
          const currentPatient = (crmData.patients || []).find((p: any) => p.id === patientId);
          const currentPatientName = (currentPatient?.name || '').trim().toLowerCase();
          const parsedName = (parsed?.patientName || '').trim().toLowerCase();

          // Validate that the cached proposal belongs to this patient
          if (parsedName && currentPatientName && parsedName !== currentPatientName) {
            console.warn(`[PatientContext] Cache em agnaldo_dent_proposal_${patientId} pertence a "${parsed.patientName}", mas o paciente atual é "${currentPatient?.name}". Descartando cache contaminado.`);
            localStorage.removeItem(`agnaldo_dent_proposal_${patientId}`);
            const latestTratamento = (crmData.tratamentos || []).filter((t: any) => t.patientId === patientId).pop();
            if (latestTratamento && latestTratamento.proposal) setActiveProposal(latestTratamento.proposal);
            else setActiveProposal(INITIAL_PROPOSAL);
          } else {
            setActiveProposal(parsed);
          }
        } catch (e) {
          const latestTratamento = (crmData.tratamentos || []).filter((t: any) => t.patientId === patientId).pop();
          if (latestTratamento && latestTratamento.proposal) setActiveProposal(latestTratamento.proposal);
          else {
            setActiveProposal(INITIAL_PROPOSAL);
          }
        }
      } else {
        const latestTratamento = (crmData.tratamentos || []).filter((t: any) => t.patientId === patientId).pop();
        if (latestTratamento && latestTratamento.proposal) {
          setActiveProposal(latestTratamento.proposal);
        } else {
          setActiveProposal(INITIAL_PROPOSAL);
        }
      }
    } catch (err) {
      console.error("Falha ao recarregar dados do paciente:", err);
    }
  }, []);

  const prevPatientIdRef = useRef<string | null>(null);

  useEffect(() => {
    if (isPresentation) return;
    if (selectedPatient) {
      // Se trocou de paciente, reseta imediatamente proposta e seções ativas para não vazar dados do paciente anterior
      if (prevPatientIdRef.current !== selectedPatient.id) {
        prevPatientIdRef.current = selectedPatient.id;
        setActiveSections(INITIAL_SECTIONS);
        setActiveProposal(INITIAL_PROPOSAL);
      }
      refreshPatientSubModules(selectedPatient.id);
    } else {
      prevPatientIdRef.current = null;
      setAppointments([]);
      setClinicalHistory([]);
      setCommunications([]);
      setAnamneseList([]);
      setAvisosList([]);
      setDocumentosList([]);
      setGaleriaList([]);
      setPagamentosList([]);
      setTratamentosList([]);
      setOdontogramaList([]);
      setActiveSections(INITIAL_SECTIONS);
      setActiveProposal(INITIAL_PROPOSAL);
    }
  }, [selectedPatient, refreshPatientSubModules]);

  useEffect(() => {
    if (isPresentation || !selectedPatient) return;

    // GUARD: Não salvar seções se a proposta ativa pertencer a outro paciente
    const propPatientName = (activeProposal?.patientName || '').trim().toLowerCase();
    const selPatientName = (selectedPatient?.name || '').trim().toLowerCase();
    if (propPatientName && selPatientName && propPatientName !== selPatientName) {
      return;
    }

    // Use BroadcastChannel to bypass localStorage 5MB limits for the pop-up screen
    const channelName = `dental_crm_sync_${selectedPatient.id}`;
    const channel = new BroadcastChannel(channelName);
    const globalChannel = new BroadcastChannel('dental_crm_sync_global');

    const pushSections = () => {
      channel.postMessage({ type: 'SECTIONS_UPDATE', payload: activeSections });
      globalChannel.postMessage({ type: 'SECTIONS_UPDATE', payload: activeSections });
    };

    pushSections();

    channel.onmessage = (e) => {
      if (e.data.type === 'REQUEST_SYNC') pushSections();
    };
    globalChannel.onmessage = (e) => {
      if (e.data.type === 'REQUEST_SYNC') pushSections();
    };

    try {
      const serialized = JSON.stringify(activeSections);
      localStorage.setItem(`agnaldo_dent_sections_${selectedPatient.id}`, serialized);
      localStorage.setItem('agnaldo_dent_sections', serialized);
    } catch (e) {
      // Fallback seguro se a cota do localStorage estourar por imagens Base64:
      // preserva 100% dos dentes/marcadores e mantém imagens leves, sem perder os dados em memória/Supabase
      try {
        const lightSections = activeSections.map(sec => {
          if (sec.image && sec.image.length > 350000 && sec.image.startsWith('data:image')) {
            return { ...sec, image: null };
          }
          return sec;
        });
        const fallbackSerialized = JSON.stringify(lightSections);
        localStorage.setItem(`agnaldo_dent_sections_${selectedPatient.id}`, fallbackSerialized);
        localStorage.setItem('agnaldo_dent_sections', fallbackSerialized);
      } catch (innerErr) {
        console.warn('Não foi possível salvar activeSections no localStorage (limite excedido)', innerErr);
      }
    }

    return () => {
      channel.close();
      globalChannel.close();
    };
  }, [activeSections, selectedPatient, activeProposal]);

  useEffect(() => {
    if (isPresentation || !selectedPatient) return;

    const propPatientName = (activeProposal?.patientName || '').trim().toLowerCase();
    const selPatientName = (selectedPatient?.name || '').trim().toLowerCase();

    // GUARD: Nunca salvar proposta de outro paciente no storage do paciente atual
    if (propPatientName && selPatientName && propPatientName !== selPatientName) {
      return;
    }

    // GUARD: Não salvar template inicial em branco sobre o storage do paciente
    if (!propPatientName) {
      return;
    }

    const channelName = `dental_crm_sync_${selectedPatient.id}`;
    const channel = new BroadcastChannel(channelName);
    const globalChannel = new BroadcastChannel('dental_crm_sync_global');

    const pushProposal = () => {
      const enrichedProposal = { 
        ...activeProposal, 
        patientName: activeProposal?.patientName || selectedPatient?.name || '' 
      };
      channel.postMessage({ type: 'PROPOSAL_UPDATE', payload: enrichedProposal });
      globalChannel.postMessage({ type: 'PROPOSAL_UPDATE', payload: enrichedProposal });
    };

    pushProposal();

    channel.onmessage = (e) => {
      if (e.data.type === 'REQUEST_SYNC') pushProposal();
    };
    globalChannel.onmessage = (e) => {
      if (e.data.type === 'REQUEST_SYNC') pushProposal();
    };

    try {
      const enrichedProposal = { 
        ...activeProposal, 
        patientName: activeProposal?.patientName || selectedPatient?.name || '' 
      };
      const serialized = JSON.stringify(enrichedProposal);
      localStorage.setItem(`agnaldo_dent_proposal_${selectedPatient.id}`, serialized);
      localStorage.setItem('agnaldo_dent_proposal', serialized);
    } catch (e) {
      console.warn('Não foi possível salvar activeProposal no localStorage', e);
    }

    return () => {
      channel.close();
      globalChannel.close();
    };
  }, [activeProposal, selectedPatient, isPresentation]);

  const saveContextToSupabase = async () => {
    if (!selectedPatient || saveInFlightRef.current) return;
    saveInFlightRef.current = true;
    setIsSavingToSupabase(true);
    try {
      const crmData = await getSupabaseCRMDatabase();
      const pId = selectedPatient.id;

      // R6: Strict CRM Data Preservation — Only add patient if new, do NOT overwrite demographic fields on existing patient
      if (crmData.patients) {
        const pIndex = crmData.patients.findIndex((p: any) => p.id === pId);
        if (pIndex === -1) {
          crmData.patients.push(selectedPatient);
        }
      }

      // Substitui as listas deste paciente no banco global
      const mergeLists = (globalList: any[] = [], localList: any[]) => {
        const filtered = globalList.filter((item: any) => item.patientId !== pId);
        return [...filtered, ...localList];
      };

      crmData.appointments = mergeLists(crmData.appointments, appointments);
      crmData.clinical_history = mergeLists(crmData.clinical_history, clinicalHistory);
      crmData.communications = mergeLists(crmData.communications, communications);
      crmData.anamnese = mergeLists(crmData.anamnese, anamneseList);
      crmData.avisos = mergeLists(crmData.avisos, avisosList);
      crmData.documentos = mergeLists(crmData.documentos, documentosList);
      crmData.galeria = mergeLists(crmData.galeria, galeriaList);
      crmData.pagamentos = mergeLists(crmData.pagamentos, pagamentosList.map((p: any) => ({
        ...p,
        amount: typeof p.amount === 'number' ? p.amount : Number(p.value) || 0,
        value: typeof p.value === 'number' ? p.value : Number(p.amount) || 0,
        paymentMethod: p.paymentMethod || p.method || 'Dinheiro',
        method: p.method || p.paymentMethod || 'Dinheiro',
        status: p.status || 'Pago'
      })));

      // R1: Versioned budget / odontograma item tracking
      const budgetTimestamp = Date.now();
      const currentOdontogramaItem = {
        id: `od-${pId}-${budgetTimestamp}`,
        patientId: pId,
        date: new Date().toISOString(),
        sections: activeSections
      };

      const currentTratamentoItem = {
        id: `tr-${pId}-${budgetTimestamp}`,
        patientId: pId,
        date: new Date().toISOString(),
        proposal: activeProposal
      };

      const updatedOdontogramaList = [...odontogramaList, currentOdontogramaItem];
      const updatedTratamentosList = [...tratamentosList, currentTratamentoItem];

      setOdontogramaList(updatedOdontogramaList);
      setTratamentosList(updatedTratamentosList);

      crmData.tratamentos = mergeLists(crmData.tratamentos, updatedTratamentosList);
      crmData.odontograma = mergeLists(crmData.odontograma, updatedOdontogramaList);

      await saveSupabaseCRMDatabase(crmData);
      console.log('Salvo com sucesso no Supabase via Context API!');
    } catch (err) {
      console.error("Erro ao salvar no Drive:", err);
      throw err; // Permite que a UI exiba o erro
    } finally {
      saveInFlightRef.current = false;
      setIsSavingToSupabase(false);
    }
  };

  return (
    <PatientContext.Provider value={{
      selectedPatient, setSelectedPatient,
      appointments, setAppointments,
      clinicalHistory, setClinicalHistory,
      communications, setCommunications,
      anamneseList, setAnamneseList,
      avisosList, setAvisosList,
      documentosList, setDocumentosList,
      galeriaList, setGaleriaList,
      pagamentosList, setPagamentosList,
      tratamentosList, setTratamentosList,
      odontogramaList, setOdontogramaList,
      activeSections, setActiveSections,
      activeProposal, setActiveProposal,
      saveContextToSupabase,
      isSavingToSupabase,
      refreshPatientSubModules
    }}>
      {children}
    </PatientContext.Provider>
  );
}

export function usePatientContext() {
  const context = useContext(PatientContext);
  if (!context) {
    throw new Error('usePatientContext deve ser usado dentro de um PatientProvider');
  }
  return context;
}

import { supabase } from './lib/supabase';
import type { User } from '@supabase/supabase-js';
import { isAiSandboxMode, enableAiSandboxMode, disableAiSandboxMode } from './lib/aiSandbox';

let cachedAccessToken: string | null = localStorage.getItem('provider_token');

export const initAuth = (
  onAuthSuccess?: (user: User, token: string) => void,
  onAuthFailure?: () => void
) => {
  // Modo Sandbox para Inspeção de IA (100% dados fictícios isolados em sessionStorage, sem tocar no Supabase)
  if (isAiSandboxMode()) {
    enableAiSandboxMode();
    const sandboxUser: any = {
      id: 'ai-sandbox-inspector',
      email: 'ai-inspector@sandbox.local',
      user_metadata: { full_name: 'Modo Sandbox IA (Dados Fictícios)' },
      aud: 'sandbox',
      role: 'sandbox_inspector'
    };
    setTimeout(() => {
      if (onAuthSuccess) onAuthSuccess(sandboxUser, 'sandbox-mock-token');
    }, 50);
    return () => {};
  }

  // Regra AGENTS.md: NUNCA habilitar bypass_auth fora de NODE_ENV=development
  const isDev = import.meta.env.DEV;
  const hasBypassParam = typeof window !== 'undefined' && 
    (new URLSearchParams(window.location.search).get('bypass_auth') === 'true' || 
     localStorage.getItem('bypass_auth') === 'true');

  if (isDev && hasBypassParam) {
    if (typeof window !== 'undefined') {
      localStorage.setItem('bypass_auth', 'true');
    }
    const mockUser: any = {
      id: 'mock-user-id-dr-agnaldo',
      email: 'dr.agnaldo@example.com',
      user_metadata: { full_name: 'Dr. Agnaldo Ferreira (Mock)' },
      aud: 'authenticated',
      role: 'authenticated'
    };
    setTimeout(() => {
      if (onAuthSuccess) onAuthSuccess(mockUser, 'mock-access-token');
    }, 100);
    return () => {};
  }

  supabase.auth.getSession().then(({ data: { session } }) => {
    if (session) {
      if (session.provider_token) {
        cachedAccessToken = session.provider_token;
        localStorage.setItem('provider_token', session.provider_token);
        localStorage.setItem('provider_token_saved_at', Date.now().toString());
      }
      if (session.provider_refresh_token) {
        localStorage.setItem('provider_refresh_token', session.provider_refresh_token);
      }
      if (onAuthSuccess) onAuthSuccess(session.user, cachedAccessToken || '');
    } else {
      if (onAuthFailure) onAuthFailure();
    }
  });

  const { data: { subscription } } = supabase.auth.onAuthStateChange(
    (event, session) => {
      if (session) {
        if (session.provider_token) {
          cachedAccessToken = session.provider_token;
          localStorage.setItem('provider_token', session.provider_token);
          localStorage.setItem('provider_token_saved_at', Date.now().toString());
        }
        if (session.provider_refresh_token) {
          localStorage.setItem('provider_refresh_token', session.provider_refresh_token);
        }
        if (onAuthSuccess) onAuthSuccess(session.user, cachedAccessToken || '');
      } else {
        cachedAccessToken = null;
        localStorage.removeItem('provider_token');
        localStorage.removeItem('provider_token_saved_at');
        localStorage.removeItem('provider_refresh_token');
        if (onAuthFailure) onAuthFailure();
      }
    }
  );

  return () => subscription.unsubscribe();
};

export const googleSignIn = async (): Promise<{ user: User; accessToken: string } | null> => {
  try {
    const { data, error } = await supabase.auth.signInWithOAuth({
      provider: 'google',
      options: {
        redirectTo: window.location.href,
        scopes: 'https://www.googleapis.com/auth/calendar https://www.googleapis.com/auth/calendar.events',
        queryParams: {
          access_type: 'offline',
          prompt: 'consent'
        }
      }
    });

    if (error) throw error;
    // signInWithOAuth redirects, so this won't actually be reached in most flows
    return null;
  } catch (error) {
    console.error('Sign in error:', error);
    throw error;
  }
};

export const getAccessToken = async (): Promise<string | null> => {
  const token = localStorage.getItem('provider_token');
  const refreshToken = localStorage.getItem('provider_refresh_token');
  const savedAtStr = localStorage.getItem('provider_token_saved_at');

  if (!token) return null;

  if (refreshToken && savedAtStr) {
    const savedAt = parseInt(savedAtStr, 10);
    const isExpired = Date.now() - savedAt > 50 * 60 * 1000; // 50 minutos (token do Google dura 60 minutos)

    if (isExpired) {
      console.log('Google Access Token expirado ou prestes a expirar. Tentando renovar...');
      try {
        const response = await fetch('/api/auth/google/refresh', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ refresh_token: refreshToken })
        });

        if (response.ok) {
          const data = await response.json();
          if (data.access_token) {
            cachedAccessToken = data.access_token;
            localStorage.setItem('provider_token', data.access_token);
            localStorage.setItem('provider_token_saved_at', Date.now().toString());
            if (data.refresh_token) {
              localStorage.setItem('provider_refresh_token', data.refresh_token);
            }
            console.log('Google Access Token renovado com sucesso!');
            return data.access_token;
          }
        } else {
          console.warn('Erro ao renovar token com o backend:', await response.text());
          // If refresh fails (e.g. invalid_grant due to 7-day expiry), force logout
          await logout();
          window.location.reload();
          return null;
        }
      } catch (err) {
        console.error('Falha na requisição de refresh do token:', err);
      }
    }
  }

  return token || cachedAccessToken;
};

export const logout = async () => {
  disableAiSandboxMode();
  await supabase.auth.signOut();
  cachedAccessToken = null;
  localStorage.removeItem('provider_token');
  localStorage.removeItem('provider_token_saved_at');
  localStorage.removeItem('provider_refresh_token');
  localStorage.removeItem('bypass_auth');
};

import { useState, useEffect, useRef, useCallback } from 'react';
import {
  saveBudgetLocally,
  uploadBudgetToCloud,
  BudgetSyncStatus,
  getBudgetDraft
} from '../services/budgetSyncService';
import { TreatmentProposal, PhotoSection, Procedure } from '../types';

export interface UseAutoSaveBudgetProps {
  patientId?: string;
  patientName?: string;
  currentFileId?: string | null;
  setCurrentFileId?: (id: string | null) => void;
  proposal: TreatmentProposal;
  sections: PhotoSection[];
  procedures: Procedure[];
  simulations: any[];
  selectedPlanIndices: number[];
  customNetDesired?: number | null;
  boxEntradas?: number[];
  boxMethods?: string[];
  boxInstallments?: number[];
  debounceCloudMs?: number;
  enabled?: boolean;
}

export function useAutoSaveBudget({
  patientId,
  patientName = 'Paciente',
  currentFileId,
  setCurrentFileId,
  proposal,
  sections,
  procedures,
  simulations,
  selectedPlanIndices,
  customNetDesired,
  boxEntradas,
  boxMethods,
  boxInstallments,
  debounceCloudMs = 2500,
  enabled = true
}: UseAutoSaveBudgetProps) {
  const [syncStatus, setSyncStatus] = useState<BudgetSyncStatus>('idle');
  const [lastSavedLocal, setLastSavedLocal] = useState<Date | null>(null);
  const [lastSyncedCloud, setLastSyncedCloud] = useState<Date | null>(null);
  const [cloudError, setCloudError] = useState<string | null>(null);

  const cloudTimerRef = useRef<NodeJS.Timeout | null>(null);
  const latestDataRef = useRef<{ jsonStr: string; filename: string; patientId: string } | null>(null);
  const isInitialMount = useRef(true);

  // Calcula o nome do arquivo a ser gravado (opção de rascunho ativo vs arquivo existente)
  const getActiveFilename = useCallback(() => {
    if (currentFileId && currentFileId !== 'NEW_FILE' && currentFileId.includes('.json')) {
      return currentFileId.split('/').pop()!;
    }
    return 'orcamento_ativo.json';
  }, [currentFileId]);

  // Força sincronização imediata com a nuvem (sem aguardar o debounce)
  const forceCloudSync = useCallback(async () => {
    if (!patientId || !enabled) return;

    if (cloudTimerRef.current) {
      clearTimeout(cloudTimerRef.current);
      cloudTimerRef.current = null;
    }

    const filename = getActiveFilename();
    const statePayload = {
      proposal,
      sections,
      procedures,
      simulations,
      selectedPlanIndices,
      customNetDesired,
      boxEntradas,
      boxMethods,
      boxInstallments
    };

    // 1. Garante salvamento local prévio
    const { jsonStr, timestamp } = saveBudgetLocally(patientId, patientName, filename, statePayload);
    setLastSavedLocal(new Date(timestamp));

    // 2. Dispara upload imediato para o Supabase
    if (typeof navigator !== 'undefined' && !navigator.onLine) {
      setSyncStatus('offline');
      return;
    }

    setSyncStatus('syncing_cloud');
    setCloudError(null);

    const res = await uploadBudgetToCloud(patientId, filename, jsonStr);
    if (res.success) {
      setSyncStatus('synced_cloud');
      setLastSyncedCloud(new Date());
    } else {
      setSyncStatus('error');
      setCloudError(res.error?.message || 'Erro ao sincronizar com a nuvem');
    }
  }, [
    patientId,
    patientName,
    enabled,
    getActiveFilename,
    proposal,
    sections,
    procedures,
    simulations,
    selectedPlanIndices,
    customNetDesired,
    boxEntradas,
    boxMethods,
    boxInstallments
  ]);

  // Cria uma versão permanente fechada (ex: orcamento_v{timestamp}.json)
  const sealPermanentVersion = useCallback(async (customLabel?: string) => {
    if (!patientId) return null;

    let versionFilename = `orcamento_v${Date.now()}.json`;
    if (customLabel) {
      const safeLabel = customLabel.toLowerCase().replace(/[^a-z0-9_-]/g, '_');
      versionFilename = `orcamento_${safeLabel}_${Date.now()}.json`;
    }

    const statePayload = {
      proposal,
      sections,
      procedures,
      simulations,
      selectedPlanIndices,
      customNetDesired,
      boxEntradas,
      boxMethods,
      boxInstallments
    };

    // Salva local e sobe para o Supabase
    const { jsonStr } = saveBudgetLocally(patientId, patientName, versionFilename, statePayload);
    setSyncStatus('syncing_cloud');

    const res = await uploadBudgetToCloud(patientId, versionFilename, jsonStr);
    if (res.success) {
      setSyncStatus('synced_cloud');
      setLastSyncedCloud(new Date());
      if (setCurrentFileId) {
        setCurrentFileId(`Orcamentos/${versionFilename}`);
      }
      return versionFilename;
    } else {
      setSyncStatus('error');
      return null;
    }
  }, [
    patientId,
    patientName,
    proposal,
    sections,
    procedures,
    simulations,
    selectedPlanIndices,
    customNetDesired,
    boxEntradas,
    boxMethods,
    boxInstallments,
    setCurrentFileId
  ]);

  // Efeito principal: auto-salvamento a cada alteração
  useEffect(() => {
    // Pula o primeiro frame para evitar salvar antes do carregamento inicial dos dados do paciente
    if (isInitialMount.current) {
      isInitialMount.current = false;
      return;
    }

    if (!patientId || !enabled) return;

    const filename = getActiveFilename();
    const statePayload = {
      proposal,
      sections,
      procedures,
      simulations,
      selectedPlanIndices,
      customNetDesired,
      boxEntradas,
      boxMethods,
      boxInstallments
    };

    // 🚀 PASSO 1: Salvamento LOCAL IMEDIATO (0s)
    const { jsonStr, timestamp } = saveBudgetLocally(patientId, patientName, filename, statePayload);
    setSyncStatus('saved_local');
    setLastSavedLocal(new Date(timestamp));
    latestDataRef.current = { jsonStr, filename, patientId };

    // ☁️ PASSO 2: Agendamento do Upload para a Nuvem com Debounce
    if (cloudTimerRef.current) {
      clearTimeout(cloudTimerRef.current);
    }

    cloudTimerRef.current = setTimeout(async () => {
      if (typeof navigator !== 'undefined' && !navigator.onLine) {
        setSyncStatus('offline');
        return;
      }

      setSyncStatus('syncing_cloud');
      setCloudError(null);

      const res = await uploadBudgetToCloud(patientId, filename, jsonStr);
      if (res.success) {
        setSyncStatus('synced_cloud');
        setLastSyncedCloud(new Date());
      } else {
        setSyncStatus('error');
        setCloudError(res.error?.message || 'Erro ao salvar na nuvem');
      }
    }, debounceCloudMs);

    return () => {
      if (cloudTimerRef.current) {
        clearTimeout(cloudTimerRef.current);
      }
    };
  }, [
    patientId,
    patientName,
    enabled,
    getActiveFilename,
    proposal,
    sections,
    procedures,
    simulations,
    selectedPlanIndices,
    customNetDesired,
    boxEntradas,
    boxMethods,
    boxInstallments,
    debounceCloudMs
  ]);

  // Flush ao descarregar a página ou fechar a aba
  useEffect(() => {
    const handleBeforeUnload = () => {
      if (latestDataRef.current) {
        const { patientId: pId, filename, jsonStr } = latestDataRef.current;
        // Garante que o estado local mais recente esteja gravado no disco
        saveBudgetLocally(pId, patientName, filename, JSON.parse(jsonStr));
      }
    };

    window.addEventListener('beforeunload', handleBeforeUnload);
    return () => {
      window.removeEventListener('beforeunload', handleBeforeUnload);
    };
  }, [patientName]);

  return {
    syncStatus,
    lastSavedLocal,
    lastSyncedCloud,
    cloudError,
    forceCloudSync,
    sealPermanentVersion
  };
}

import { useState, useEffect } from 'react';

export function useReactiveLocalStorage<T>(key: string, initialValue: T): [T, (value: T | ((val: T) => T)) => void] {
  const [storedValue, setStoredValue] = useState<T>(() => {
    try {
      const item = window.localStorage.getItem(key);
      return item ? JSON.parse(item) : initialValue;
    } catch (error) {
      console.warn(error);
      return initialValue;
    }
  });

  const setValue = (value: T | ((val: T) => T)) => {
    try {
      const valueToStore = value instanceof Function ? value(storedValue) : value;
      setStoredValue(valueToStore);
      window.localStorage.setItem(key, JSON.stringify(valueToStore));
      window.dispatchEvent(new Event('local-storage'));
    } catch (error) {
      console.warn(error);
    }
  };

  useEffect(() => {
    const handleStorageChange = () => {
      try {
        const item = window.localStorage.getItem(key);
        setStoredValue(item ? JSON.parse(item) : initialValue);
      } catch (error) {
        console.warn(error);
      }
    };

    window.addEventListener('local-storage', handleStorageChange);
    window.addEventListener('storage', handleStorageChange);

    return () => {
      window.removeEventListener('local-storage', handleStorageChange);
      window.removeEventListener('storage', handleStorageChange);
    };
  }, [key, initialValue]);

  return [storedValue, setValue];
}

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&family=Playfair+Display:wght@400;500;600;700&display=swap');
@import "tailwindcss";

/* ============================================================
   DESIGN TOKENS — Dr. Agnaldo Ferreira Sistema Clínico
   ============================================================ */
:root {
  /* Brand Colors */
  --brand-red:        #8B0000;
  --brand-red-dark:   #5C0000;
  --brand-red-light:  #A30000;
  --brand-gold:       #C09553;
  --brand-gold-light: #E1CDAC;
  --brand-cream:      #FAF8F5;
  --brand-leather:    #F2EDE6;

  /* Sidebar */
  --sidebar-bg:       #6B0000;
  --sidebar-width:    260px;
  --sidebar-collapsed:72px;

  /* Text */
  --text-primary:     #1C0A0A;
  --text-secondary:   #52525B;
  --text-muted:       #A1A1AA;

  /* Borders */
  --border-light:     #E6DEC9;
  --border-gold:      #C09553;

  /* Surfaces */
  --surface-white:    #FFFFFF;
  --surface-card:     #FFFFFF;

  /* Shadows */
  --shadow-sm:        0 1px 3px rgba(0,0,0,.07), 0 1px 2px rgba(0,0,0,.05);
  --shadow-md:        0 4px 12px rgba(0,0,0,.08), 0 2px 4px rgba(0,0,0,.05);
  --shadow-lg:        0 10px 30px rgba(0,0,0,.12), 0 4px 8px rgba(0,0,0,.06);
  --shadow-sidebar:   4px 0 24px rgba(0,0,0,.25);
}

/* ============================================================
   GLOBAL BASE
   ============================================================ */
*, *::before, *::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  background-color: var(--brand-cream);
  color: var(--text-primary);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.font-serif, .font-display {
  font-family: 'Playfair Display', Georgia, serif;
}

/* ============================================================
   SIDEBAR LAYOUT
   ============================================================ */
.app-shell {
  display: flex;
  min-height: 100vh;
  overflow: hidden;
}

/* Sidebar */
.sidebar {
  position: fixed;
  top: 0;
  left: 0;
  height: 100vh;
  width: var(--sidebar-width);
  background: linear-gradient(180deg, var(--brand-red) 0%, var(--brand-red-dark) 100%);
  box-shadow: var(--shadow-sidebar);
  z-index: 50;
  display: flex;
  flex-direction: column;
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1),
              width 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  overflow: hidden;
}

.sidebar.collapsed {
  width: var(--sidebar-collapsed);
}

/* On mobile, sidebar is off-screen by default */
@media (max-width: 1023px) {
  .sidebar {
    transform: translateX(-100%);
  }
  .sidebar.mobile-open {
    transform: translateX(0);
  }
  .main-content {
    margin-left: 0 !important;
  }
}

.sidebar-overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.5);
  z-index: 40;
  backdrop-filter: blur(2px);
}

@media (max-width: 1023px) {
  .sidebar-overlay.visible {
    display: block;
  }
}

/* Main content shifts right by sidebar width */
.main-content {
  margin-left: var(--sidebar-width);
  flex: 1;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  transition: margin-left 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  min-width: 0;
}

.main-content.sidebar-collapsed {
  margin-left: var(--sidebar-collapsed);
}

/* Sidebar Logo Area */
.sidebar-logo {
  padding: 24px 20px 20px;
  border-bottom: 1px solid rgba(255,255,255,0.1);
  flex-shrink: 0;
}

/* Sidebar Nav */
.sidebar-nav {
  flex: 1;
  overflow-y: auto;
  padding: 12px 10px;
  scrollbar-width: none;
}

.sidebar-nav::-webkit-scrollbar {
  display: none;
}

.nav-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 11px 14px;
  border-radius: 10px;
  cursor: pointer;
  transition: all 0.2s ease;
  color: rgba(255,255,255,0.65);
  font-size: 13.5px;
  font-weight: 500;
  margin-bottom: 2px;
  white-space: nowrap;
  overflow: hidden;
  position: relative;
  text-decoration: none;
}

.nav-item:hover {
  background: rgba(255,255,255,0.12);
  color: #ffffff;
}

.nav-item.active {
  background: rgba(255,255,255,0.18);
  color: #ffffff;
  font-weight: 600;
}

.nav-item.active::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 3px;
  height: 60%;
  background: var(--brand-gold);
  border-radius: 0 3px 3px 0;
}

.nav-item-icon {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
}

.nav-section-label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.3);
  padding: 12px 14px 4px;
}

/* Sidebar Footer */
.sidebar-footer {
  padding: 16px 12px;
  border-top: 1px solid rgba(255,255,255,0.1);
  flex-shrink: 0;
}

/* ============================================================
   TOP BAR
   ============================================================ */
.topbar {
  height: 60px;
  background: #ffffff;
  border-bottom: 1px solid var(--border-light);
  display: flex;
  align-items: center;
  padding: 0 24px;
  gap: 16px;
  flex-shrink: 0;
  box-shadow: var(--shadow-sm);
  position: sticky;
  top: 0;
  z-index: 30;
}

/* ============================================================
   CARDS & SURFACES
   ============================================================ */
.card {
  background: var(--surface-card);
  border: 1px solid var(--border-light);
  border-radius: 16px;
  box-shadow: var(--shadow-sm);
}

.card-hover {
  transition: box-shadow 0.2s ease, transform 0.2s ease;
}

.card-hover:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

/* ============================================================
   TABS
   ============================================================ */
.tab-bar {
  display: flex;
  gap: 4px;
  background: #F4F0EC;
  padding: 4px;
  border-radius: 12px;
}

.tab-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  border-radius: 9px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  transition: all 0.2s ease;
  cursor: pointer;
  color: var(--text-secondary);
  white-space: nowrap;
}

.tab-btn.active {
  background: var(--brand-red);
  color: white;
  box-shadow: 0 2px 8px rgba(139,0,0,0.3);
}

.tab-btn:not(.active):hover {
  background: rgba(139,0,0,0.07);
  color: var(--brand-red);
}

/* ============================================================
   ANIMATIONS
   ============================================================ */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fadeIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}

@keyframes slideInLeft {
  from {
    opacity: 0;
    transform: translateX(-16px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes pulse-gold {
  0%, 100% { box-shadow: 0 0 0 0 rgba(192,149,83,0.4); }
  50%       { box-shadow: 0 0 0 8px rgba(192,149,83,0); }
}

.animate-fade-in-up { animation: fadeInUp 0.4s ease both; }
.animate-fade-in    { animation: fadeIn 0.3s ease both; }
.animate-slide-left { animation: slideInLeft 0.35s ease both; }
.animate-pulse-gold { animation: pulse-gold 2s ease-in-out infinite; }

/* Stagger children */
.stagger > *:nth-child(1) { animation-delay: 0.05s; }
.stagger > *:nth-child(2) { animation-delay: 0.10s; }
.stagger > *:nth-child(3) { animation-delay: 0.15s; }
.stagger > *:nth-child(4) { animation-delay: 0.20s; }
.stagger > *:nth-child(5) { animation-delay: 0.25s; }
.stagger > *:nth-child(6) { animation-delay: 0.30s; }

/* ============================================================
   INPUTS & FORMS
   ============================================================ */
.field-input {
  width: 100%;
  background: var(--brand-cream);
  border: 1.5px solid var(--border-light);
  border-radius: 10px;
  padding: 10px 14px;
  font-size: 13px;
  font-family: 'Inter', sans-serif;
  color: var(--text-primary);
  transition: border-color 0.2s, box-shadow 0.2s;
  outline: none;
}

.field-input:focus {
  border-color: var(--brand-red);
  box-shadow: 0 0 0 3px rgba(139,0,0,0.08);
}

.field-label {
  font-size: 11px;
  font-weight: 600;
