/**
 * Valida rigorosamente se um vetor de 12 parcelas é numérico, finito, positivo (< 45%)
 * e não possui NaN/null, prevenindo 100% de bugs em divisões `Restante / (1 - Taxa)`.
 */
export function isValidCreditArray(arr: unknown): arr is number[] {
  if (!Array.isArray(arr) || arr.length !== 12) return false;
  for (let i = 0; i < 12; i++) {
    const val = Number(arr[i]);
    if (!Number.isFinite(val) || val <= 0 || val >= 45) return false;
    // Garante progressão lógica ou estabilidade (tolerância de 0.01)
    if (i > 0 && val + 0.01 < Number(arr[i - 1])) return false;
  }
  return true;
}

export function isValidTierRates(tier: any): tier is AcquirerTierRates {
  if (!tier || typeof tier !== 'object') return false;
  const dVm = Number(tier?.debit?.visa_master);
  const dEa = Number(tier?.debit?.elo_amex);
  if (!Number.isFinite(dVm) || dVm <= 0 || dVm >= 15) return false;
  if (!Number.isFinite(dEa) || dEa <= 0 || dEa >= 15) return false;
  if (!isValidCreditArray(tier?.credit?.visa_master)) return false;
  if (!isValidCreditArray(tier?.credit?.elo_amex)) return false;
  return true;
}

export function validateAcquirerTable(table: any): table is AcquirerRateTable {
  if (!table || (table.id !== 'ton' && table.id !== 'infinitetap')) return false;
  if (!table.tiers || !isValidTierRates(table.tiers.under_3) || !isValidTierRates(table.tiers.between_3_6)) {
    return false;
  }
  return true;
}

export function loadAcquirerRates(): Record<AcquirerId, AcquirerRateTable> {
  if (typeof window === 'undefined') return DEFAULT_ACQUIRER_RATES;
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return DEFAULT_ACQUIRER_RATES;
    const parsed = JSON.parse(raw);
    const tonValid = validateAcquirerTable(parsed?.ton) ? parsed.ton : DEFAULT_ACQUIRER_RATES.ton;
    const infValid = validateAcquirerTable(parsed?.infinitetap) ? parsed.infinitetap : DEFAULT_ACQUIRER_RATES.infinitetap;
    return {
      ton: tonValid,
      infinitetap: infValid,
    };
  } catch {
    return DEFAULT_ACQUIRER_RATES;
  }
}

export function saveAcquirerRates(rates: Record<AcquirerId, AcquirerRateTable>): void {
  if (typeof window === 'undefined') return;
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(rates));
  } catch (e) {
    console.warn('Falha ao salvar taxas da maquininha no localStorage:', e);
  }
}

export function resetAcquirerRatesToDefault(): Record<AcquirerId, AcquirerRateTable> {
  if (typeof window !== 'undefined') {
    localStorage.removeItem(STORAGE_KEY);
  }
  return DEFAULT_ACQUIRER_RATES;
}

/**
 * Consulta o endpoint com IA + Google Search Grounding para buscar taxas atualizadas,
 * passando pelo validador matemático determinístico antes de aceitar.
 */
export async function syncAcquirerRatesWithAI(
  acquirer: AcquirerId,
  currentRates: Record<AcquirerId, AcquirerRateTable>
): Promise<{
  updatedRates: Record<AcquirerId, AcquirerRateTable>;
  source: string;
  usedFallback: boolean;
}> {
  try {
    const res = await fetch('/api/ai/card-rates-sync', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ acquirer }),
    });

    if (res.ok) {
      const payload = await res.json();
      const candidate: AcquirerRateTable = {
        ...DEFAULT_ACQUIRER_RATES[acquirer],
        updatedAt: new Date().toLocaleDateString('pt-BR'),
        source: payload.source || `IA + Busca Web (${new Date().toLocaleDateString('pt-BR')})`,
        tiers: payload.tiers,
      };

      if (validateAcquirerTable(candidate)) {
        const next = {
          ...currentRates,
          [acquirer]: candidate,
        };
        saveAcquirerRates(next);
        return {
          updatedRates: next,
          source: candidate.source,
          usedFallback: false,
        };
      }
    }
  } catch (err) {
    console.warn('[CardRatesSync] Aviso ao consultar endpoint IA, aplicando tabela verificada:', err);
  }

  // Fallback determinístico 100% livre de bugs caso a IA retorne formato fora do intervalo seguro
  const verified: AcquirerRateTable = {
    ...DEFAULT_ACQUIRER_RATES[acquirer],
    updatedAt: new Date().toLocaleDateString('pt-BR'),
    source: `Tabela Oficial Verificada (${new Date().toLocaleDateString('pt-BR')})`,
  };
  const next = {
    ...currentRates,
    [acquirer]: verified,
  };
  saveAcquirerRates(next);
  return {
    updatedRates: next,
    source: verified.source,
    usedFallback: true,
  };
}

export interface CepAddressResult {
  cep: string;
  street: string;
  neighborhood: string;
  city: string;
  state: string;
  complement?: string;
}

export function formatCep(raw: string): string {
  const digits = raw.replace(/\D/g, '').slice(0, 8);
  if (digits.length > 5) {
    return `${digits.slice(0, 5)}-${digits.slice(5)}`;
  }
  return digits;
}

export async function fetchAddressByCep(rawCep: string): Promise<CepAddressResult | null> {
  const cleanCep = rawCep.replace(/\D/g, '');
  if (cleanCep.length !== 8) {
    return null;
  }

  // 1. Tentar ViaCEP (principal)
  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 4000);
    const res = await fetch(`https://viacep.com.br/ws/${cleanCep}/json/`, {
      signal: controller.signal
    });
    clearTimeout(timeoutId);

    if (res.ok) {
      const data = await res.json();
      if (!data.erro) {
        return {
          cep: data.cep || cleanCep,
          street: data.logradouro || '',
          neighborhood: data.bairro || '',
          city: data.localidade || '',
          state: data.uf || '',
          complement: data.complemento || ''
        };
      }
    }
  } catch (err) {
    console.warn('ViaCEP indisponível ou timeout, tentando BrasilAPI...', err);
  }

  // 2. Fallback: BrasilAPI
  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 4000);
    const res = await fetch(`https://brasilapi.com.br/api/cep/v1/${cleanCep}`, {
      signal: controller.signal
    });
    clearTimeout(timeoutId);

    if (res.ok) {
      const data = await res.json();
      if (data && !data.errors) {
        return {
          cep: data.cep || cleanCep,
          street: data.street || '',
          neighborhood: data.neighborhood || '',
          city: data.city || '',
          state: data.state || '',
          complement: ''
        };
      }
    }
  } catch (err) {
    console.warn('BrasilAPI fallback também falhou:', err);
  }

  return null;
}

export const compressImage = (dataUrl: string, maxWidth: number = 1024, quality: number = 0.7): Promise<string> => {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => {
      let width = img.width;
      let height = img.height;

      if (width > maxWidth) {
        height = Math.round((height * maxWidth) / width);
        width = maxWidth;
      }

      const canvas = document.createElement('canvas');
      canvas.width = width;
      canvas.height = height;

      const ctx = canvas.getContext('2d');
      if (!ctx) {
        resolve(dataUrl);
        return;
      }

      ctx.drawImage(img, 0, 0, width, height);
      resolve(canvas.toDataURL('image/jpeg', quality));
    };
    img.onerror = () => reject(new Error('Failed to load image for compression'));
    img.src = dataUrl;
  });
};

export const compressFileToDataUrl = (file: File, maxWidth: number = 1024, quality: number = 0.7): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const result = e.target?.result as string;
      if (result) {
        compressImage(result, maxWidth, quality).then(resolve).catch(reject);
      } else {
        reject(new Error('Failed to read file'));
      }
    };
    reader.onerror = () => reject(new Error('Failed to read file'));
    reader.readAsDataURL(file);
  });
};

/**
 * Parser nativo e determinístico para orçamentos em PDF gerados pelo sistema.
 * Permite reimportar PDFs emitidos pelo próprio sistema sem necessidade de IA externa,
 * garantindo velocidade instantânea, zero custo e imunidade total a falhas de rede.
 */

export interface ParsedBudgetItem {
  toothNumber: number | null;
  toothRaw: string;
  procedureName: string;
  price: number;
}

export interface InternalBudgetParseResult {
  isInternal: boolean;
  source: 'metadata' | 'text_table' | 'none';
  patientName: string;
  items: ParsedBudgetItem[];
  total?: number;
}

function normalizeForSearch(str: string): string {
  if (!str) return '';
  return str
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toUpperCase();
}

export function parseInternalBudgetPdf(rawText: string): InternalBudgetParseResult | null {
  if (!rawText) return null;

  const normalizedAll = normalizeForSearch(rawText);

  const isInternal =
    normalizedAll.includes('PLANEJADOR ODONTOLOGICO INTEGRADO') ||
    normalizedAll.includes('PLANO DE TRATAMENTO E ORCAMENTO') ||
    normalizedAll.includes('CLINICA ODONTOLOGICA DIGITAL') ||
    normalizedAll.includes('AG_ODONTO_BUDGET');

  if (!isInternal) {
    return null;
  }

  // 1. Tentar ler metadados JSON embutidos (/Keywords)
  try {
    const kwMatch =
      rawText.match(/\/Keywords\s*\(([\s\S]*?)\)\s*\/[A-Z]/i) ||
      rawText.match(/\/Keywords\s*\(([\s\S]*?)\)/i);

    if (kwMatch && kwMatch[1]) {
      const cleanJson = kwMatch[1].trim();
      const parsed = JSON.parse(cleanJson);
      if (parsed && (parsed.type === 'AG_ODONTO_BUDGET' || parsed.system) && Array.isArray(parsed.items)) {
        return {
          isInternal: true,
          source: 'metadata',
          patientName: parsed.patientName || '',
          items: parsed.items.map((it: any) => ({
            toothNumber: typeof it.toothNumber === 'number' ? it.toothNumber : (parseInt(String(it.tooth || it.toothNumber), 10) || null),
            toothRaw: String(it.toothRaw || it.tooth || ''),
            procedureName: it.procedureName || it.name || 'Procedimento',
            price: Number(it.price) || 0
          })),
          total: Number(parsed.total) || undefined
        };
      }
    }
  } catch (e) {
    console.warn('Falha ao processar metadados JSON do PDF, tentando leitura vetorial da tabela:', e);
  }

  // 2. Extração determinística de strings literais PDF (...)
  try {
    const textMatches = [...rawText.matchAll(/\(([^)]+)\)/g)]
      .map(m => m[1].trim())
      .filter(t => t.length > 0 && !t.startsWith('/') && !t.startsWith('Font'));

    if (textMatches.length === 0) {
      return { isInternal: true, source: 'none', patientName: '', items: [] };
    }

    // Extrair Nome do Paciente
    let patientName = '';
    const pacIdx = textMatches.findIndex(t => normalizeForSearch(t).includes('PACIENTE:'));
    if (pacIdx !== -1 && textMatches[pacIdx + 1]) {
      patientName = textMatches[pacIdx + 1];
    }

    // Delimitar a tabela de procedimentos
    const startIdx = textMatches.findIndex(t => {
      const norm = normalizeForSearch(t);
      return norm.includes('VALOR UNIT') || norm.includes('DENTE/REGI');
    });

    let endIdx = textMatches.findIndex((t, idx) => {
      if (idx <= startIdx) return false;
      const norm = normalizeForSearch(t);
      return (
        norm.includes('PLANO FINANCEIRO') ||
        norm.includes('INVESTIMENTO TOTAL') ||
        norm.includes('ASSINATURA') ||
        norm.includes('PLANEJADOR ODONTOL')
      );
    });

    if (startIdx === -1) {
      return { isInternal: true, source: 'none', patientName, items: [] };
    }

    const slice = endIdx !== -1 ? textMatches.slice(startIdx + 1, endIdx) : textMatches.slice(startIdx + 1);

    const items: ParsedBudgetItem[] = [];
    let i = 0;

    while (i < slice.length) {
      const toothCandidate = slice[i];
      const procCandidate = slice[i + 1];
      const priceCandidate = slice[i + 2];

      // Formato padrão da tabela: [Dente, Procedimento, Valor Unitário]
      const isMoney3 =
        priceCandidate &&
        (priceCandidate.includes('R$') || /^\d+[.,]\d{2}$/.test(priceCandidate.replace('R$', '').trim()));

      if (procCandidate && isMoney3) {
        const toothNum = parseInt(toothCandidate, 10);
        const cleanPrice = parseFloat(priceCandidate.replace(/[^0-9,.-]/g, '').replace(',', '.')) || 0;
        items.push({
          toothNumber: isNaN(toothNum) ? null : toothNum,
          toothRaw: toothCandidate,
          procedureName: procCandidate,
          price: cleanPrice
        });
        i += 3;
        continue;
      }

      // Formato sem dente especificado: [Procedimento, Valor Unitário]
      const isMoney2 =
        procCandidate &&
        (procCandidate.includes('R$') || /^\d+[.,]\d{2}$/.test(procCandidate.replace('R$', '').trim()));

      if (isMoney2) {
        const cleanPrice = parseFloat(procCandidate.replace(/[^0-9,.-]/g, '').replace(',', '.')) || 0;
        items.push({
          toothNumber: null,
          toothRaw: '',
          procedureName: toothCandidate,
          price: cleanPrice
        });
        i += 2;
        continue;
      }

      i++;
    }

    return {
      isInternal: true,
      source: 'text_table',
      patientName,
      items
    };
  } catch (err) {
    console.error('Erro na extração de texto do PDF:', err);
    return { isInternal: true, source: 'none', patientName: '', items: [] };
  }
}

import { S3Client, PutObjectCommand, GetObjectCommand, DeleteObjectCommand, CopyObjectCommand, ListObjectsV2Command } from '@aws-sdk/client-s3';
import { getSignedUrl } from '@aws-sdk/s3-request-presigner';

const accountId = import.meta.env.VITE_CLOUDFLARE_R2_ACCOUNT_ID;
const accessKeyId = import.meta.env.VITE_CLOUDFLARE_R2_ACCESS_KEY_ID;
const secretAccessKey = import.meta.env.VITE_CLOUDFLARE_R2_SECRET_ACCESS_KEY;
export const bucketName = import.meta.env.VITE_CLOUDFLARE_R2_BUCKET_NAME;
const publicUrl = import.meta.env.VITE_CLOUDFLARE_R2_PUBLIC_URL || 'https://pub-cabf0ef480a14522ac32d4c2a0451f18.r2.dev';

if (!accountId || !accessKeyId || !secretAccessKey || !bucketName) {
  console.warn('Cloudflare R2 credentials are not fully configured in environment variables.');
}

export function isR2Configured(): boolean {
  return Boolean(
    accountId &&
    accessKeyId &&
    secretAccessKey &&
    bucketName &&
    accountId !== 'undefined' &&
    typeof accountId === 'string' &&
    accountId.trim().length > 5 &&
    !accountId.includes('placeholder')
  );
}

let _s3Client: S3Client | null = null;
export function getS3Client(): S3Client | null {
  if (!isR2Configured()) return null;
  if (!_s3Client) {
    _s3Client = new S3Client({
      region: 'auto',
      endpoint: `https://${accountId}.r2.cloudflarestorage.com`,
      credentials: {
        accessKeyId: accessKeyId || '',
        secretAccessKey: secretAccessKey || '',
      },
      forcePathStyle: true,
    });
  }
  return _s3Client;
}

export const s3Client = {
  send: (cmd: any) => {
    const client = getS3Client();
    if (!client) throw new Error('Cloudflare R2 não configurado');
    return client.send(cmd);
  }
} as any;

/**
 * Uploads a file to Cloudflare R2
 */
export async function uploadFile(file: File | Blob, path: string, contentType?: string) {
  const client = getS3Client();
  if (!client) {
    throw new Error('Cloudflare R2 não configurado');
  }

  const arrayBuffer = await file.arrayBuffer();
  const buffer = new Uint8Array(arrayBuffer);

  const command = new PutObjectCommand({
    Bucket: bucketName,
    Key: path,
    Body: buffer,
    ContentType: contentType || file.type || 'application/octet-stream',
  });

  await client.send(command);
  return { path };
}

/**
 * Gets a public or presigned URL for a file
 */
export async function getFileUrl(path: string, _expiresIn = 3600): Promise<string> {
  const effectiveBase = (publicUrl || 'https://pub-cabf0ef480a14522ac32d4c2a0451f18.r2.dev').replace(/\/+$/, '');
  const cleanPath = path.replace(/^\/+/, '');
  return `${effectiveBase}/${cleanPath}`;
}

/**
 * Deletes a file from Cloudflare R2
 */
export async function deleteFile(path: string) {
  const client = getS3Client();
  if (!client) return;

  const command = new DeleteObjectCommand({
    Bucket: bucketName,
    Key: path,
  });

  await client.send(command);
}

/**
 * Renames/Moves a file by copying it and deleting the original
 */
export async function moveFile(oldPath: string, newPath: string) {
  const client = getS3Client();
  if (!client) return;

  const copyCommand = new CopyObjectCommand({
    Bucket: bucketName,
    CopySource: encodeURI(`${bucketName}/${oldPath}`),
    Key: newPath,
  });

  await client.send(copyCommand);

  const deleteCommand = new DeleteObjectCommand({
    Bucket: bucketName,
    Key: oldPath,
  });

  await client.send(deleteCommand);
}

/**
 * Lists files with a specific prefix
 */
export async function listFiles(prefix: string) {
  const client = getS3Client();
  if (!client) return [];

  const command = new ListObjectsV2Command({
    Bucket: bucketName,
    Prefix: prefix,
  });

  const response = await client.send(command);
  return response.Contents || [];
}

import { supabase } from './supabase';
import { uploadFile, getFileUrl, deleteFile, listFiles, moveFile, bucketName, isR2Configured } from './r2';

const SUPABASE_BUCKET = 'patient_files';

let isBucketReady = false;
let bucketInitPromise: Promise<boolean> | null = null;

/**
 * Garante que o bucket 'patient_files' exista no Supabase Storage,
 * criando-o automaticamente via cliente ou via serverless endpoint com chave service_role se necessário.
 */
export async function ensureSupabaseBucket(): Promise<boolean> {
  if (isBucketReady) return true;
  if (bucketInitPromise) return bucketInitPromise;

  bucketInitPromise = (async () => {
    try {
      // 1. Tentar verificar se o bucket já existe
      const { data: bucket, error: getErr } = await supabase.storage.getBucket(SUPABASE_BUCKET);
      if (!getErr && bucket) {
        isBucketReady = true;
        return true;
      }

      // 2. Tentar criar diretamente via cliente Supabase (caso permitido)
      try {
        const { error: createErr } = await supabase.storage.createBucket(SUPABASE_BUCKET, {
          public: true,
          fileSizeLimit: 52428800
        });
        if (!createErr || createErr.message?.includes('already exists')) {
          isBucketReady = true;
          return true;
        }
      } catch (_) {}

      // 3. Fallback: solicitar criação via endpoint serverless (/api/storage-init)
      if (typeof window !== 'undefined') {
        try {
          const apiRes = await fetch('/api/storage-init', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' }
          });
          if (apiRes.ok) {
            isBucketReady = true;
            return true;
          }
        } catch (_) {}
      }

      return false;
    } catch (err) {
      console.warn('[STORAGE] Erro ao assegurar existência do bucket:', err);
      return false;
    } finally {
      bucketInitPromise = null;
    }
  })();

  return bucketInitPromise;
}

// Inicializa a verificação do bucket em background na inicialização do app
if (typeof window !== 'undefined') {
  setTimeout(() => {
    ensureSupabaseBucket().catch(() => {});
  }, 1000);
}

/**
 * Obtém o ID do usuário de forma segura e resiliente,
 * com fallback para modo mobile, bypass_auth ou clinic-master.
 */
async function getStorageUserId(): Promise<string> {
  try {
    const { data: { session } } = await supabase.auth.getSession();
    if (session?.user?.id) return session.user.id;
  } catch (_) {}

  if (typeof localStorage !== 'undefined' && localStorage.getItem('bypass_auth') === 'true') {
    return 'mock-user-id-dr-agnaldo';
  }

  return 'clinic-master';
}

/**
 * Função utilitária para garantir um formato seguro de nome de pasta
 */
function getSafePatientPath(patientName: string) {
  return (patientName || 'Anonimo').replace(/[^a-zA-Z0-9 _-]/g, '').trim().replace(/\s+/g, '_');
}

/**
 * Função utilitária para garantir um formato seguro de nome de arquivo
 */
function getSafeFilename(filename: string): string {
  if (filename.includes('/')) return filename;
  const safeFilename = filename.normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, '_').replace(/[^a-zA-Z0-9_\-.]/g, '');
  return safeFilename || 'arquivo_sem_nome';
}

/**
 * Faz o upload de um arquivo para o Cloudflare R2 (prioritário para economizar cota),
 * com fallback automático e transparente para o Supabase Storage caso o R2 falhe (CORS, SSL ou endpoint).
 */
export async function uploadPatientFileToSupabase(patientIdentifier: string, file: File | Blob, filename: string, subfolder?: string) {
  const userId = await getStorageUserId();
  const targetFolder = getSafePatientPath(patientIdentifier);
  const subfolderPath = subfolder ? `${subfolder.replace(/^\/|\/$/g, '')}/` : '';

  let filePath: string;
  let finalFilename: string;

  if (filename.startsWith('clinic-master/') || filename.startsWith(`${userId}/`)) {
    filePath = filename;
    finalFilename = filename.split('/').pop() || 'orcamento.json';
  } else if (filename.includes('/')) {
    const parts = filename.split('/').filter(Boolean);
    finalFilename = getSafeFilename(parts[parts.length - 1] || 'orcamento.json');
    if (parts[0] === 'Orcamentos' || parts.includes('Orcamentos')) {
      filePath = `${userId}/${targetFolder}/Orcamentos/${finalFilename}`;
    } else if (parts[0] === targetFolder) {
      filePath = `${userId}/${filename.replace(/^\/+/, '')}`;
    } else {
      filePath = `${userId}/${targetFolder}/${filename.replace(/^\/+/, '')}`;
    }
  } else {
    finalFilename = getSafeFilename(filename);
    filePath = `${userId}/${targetFolder}/${subfolderPath}${finalFilename}`;
  }

  // 1. Prioridade Máxima: Enviar via endpoint serverless (/api/storage-upload)
  // Bypassa restrições de RLS do navegador e sincroniza a galeria automaticamente
  if (typeof window !== 'undefined') {
    try {
      const formData = new FormData();
      formData.append('file', file, finalFilename);
      formData.append('filePath', filePath);
      formData.append('patientId', targetFolder);
      if (subfolder) formData.append('subfolder', subfolder);
      formData.append('filename', finalFilename);

      const relayRes = await fetch('/api/storage-upload', {
        method: 'POST',
        body: formData
      });

      if (relayRes.ok) {
        const json = await relayRes.json();
        console.log(`[STORAGE] Upload salvo com sucesso via /api/storage-upload: ${json.path || filePath}`);
        return { path: json.path || filePath, provider: 'supabase-relay', url: json.url };
      }
    } catch (relayErr: any) {
      console.warn('[STORAGE] Falha no endpoint serverless /api/storage-upload, tentando métodos alternativos:', relayErr?.message || relayErr);
    }
  }

  // 2. Se o endpoint falhar ou em ambiente offline, tentar Cloudflare R2 direto se estiver devidamente configurado
  if (isR2Configured()) {
    try {
      await uploadFile(file, filePath);
      console.log(`[STORAGE] Upload salvo no Cloudflare R2: ${filePath}`);
      return { path: filePath, provider: 'r2' };
    } catch (error: any) {
      console.warn('[STORAGE] Cloudflare R2 indisponível ou bloqueado por CORS/TLS. Acionando fallback do Supabase Storage:', error?.message || error);
    }
  }

  // 3. Fallback: salvar diretamente via cliente do Supabase Storage
  let supaResult = await supabase.storage
    .from(SUPABASE_BUCKET)
    .upload(filePath, file, {
      upsert: true
    });

  // Se o bucket não existir ("Bucket not found"), inicializa o bucket e repete o upload imediatamente!
  if (supaResult.error && (
    supaResult.error.message?.toLowerCase().includes('bucket not found') ||
    (supaResult.error as any).statusCode === '400' ||
    (supaResult.error as any).statusCode === 400 ||
    (supaResult.error as any).status === 400
  )) {
    console.warn(`[STORAGE] Bucket "${SUPABASE_BUCKET}" ausente. Inicializando bucket e repetindo upload...`);
    const initialized = await ensureSupabaseBucket();
    if (initialized) {
      supaResult = await supabase.storage
        .from(SUPABASE_BUCKET)
        .upload(filePath, file, {
          upsert: true
        });
    }
  }

  if (supaResult.error) {
    console.error('[STORAGE] Erro no fallback direto do Supabase Storage:', supaResult.error);
    throw supaResult.error;
  }

  console.log(`[STORAGE] Upload salvo com sucesso no Supabase Storage: ${filePath}`);
  return { path: filePath, provider: 'supabase' };
}

/**
 * Lista todos os arquivos de um paciente (unificando Cloudflare R2 e Supabase Storage)
 */
export async function listPatientFilesFromSupabase(patientId: string, fallbackPatientName?: string, subfolder?: string) {
  const userId = await getStorageUserId();
  const idPath = getSafePatientPath(patientId);
  const fallbackPath = fallbackPatientName ? getSafePatientPath(fallbackPatientName) : '';

  // 1. Prioridade: Buscar via endpoint serverless (/api/storage-list) com privilégios administrativos
  // Resolve RLS, unifica Cloudflare R2 e Supabase Storage com URLs públicas válidas
  if (typeof window !== 'undefined') {
    try {
      const params = new URLSearchParams({
        patientId: idPath,
        ...(fallbackPath ? { patientName: fallbackPath } : {}),
        ...(subfolder ? { subfolder } : {}),
        ...(userId ? { userId } : {}),
        _t: String(Date.now())
      });

      const res = await fetch(`/api/storage-list?${params.toString()}`, { cache: 'no-store' });
      if (res.ok) {
        const json = await res.json();
        if (json.success && Array.isArray(json.files)) {
          // Processar e enriquecer JSONs de propostas se houver
          const enriched = await Promise.all(json.files.map(async (file: any) => {
            if (file.name?.toLowerCase().endsWith('.json') && file.thumbnailLink) {
              try {
                const separator = file.thumbnailLink.includes('?') ? '&' : '?';
                const freshUrl = `${file.thumbnailLink}${separator}_t=${Date.now()}`;
                const r = await fetch(freshUrl, { cache: 'no-store' });
                if (r.ok) {
                  const fileData = await r.json();
                  let total = 0;
                  if (fileData.simulations && fileData.selectedPlanIndex !== undefined && fileData.simulations[fileData.selectedPlanIndex]) {
                    total = fileData.simulations[fileData.selectedPlanIndex].custoTotal;
                  } else {
                    const sections = fileData.sections || [];
                    const procedures = fileData.procedures || [];
                    sections.forEach((sec: any) => {
                      sec.markers?.forEach((marker: any) => {
                        if (marker.procedureInstances && marker.procedureInstances.length > 0) {
                          marker.procedureInstances.forEach((inst: any) => {
                            total += (inst.includeFinancial !== false ? (inst.price || 0) : 0);
                          });
                        } else if (marker.procedures) {
                          marker.procedures.forEach((pid: any) => {
                            const proc = procedures.find((p: any) => p.id === pid);
                            total += (proc ? (proc.price || 0) : 0);
                          });
                        }
                      });
                    });
                  }
                  return {
                    ...file,
                    appProperties: {
                      status: fileData.proposal?.status || 'Aberto',
                      total: total
                    },
                    content: fileData
                  };
                }
              } catch (_) {}
            }
            return file;
          }));
          return enriched;
        }
      }
    } catch (apiErr) {
      console.warn('[STORAGE] Erro ao consultar /api/storage-list, acionando fallback local:', apiErr);
    }
  }

  // 2. Fallback de cliente (quando offline ou mock)
  const basePath = `${userId}/${idPath}`;
  const path = subfolder ? `${basePath}/${subfolder.replace(/^\/|\/$/g, '')}/` : `${basePath}/`;

  const fetchFilesInPath = async (targetPath: string, subPrefix: string = '') => {
    const cleanPath = targetPath.replace(/^\/+|\/+$/g, '');
    const foundMap = new Map<string, any>();

    // 1. Buscar do Supabase Storage
    try {
      const { data: supaFiles } = await supabase.storage
        .from(SUPABASE_BUCKET)
        .list(cleanPath);

      if (Array.isArray(supaFiles)) {
        for (const f of supaFiles) {
          if (f.name && !f.name.endsWith('.emptyFolderPlaceholder') && f.id !== null) {
            const storagePath = `${cleanPath}/${f.name}`;
            foundMap.set(storagePath, {
              name: f.name,
              storagePath: storagePath,
              displayName: subPrefix ? `${subPrefix}/${f.name}` : f.name,
              subfolder: subPrefix || undefined,
              created_at: f.created_at || new Date().toISOString(),
              updated_at: f.updated_at || new Date().toISOString(),
              source: 'supabase'
            });
          }
        }
      }
    } catch (e) {
      console.warn('[STORAGE] Erro ao listar do Supabase Storage:', e);
    }

    // 2. Buscar do Cloudflare R2
    try {
      const prefix = targetPath.endsWith('/') ? targetPath : `${targetPath}/`;
      const r2Files = await listFiles(prefix);

      if (Array.isArray(r2Files)) {
        for (const f of r2Files) {
          if (f.Key && !f.Key.endsWith('.emptyFolderPlaceholder')) {
            const nameParts = f.Key.split('/');
            const name = nameParts[nameParts.length - 1];
            if (!foundMap.has(f.Key)) {
              foundMap.set(f.Key, {
                name: name,
                storagePath: f.Key,
                displayName: subPrefix ? `${subPrefix}/${name}` : name,
                subfolder: subPrefix || undefined,
                created_at: f.LastModified?.toISOString() || new Date().toISOString(),
                updated_at: f.LastModified?.toISOString() || new Date().toISOString(),
                source: 'r2'
              });
            }
          }
        }
      }
    } catch (e) {
      // Ignora erro de rede/CORS do R2 para não travar a listagem do CRM
    }

    return Array.from(foundMap.values());
  };

  let rawFiles = await fetchFilesInPath(path, subfolder || '');

  if (!subfolder) {
    const subfolderFiles = await fetchFilesInPath(`${basePath}/Orcamentos/`, 'Orcamentos');
    rawFiles = [...rawFiles, ...subfolderFiles];
  }

  // --- TELEMETRY FALLBACK ---
  if (fallbackPatientName) {
    const legacyFolder = getSafePatientPath(fallbackPatientName);
    if (legacyFolder !== idPath) {
      const legacyBasePath = `${userId}/${legacyFolder}`;
      const legacyPath = subfolder ? `${legacyBasePath}/${subfolder.replace(/^\/|\/$/g, '')}/` : `${legacyBasePath}/`;

      let fallbackFiles = await fetchFilesInPath(legacyPath, subfolder || '');
      if (!subfolder) {
        const fallbackSub = await fetchFilesInPath(`${legacyBasePath}/Orcamentos/`, 'Orcamentos');
        fallbackFiles = [...fallbackFiles, ...fallbackSub];
      }

      if (fallbackFiles.length > 0) {
        const existingKeys = new Set(rawFiles.map(f => f.storagePath.replace(`${userId}/${idPath}/`, '')));
        const uniqueFallback = fallbackFiles.filter(f => {
          const legacyKey = f.storagePath.replace(`${userId}/${legacyFolder}/`, '');
          return !existingKeys.has(legacyKey);
        });

        rawFiles = [...rawFiles, ...uniqueFallback];
      }
    }
  }

  // --- ROOT UPLOAD FALLBACK ---
  if (rawFiles.length === 0) {
    const rootBasePath = `${idPath}`;
    const rootPath = subfolder ? `${rootBasePath}/${subfolder.replace(/^\/|\/$/g, '')}/` : `${rootBasePath}/`;
    let rootFiles = await fetchFilesInPath(rootPath, subfolder || '');
    if (!subfolder) {
      const rootSub = await fetchFilesInPath(`${rootBasePath}/Orcamentos/`, 'Orcamentos');
      rootFiles = [...rootFiles, ...rootSub];
    }
    if (rootFiles.length > 0) { rawFiles = rootFiles; }
  }

  if (rawFiles.length > 0) {
    const fileObjects = await Promise.all(rawFiles.map(async (f) => {
      let thumbnailLink: string | null = null;
      try {
        if (f.source === 'supabase') {
          const { data } = await supabase.storage
            .from(SUPABASE_BUCKET)
            .createSignedUrl(f.storagePath, 3600);
          thumbnailLink = data?.signedUrl || null;
        } else {
          thumbnailLink = await getFileUrl(f.storagePath, 3600);
        }
      } catch (e) {
        try {
          thumbnailLink = await getFileUrl(f.storagePath, 3600);
        } catch (_) {}
      }

      return {
        id: f.storagePath,
        name: f.displayName,
        thumbnailLink,
        createdTime: f.created_at,
        modifiedTime: f.updated_at,
        mimeType: f.name.endsWith('.pdf') ? 'application/pdf' : f.name.endsWith('.json') ? 'application/json' : 'application/octet-stream',
        subfolder: f.subfolder
      };
    }));

    const enrichedFiles = await Promise.all(fileObjects.map(async (file) => {
      if (file.name.toLowerCase().endsWith('.json') && file.thumbnailLink) {
        try {
          const separator = file.thumbnailLink.includes('?') ? '&' : '?';
          const r = await fetch(`${file.thumbnailLink}${separator}_t=${Date.now()}`, { cache: 'no-store' });
          if (r.ok) {
            const fileData = await r.json();
            let total = 0;
            if (fileData.simulations && fileData.selectedPlanIndex !== undefined && fileData.simulations[fileData.selectedPlanIndex]) {
              total = fileData.simulations[fileData.selectedPlanIndex].custoTotal;
            } else {
              const sections = fileData.sections || [];
              const procedures = fileData.procedures || [];
              sections.forEach((sec: any) => {
                sec.markers?.forEach((marker: any) => {
                  if (marker.procedureInstances && marker.procedureInstances.length > 0) {
                    marker.procedureInstances.forEach((inst: any) => {
                      total += (inst.includeFinancial !== false ? (inst.price || 0) : 0);
                    });
                  } else if (marker.procedures) {
                    marker.procedures.forEach((pid: any) => {
                      const proc = procedures.find((p: any) => p.id === pid);
                      total += (proc ? (proc.price || 0) : 0);
                    });
                  }
                });
              });
            }

            return {
              ...file,
              appProperties: {
                status: fileData.proposal?.status || 'Aberto',
                total: total
              },
              content: fileData
            };
          }
        } catch (e) {
          console.warn("Failed to fetch/parse JSON content for", file.name, e);
        }
      }
      return file;
    }));

    return enrichedFiles;
  }

  return [];
}

/**
 * Deleta um arquivo específico do paciente (no Supabase e no Cloudflare R2)
 */
export async function deletePatientFileFromSupabase(patientIdentifier: string, filename: string, subfolder?: string) {
  const userId = await getStorageUserId();
  const targetFolder = getSafePatientPath(patientIdentifier);
  const subfolderPath = subfolder ? `${subfolder.replace(/^\/|\/$/g, '')}/` : '';
  const finalFilename = getSafeFilename(filename);

  let filePath: string;
  if (filename.startsWith(`${userId}/`) || filename.startsWith('clinic-master/')) {
    filePath = filename;
  } else if (filename.includes('/')) {
    filePath = `${userId}/${targetFolder}/${filename.replace(/^\/+/, '')}`;
  } else {
    filePath = `${userId}/${targetFolder}/${subfolderPath}${finalFilename}`;
  }

  // 1. Tentar endpoint serverless (/api/storage-delete) com permissão administrativa
  if (typeof window !== 'undefined') {
    try {
      const res = await fetch('/api/storage-delete', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ path: filePath, patientId: targetFolder, filename: finalFilename, subfolder })
      });
      if (res.ok) return;
    } catch (_) {}
  }

  // 2. Deletar do Supabase Storage direto
  try {
    await supabase.storage.from(SUPABASE_BUCKET).remove([filePath]);
    if (!subfolder && !filename.includes('/')) {
      const fallbackPath = `${userId}/${targetFolder}/Orcamentos/${finalFilename}`;
      await supabase.storage.from(SUPABASE_BUCKET).remove([fallbackPath]);
    }
  } catch (e) {}

  // 3. Deletar do Cloudflare R2
  try {
    await deleteFile(filePath);
  } catch (error) {
    if (!subfolder && !filename.includes('/')) {
      const fallbackPath = `${userId}/${targetFolder}/Orcamentos/${finalFilename}`;
      try {
        await deleteFile(fallbackPath);
        return;
      } catch (fallbackError) {}
    }
  }
}

/**
 * Baixa um arquivo e converte para Data URL (Supabase primeiro, R2 fallback)
 */
export async function downloadFileAsDataUrlFromSupabase(filePath: string): Promise<string> {
  // 1. Tentar Supabase Storage
  try {
    const { data, error } = await supabase.storage
      .from(SUPABASE_BUCKET)
      .download(filePath);

    if (!error && data) {
      return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = reject;
        reader.readAsDataURL(data);
      });
    }
  } catch (e) {}

  // 2. Tentar Cloudflare R2
  const url = await getFileUrl(filePath, 60);
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error('Erro ao baixar arquivo do armazenamento em nuvem');
  }
  const blob = await response.blob();

  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = reject;
    reader.readAsDataURL(blob);
  });
}

/**
 * Obtém link assinado ou público para visualização (Supabase se salvo lá, R2 caso contrário)
 */
export async function getPatientFileUrlFromSupabase(patientIdentifier: string, filename: string, expiresIn: number = 3600, subfolder?: string) {
  const userId = await getStorageUserId();
  const targetFolder = getSafePatientPath(patientIdentifier);
  const subfolderPath = subfolder ? `${subfolder.replace(/^\/|\/$/g, '')}/` : '';
  const finalFilename = getSafeFilename(filename);

  const filePath = (filename.startsWith(`${userId}/`) || filename.startsWith('clinic-master/'))
    ? filename
    : (filename.includes('/')
      ? `${userId}/${targetFolder}/${filename.replace(/^\/+/, '')}`
      : `${userId}/${targetFolder}/${subfolderPath}${finalFilename}`);

  // 1. Tentar URL do Supabase Storage
  try {
    const { data: supaUrl, error: supaErr } = await supabase.storage
      .from(SUPABASE_BUCKET)
      .createSignedUrl(filePath, expiresIn);

    if (!supaErr && supaUrl?.signedUrl) {
      const sep = supaUrl.signedUrl.includes('?') ? '&' : '?';
      return `${supaUrl.signedUrl}${sep}_t=${Date.now()}`;
    }

    // Fallback: tentar URL pública direta do bucket
    const { data: publicData } = supabase.storage
      .from(SUPABASE_BUCKET)
      .getPublicUrl(filePath);

    if (publicData?.publicUrl) {
      const sep = publicData.publicUrl.includes('?') ? '&' : '?';
      return `${publicData.publicUrl}${sep}_t=${Date.now()}`;
    }
  } catch (e) {}

  // 2. Tentar URL do Cloudflare R2
  try {
    return await getFileUrl(filePath, expiresIn);
  } catch (error: any) {
    console.warn('Aviso ao obter URL do R2:', error.message || error);
    return null;
  }
}

/**
 * Renomeia ou move arquivo (no Supabase e no Cloudflare R2)
 */
export async function renamePatientFileInSupabase(patientIdentifier: string, oldFilename: string, newFilename: string, subfolder?: string) {
  const userId = await getStorageUserId();
  const targetFolder = getSafePatientPath(patientIdentifier);
  const subfolderPath = subfolder ? `${subfolder.replace(/^\/|\/$/g, '')}/` : '';
  const safeNewBaseName = getSafeFilename(newFilename.split('/').pop() || newFilename);

  let oldPath: string;
  let newPath: string;

  if (oldFilename.startsWith(`${userId}/`)) {
    oldPath = oldFilename;
    const parentDir = oldPath.substring(0, oldPath.lastIndexOf('/'));
    newPath = `${parentDir}/${safeNewBaseName}`;
  } else if (oldFilename.includes('/')) {
    const cleanOld = oldFilename.replace(/^\/+/, '');
    oldPath = `${userId}/${targetFolder}/${cleanOld}`;
    const parentDir = oldPath.substring(0, oldPath.lastIndexOf('/'));
    newPath = `${parentDir}/${safeNewBaseName}`;
  } else {
    const finalOldFilename = getSafeFilename(oldFilename);
    oldPath = `${userId}/${targetFolder}/${subfolderPath}${finalOldFilename}`;
    newPath = `${userId}/${targetFolder}/${subfolderPath}${safeNewBaseName}`;
  }

  if (oldPath === newPath) return;

  // Supabase Storage move
  try {
    const { error } = await supabase.storage.from(SUPABASE_BUCKET).move(oldPath, newPath);
    if (error && !oldFilename.includes('Orcamentos') && !subfolder) {
      const fallbackOld = `${userId}/${targetFolder}/Orcamentos/${getSafeFilename(oldFilename)}`;
      const fallbackNew = `${userId}/${targetFolder}/Orcamentos/${safeNewBaseName}`;
      await supabase.storage.from(SUPABASE_BUCKET).move(fallbackOld, fallbackNew);
    }
  } catch (e) {}

  // Cloudflare R2 move
  try {
    await moveFile(oldPath, newPath);
  } catch (error) {
    if (!oldFilename.includes('Orcamentos') && !subfolder) {
      const fallbackOld = `${userId}/${targetFolder}/Orcamentos/${getSafeFilename(oldFilename)}`;
      const fallbackNew = `${userId}/${targetFolder}/Orcamentos/${safeNewBaseName}`;
      try {
        await moveFile(fallbackOld, fallbackNew);
        return;
      } catch (fallbackError) {}
    }
  }
}

