import { uploadPatientFileToSupabase, ensureSupabaseBucket } from '../lib/storage';

export type BudgetSyncStatus = 
  | 'idle'
  | 'saving_local'
  | 'saved_local'
  | 'syncing_cloud'
  | 'synced_cloud'
  | 'offline'
  | 'error';

export interface BudgetDraftState {
  patientId: string;
  patientName: string;
  fileId: string;
  timestamp: number;
  data: {
    proposal: any;
    sections: any[];
    procedures: any[];
    simulations: any[];
    selectedPlanIndices: number[];
    customNetDesired?: number | null;
    boxEntradas?: number[];
    boxMethods?: string[];
    boxInstallments?: number[];
  };
}

export interface OfflineBudgetItem {
  id: string; // ex: 'orcamento_ativo.json' ou 'orcamento_v1.json'
  patientId: string;
  patientName: string;
  data: string; // JSON serializado
  timestamp: number;
}

const OFFLINE_QUEUE_KEY = 'ag_offline_budgets';
const DRAFT_PREFIX = 'ag_budget_draft_';

// IndexedDB para armazenamento robusto de orçamentos completos (sem limites de quota de 5MB)
const IDB_NAME = 'agnaldo_dental_offline_v1';
const IDB_STORE = 'offline_budgets';

function openIDB(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    if (typeof indexedDB === 'undefined') {
      return reject(new Error('IndexedDB não suportado'));
    }
    const req = indexedDB.open(IDB_NAME, 1);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(IDB_STORE)) {
        db.createObjectStore(IDB_STORE, { keyPath: 'storageKey' });
      }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

async function saveToIndexedDB(storageKey: string, item: OfflineBudgetItem): Promise<void> {
  try {
    const db = await openIDB();
    const tx = db.transaction(IDB_STORE, 'readwrite');
    tx.objectStore(IDB_STORE).put({ ...item, storageKey });
    return new Promise((resolve) => {
      tx.oncomplete = () => resolve();
      tx.onerror = () => resolve(); // fail silently
    });
  } catch (err) {
    console.warn('[budgetSyncService] Aviso ao salvar no IndexedDB:', err);
  }
}

async function getFromIndexedDB(storageKey: string): Promise<OfflineBudgetItem | null> {
  try {
    const db = await openIDB();
    const tx = db.transaction(IDB_STORE, 'readonly');
    const req = tx.objectStore(IDB_STORE).get(storageKey);
    return new Promise((resolve) => {
      req.onsuccess = () => resolve(req.result || null);
      req.onerror = () => resolve(null);
    });
  } catch {
    return null;
  }
}

async function deleteFromIndexedDB(storageKey: string): Promise<void> {
  try {
    const db = await openIDB();
    const tx = db.transaction(IDB_STORE, 'readwrite');
    tx.objectStore(IDB_STORE).delete(storageKey);
  } catch {}
}

/**
 * Sanitiza o estado para o LocalStorage:
 * Remove fotos base64 gigantes (>50KB) das seções do odontograma para que o JSON
 * ocupe apenas ~15KB em vez de 5MB+, impedindo o erro 'exceeded the quota'.
 */
export function sanitizeStateForLocalStorage(state: any): any {
  if (!state || typeof state !== 'object') return state;
  try {
    const clone = JSON.parse(JSON.stringify(state));
    if (Array.isArray(clone.sections)) {
      clone.sections = clone.sections.map((sec: any) => {
        if (sec && sec.image && typeof sec.image === 'string' && sec.image.length > 50000) {
          return {
            ...sec,
            image: sec.image.startsWith('data:') ? null : sec.image
          };
        }
        return sec;
      });
    }
    return clone;
  } catch {
    return state;
  }
}

/**
 * Grava de forma segura no LocalStorage com proteção anti-estouro de cota
 */
function safeSetLocalStorage(key: string, value: string): boolean {
  if (typeof window === 'undefined') return false;
  try {
    localStorage.setItem(key, value);
    return true;
  } catch (err: any) {
    if (
      err &&
      (err.name === 'QuotaExceededError' ||
        err.name === 'NS_ERROR_DOM_QUOTA_REACHED' ||
        err.code === 22 ||
        err.code === 1014 ||
        err.number === -2147024882)
    ) {
      console.warn(`[budgetSyncService] ⚠️ Quota do LocalStorage excedida para ${key}. Executando limpeza automática de contingência...`);
      try {
        // Reduz a fila ag_offline_budgets mantendo apenas o último registro sanitizado
        const raw = localStorage.getItem(OFFLINE_QUEUE_KEY);
        if (raw) {
          const queue = JSON.parse(raw);
          if (Array.isArray(queue)) {
            const trimmed = queue.slice(-1).map((item: any) => {
              try {
                const parsed = JSON.parse(item.data);
                return { ...item, data: JSON.stringify(sanitizeStateForLocalStorage(parsed)) };
              } catch {
                return item;
              }
            });
            localStorage.setItem(OFFLINE_QUEUE_KEY, JSON.stringify(trimmed));
          }
        }
      } catch {
        localStorage.removeItem(OFFLINE_QUEUE_KEY);
      }

      // Tenta gravar novamente após a limpeza
      try {
        localStorage.setItem(key, value);
        return true;
      } catch {
        console.warn(`[budgetSyncService] LocalStorage ainda indisponível. Dados salvos com segurança no IndexedDB.`);
        return false;
      }
    }
    return false;
  }
}

/**
 * Limpa qualquer resquício de dados inflados em ag_offline_budgets na inicialização
 */
function cleanupBloatedStorageOnStart(): void {
  if (typeof window === 'undefined') return;
  try {
    const raw = localStorage.getItem(OFFLINE_QUEUE_KEY);
    if (!raw) return;

    // Se o valor armazenado passar de 250KB, sanitiza imediatamente
    if (raw.length > 250000) {
      console.log('[budgetSyncService] 🧹 Otimizando ag_offline_budgets no LocalStorage para liberar cota...');
      const queue = JSON.parse(raw);
      if (Array.isArray(queue)) {
        const sanitized = queue.slice(-3).map((item: any) => {
          try {
            const parsed = JSON.parse(item.data);
            return {
              ...item,
              data: JSON.stringify(sanitizeStateForLocalStorage(parsed))
            };
          } catch {
            return item;
          }
        });
        safeSetLocalStorage(OFFLINE_QUEUE_KEY, JSON.stringify(sanitized));
      }
    }
  } catch (e) {
    try {
      localStorage.removeItem(OFFLINE_QUEUE_KEY);
    } catch {}
  }
}

cleanupBloatedStorageOnStart();

/**
 * Retorna a fila de orçamentos pendentes de sincronização
 */
export function getOfflineQueue(): OfflineBudgetItem[] {
  if (typeof window === 'undefined') return [];
  try {
    const raw = localStorage.getItem(OFFLINE_QUEUE_KEY);
    return raw ? JSON.parse(raw) : [];
  } catch (err) {
    console.warn('[budgetSyncService] Erro ao ler fila offline de orçamentos:', err);
    return [];
  }
}

/**
 * Salva a fila offline no LocalStorage de forma segura
 */
export function saveOfflineQueue(queue: OfflineBudgetItem[]): void {
  if (typeof window === 'undefined') return;
  try {
    safeSetLocalStorage(OFFLINE_QUEUE_KEY, JSON.stringify(queue));
    window.dispatchEvent(new Event('local-storage'));
    window.dispatchEvent(new Event('storage'));
  } catch (err) {
    console.warn('[budgetSyncService] Erro ao gravar fila offline de orçamentos:', err);
  }
}

/**
 * Recupera o último rascunho salvo localmente para determinado paciente
 */
export function getBudgetDraft(patientId: string): BudgetDraftState | null {
  if (typeof window === 'undefined' || !patientId) return null;
  try {
    const raw = localStorage.getItem(`${DRAFT_PREFIX}${patientId}`);
    return raw ? JSON.parse(raw) : null;
  } catch (err) {
    console.warn(`[budgetSyncService] Erro ao recuperar rascunho de ${patientId}:`, err);
    return null;
  }
}

/**
 * Limpa o rascunho salvo localmente de um paciente
 */
export function clearBudgetDraft(patientId: string): void {
  if (typeof window === 'undefined' || !patientId) return;
  try {
    localStorage.removeItem(`${DRAFT_PREFIX}${patientId}`);
  } catch (err) {
    console.warn(`[budgetSyncService] Erro ao limpar rascunho de ${patientId}:`, err);
  }
}

/**
 * Salva o orçamento imediatamente no armazenamento local (0s de delay)
 * usando IndexedDB (para dados completos) e LocalStorage sanitizado (anti-quota).
 */
export function saveBudgetLocally(
  patientId: string,
  patientName: string,
  filename: string,
  state: BudgetDraftState['data']
): { jsonStr: string; timestamp: number } {
  const timestamp = Date.now();
  const cleanFilename = filename.includes('/') ? filename.split('/').pop()! : filename;
  const storageKey = `${patientId}::${cleanFilename}`;

  // 1. JSON completo (para upload em nuvem e IndexedDB)
  const fullJsonStr = JSON.stringify(state);

  // 2. JSON sanitizado leve (sem fotos base64 gigantes, ~15KB) para o LocalStorage
  const sanitizedState = sanitizeStateForLocalStorage(state);
  const sanitizedJsonStr = JSON.stringify(sanitizedState);

  const draft: BudgetDraftState = {
    patientId,
    patientName,
    fileId: cleanFilename,
    timestamp,
    data: sanitizedState
  };

  // 3. Salva no IndexedDB (capacidade em gigabytes, imune a QuotaExceededError)
  const fullQueueItem: OfflineBudgetItem = {
    id: cleanFilename,
    patientId,
    patientName,
    data: fullJsonStr,
    timestamp
  };
  saveToIndexedDB(storageKey, fullQueueItem).catch(console.warn);

  // 4. Salva rascunho individual leve no LocalStorage
  safeSetLocalStorage(`${DRAFT_PREFIX}${patientId}`, JSON.stringify(draft));

  // 5. Registra na fila persistente ag_offline_budgets (versão leve sanitizada)
  const queue = getOfflineQueue();
  const existingIdx = queue.findIndex(q => q.id === cleanFilename && q.patientId === patientId);
  const queueItemLight: OfflineBudgetItem = {
    id: cleanFilename,
    patientId,
    patientName,
    data: sanitizedJsonStr,
    timestamp
  };

  if (existingIdx > -1) {
    queue[existingIdx] = queueItemLight;
  } else {
    queue.push(queueItemLight);
  }
  saveOfflineQueue(queue);

  // 6. Notifica a aplicação do salvamento local imediato
  if (typeof window !== 'undefined') {
    window.dispatchEvent(new CustomEvent('ag-budget-saved-local', {
      detail: { patientId, filename: cleanFilename, timestamp }
    }));
  }

  return { jsonStr: fullJsonStr, timestamp };
}

/**
 * Envia o orçamento diretamente para a nuvem (Nuvem (R2))
 */
export async function uploadBudgetToCloud(
  patientId: string,
  filename: string,
  jsonStr: string
): Promise<{ success: boolean; error?: any }> {
  if (typeof navigator !== 'undefined' && !navigator.onLine) {
    return { success: false, error: new Error('Dispositivo sem conexão de internet (offline)') };
  }

  const cleanFilename = filename.includes('/') ? filename.split('/').pop()! : filename;
  const storageKey = `${patientId}::${cleanFilename}`;

  try {
    // Tenta obter o JSON completo do IndexedDB caso o fornecido tenha sido sanitizado
    const idbItem = await getFromIndexedDB(storageKey);
    const finalPayload = idbItem?.data || jsonStr;

    const fileBlob = new Blob([finalPayload], { type: 'application/json' });
    await uploadPatientFileToSupabase(patientId, fileBlob, cleanFilename, 'Orcamentos');
    
    // Remove este item da fila offline e do IndexedDB
    deleteFromIndexedDB(storageKey).catch(() => {});
    const queue = getOfflineQueue();
    const updatedQueue = queue.filter(
      q => !(q.id === cleanFilename && q.patientId === patientId)
    );
    saveOfflineQueue(updatedQueue);

    // Dispara evento de sucesso de sincronização com o Supabase
    if (typeof window !== 'undefined') {
      window.dispatchEvent(new CustomEvent('ag-budget-synced', {
        detail: { patientId, filename: cleanFilename, timestamp: Date.now() }
      }));
    }

    return { success: true };
  } catch (err: any) {
    console.warn(`[budgetSyncService] Falha ao enviar ${cleanFilename} para o Supabase:`, err);
    return { success: false, error: err };
  }
}

/**
 * Processa e envia todos os orçamentos pendentes na fila offline
 */
let isSyncingQueue = false;
const lastFailedLogTime = new Map<string, number>();

export async function syncAllPendingBudgets(): Promise<{ synced: number; failed: number }> {
  if (isSyncingQueue) return { synced: 0, failed: 0 };
  if (typeof navigator !== 'undefined' && !navigator.onLine) return { synced: 0, failed: 0 };

  isSyncingQueue = true;
  const queue = getOfflineQueue();
  if (queue.length === 0) {
    isSyncingQueue = false;
    return { synced: 0, failed: 0 };
  }

  let syncedCount = 0;
  let failedCount = 0;
  const remaining: OfflineBudgetItem[] = [];
  const now = Date.now();

  for (const item of queue) {
    try {
      const cleanFilename = item.id.includes('/') ? item.id.split('/').pop()! : item.id;
      const storageKey = `${item.patientId || item.patientName}::${cleanFilename}`;
      
      const idbItem = await getFromIndexedDB(storageKey);
      const payload = idbItem?.data || item.data;

      const fileBlob = new Blob([payload], { type: 'application/json' });
      await uploadPatientFileToSupabase(item.patientId || item.patientName, fileBlob, cleanFilename, 'Orcamentos');
      
      deleteFromIndexedDB(storageKey).catch(() => {});
      lastFailedLogTime.delete(item.id);
      syncedCount++;

      if (typeof window !== 'undefined') {
        window.dispatchEvent(new CustomEvent('ag-budget-synced', {
          detail: { patientId: item.patientId, filename: cleanFilename, timestamp: Date.now() }
        }));
      }
    } catch (err: any) {
      if (err?.message?.includes('Bucket not found') || (err as any)?.statusCode === '400') {
        ensureSupabaseBucket().catch(() => {});
      }

      const lastLogged = lastFailedLogTime.get(item.id) || 0;
      if (now - lastLogged > 30000) {
        console.warn(`[budgetSyncService] ⏳ Mantendo ${item.id} na fila offline:`, err?.message || err);
        lastFailedLogTime.set(item.id, now);
      }
      failedCount++;
      remaining.push(item);
    }
  }

  saveOfflineQueue(remaining);
  isSyncingQueue = false;
  return { synced: syncedCount, failed: failedCount };
}

// Inicializa o ouvinte de reconexão de internet no navegador
if (typeof window !== 'undefined') {
  window.addEventListener('online', () => {
    console.log('[budgetSyncService] 🌐 Conexão restaurada! Sincronizando orçamentos pendentes...');
    syncAllPendingBudgets();
  });
}

import React, { useState } from 'react';
import { usePlanning3D } from '../hooks/usePlanning3D';
import { Sparkles, Send, Brain, RefreshCw, AlertCircle } from 'lucide-react';

export function AIAssistancePanel() {
  const { updateToothCondition, updateToothSurfaceCondition, addProcedure } = usePlanning3D();

  const [notes, setNotes] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [successCount, setSuccessCount] = useState<number | null>(null);

  const PRESETS = [
    "Paciente tem cárie oclusal no 16 e fratura na distal do dente 23",
    "Precisa de implante no dente 46 por ausência coronária e tratamento de canal no 11",
    "Realizar faceta de porcelana no dente 21 e restauração vestibular no dente 12",
  ];

  const handleProcessIA = async () => {
    if (!notes.trim()) return;

    setLoading(true);
    setError(null);
    setSuccessCount(null);

    try {
      const response = await fetch('/api/ai/suggest-plan', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ notes }),
      });

      if (!response.ok) {
        throw new Error('Falha ao processar sugestão clínica da IA.');
      }

      const data = await response.json();

      if (data && data.teeth && Array.isArray(data.teeth)) {
        data.teeth.forEach((t: any) => {
          // 1. Atualiza condição básica do dente
          updateToothCondition(t.tooth, t.condition, t.notes || '');

          // 2. Atualiza superfícies específicas, se informadas
          if (t.surfaces && t.surfaces.length > 0) {
            t.surfaces.forEach((s: any) => {
              updateToothSurfaceCondition(t.tooth, s, t.condition);
            });
          }

          // 3. Adiciona os procedimentos sugeridos
          if (t.procedures && Array.isArray(t.procedures)) {
            t.procedures.forEach((p: any) => {
              addProcedure(t.tooth, 'ai-' + Math.random().toString(36).substr(2, 9), p.price || 0, p.name);
            });
          }
        });

        setSuccessCount(data.teeth.length);
        setNotes('');
      } else {
        throw new Error('Nenhum dente ou tratamento identificado no texto.');
      }
    } catch (err: any) {
      console.error(err);
      setError(err.message || 'Erro de rede ou faturamento excedido.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex flex-col gap-4 text-white">
      {/* Cabeçalho */}
      <div className="flex items-center gap-2 text-sky-400 font-bold uppercase tracking-wider text-xs border-b border-slate-800 pb-3">
        <Brain className="w-4 h-4" />
        <span>Assistente de IA Integrado</span>
      </div>

      {/* Caixa de Texto */}
      <div className="flex flex-col gap-2">
        <label className="text-[10px] text-slate-400 font-bold uppercase block">Relato Clínico em Texto Livre:</label>
        <textarea
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          placeholder="Descreva as patologias, dentes e tratamentos sugeridos..."
          className="w-full bg-slate-900 border border-slate-800 rounded-xl p-3 text-xs text-slate-200 placeholder-slate-600 focus:outline-none focus:ring-1 focus:ring-sky-500"
          rows={4}
          disabled={loading}
        />
      </div>

      {/* Sugestões/Presets rápidos */}
      <div>
        <p className="text-[9px] text-slate-500 font-bold uppercase mb-2">Exemplos de Sugestões:</p>
        <div className="flex flex-col gap-1.5">
          {PRESETS.map((preset, idx) => (
            <button
              key={idx}
              onClick={() => setNotes(preset)}
              disabled={loading}
              className="w-full text-left p-2 bg-slate-900/60 hover:bg-slate-900 border border-slate-800/80 hover:border-slate-700 text-slate-400 hover:text-slate-300 text-[10px] rounded-lg transition-colors truncate"
            >
              "{preset}"
            </button>
          ))}
        </div>
      </div>

      {/* Alertas / Mensagens de Status */}
      {error && (
        <div className="p-3 bg-red-950/40 border border-red-900 text-red-400 text-xs rounded-xl flex items-start gap-2">
          <AlertCircle className="w-4 h-4 shrink-0 mt-0.5" />
          <span>{error}</span>
        </div>
      )}

      {successCount !== null && (
        <div className="p-3 bg-emerald-950/40 border border-emerald-900 text-emerald-400 text-xs rounded-xl flex items-start gap-2">
          <Sparkles className="w-4 h-4 shrink-0 mt-0.5" />
          <span>Sucesso! O odontograma foi atualizado com {successCount} diagnóstico(s) pela IA.</span>
        </div>
      )}

      {/* Botão de Envio */}
      <button
        onClick={handleProcessIA}
        disabled={loading || !notes.trim()}
        className="w-full py-3 bg-sky-600 border border-sky-500 hover:bg-sky-500 disabled:bg-slate-800 disabled:border-slate-800 disabled:text-slate-500 disabled:cursor-not-allowed text-white font-bold text-xs uppercase tracking-wider rounded-xl shadow-lg flex items-center justify-center gap-2 transition-all"
      >
        {loading ? (
          <>
            <RefreshCw className="w-4 h-4 animate-spin" />
            <span>Processando Plano...</span>
          </>
        ) : (
          <>
            <Sparkles className="w-4 h-4" />
            <span>Analisar Prontuário com IA</span>
          </>
        )}
      </button>
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import { usePlanning3D } from '../hooks/usePlanning3D';
import { calculateBudget } from '../services/budgetEngine';
import { usePatientContext } from '../../context/PatientContext';
import { saveBudgetLocally, uploadBudgetToCloud } from '../../services/budgetSyncService';
import { jsPDF } from 'jspdf';
import { Coins, Calendar, Printer, Trash2, PlusCircle, Pencil, Check, X, ChevronDown } from 'lucide-react';

export function BudgetPanel3D() {
  const { procedures, teeth, getPlanTotal, removeProcedure, updateProcedure, addProcedure, globalProcedures } = usePlanning3D();
  const { activeProposal, selectedPatient } = usePatientContext();

  const [paymentMethod, setPaymentMethod] = useState<'PIX' | 'CREDIT_CARD' | 'CASH'>('PIX');
  const [discountType, setDiscountType] = useState<'PERCENT' | 'FIXED'>('PERCENT');
  const [discountValue, setDiscountValue] = useState<number>(5);
  const [installmentsCount, setInstallmentsCount] = useState<number>(1);
  const [generatingPdf, setGeneratingPdf] = useState(false);

  // Helper para determinar limite de parcelas
  const getMaxInstallments = (method: 'PIX' | 'CREDIT_CARD' | 'CASH') => {
    if (method === 'CREDIT_CARD') return 12;
    return 1;
  };

  // Handler para troca de meio de pagamento
  const handlePaymentMethodChange = (method: 'PIX' | 'CREDIT_CARD' | 'CASH') => {
    setPaymentMethod(method);
    const max = getMaxInstallments(method);
    if (installmentsCount > max || method === 'PIX' || method === 'CASH') {
      setInstallmentsCount(max);
    }
  };

  // State para edição inline de procedimentos
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');
  const [editPrice, setEditPrice] = useState('');

  // State para adicionar procedimento
  const [showAddDropdown, setShowAddDropdown] = useState(false);
  const [addSearch, setAddSearch] = useState('');

  const prices = procedures.map((p) => p.price);
  
  const budget = calculateBudget(
    prices,
    discountType,
    discountValue,
    paymentMethod === 'CREDIT_CARD' ? installmentsCount : 1,
    paymentMethod
  );

  // Auto-Save Local Imediato (0s) + Upload com Debounce na Nuvem (Opções A, B e A)
  const [syncStatus3D, setSyncStatus3D] = useState<'idle' | 'saved_local' | 'syncing' | 'synced'>('idle');
  const timer3DRef = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => {
    if (!selectedPatient?.id || procedures.length === 0) return;

    const patientId = selectedPatient.id;
    const patientName = selectedPatient.name || activeProposal?.patientName || 'Paciente';
    const filename = 'orcamento_3d_ativo.json';

    const statePayload = {
      procedures,
      teeth,
      budget,
      paymentMethod,
      discountType,
      discountValue,
      installmentsCount,
      timestamp: Date.now()
    };

    // 1. Salvamento local imediato (0s)
    const { jsonStr } = saveBudgetLocally(patientId, patientName, filename, statePayload as any);
    setSyncStatus3D('saved_local');

    // 2. Debounce na nuvem (2.5s)
    if (timer3DRef.current) clearTimeout(timer3DRef.current);
    timer3DRef.current = setTimeout(async () => {
      if (typeof navigator !== 'undefined' && !navigator.onLine) return;
      setSyncStatus3D('syncing');
      const res = await uploadBudgetToCloud(patientId, filename, jsonStr);
      if (res.success) setSyncStatus3D('synced');
    }, 2500);

    return () => {
      if (timer3DRef.current) clearTimeout(timer3DRef.current);
    };
  }, [procedures, paymentMethod, discountType, discountValue, installmentsCount, selectedPatient?.id]);

  const startEditing = (proc: { id: string; procedure: string; price: number }) => {
    setEditingId(proc.id);
    setEditName(proc.procedure);
    setEditPrice(proc.price.toFixed(2));
  };

  const saveEdit = () => {
    if (!editingId) return;
    const newPrice = parseFloat(editPrice.replace(',', '.'));
    updateProcedure(editingId, {
      name: editName.trim() || undefined,
      price: isNaN(newPrice) ? undefined : Math.max(0, newPrice),
    });
    setEditingId(null);
  };

  const cancelEdit = () => {
    setEditingId(null);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') saveEdit();
    if (e.key === 'Escape') cancelEdit();
  };

  const filteredGlobalProcedures = globalProcedures.filter((p: any) =>
    p.name.toLowerCase().includes(addSearch.toLowerCase())
  );

  const handleAddProcedure = (proc: any) => {
    // Adiciona ao primeiro dente diagnosticado ou cria um genérico
    const firstToothKey = Object.keys(teeth)[0];
    const toothNumber = firstToothKey ? parseInt(firstToothKey) : 11;
    addProcedure(toothNumber, proc.id, proc.price, proc.name);
    setShowAddDropdown(false);
    setAddSearch('');
  };

  const handleExportPdf = () => {
    setGeneratingPdf(true);
    try {
      const doc = new jsPDF({
        orientation: 'portrait',
        unit: 'mm',
        format: 'a4',
      });

      // 1. Cabeçalho Clínico (Papel Timbrado Premium)
      doc.setFillColor(139, 0, 0);
      doc.rect(0, 0, 210, 30, 'F');

      doc.setTextColor(255, 255, 255);
      doc.setFont('Helvetica', 'bold');
      doc.setFontSize(16);
      doc.text('DR. AGNALDO FERREIRA', 15, 12);
      
      doc.setFont('Helvetica', 'normal');
      doc.setFontSize(8);
      doc.setTextColor(240, 240, 240);
      doc.text('ODONTOLOGIA RESTAURADORA • CRO-SP 123456', 15, 18);
      doc.text('Email: contato@dragnaldo.com.br • WhatsApp: (11) 99999-9999', 15, 23);

      // 2. Dados do Paciente e do Orçamento
      doc.setTextColor(30, 30, 30);
      doc.setFont('Helvetica', 'bold');
      doc.setFontSize(11);
      doc.text('PROPOSTA COMERCIAL DE TRATAMENTO 3D', 15, 42);

      doc.setFont('Helvetica', 'normal');
      doc.setFontSize(9);
      doc.text(`Paciente: ${selectedPatient?.name || activeProposal.patientName || 'Paciente de Teste'}`, 15, 49);
      doc.text(`Data de Emissão: ${new Date().toLocaleDateString('pt-BR')}`, 15, 54);
      doc.text(`Status do Plano: ${activeProposal.status || 'Em Planejamento'}`, 15, 59);

      // Linha separadora
      doc.setDrawColor(230, 222, 201);
      doc.setLineWidth(0.5);
      doc.line(15, 64, 195, 64);

      // 3. Captura do Canvas 3D
      const canvas = document.querySelector('canvas');
      if (canvas) {
        try {
          const imgData = canvas.toDataURL('image/png');
          doc.setFont('Helvetica', 'bold');
          doc.setFontSize(9);
          doc.text('Mapa Anatômico Digital da Arcada:', 15, 71);
          
          doc.addImage(imgData, 'PNG', 15, 74, 90, 60);
          
          doc.setFont('Helvetica', 'normal');
          doc.setFontSize(8);
          doc.setTextColor(100, 100, 100);
          doc.text('Notas de Planejamento:', 115, 76);
          
          const splitNotes = doc.splitTextToSize(
            activeProposal.notes || 'Mapa visual em 3D gerado para ilustrar as patologias indicadas, servindo de base didática para o entendimento clínico dos procedimentos.',
            80
          );
          doc.text(splitNotes, 115, 82);
        } catch (canvasErr) {
          console.error('[BudgetPanel3D:Pdf] Falha ao renderizar imagem do Canvas:', canvasErr);
        }
      }

      // 4. Tabela de Procedimentos e Valores
      let yOffset = 145;
      doc.setFillColor(245, 245, 245);
      doc.rect(15, yOffset, 180, 7, 'F');
      
      doc.setFont('Helvetica', 'bold');
      doc.setFontSize(8);
      doc.setTextColor(50, 50, 50);
      doc.text('Dente', 17, yOffset + 5);
      doc.text('Procedimento Realizado', 35, yOffset + 5);
      doc.text('Valor Unitário', 165, yOffset + 5);

      doc.setFont('Helvetica', 'normal');
      doc.setTextColor(80, 80, 80);
      
      procedures.forEach((p, idx) => {
        const itemY = yOffset + 12 + (idx * 6);
        if (itemY < 270) {
          const toothObj = Object.values(teeth).find((t) => t.id === p.tooth_id);
          const toothNum = toothObj ? `Dente ${toothObj.tooth}` : 'Geral';
          
          doc.text(toothNum, 17, itemY);
          doc.text(p.procedure, 35, itemY);
          doc.text(`R$ ${p.price.toFixed(2)}`, 165, itemY);
        }
      });

      // 5. Consolidação Financeira
      const summaryY = yOffset + 18 + (procedures.length * 6);
      doc.setDrawColor(220, 220, 220);
      doc.line(15, summaryY, 195, summaryY);

      doc.setFont('Helvetica', 'normal');
      doc.text('Subtotal Bruto:', 125, summaryY + 8);
      doc.text(`R$ ${budget.subtotal.toFixed(2)}`, 165, summaryY + 8);

      doc.text('Desconto Concedido:', 125, summaryY + 13);
      doc.text(`R$ ${budget.discountAmount.toFixed(2)}`, 165, summaryY + 13);

      doc.setFont('Helvetica', 'bold');
      doc.setTextColor(139, 0, 0);
      doc.text('Valor Total Líquido:', 125, summaryY + 19);
      doc.text(`R$ ${budget.total.toFixed(2)}`, 165, summaryY + 19);

      // 6. Condições de Pagamento
      doc.setFont('Helvetica', 'normal');
      doc.setTextColor(50, 50, 50);
      doc.setFontSize(8.5);
      
      let paymentMethodLabel = '';
      if (paymentMethod === 'PIX') {
        paymentMethodLabel = 'PIX (À Vista)';
      } else if (paymentMethod === 'CASH') {
        paymentMethodLabel = 'Dinheiro/Espécie (À Vista)';
      } else if (paymentMethod === 'CREDIT_CARD') {
        paymentMethodLabel = `${installmentsCount}x no Cartão de Crédito`;
      }
      
      doc.text(`Condição de Pagamento: ${paymentMethodLabel}`, 15, summaryY + 28);
      
      if (paymentMethod === 'CREDIT_CARD' && installmentsCount > 1) {
        doc.setFontSize(7.5);
        doc.setTextColor(100, 100, 100);
        doc.text(`Parcelas: ${installmentsCount} parcelas mensais e sucessivas de R$ ${budget.installmentsList[0].amount.toFixed(2)}`, 15, summaryY + 33);
      }

      // Rodapé
      doc.setFontSize(7);
      doc.setTextColor(150, 150, 150);
      doc.text('Este documento é uma estimativa comercial sujeita a alterações conforme diagnóstico de exames complementares.', 15, 283);
      doc.text('* ATENÇÃO: As taxas informadas são valores aproximados. O valor praticado pela maquininha deve ser consultado e conferido no dia de efetuar o pagamento.', 15, 287);

      doc.save(`Proposta_3D_${selectedPatient?.name || activeProposal.patientName || 'Paciente'}.pdf`);
    } catch (err) {
      console.error('[BudgetPanel3D:Pdf] Erro na exportação do PDF:', err);
      alert('Ocorreu um erro ao gerar o PDF. Verifique se o navegador suporta exportação.');
    } finally {
      setGeneratingPdf(false);
    }
  };

  return (
    <div className="flex flex-col gap-5 text-white">
      {/* Cabeçalho */}
      <div className="flex items-center justify-between text-sky-400 font-bold uppercase tracking-wider text-xs border-b border-slate-800 pb-3">
        <div className="flex items-center gap-2">
          <Coins className="w-4 h-4" />
          <span>Motor Financeiro Integrado</span>
        </div>
        {syncStatus3D === 'saved_local' && (
          <span className="text-[10px] text-amber-400/90 font-medium normal-case flex items-center gap-1">
            💾 salvo local...
          </span>
        )}
        {syncStatus3D === 'syncing' && (
          <span className="text-[10px] text-sky-300 font-medium normal-case animate-pulse flex items-center gap-1">
            ☁️ enviando nuvem...
          </span>
        )}
        {syncStatus3D === 'synced' && (
          <span className="text-[10px] text-emerald-400 font-medium normal-case flex items-center gap-1">
            <Check className="w-3 h-3" /> nuvem sincronizada
          </span>
        )}
      </div>

      {/* ═══ LISTA EDITÁVEL DE PROCEDIMENTOS ═══ */}
      <div className="flex flex-col gap-2 bg-slate-900 border border-slate-800 p-4 rounded-xl">
        <div className="flex items-center justify-between mb-1">
          <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">Procedimentos no Orçamento</p>
          <span className="text-[10px] text-slate-500 font-semibold">{procedures.length} item(s)</span>
        </div>

        {/* Lista de procedimentos */}
        <div className="flex flex-col gap-1.5 max-h-[200px] overflow-y-auto pr-1">
          {procedures.length > 0 ? (
            procedures.map((proc) => {
              const toothObj = Object.values(teeth).find((t) => t.id === proc.tooth_id);
              const toothLabel = toothObj ? `D${toothObj.tooth}` : '—';
              const isEditing = editingId === proc.id;

              return (
                <div
                  key={proc.id}
                  className={`flex items-center gap-2 p-2 rounded-lg border transition-all ${
                    isEditing
                      ? 'bg-slate-800 border-sky-500/50 ring-1 ring-sky-500/30'
                      : 'bg-slate-950/60 border-slate-800/60 hover:border-slate-700'
                  }`}
                >
                  {/* Badge do dente */}
                  <span className="text-[9px] font-bold text-sky-400 bg-sky-950 border border-sky-900 px-1.5 py-0.5 rounded shrink-0">
                    {toothLabel}
                  </span>

                  {isEditing ? (
                    /* ═══ MODO EDIÇÃO ═══ */
                    <>
                      <input
                        type="text"
                        value={editName}
                        onChange={(e) => setEditName(e.target.value)}
                        onKeyDown={handleKeyDown}
                        className="flex-1 bg-slate-900 border border-slate-700 text-slate-200 text-[11px] rounded px-2 py-1 focus:outline-none focus:ring-1 focus:ring-sky-500 min-w-0"
                        autoFocus
                      />
                      <div className="flex items-center gap-1 shrink-0">
                        <span className="text-[10px] text-slate-500">R$</span>
                        <input
                          type="text"
                          value={editPrice}
                          onChange={(e) => setEditPrice(e.target.value)}
                          onKeyDown={handleKeyDown}
                          className="w-16 bg-slate-900 border border-slate-700 text-emerald-400 text-[11px] font-bold rounded px-2 py-1 focus:outline-none focus:ring-1 focus:ring-sky-500 text-right"
                        />
                      </div>
                      <button onClick={saveEdit} className="p-1 rounded bg-emerald-950 hover:bg-emerald-900 text-emerald-400 border border-emerald-800 transition-colors shrink-0" title="Salvar (Enter)">
                        <Check className="w-3 h-3" />
                      </button>
                      <button onClick={cancelEdit} className="p-1 rounded bg-slate-800 hover:bg-slate-700 text-slate-400 border border-slate-700 transition-colors shrink-0" title="Cancelar (Esc)">
                        <X className="w-3 h-3" />
                      </button>
                    </>
                  ) : (
                    /* ═══ MODO LEITURA ═══ */
                    <>
                      <span className="flex-1 text-[11px] text-slate-200 font-medium truncate min-w-0">{proc.procedure}</span>
                      <span className="text-[11px] text-emerald-400 font-bold shrink-0">
                        R$ {proc.price.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                      </span>
                      <button
                        onClick={() => startEditing(proc)}
                        className="p-1 rounded bg-slate-800/50 hover:bg-sky-950 text-slate-500 hover:text-sky-400 border border-slate-700/50 hover:border-sky-800 transition-colors shrink-0"
                        title="Editar procedimento"
                      >
                        <Pencil className="w-3 h-3" />
                      </button>
                      <button
                        onClick={() => removeProcedure(proc.id)}
                        className="p-1 rounded bg-slate-800/50 hover:bg-red-950 text-slate-500 hover:text-red-400 border border-slate-700/50 hover:border-red-900 transition-colors shrink-0"
                        title="Remover procedimento"
                      >
                        <Trash2 className="w-3 h-3" />
                      </button>
                    </>
                  )}
                </div>
              );
            })
          ) : (
            <p className="text-[11px] text-slate-500 italic text-center py-4">
              Nenhum procedimento adicionado ao orçamento.
            </p>
          )}
        </div>

        {/* Botão Adicionar Procedimento */}
        <div className="relative mt-1">
          <button
            onClick={() => setShowAddDropdown(!showAddDropdown)}
            className="w-full flex items-center justify-center gap-2 py-2 bg-sky-600/20 hover:bg-sky-600/30 text-sky-400 rounded-lg transition-all border border-sky-800/50 hover:border-sky-700 text-xs font-bold"
          >
            <PlusCircle className="w-3.5 h-3.5" />
            Adicionar Procedimento
            <ChevronDown className={`w-3 h-3 transition-transform ${showAddDropdown ? 'rotate-180' : ''}`} />
          </button>

          {/* Dropdown de seleção */}
          {showAddDropdown && (
            <div className="absolute bottom-full left-0 right-0 mb-1 bg-slate-900 border border-slate-700 rounded-xl shadow-2xl z-20 overflow-hidden">
              {/* Campo de busca */}
              <div className="p-2 border-b border-slate-800">
                <input
                  type="text"
                  value={addSearch}
                  onChange={(e) => setAddSearch(e.target.value)}
                  placeholder="Buscar procedimento..."
                  className="w-full bg-slate-800 border border-slate-700 text-slate-200 text-xs rounded-lg px-3 py-1.5 focus:outline-none focus:ring-1 focus:ring-sky-500 placeholder-slate-500"
                  autoFocus
                />
              </div>

              {/* Lista de procedimentos disponíveis */}
              <div className="max-h-[160px] overflow-y-auto">
                {filteredGlobalProcedures.length > 0 ? (
                  filteredGlobalProcedures.map((proc: any) => (
                    <button
                      key={proc.id}
                      onClick={() => handleAddProcedure(proc)}
                      className="w-full flex items-center justify-between px-3 py-2 hover:bg-slate-800 text-left transition-colors border-b border-slate-800/50 last:border-b-0"
                    >
                      <span className="text-xs text-slate-200 font-medium">{proc.name}</span>
                      <span className="text-xs text-emerald-400 font-bold shrink-0 ml-2">
                        R$ {proc.price.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}
                      </span>
                    </button>
                  ))
                ) : (
                  <p className="text-xs text-slate-500 italic text-center py-3">
                    {globalProcedures.length === 0 ? 'Nenhum procedimento cadastrado.' : 'Nenhum resultado encontrado.'}
                  </p>
                )}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Inputs de Configuração Financeira */}
      <div className="flex flex-col gap-4 bg-slate-900 border border-slate-800 p-4 rounded-xl">
        {/* Forma de Pagamento */}
        <div>
          <label className="text-[10px] text-slate-400 font-bold uppercase block mb-1.5">Forma de Pagamento</label>
          <div className="grid grid-cols-3 gap-2">
            <button
              onClick={() => handlePaymentMethodChange('PIX')}
              className={`py-2 px-3 rounded-lg text-xs font-semibold border transition-all ${
                paymentMethod === 'PIX'
                  ? 'bg-sky-600 border-sky-500 text-white'
                  : 'bg-slate-800 border-slate-700 text-slate-400 hover:bg-slate-700'
              }`}
            >
              PIX
            </button>
            <button
              onClick={() => handlePaymentMethodChange('CREDIT_CARD')}
              className={`py-2 px-3 rounded-lg text-xs font-semibold border transition-all ${
                paymentMethod === 'CREDIT_CARD'
                  ? 'bg-sky-600 border-sky-500 text-white'
                  : 'bg-slate-800 border-slate-700 text-slate-400 hover:bg-slate-700'
              }`}
            >
              Cartão de Crédito
            </button>
            <button
              onClick={() => handlePaymentMethodChange('CASH')}
              className={`py-2 px-3 rounded-lg text-xs font-semibold border transition-all ${
                paymentMethod === 'CASH'
                  ? 'bg-sky-600 border-sky-500 text-white'
                  : 'bg-slate-800 border-slate-700 text-slate-400 hover:bg-slate-700'
              }`}
            >
              Dinheiro/Espécie
            </button>
          </div>
        </div>

        {/* Descontos */}
        <div>
          <label className="text-[10px] text-slate-400 font-bold uppercase block mb-1.5">Desconto Comercial</label>
          <div className="flex gap-2">
            <select
              value={discountType}
              onChange={(e) => setDiscountType(e.target.value as 'PERCENT' | 'FIXED')}
              className="bg-slate-800 border border-slate-700 text-slate-200 text-xs rounded-lg px-2 py-1.5 focus:outline-none focus:ring-1 focus:ring-sky-500"
            >
              <option value="PERCENT">% Desc.</option>
              <option value="FIXED">Valor Fixo (R$)</option>
            </select>
            <input
              type="number"
              value={discountValue}
              onChange={(e) => setDiscountValue(Math.max(0, parseFloat(e.target.value) || 0))}
              className="flex-1 bg-slate-800 border border-slate-700 text-slate-200 text-xs rounded-lg px-3 py-1.5 focus:outline-none focus:ring-1 focus:ring-sky-500"
              min="0"
            />
          </div>
        </div>

        {/* Parcelas (Só se for cartão) */}
        {paymentMethod === 'CREDIT_CARD' && (
          <div>
            <label className="text-[10px] text-slate-400 font-bold uppercase block mb-1.5">Número de Parcelas</label>
            <select
              value={installmentsCount}
              onChange={(e) => setInstallmentsCount(parseInt(e.target.value))}
              className="w-full bg-slate-800 border border-slate-700 text-slate-200 text-xs rounded-lg p-2 focus:outline-none focus:ring-1 focus:ring-sky-500"
            >
              {Array.from({ length: getMaxInstallments(paymentMethod) }, (_, i) => i + 1).map((n) => (
                <option key={n} value={n}>{n}x sem juros</option>
              ))}
            </select>
          </div>
        )}
      </div>

      {/* Resumo Financeiro Consolidado */}
      <div className="bg-slate-900 border border-slate-800 p-4 rounded-xl space-y-2">
        <div className="flex justify-between text-xs text-slate-400 font-semibold">
          <span>Subtotal Bruto:</span>
