import React, { useRef, useState } from 'react';
import * as THREE from 'three';
import { usePlanning3D } from '../hooks/usePlanning3D';
import { ToothCondition, ToothSurface } from '../types';

interface ToothMeshProps {
  toothNumber: number;
  position: [number, number, number];
  rotation?: [number, number, number];
}

export function isAnteriorTooth(toothNumber: number): boolean {
  const code = toothNumber % 10;
  return code >= 1 && code <= 3;
}

// Geometrias compartilhadas para economizar alocação de GPU e evitar WebGL Context Lost
const sharedBoxGeometry = new THREE.BoxGeometry(0.8, 0.9, 0.8);
const sharedConeGeometry = new THREE.ConeGeometry(0.3, 0.8, 4);
const sharedCylinderGeometry = new THREE.CylinderGeometry(0.05, 0.05, 0.6, 4);
const sharedSphereGeometry = new THREE.SphereGeometry(0.08, 16, 16);

// Geometrias anatômicas realistas
const sharedMolarCrownCylinder = new THREE.CylinderGeometry(0.42, 0.42, 0.7, 16);
const sharedMolarCrownSphere = new THREE.SphereGeometry(0.42, 16, 16);
const sharedAnteriorCrownCylinder = new THREE.CylinderGeometry(0.38, 0.2, 0.8, 16);
const sharedMolarRootCone = new THREE.ConeGeometry(0.15, 0.8, 8);
const sharedAnteriorRootCone = new THREE.ConeGeometry(0.15, 1.0, 8);

const sharedMolarBox = new THREE.BoxGeometry(0.88, 0.78, 0.88);
const sharedAnteriorBox = new THREE.BoxGeometry(0.78, 0.83, 0.32);

export function ToothMesh({ toothNumber, position, rotation = [0, 0, 0] }: ToothMeshProps) {
  const { viewerState, selectTooth, getToothState, getSurfaceCondition } = usePlanning3D();
  const groupRef = useRef<THREE.Group>(null);
  const [hovered, setHovered] = useState(false);

  const toothState = getToothState(toothNumber);
  const isSelected = viewerState.activeTooth === toothNumber;
  const isAnterior = isAnteriorTooth(toothNumber);
  const isAfterSimulation = viewerState.simulationState === 'AFTER';

  // Se o dente estiver ausente (MISSING):
  // No modo "Antes": Fica ocultado.
  // No modo "Depois" (AFTER): Simula reabilitação com coroa de porcelana
  if (toothState?.condition === 'MISSING') {
    if (isAfterSimulation) {
      return (
        <group position={position} rotation={rotation}>
          {isAnterior ? (
            <mesh castShadow receiveShadow geometry={sharedAnteriorCrownCylinder} scale={[1, 1, 0.3]}>
              <meshStandardMaterial color="#FAF8F5" roughness={0.05} metalness={0.1} />
            </mesh>
          ) : (
            <group>
              <mesh castShadow receiveShadow geometry={sharedMolarCrownCylinder}>
                <meshStandardMaterial color="#FAF8F5" roughness={0.05} metalness={0.1} />
              </mesh>
              <mesh castShadow receiveShadow geometry={sharedMolarCrownSphere} position={[0, 0.35, 0]} scale={[1, 0.3, 1]}>
                <meshStandardMaterial color="#FAF8F5" roughness={0.05} metalness={0.1} />
              </mesh>
            </group>
          )}
        </group>
      );
    }
    return null;
  }

  // Helper para obter a cor de cada face (superfície) individual
  const getSurfaceColor = (surface: ToothSurface) => {
    let cond = getSurfaceCondition(toothNumber, surface);

    // No modo "Depois", todas as patologias de cáries/fraturas são limpas (ficam saudáveis)
    if (isAfterSimulation) {
      if (cond === 'CARIES' || cond === 'FRACTURE') {
        cond = 'HEALTHY';
      }
    }

    // Se for Implante ou Coroa
    if (toothState?.condition === 'IMPLANT' || cond === 'IMPLANT') return '#9CA3AF';
    if (toothState?.condition === 'CROWN' || cond === 'CROWN') return '#F59E0B';

    switch (cond) {
      case 'CARIES':
      case 'FRACTURE':
        return '#EF4444'; // Vermelho para patologias
      case 'HEALTHY':
      default:
        const isSurfaceSelected = isSelected && viewerState.activeSurfaces.includes(surface);
        if (isSurfaceSelected) {
          return '#3B82F6'; // Azul para seleção
        }
        return '#FAF8F5';
    }
  };

  const isSurfaceActive = (surface: ToothSurface) => {
    const cond = getSurfaceCondition(toothNumber, surface);
    
    let activeCond = cond;
    if (isAfterSimulation && (cond === 'CARIES' || cond === 'FRACTURE')) {
      activeCond = 'HEALTHY';
    }

    const isSurfaceSelected = isSelected && viewerState.activeSurfaces.includes(surface);
    return activeCond !== 'HEALTHY' || isSurfaceSelected;
  };

  const getCrownMaterialProps = () => {
    let color = hovered ? '#E0F2FE' : '#FAF8F5';
    let roughness = 0.05;
    let metalness = 0.15;

    if (toothState?.condition === 'IMPLANT') {
      color = '#9CA3AF';
      roughness = 0.2;
      metalness = 0.8;
    } else if (toothState?.condition === 'CROWN') {
      color = '#F59E0B';
      roughness = 0.1;
      metalness = 0.7;
    }

    return { color, roughness, metalness };
  };

  const topSurface: ToothSurface = isAnterior ? 'I' : 'O';
  
  const faceColors = {
    distal: getSurfaceColor('D'),
    mesial: getSurfaceColor('M'),
    top: getSurfaceColor(topSurface),
    cervical: getSurfaceColor('C'),
    vestibular: getSurfaceColor('V'),
    lingual: getSurfaceColor('L'),
  };

  const handlePointerOver = (e: any) => {
    e.stopPropagation();
    if (viewerState.presentationMode) return;
    setHovered(true);
    document.body.style.cursor = 'pointer';
  };

  const handlePointerOut = (e: any) => {
    setHovered(false);
    document.body.style.cursor = 'default';
  };

  const handleClick = (e: any) => {
    e.stopPropagation();
    if (viewerState.presentationMode) return;
    if (isSelected) {
      selectTooth(null);
    } else {
      selectTooth(toothNumber);
    }
  };

  const crownProps = getCrownMaterialProps();

  return (
    <group
      ref={groupRef}
      position={position}
      rotation={rotation}
      onPointerOver={handlePointerOver}
      onPointerOut={handlePointerOut}
      onClick={handleClick}
    >
      {/* 1. COROA ANATÔMICA DO DENTE (Formas orgânicas realistas) */}
      {isAnterior ? (
        // Dente Anterior: Formato cinzel/cuneiforme
        <mesh castShadow receiveShadow geometry={sharedAnteriorCrownCylinder} scale={[1, 1, 0.3]}>
          <meshStandardMaterial color={crownProps.color} roughness={crownProps.roughness} metalness={crownProps.metalness} />
        </mesh>
      ) : (
        // Dente Posterior (Molar/Pré-molar): Formato cilíndrico com cúspides arredondadas
        <group>
          <mesh castShadow receiveShadow geometry={sharedMolarCrownCylinder}>
            <meshStandardMaterial color={crownProps.color} roughness={crownProps.roughness} metalness={crownProps.metalness} />
          </mesh>
          <mesh castShadow receiveShadow geometry={sharedMolarCrownSphere} position={[0, 0.35, 0]} scale={[1, 0.3, 1]}>
            <meshStandardMaterial color={crownProps.color} roughness={crownProps.roughness} metalness={crownProps.metalness} />
          </mesh>
        </group>
      )}

      {/* 2. RAÍZES ANATÔMICAS (Duas para molares, uma para anteriores) */}
      {!isAnterior ? (
        <group visible={toothState?.condition !== 'IMPLANT'}>
          <mesh
            position={[-0.2, -0.65, 0]}
            rotation={[0, 0, 0.15]}
            castShadow
            receiveShadow
            geometry={sharedMolarRootCone}
          >
            <meshStandardMaterial
              color={viewerState.transparencyMode ? '#FCA5A5' : '#D1D5DB'}
              opacity={viewerState.transparencyMode ? 0.3 : 1}
              transparent={viewerState.transparencyMode}
              roughness={0.8}
            />
          </mesh>
          <mesh
            position={[0.2, -0.65, 0]}
            rotation={[0, 0, -0.15]}
            castShadow
            receiveShadow
            geometry={sharedMolarRootCone}
          >
            <meshStandardMaterial
              color={viewerState.transparencyMode ? '#FCA5A5' : '#D1D5DB'}
              opacity={viewerState.transparencyMode ? 0.3 : 1}
              transparent={viewerState.transparencyMode}
              roughness={0.8}
            />
          </mesh>
        </group>
      ) : (
        <mesh
          position={[0, -0.8, 0]}
          scale={[1, 1, 0.6]}
          castShadow
          receiveShadow
          geometry={sharedAnteriorRootCone}
          visible={toothState?.condition !== 'IMPLANT'}
        >
          <meshStandardMaterial
            color={viewerState.transparencyMode ? '#FCA5A5' : '#D1D5DB'}
            opacity={viewerState.transparencyMode ? 0.3 : 1}
            transparent={viewerState.transparencyMode}
          />
        </mesh>
      )}

      {/* 2.5. GENGIVA MARGINAL / PAPILA (Garante o contorno realista da gengiva ao redor do dente) */}
      {!viewerState.transparencyMode && (
        <mesh
          position={[0, -0.32, 0.05]}
          scale={[1.1, 0.5, 1.1]}
        >
          <sphereGeometry args={[0.48, 16, 16]} />
          <meshStandardMaterial
            color="#C77373" // Cor rosada realista da gengiva
            roughness={0.15}
            metalness={0.05}
          />
        </mesh>
      )}

      {/* 3. MESH DO CANAL RADICULAR */}
      <mesh
        position={[0, -0.6, 0]}
        geometry={sharedCylinderGeometry}
        visible={(toothState?.condition === 'PULPITIS' || viewerState.transparencyMode) && !isAfterSimulation}
      >
        <meshStandardMaterial
          color={toothState?.condition === 'PULPITIS' ? '#EF4444' : '#F43F5E'}
          emissive="#EF4444"
          emissiveIntensity={0.5}
        />
      </mesh>

      {/* 4. OVERLAY DAS SUPERFÍCIES (Exibe as cores de patologias/seleção nas faces correspondentes) */}
      <mesh castShadow receiveShadow geometry={isAnterior ? sharedAnteriorBox : sharedMolarBox}>
        <meshStandardMaterial attach="material-0" color={faceColors.distal} roughness={0.1} transparent opacity={isSurfaceActive('D') ? 0.85 : 0} />
        <meshStandardMaterial attach="material-1" color={faceColors.mesial} roughness={0.1} transparent opacity={isSurfaceActive('M') ? 0.85 : 0} />
        <meshStandardMaterial attach="material-2" color={faceColors.top} roughness={0.1} transparent opacity={isSurfaceActive(topSurface) ? 0.85 : 0} />
        <meshStandardMaterial attach="material-3" color={faceColors.cervical} roughness={0.1} transparent opacity={isSurfaceActive('C') ? 0.85 : 0} />
        <meshStandardMaterial attach="material-4" color={faceColors.vestibular} roughness={0.1} transparent opacity={isSurfaceActive('V') ? 0.85 : 0} />
        <meshStandardMaterial attach="material-5" color={faceColors.lingual} roughness={0.1} transparent opacity={isSurfaceActive('L') ? 0.85 : 0} />
      </mesh>

      {/* Rótulo de seleção ativo */}
      {isSelected && (
        <mesh position={[0, 0.8, 0.5]} geometry={sharedSphereGeometry}>
          <meshBasicMaterial color="#3B82F6" />
        </mesh>
      )}
    </group>
  );
}

import React, { createContext, useContext, useState, ReactNode, useMemo, useRef, useEffect } from 'react';
import { TreatmentPlan, TreatmentTooth, TreatmentProcedure, Viewer3DState, ToothCondition, ToothSurface, LayerKey, LayerConfig } from '../types';
import { usePatientContext } from '../../context/PatientContext';

interface Planning3DContextType {
  activePlan: TreatmentPlan | null;
  teeth: Record<number, TreatmentTooth>;
  procedures: TreatmentProcedure[];
  globalProcedures: any[];
  viewerState: Viewer3DState;
  setActivePlan: (plan: TreatmentPlan | null) => void;
  selectTooth: (toothNumber: number | null, pos?: { x: number, y: number }) => void;
  selectSurface: (surface: ToothSurface) => void;
  updateToothCondition: (toothNumber: number, condition: ToothCondition, notes?: string) => void;
  updateToothSurfaceCondition: (toothNumber: number, surface: ToothSurface, condition: ToothCondition) => void;
  addProcedure: (toothNumber: number, procedureId: string, price: number, name: string) => void;
  removeProcedure: (procedureInstanceId: string) => void;
  updateProcedure: (instanceId: string, updates: { name?: string; price?: number }) => void;
  setTransparencyMode: (mode: boolean) => void;
  setLoading: (loading: boolean) => void;
  setPresentationMode: (mode: boolean) => void;
  setSimulationState: (state: 'BEFORE' | 'AFTER') => void;
  acceptPlan: (signature?: string) => void;
  setLayerVisibility: (layerKey: LayerKey, visible: boolean) => void;
  setLayerOpacity: (layerKey: LayerKey, opacity: number) => void;
  toggleMissingTooth: (toothNumber: number) => void;
  setViewingAnatomy: (state: boolean) => void;
  onOpenProcedureManager?: () => void;
  planStatus: 'DRAFT' | 'ACCEPTED';
  signatureData: string | null;
  setPlanStatus: (status: 'DRAFT' | 'ACCEPTED') => void;
  setSignatureData: (sig: string | null) => void;
}

const Planning3DContext = createContext<Planning3DContextType | undefined>(undefined);

const isPresentation = typeof window !== 'undefined' && new URLSearchParams(window.location.search).get('view') === 'presentation';

export function Planning3DProvider({ children, globalProcedures = [], onOpenProcedureManager }: { children: ReactNode, globalProcedures?: any[], onOpenProcedureManager?: () => void }) {
  // Integração unificada com o CRM
  const { activeSections, setActiveSections, activeProposal, setActiveProposal, selectedPatient, saveContextToSupabase } = usePatientContext();

  const [viewerState, setViewerState] = useState<Viewer3DState>({
    activeTooth: null,
    viewingAnatomy: false,
    activeSurfaces: [],
    transparencyMode: false,
    loading: false,
    presentationMode: isPresentation,
    simulationState: 'BEFORE',
    missingTeeth: [],
    layers: {
      gums: { visible: true, opacity: 0.95 },
      bone: { visible: true, opacity: 0.8 },
      teeth: { visible: true, opacity: 1.0 },
      roots: { visible: true, opacity: 1.0 },
      pulp: { visible: true, opacity: 1.0 },
      canals: { visible: true, opacity: 1.0 },
      nerves: { visible: true, opacity: 1.0 },
      sinus: { visible: true, opacity: 1.0 },
    },
  });

  const setViewingAnatomy = (state: boolean) => {
    setViewerState(prev => ({ ...prev, viewingAnatomy: state }));
  };

  const toggleMissingTooth = (toothNumber: number) => {
    setViewerState(prev => {
      const isMissing = prev.missingTeeth.includes(toothNumber);
      return {
        ...prev,
        missingTeeth: isMissing 
          ? prev.missingTeeth.filter(t => t !== toothNumber) 
          : [...prev.missingTeeth, toothNumber]
      };
    });
  };

  // 1. Derivar o estado local (teeth, procedures) a partir das activeSections globais
  const { teeth, procedures } = useMemo(() => {
    const t: Record<number, TreatmentTooth> = {};
    const p: TreatmentProcedure[] = [];

    activeSections.forEach(section => {
      section.markers.forEach(marker => {
        if (!t[marker.toothNumber]) {
          t[marker.toothNumber] = {
            id: marker.id,
            plan_id: activeProposal?.patientName || 'plan',
            tooth: marker.toothNumber,
            condition: marker.condition || 'HEALTHY',
            notes: marker.notes || '',
            surfaces: marker.surfaces || {}
          };
        }
        
        if (marker.procedureInstances) {
          marker.procedureInstances.forEach(inst => {
            p.push({
              id: inst.id,
              tooth_id: marker.id,
              procedure: inst.name,
              price: inst.price,
              procedureId: inst.procedureId,
              surfaces: inst.faces || [],
              status: inst.status,
              date: inst.date
            });
          });
        } else if (marker.procedures) {
          // Compatibilidade antiga
          marker.procedures.forEach(procId => {
            const procInfo = globalProcedures.find(p => p.id === procId);
            if (procInfo) {
              p.push({
                id: `${marker.id}-${procId}`,
                tooth_id: marker.id,
                procedure: procInfo.name,
                price: procInfo.price
              });
            }
          });
        }
      });
    });

    return { teeth: t, procedures: p };
  }, [activeSections, activeProposal, globalProcedures]);

  const activePlan: TreatmentPlan = {
    id: 'unified-plan',
    patient_id: selectedPatient?.id || 'unknown',
    created_at: new Date().toISOString(),
    status: 'DRAFT'
  };

  const setActivePlan = () => {};

  const getSectionForTooth = (toothNumber: number) => {
    return toothNumber < 30 ? 'upper' : 'lower';
  };

  const updateMarkerInSections = (toothNumber: number, updater: (marker: any) => any) => {
    setActiveSections(prev => {
      let found = false;
      const newSections = prev.map(sec => {
        const markerIndex = sec.markers.findIndex(m => m.toothNumber === toothNumber);
        if (markerIndex !== -1) {
          found = true;
          const newMarkers = [...sec.markers];
          newMarkers[markerIndex] = updater({ ...newMarkers[markerIndex] });
          return { ...sec, markers: newMarkers };
        }
        return sec;
      });

      if (!found) {
        // Create new marker if it doesn't exist
        const targetSecId = getSectionForTooth(toothNumber);
        const newMarker = updater({
          id: `${targetSecId}-${toothNumber}-${Date.now()}`,
          toothNumber,
          x: 0,
          y: 0,
          procedures: [],
          procedureInstances: [],
          condition: 'HEALTHY',
          surfaces: {}
        });
        
        return newSections.map(sec => 
          sec.id === targetSecId ? { ...sec, markers: [...sec.markers, newMarker] } : sec
        );
      }

      return newSections;
    });
  };

  const selectTooth = (toothNumber: number | null, pos?: { x: number, y: number }) => {
    if (viewerState.presentationMode) return;
    setViewerState((prev) => ({
      ...prev,
      activeTooth: toothNumber,
      activeToothPos: toothNumber === null ? null : pos,
      activeSurfaces: [],
    }));
  };

  const selectSurface = (surface: ToothSurface) => {
    if (viewerState.presentationMode) return;
    setViewerState((prev) => {
      const exists = prev.activeSurfaces.includes(surface);
      const newSurfaces = exists
        ? prev.activeSurfaces.filter((s) => s !== surface)
        : [...prev.activeSurfaces, surface];
      return {
        ...prev,
        activeSurfaces: newSurfaces,
      };
    });
  };

  const updateToothCondition = (toothNumber: number, condition: ToothCondition, notes?: string) => {
    updateMarkerInSections(toothNumber, (marker) => {
      return {
        ...marker,
        condition,
        notes: notes !== undefined ? notes : marker.notes
      };
    });
  };

  const updateToothSurfaceCondition = (toothNumber: number, surface: ToothSurface, condition: ToothCondition) => {
    updateMarkerInSections(toothNumber, (marker) => {
      const updatedSurfaces = { ...(marker.surfaces || {}), [surface]: condition };
      let toothCond = marker.condition || 'HEALTHY';
      if (condition === 'CARIES' || condition === 'FRACTURE') {
        toothCond = condition;
      }
      return {
        ...marker,
        condition: toothCond,
        surfaces: updatedSurfaces
      };
    });
  };

  const addProcedure = (toothNumber: number, procedureId: string, price: number, name: string) => {
    updateMarkerInSections(toothNumber, (marker) => {
      const newInst = {
        id: `inst-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
        procedureId,
        name,
        price,
        includeFinancial: true,
        status: 'A realizar',
        date: new Date().toISOString(),
        dentist: 'Sistema 3D',
        faces: [...viewerState.activeSurfaces]
      };
      
      const instances = [...(marker.procedureInstances || []), newInst];
      const procs = [...(marker.procedures || []), procedureId];
      
      return { ...marker, procedureInstances: instances, procedures: procs };
    });

    // Limpar faces selecionadas após o lançamento do procedimento
    selectTooth(toothNumber);
  };

  const removeProcedure = (procedureInstanceId: string) => {
    setActiveSections(prev => {
      return prev.map(sec => ({
        ...sec,
        markers: sec.markers.map(m => ({
          ...m,
          procedureInstances: (m.procedureInstances || []).filter(inst => inst.id !== procedureInstanceId)
        }))
      }));
    });
  };

  const updateProcedure = (instanceId: string, updates: { name?: string; price?: number }) => {
    setActiveSections(prev => {
      return prev.map(sec => ({
        ...sec,
        markers: sec.markers.map(m => ({
          ...m,
          procedureInstances: (m.procedureInstances || []).map(inst => {
            if (inst.id !== instanceId) return inst;
            return {
              ...inst,
              ...(updates.name !== undefined && { name: updates.name }),
              ...(updates.price !== undefined && { price: updates.price }),
            };
          })
        }))
      }));
    });
  };

  const setTransparencyMode = (mode: boolean) => {
    setViewerState((prev) => ({
      ...prev,
      transparencyMode: mode,
      layers: {
        ...prev.layers,
        gums: { ...prev.layers.gums, opacity: mode ? 0.2 : 0.95 },
        bone: { ...prev.layers.bone, opacity: mode ? 0.1 : 0.8 },
      },
    }));
  };

  const setLoading = (loading: boolean) => {
    setViewerState((prev) => ({ ...prev, loading }));
  };

  const setPresentationMode = (mode: boolean) => {
    setViewerState((prev) => ({
      ...prev,
      presentationMode: mode,
      activeTooth: null,
      activeSurfaces: [],
      simulationState: 'BEFORE',
    }));
  };

  const setSimulationState = (state: 'BEFORE' | 'AFTER') => {
    setViewerState((prev) => ({ ...prev, simulationState: state }));
  };

  const [planStatus, setPlanStatus] = useState<'DRAFT' | 'ACCEPTED'>('DRAFT');
  const [signatureData, setSignatureData] = useState<string | null>(null);
  const [pendingSave, setPendingSave] = useState(false);

  const acceptPlan = (signature?: string) => {
    setPlanStatus('ACCEPTED');
    if (signature) {
      setSignatureData(signature);
    }
    
    if (isPresentation) {
      const channel = new BroadcastChannel('planning_3d_channel');
      channel.postMessage({
        type: 'accept_plan_viewer',
        payload: { signatureData: signature || null }
      });
      channel.close();
    } else {
      setActiveProposal(prev => ({
        ...prev,
        status: 'Aprovado (paciente pagou)'
      }));
      setPendingSave(true);
    }
  };

  useEffect(() => {
    if (pendingSave && activeProposal.status === 'Aprovado (paciente pagou)') {
      setPendingSave(false);
      saveContextToSupabase().catch(err => {
        console.error("Erro ao salvar aceite do plano no Supabase:", err);
      });
    }
  }, [pendingSave, activeProposal, saveContextToSupabase]);

  // Sync state via BroadcastChannel
  const latestViewerStateRef = useRef({ viewerState, planStatus, signatureData });
  useEffect(() => {
    latestViewerStateRef.current = { viewerState, planStatus, signatureData };
  }, [viewerState, planStatus, signatureData]);

  useEffect(() => {
    const channel = new BroadcastChannel('planning_3d_channel');

    if (!isPresentation) {
      const handleMessage = (event: MessageEvent) => {
        if (event.data?.type === 'request_initial_viewer_state') {
          const current = latestViewerStateRef.current;
          channel.postMessage({
            type: 'viewer_sync',
            payload: {
              viewerState: current.viewerState,
              planStatus: current.planStatus,
              signatureData: current.signatureData
            }
          });
        } else if (event.data?.type === 'accept_plan_viewer') {
          acceptPlan(event.data.payload?.signatureData);
        }
      };
      channel.addEventListener('message', handleMessage);
      return () => {
        channel.removeEventListener('message', handleMessage);
        channel.close();
      };
    } else {
      const handleMessage = (event: MessageEvent) => {
        if (event.data?.type === 'viewer_sync' && event.data.payload) {
          const { viewerState: syncViewerState, planStatus: syncPlanStatus, signatureData: syncSignatureData } = event.data.payload;
          setViewerState({
            ...syncViewerState,
            presentationMode: true
          });
          setPlanStatus(syncPlanStatus);
          setSignatureData(syncSignatureData);
        }
      };
      channel.addEventListener('message', handleMessage);
      channel.postMessage({ type: 'request_initial_viewer_state' });
      return () => {
        channel.removeEventListener('message', handleMessage);
        channel.close();
      };
    }
  }, []);

  useEffect(() => {
    if (!isPresentation) {
      const channel = new BroadcastChannel('planning_3d_channel');
      channel.postMessage({
        type: 'viewer_sync',
        payload: { viewerState, planStatus, signatureData }
      });
      return () => {
        channel.close();
      };
    }
  }, [viewerState, planStatus, signatureData]);

  const setLayerVisibility = (layerKey: LayerKey, visible: boolean) => {
    setViewerState((prev) => ({
      ...prev,
      layers: {
        ...prev.layers,
        [layerKey]: { ...prev.layers[layerKey], visible },
      },
    }));
  };

  const setLayerOpacity = (layerKey: LayerKey, opacity: number) => {
    setViewerState((prev) => ({
      ...prev,
      layers: {
        ...prev.layers,
        [layerKey]: { ...prev.layers[layerKey], opacity },
      },
    }));
  };

  return (
    <Planning3DContext.Provider
      value={{
        activePlan,
        teeth,
        procedures,
        globalProcedures,
        viewerState,
        setActivePlan,
        selectTooth,
        selectSurface,
        updateToothCondition,
        updateToothSurfaceCondition,
        addProcedure,
        removeProcedure,
        updateProcedure,
        setTransparencyMode,
        setLoading,
        setPresentationMode,
        setSimulationState,
        acceptPlan,
        toggleMissingTooth,
        setViewingAnatomy,
        setLayerVisibility,
        setLayerOpacity,
        onOpenProcedureManager,
        planStatus,
        signatureData,
        setPlanStatus,
        setSignatureData,
      }}
    >
      {children}
    </Planning3DContext.Provider>
  );
}

export function usePlanning3DContext() {
  const context = useContext(Planning3DContext);
  if (!context) {
    throw new Error('usePlanning3DContext deve ser usado dentro de um Planning3DProvider');
  }
  return context;
}

