import * as THREE from 'three';

export interface SelectionState {
  selectedTooth: number | null;
  hoveredTooth: number | null;
}

export class SelectionManager {
  private static instance: SelectionManager;
  private selectedTooth: number | null = null;
  private hoveredTooth: number | null = null;
  private listeners: ((state: SelectionState) => void)[] = [];

  private constructor() {}

  public static getInstance(): SelectionManager {
    if (!SelectionManager.instance) {
      SelectionManager.instance = new SelectionManager();
    }
    return SelectionManager.instance;
  }

  public getSelectionState(): SelectionState {
    return {
      selectedTooth: this.selectedTooth,
      hoveredTooth: this.hoveredTooth,
    };
  }

  public selectTooth(toothNumber: number | null) {
    this.selectedTooth = toothNumber;
    this.notify();
  }

  public hoverTooth(toothNumber: number | null) {
    this.hoveredTooth = toothNumber;
    this.notify();
  }

  public subscribe(callback: (state: SelectionState) => void) {
    this.listeners.push(callback);
    return () => {
      this.listeners = this.listeners.filter((l) => l !== callback);
    };
  }

  private notify() {
    const state = this.getSelectionState();
    this.listeners.forEach((l) => l(state));
  }

  // Auxiliar para obter propriedades de destaque (Highlight emissivo)
  public getHighlightProps(
    toothNumber: number,
    activeTooth: number | null,
    isHovered: boolean
  ) {
    const isSelected = activeTooth === toothNumber;
    if (isSelected) {
      return {
        emissive: new THREE.Color('#3B82F6'),
        emissiveIntensity: 0.6,
      };
    }
    if (isHovered) {
      return {
        emissive: new THREE.Color('#E0F2FE'),
        emissiveIntensity: 0.3,
      };
    }
    return {
      emissive: new THREE.Color('#000000'),
      emissiveIntensity: 0,
    };
  }
}

import React from 'react';
import * as THREE from 'three';
import { usePlanning3D } from '../hooks/usePlanning3D';
import { LayerKey } from '../types';

interface StructureMeshProps {
  layerKey: LayerKey;
  geometry?: THREE.BufferGeometry;
  color: string;
  defaultPosition?: [number, number, number];
  defaultRotation?: [number, number, number];
  children?: React.ReactNode;
}

export function StructureMesh({
  layerKey,
  geometry,
  color,
  defaultPosition = [0, 0, 0],
  defaultRotation = [0, 0, 0],
  children
}: StructureMeshProps) {
  const { viewerState } = usePlanning3D();
  const layerState = viewerState.layers[layerKey];

  if (!layerState || !layerState.visible) return null;

  // Se houver geometria provida pelo GLTF Loader
  if (geometry) {
    return (
      <mesh
        geometry={geometry}
        position={defaultPosition}
        rotation={defaultRotation}
        castShadow
        receiveShadow
      >
        <meshStandardMaterial
          color={color}
          roughness={layerKey === 'gums' ? 0.15 : 0.6}
          metalness={layerKey === 'bone' ? 0.1 : 0.05}
          transparent={layerState.opacity < 1}
          opacity={layerState.opacity}
        />
      </mesh>
    );
  }

  // Caso seja renderizado como Fallback Procedural via filhos
  if (children) {
    return <group>{children}</group>;
  }

  return null;
}

import React, { Component, Suspense } from 'react';
import { useGLTF, Environment, Center } from '@react-three/drei';
import { ToothMesh, setupToothShader, updateToothUniforms } from './ToothMesh';
import * as THREE from 'three';
import { usePlanning3D } from '../hooks/usePlanning3D';

interface ToothDetailLoaderProps {
  toothNumber: number;
  variant: 'anatomic' | 'endodontic';
}

// Fallback caso o usuário não tenha feito o download do dente individual ainda
function FallbackSingleTooth({ toothNumber }: { toothNumber: number }) {
  return (
    <group position={[0, 0, 0]} scale={[3, 3, 3]}>
      <ToothMesh
        toothNumber={toothNumber}
