export async function getActivePlan(patientId: string): Promise<TreatmentPlan> {
  return new Promise((resolve) => {
    setTimeout(() => {
      resolve({
        id: `plan-${Date.now()}`,
        patient_id: patientId,
        created_at: new Date().toISOString(),
        status: 'DRAFT',
      });
    }, 500);
  });
}

